window.BANK_INTL={"cam": {"eng": {"1": [{"id": "cam-eng-k1-0", "name": "Phonics and spelling", "desc": "Letter sounds and simple words", "idx": 0, "soal": [{"lv": 1, "q": "Which letter makes the sound at the beginning of the word 'apple'?", "o": ["s", "a", "t", "p"], "a": 1, "p": "The word 'apple' begins with the short 'a' sound, represented by the letter 'a'."}, {"lv": 1, "q": "What is the starting sound of the word 'sun'?", "o": ["s", "m", "n", "c"], "a": 0, "p": "The word 'sun' starts with the /s/ sound, which is made by the letter 's'."}, {"lv": 1, "q": "Which letter makes the sound at the beginning of 'dog'?", "o": ["b", "p", "d", "g"], "a": 2, "p": "The word 'dog' begins with the /d/ sound, written with the letter 'd'."}, {"lv": 1, "q": "Choose the letter that makes the sound at the start of 'cat'.", "o": ["k", "c", "s", "t"], "a": 1, "p": "The word 'cat' starts with the /k/ sound, which is commonly spelled with the letter 'c'."}, {"lv": 2, "q": "Blend the sounds together to read the word: /c/ - /a/ - /t/", "o": ["cut", "cot", "cat", "cap"], "a": 2, "p": "When you blend the sounds /c/, /a/, and /t/ together, they make the word 'cat'."}, {"lv": 2, "q": "Which word is spelled correctly using these letter sounds: /p/ - /i/ - /g/?", "o": ["pag", "pig", "pug", "peg"], "a": 1, "p": "The sounds /p/, /i/, and /g/ spell the word 'pig'."}, {"lv": 2, "q": "What is the ending sound in the word 'sun'?", "o": ["s", "u", "n", "m"], "a": 2, "p": "The word 'sun' ends with the /n/ sound, represented by the letter 'n'."}, {"lv": 2, "q": "Choose the correct spelling for the word that means a small animal that hops.", "o": ["rabit", "rabbit", "rabiit", "rabett"], "a": 1, "p": "The correct spelling is 'rabbit', featuring double 'b'."}, {"lv": 3, "q": "Which word contains the 'sh' digraph?", "o": ["chip", "ship", "ring", "this"], "a": 1, "p": "The word 'ship' starts with the 'sh' digraph, which makes a single /ʃ/ sound."}, {"lv": 3, "q": "Identify the word that ends with the 'ck' sound.", "o": ["cat", "cap", "duck", "cut"], "a": 2, "p": "The word 'duck' ends with the 'ck' digraph sound."}, {"lv": 3, "q": "Which of these words has a long 'a' sound created by a magic 'e' at the end?", "o": ["cat", "cake", "cut", "cot"], "a": 1, "p": "The 'e' at the end of 'cake' makes the 'a' say its own name (long 'a' sound)."}, {"lv": 3, "q": "Choose the correct spelling for the word that names the number after nine.", "o": ["ten", "tin", "tan", "taen"], "a": 0, "p": "The number after nine is spelled 't-e-n' (ten)."}]}, {"id": "cam-eng-k1-1", "name": "Nouns and verbs", "desc": "Naming and doing words", "idx": 1, "soal": [{"lv": 1, "q": "Which word is a naming word (noun)?", "o": ["Run", "Apple", "Jump", "Fast"], "a": 1, "p": "'Apple' is a noun because it is the name of a thing. The others are action or descriptive words."}, {"lv": 1, "q": "What is the doing word (verb) in this list?", "o": ["Cat", "Book", "Sleep", "Hat"], "a": 2, "p": "'Sleep' is a verb because it is an action that you can do."}, {"lv": 1, "q": "Which word names a person?", "o": ["Ball", "Boy", "Sit", "Blue"], "a": 1, "p": "'Boy' is a noun that names a person."}, {"lv": 1, "q": "Identify the noun in this sentence: 'The sun is big.'", "o": ["The", "sun", "is", "big"], "a": 1, "p": "'Sun' is the noun because it is the name of something in the sky."}, {"lv": 2, "q": "Identify the verb in this sentence: 'The dog barks.'", "o": ["The", "dog", "barks", "None"], "a": 2, "p": "'Barks' is the action word (verb) telling us what the dog is doing."}, {"lv": 2, "q": "Which sentence has both a noun and a verb?", "o": ["Big red", "Birds fly", "Very fast", "On the mat"], "a": 1, "p": "'Birds' is a noun and 'fly' is a verb."}, {"lv": 2, "q": "Choose the noun that names a place.", "o": ["Jump", "School", "Eat", "Walk"], "a": 1, "p": "'School' is a noun that names a place where we learn."}, {"lv": 2, "q": "What is the doing word (verb) in the sentence: 'Mom cooks dinner.'?", "o": ["Mom", "cooks", "dinner", "The"], "a": 1, "p": "'Cooks' is the action word (verb) showing what Mom is doing."}, {"lv": 3, "q": "In the sentence 'The happy frog jumps high.', which word is the noun?", "o": ["happy", "frog", "jumps", "high"], "a": 1, "p": "'Frog' is the noun (naming word), while 'jumps' is the verb."}, {"lv": 3, "q": "Identify the verb in the sentence: 'Children play in the park.'", "o": ["Children", "play", "park", "the"], "a": 1, "p": "'Play' is the action word (verb) that tells us what the children are doing."}, {"lv": 3, "q": "Which option lists a noun first, then a verb?", "o": ["Jump, ball", "Fish, swim", "Run, fast", "Eat, apple"], "a": 1, "p": "'Fish' is a noun and 'swim' is a verb."}, {"lv": 3, "q": "Look at the sentence: 'The baby drinks milk.' Which words are the noun and the verb?", "o": ["baby (verb), drinks (noun)", "baby (noun), drinks (verb)", "milk (verb), drinks (noun)", "The (noun), baby (verb)"], "a": 1, "p": "'Baby' is the noun and 'drinks' is the verb."}]}, {"id": "cam-eng-k1-2", "name": "Simple sentences", "desc": "Capital letters and full stops", "idx": 2, "soal": [{"lv": 1, "q": "Which mark goes at the very beginning of a sentence?", "o": ["A full stop", "A capital letter", "A question mark", "A comma"], "a": 1, "p": "Every sentence begins with a capital letter."}, {"lv": 1, "q": "What do you need at the end of a telling sentence?", "o": ["A dot called a full stop", "A big letter", "A star", "A space"], "a": 0, "p": "A full stop is placed at the end of a statement."}, {"lv": 1, "q": "Look at this letter: 'B'. Is it a capital letter or a small letter?", "o": ["A small letter", "A capital letter", "A punctuation mark", "A number"], "a": 1, "p": "'B' is an upper-case or capital letter."}, {"lv": 1, "q": "Which of these is a small (lower-case) letter?", "o": ["A", "M", "s", "T"], "a": 2, "p": "'s' is a small letter, while the others are capital letters."}, {"lv": 2, "q": "Which word in this sentence needs a capital letter: 'birds can fly high.'?", "o": ["birds", "can", "fly", "high"], "a": 0, "p": "The first word 'birds' must start with a capital 'B'."}, {"lv": 2, "q": "What is wrong with this sentence: 'I like milk.'?", "o": ["Missing capital letter", "Missing full stop", "Nothing is wrong", "Wrong words used"], "a": 2, "p": "The sentence starts with a capital 'I' and ends with a full stop, so it is correct."}, {"lv": 2, "q": "If you write a new sentence, what should the very first letter look like?", "o": ["Small and low", "Big and tall (capital)", "Drawn as a picture", "It does not matter"], "a": 1, "p": "The first letter of any new sentence must always be a capital letter."}, {"lv": 3, "q": "Read this short text: 'cats sleep in the sun. they are warm.' How many capital letters are missing?", "o": ["One", "Two", "Three", "None"], "a": 1, "p": "Both sentences ('Cats...' and 'They...') need capital letters at the beginning, so two are missing."}, {"lv": 3, "q": "Identify the sentence that has a punctuation error.", "o": ["The frogs jump.", "fish swim fast.", "Cows eat grass.", "Birds sing loud."], "a": 1, "p": "'fish swim fast.' is missing a capital letter at the beginning ('Fish')."}, {"lv": 3, "q": "Look at these four items. Which one is a complete and correct sentence?", "o": ["running in the park", "The big tree is green.", "Playing with toys", "jump high"], "a": 1, "p": "'The big tree is green.' is a complete sentence: it has a subject (the big tree) and a verb (is), starts with a capital letter and ends with a full stop."}]}], "10": [{"id": "cam-eng-k10-0", "name": "Reading for explicit and implicit meaning", "desc": "IGCSE reading skills", "idx": 0, "soal": [{"lv": 1, "q": "Explicit information is ...", "o": ["stated directly in the text", "hinted at", "the reader's opinion", "never in the text"], "a": 0, "p": "It is clearly written."}, {"lv": 1, "q": "Implicit meaning must be ...", "o": ["inferred from clues", "copied word for word", "ignored", "found in the title only"], "a": 0, "p": "Read between the lines."}, {"lv": 1, "q": "\"The room was freezing.\" What is explicitly stated?", "o": ["The room was very cold.", "The heating was broken.", "It was winter.", "Someone left a window open."], "a": 0, "p": "Only the temperature is stated."}, {"lv": 1, "q": "Which question asks for implicit meaning?", "o": ["What does the writer suggest about the character's mood?", "What colour was the car?", "How many people were there?", "What is the title?"], "a": 0, "p": "Suggest means infer."}, {"lv": 2, "q": "\"She glanced at her phone again, then at the door.\" What is implied?", "o": ["She is waiting for someone or something.", "She is asleep.", "She hates phones.", "She is reading a book."], "a": 0, "p": "Repeated glances suggest anticipation."}, {"lv": 2, "q": "\"The garden, once full of roses, was now a tangle of weeds.\" What is implied?", "o": ["The garden has been neglected.", "Weeds are beautiful.", "Roses were just planted.", "It is spring."], "a": 0, "p": "Contrast shows change over time."}, {"lv": 2, "q": "Which phrase most strongly implies wealth?", "o": ["a sweeping marble staircase", "a small kitchen", "a broken chair", "a narrow path"], "a": 0, "p": "Marble suggests luxury."}, {"lv": 2, "q": "Why do exam questions ask you to use 'your own words'?", "o": ["to show understanding rather than copying", "to make answers longer", "to avoid the text", "to add opinions"], "a": 0, "p": "Paraphrasing shows comprehension."}, {"lv": 3, "q": "\"Mr Jones smiled, though his knuckles were white around the pen.\" What does this suggest?", "o": ["He is hiding tension or anger.", "He is relaxed.", "He is cold.", "He is writing a poem."], "a": 0, "p": "The physical detail contradicts the smile."}, {"lv": 3, "q": "\"Few visitors now came to the seaside town.\" What can be inferred about the town?", "o": ["It has declined in popularity.", "It is very busy.", "It is new.", "It has no sea."], "a": 0, "p": "Few visitors 'now' implies decline."}, {"lv": 3, "q": "A writer describes a character's 'thin coat, patched at the elbows'. What does this imply?", "o": ["The character may be poor.", "The character is rich.", "The character is a tailor.", "It is summer."], "a": 0, "p": "Patches suggest little money."}, {"lv": 3, "q": "Which answer best explains an implicit meaning?", "o": ["The word 'trapped' suggests the character feels unable to escape her situation.", "The text says trapped.", "Trapped is a verb.", "I like the word trapped."], "a": 0, "p": "It interprets the effect."}]}, {"id": "cam-eng-k10-1", "name": "Directed writing", "desc": "Letters, speeches, articles", "idx": 1, "soal": [{"lv": 1, "q": "Directed writing asks you to ...", "o": ["write for a specific audience, purpose and form using a given text", "write any story", "copy a passage", "draw a picture"], "a": 0, "p": "It responds to a task with given content."}, {"lv": 1, "q": "Which form starts with 'Dear Editor'?", "o": ["a letter", "a speech", "a diary", "a poem"], "a": 0, "p": "Letters have a salutation."}, {"lv": 1, "q": "A speech should ...", "o": ["address the audience directly", "have footnotes", "be written as a list only", "never use 'you'"], "a": 0, "p": "Speeches engage listeners."}, {"lv": 1, "q": "An article usually has ...", "o": ["a headline", "a salutation", "a signature only", "stage directions"], "a": 0, "p": "Articles are headed by titles."}, {"lv": 2, "q": "Which opening suits a speech to your school about recycling?", "o": ["Good morning, everyone. Today I want to talk about something we can all change.", "Dear Sir,", "Once upon a time...", "Yours sincerely,"], "a": 0, "p": "A greeting engages the audience."}, {"lv": 2, "q": "In directed writing, you should ...", "o": ["use and develop ideas from the reading passage", "ignore the passage", "copy the passage exactly", "write about something unrelated"], "a": 0, "p": "Marks reward using the text."}, {"lv": 2, "q": "Which tone suits a letter to a local council complaining about litter?", "o": ["formal and polite but firm", "slang and jokes", "rude", "poetic"], "a": 0, "p": "Formal tone suits officials."}, {"lv": 2, "q": "What is the main purpose of a magazine article reviewing a new phone?", "o": ["to inform and evaluate", "to tell a fairy tale", "to give a speech", "to write a diary"], "a": 0, "p": "Reviews inform and judge."}, {"lv": 3, "q": "Which is the most effective way to end a persuasive letter?", "o": ["a clear call to action and polite closing", "a new unrelated topic", "an insult", "a list of random facts"], "a": 0, "p": "Ends purposefully."}, {"lv": 3, "q": "The task: write a speech to Year 7s about starting secondary school. Which register fits?", "o": ["friendly, encouraging and clear", "highly academic and complex", "rude and dismissive", "legal and technical"], "a": 0, "p": "Suits a young audience."}, {"lv": 3, "q": "Why should you adapt (not copy) material from the passage?", "o": ["to show understanding and fit the new purpose and audience", "to make it shorter", "because copying is longer", "to avoid using ideas"], "a": 0, "p": "Adapting demonstrates skill."}, {"lv": 3, "q": "Which detail would best support an article arguing for longer school lunches?", "o": ["Students who eat calmly report better concentration in afternoon lessons.", "Lunch is at noon.", "I like sandwiches.", "The canteen is blue."], "a": 0, "p": "Relevant evidence supports the argument."}]}, {"id": "cam-eng-k10-2", "name": "Vocabulary in context", "desc": "Meaning of words in passages", "idx": 2, "soal": [{"lv": 1, "q": "\"The ancient castle stood on the hill.\" 'Ancient' means ...", "o": ["very old", "new", "tiny", "broken"], "a": 0, "p": "Ancient = very old."}, {"lv": 1, "q": "\"He was elated by the news.\" 'Elated' means ...", "o": ["very happy", "angry", "bored", "confused"], "a": 0, "p": "Elated = overjoyed."}, {"lv": 1, "q": "\"The path was treacherous after the rain.\" 'Treacherous' means ...", "o": ["dangerous", "beautiful", "dry", "short"], "a": 0, "p": "Hazardous."}, {"lv": 1, "q": "\"She gave a brief speech.\" 'Brief' means ...", "o": ["short", "long", "loud", "boring"], "a": 0, "p": "Brief = short."}, {"lv": 2, "q": "\"The scientist was meticulous in recording results.\" 'Meticulous' means ...", "o": ["very careful and precise", "careless", "fast", "lazy"], "a": 0, "p": "Attention to detail."}, {"lv": 2, "q": "\"The villagers were wary of strangers.\" 'Wary' means ...", "o": ["cautious", "friendly", "excited", "angry"], "a": 0, "p": "Wary = careful, suspicious."}, {"lv": 2, "q": "\"Supplies were scarce during the war.\" 'Scarce' means ...", "o": ["in short supply", "plentiful", "expensive", "fresh"], "a": 0, "p": "Scarce = few."}, {"lv": 2, "q": "\"His explanation was ambiguous.\" 'Ambiguous' means ...", "o": ["having more than one possible meaning", "very clear", "too long", "funny"], "a": 0, "p": "Unclear."}, {"lv": 3, "q": "\"The politician's speech was full of rhetoric but little substance.\" 'Substance' here means ...", "o": ["real meaning or content", "a chemical", "weight", "food"], "a": 0, "p": "Context shows meaning, not a material."}, {"lv": 3, "q": "\"She was reluctant to leave the warm fire.\" Which word is closest to 'reluctant'?", "o": ["unwilling", "eager", "ready", "pleased"], "a": 0, "p": "Reluctant = not wanting to."}, {"lv": 3, "q": "\"The lecture was so tedious that half the audience dozed off.\" 'Tedious' means ...", "o": ["boring and long", "exciting", "short", "loud"], "a": 0, "p": "Dozing off is the clue."}, {"lv": 3, "q": "\"The evidence was compelling.\" In this context 'compelling' means ...", "o": ["convincing", "forcing physically", "weak", "confusing"], "a": 0, "p": "Persuasive evidence."}]}], "11": [{"id": "cam-eng-k11-0", "name": "Descriptive and narrative composition", "desc": "Structure and technique", "idx": 0, "soal": [{"lv": 1, "q": "Descriptive writing focuses mainly on ...", "o": ["creating vivid images of a place, person or moment", "giving instructions", "arguing a point", "listing statistics"], "a": 0, "p": "It uses the senses."}, {"lv": 1, "q": "Using the five senses helps writers ...", "o": ["make descriptions more vivid", "shorten the text", "give facts", "argue"], "a": 0, "p": "Sight, sound, smell, touch and taste."}, {"lv": 1, "q": "A narrative must include ...", "o": ["a sequence of events", "a bibliography", "a list of instructions", "a table"], "a": 0, "p": "Narratives tell stories."}, {"lv": 1, "q": "Which opening is most engaging?", "o": ["The scream echoed through the empty corridor.", "This is my story.", "I woke up.", "Hello reader."], "a": 0, "p": "It creates intrigue."}, {"lv": 2, "q": "Which sentence uses sensory detail best?", "o": ["The salty wind stung my cheeks as gulls shrieked overhead.", "It was windy.", "The beach was nice.", "There were birds."], "a": 0, "p": "Touch, smell and sound."}, {"lv": 2, "q": "In descriptive writing, plot ...", "o": ["is less important than atmosphere and detail", "must be very complex", "must include dialogue", "is forbidden"], "a": 0, "p": "Description builds atmosphere rather than action."}, {"lv": 2, "q": "Which technique creates a circular structure?", "o": ["ending with an image or line that echoes the opening", "ending suddenly", "adding a new character at the end", "listing facts"], "a": 0, "p": "This gives a sense of completion."}, {"lv": 2, "q": "Varying sentence length helps to ...", "o": ["control pace and effect", "confuse readers", "save time", "remove description"], "a": 0, "p": "Short sentences add impact; long ones build detail."}, {"lv": 3, "q": "What is the effect of zooming from a wide view of a market to a single coin in a beggar's hand?", "o": ["It focuses the reader's attention and emotion on a significant detail.", "It confuses the reader.", "It makes the story longer.", "It has no effect."], "a": 0, "p": "A cinematic focus technique."}, {"lv": 3, "q": "Which is a cliché best avoided?", "o": ["It was a dark and stormy night.", "Rain needled the tin roofs.", "The fog swallowed the streetlights.", "Thunder rolled like distant drums."], "a": 0, "p": "It is overused."}, {"lv": 3, "q": "Why might a narrative use a limited first-person narrator?", "o": ["to create mystery since readers know only what the narrator knows", "to reveal every character's thoughts", "to avoid any emotion", "to list facts"], "a": 0, "p": "Limited knowledge builds suspense."}, {"lv": 3, "q": "Which ending is most effective for a narrative about losing a pet?", "o": ["She folded the collar carefully and placed it in the drawer, beside her childhood.", "The end.", "And then I woke up and it was all a dream.", "Pets are nice."], "a": 0, "p": "A subtle, resonant image."}]}, {"id": "cam-eng-k11-1", "name": "Analysing writers' effects", "desc": "Language and its impact", "idx": 1, "soal": [{"lv": 1, "q": "When analysing a writer's effects, you should comment on ...", "o": ["word choices and their impact on the reader", "the number of pages", "the price of the book", "the font"], "a": 0, "p": "Focus on language and its effects."}, {"lv": 1, "q": "Connotations are ...", "o": ["the associations a word carries", "dictionary definitions only", "spelling rules", "page numbers"], "a": 0, "p": "For example, 'home' suggests comfort."}, {"lv": 1, "q": "\"The sky bled red at sunset.\" 'Bled' suggests ...", "o": ["violence or pain", "happiness", "calm", "cold"], "a": 0, "p": "Blood has strong associations."}, {"lv": 1, "q": "Which word has a positive connotation?", "o": ["slim", "skinny", "bony", "scrawny"], "a": 0, "p": "Slim sounds attractive."}, {"lv": 2, "q": "\"The waves clawed at the shore.\" What is the effect of 'clawed'?", "o": ["presents the sea as aggressive, like a predator", "shows the sea is calm", "suggests the beach is clean", "shows sunshine"], "a": 0, "p": "An animal metaphor."}, {"lv": 2, "q": "\"The streets were silent, empty, dead.\" What is the effect of the list?", "o": ["builds a sense of desolation", "creates excitement", "adds humour", "gives directions"], "a": 0, "p": "Escalating adjectives."}, {"lv": 2, "q": "\"Crowds swarmed the stalls.\" 'Swarmed' suggests ...", "o": ["a large, busy, slightly overwhelming crowd", "a few calm people", "nobody", "sleeping people"], "a": 0, "p": "Like insects."}, {"lv": 2, "q": "Which is the best way to structure an analysis point?", "o": ["quote, identify the effect, explain how it affects the reader", "summarise the plot", "give your opinion only", "copy the passage"], "a": 0, "p": "Evidence plus explanation."}, {"lv": 3, "q": "\"The house loomed over us, its windows like hollow eyes.\" Explain the combined effect.", "o": ["Personification and simile make the house seem threatening and alive.", "It shows the house is small.", "It shows the house is cheerful.", "It describes the weather."], "a": 0, "p": "Looming plus eyes create menace."}, {"lv": 3, "q": "\"Her words were ice.\" How does the metaphor shape our view of the character?", "o": ["She seems cold and unfriendly.", "She is cold physically.", "She is warm-hearted.", "She is a scientist."], "a": 0, "p": "Ice equals emotional coldness."}, {"lv": 3, "q": "Why might a writer suddenly use a one-word paragraph: 'Gone.'?", "o": ["for shock and emphasis", "to save space", "by mistake", "to add a list"], "a": 0, "p": "Isolation gives impact."}, {"lv": 3, "q": "Which response shows the highest level of analysis?", "o": ["The verb 'devoured' suggests the fire's insatiable hunger, making it seem a living predator and heightening the reader's fear.", "The fire was big.", "The writer uses a verb.", "I think the fire is scary."], "a": 0, "p": "Precise, explores connotations and effect."}]}, {"id": "cam-eng-k11-2", "name": "Summary writing", "desc": "Concise, own words", "idx": 2, "soal": [{"lv": 1, "q": "A summary in IGCSE should be written in ...", "o": ["your own words where possible, in continuous prose", "bullet points of quotations", "poetry", "a table"], "a": 0, "p": "Fluent, concise writing."}, {"lv": 1, "q": "What must a summary avoid?", "o": ["adding your own opinions", "key points", "concise language", "accuracy"], "a": 0, "p": "Stay objective."}, {"lv": 1, "q": "Before writing a summary, you should ...", "o": ["identify the relevant points for the task", "count the commas", "copy the whole passage", "write the title only"], "a": 0, "p": "Plan first."}, {"lv": 1, "q": "Concise means ...", "o": ["expressing ideas clearly in few words", "using as many words as possible", "being vague", "using quotations"], "a": 0, "p": "Brevity and clarity."}, {"lv": 2, "q": "Which sentence is a good paraphrase of: 'The town's economy relied heavily upon fishing'?", "o": ["Fishing was the town's main source of income.", "The town relied heavily upon fishing for the economy.", "The town liked fish.", "Fish lived near the town."], "a": 0, "p": "The meaning is kept in new words."}, {"lv": 2, "q": "How should repeated examples be handled in a summary?", "o": ["group them into a general point", "include every one", "quote them all", "ignore the main point"], "a": 0, "p": "Generalise examples."}, {"lv": 2, "q": "Which is the best way to stay within a word limit?", "o": ["remove repetition and minor detail", "use bigger font", "add more adjectives", "include quotations"], "a": 0, "p": "Cut unnecessary content."}, {"lv": 2, "q": "A summary question asks only for the 'advantages of city life'. You should ...", "o": ["include only advantages", "include disadvantages too", "describe your own city", "write a story"], "a": 0, "p": "Answer the specific focus."}, {"lv": 3, "q": "Which is the most concise version?", "o": ["Many people moved away because jobs disappeared.", "A great number of the people who lived there decided to move away due to the fact that jobs were disappearing.", "People, many of them, moved, because jobs, which were disappearing, went.", "Jobs disappearing caused a moving-away situation for people."], "a": 0, "p": "Fewest words, clear meaning."}, {"lv": 3, "q": "Why might copying long phrases lose marks?", "o": ["It shows less understanding and reduces concision.", "It is always incorrect grammar.", "It makes the summary too short.", "Examiners cannot read it."], "a": 0, "p": "Own words are rewarded."}, {"lv": 3, "q": "Which point would NOT belong in a summary of 'reasons coral reefs are declining'?", "o": ["Reefs are popular with tourists who take photographs.", "Rising sea temperatures cause bleaching.", "Pollution damages coral.", "Overfishing disrupts ecosystems."], "a": 0, "p": "It is not a reason for decline."}, {"lv": 3, "q": "What is the best order for summary points?", "o": ["a logical order that groups related ideas", "random order", "alphabetical order", "the reverse order of the text"], "a": 0, "p": "Coherence matters."}]}], "12": [{"id": "cam-eng-k12-0", "name": "Discursive essays", "desc": "Balanced argument", "idx": 0, "soal": [{"lv": 1, "q": "A discursive essay ...", "o": ["explores different perspectives on an issue", "tells a fictional story", "is a set of instructions", "is a poem"], "a": 0, "p": "It weighs views."}, {"lv": 1, "q": "A balanced argument presents ...", "o": ["multiple sides fairly", "only one side", "no evidence", "only jokes"], "a": 0, "p": "Balance is key."}, {"lv": 1, "q": "Which connective signals an opposing view?", "o": ["Conversely", "Furthermore", "Additionally", "Similarly"], "a": 0, "p": "Conversely introduces contrast."}, {"lv": 1, "q": "The conclusion of a discursive essay should ...", "o": ["weigh the arguments and reach a reasoned judgement", "introduce a new topic", "repeat the introduction word for word", "end with a joke only"], "a": 0, "p": "A reasoned stance."}, {"lv": 2, "q": "Which is a well-qualified claim?", "o": ["Social media can, in some contexts, harm adolescent wellbeing.", "Social media ruins everyone.", "Social media is perfect.", "Nobody uses social media."], "a": 0, "p": "Hedged and precise."}, {"lv": 2, "q": "Why use counter-arguments in discursive writing?", "o": ["to show critical thinking and balance", "to confuse readers", "to fill space", "to avoid a conclusion"], "a": 0, "p": "Shows nuance."}, {"lv": 2, "q": "Which essay question suits discursive writing?", "o": ["To what extent should governments regulate AI?", "Describe your bedroom.", "Write a poem about rain.", "List your favourite foods."], "a": 0, "p": "It is open to debate."}, {"lv": 2, "q": "A topic sentence in a discursive essay should ...", "o": ["state the paragraph's argument clearly", "be a question only", "be a quotation", "repeat the title"], "a": 0, "p": "It guides the reader."}, {"lv": 3, "q": "Which sentence best evaluates evidence?", "o": ["While the survey suggests a link, its small sample limits how far it can be generalised.", "The survey proves everything.", "Surveys are boring.", "I agree with the survey."], "a": 0, "p": "It is critical and nuanced."}, {"lv": 3, "q": "What makes a discursive essay sophisticated?", "o": ["nuanced judgement acknowledging complexity", "extreme one-sided claims", "no paragraphs", "slang"], "a": 0, "p": "Complexity is valued."}, {"lv": 3, "q": "Which is the best introduction?", "o": ["Few issues divide opinion as sharply as whether wealthy nations owe climate reparations; this essay weighs moral, economic and practical arguments.", "This essay is about climate.", "Climate change is bad.", "Hello, today I will write."], "a": 0, "p": "Engaging, frames the issue and signals the approach."}, {"lv": 3, "q": "Which is a 'straw man' error?", "o": ["misrepresenting an opponent's view to make it easier to attack", "citing statistics", "using a counter-argument fairly", "qualifying claims"], "a": 0, "p": "Distorting an argument."}]}, {"id": "cam-eng-k12-1", "name": "Language and context", "desc": "Audience, purpose, form", "idx": 1, "soal": [{"lv": 1, "q": "Context refers to ...", "o": ["the circumstances in which a text is produced and received", "the font size", "the length", "the title"], "a": 0, "p": "Audience, purpose and setting."}, {"lv": 1, "q": "Audience means ...", "o": ["the intended readers or listeners", "the writer", "the publisher", "the printer"], "a": 0, "p": "Who the text is for."}, {"lv": 1, "q": "Purpose refers to ...", "o": ["what the text aims to achieve", "how long it is", "its colour", "its price"], "a": 0, "p": "To inform, persuade, entertain and so on."}, {"lv": 1, "q": "Form refers to ...", "o": ["the type of text, e.g. a blog, speech or letter", "its spelling", "its paper", "its title"], "a": 0, "p": "Genre or format."}, {"lv": 2, "q": "A politician's speech uses 'we' repeatedly. The likely effect is ...", "o": ["to create unity with the audience", "to exclude the audience", "to confuse", "to sound informal only"], "a": 0, "p": "Inclusive pronouns."}, {"lv": 2, "q": "Text messages often use abbreviations because of ...", "o": ["informal context and speed", "legal rules", "formal audience", "academic purpose"], "a": 0, "p": "Context shapes language."}, {"lv": 2, "q": "A scientific report avoids 'I' mainly to ...", "o": ["sound objective and impersonal", "be friendly", "entertain", "rhyme"], "a": 0, "p": "Formal convention."}, {"lv": 2, "q": "Which feature suits a children's TV advert?", "o": ["simple language, repetition and exclamations", "complex legal terms", "footnotes", "passive voice"], "a": 0, "p": "Matches the audience."}, {"lv": 3, "q": "How might a 19th-century letter differ from a modern email?", "o": ["more formal register, longer sentences and elaborate courtesy phrases", "more emojis", "shorter and casual", "no greeting"], "a": 0, "p": "Historical context affects style."}, {"lv": 3, "q": "A charity advert uses second person and imperatives. Why?", "o": ["to address readers directly and prompt action", "to tell a story", "to inform neutrally", "to sound academic"], "a": 0, "p": "Persuasive purpose."}, {"lv": 3, "q": "Why might a writer deliberately use non-standard English in a novel's dialogue?", "o": ["to create authentic voices and convey identity", "because of errors", "to save space", "to sound formal"], "a": 0, "p": "It characterises speakers."}, {"lv": 3, "q": "Which best explains how context affects meaning?", "o": ["The same word can carry different connotations depending on audience, era and purpose.", "Words have only one meaning.", "Context never matters.", "Only spelling matters."], "a": 0, "p": "Meaning is contextual."}]}, {"id": "cam-eng-k12-2", "name": "Critical reading of arguments", "desc": "Bias, assumptions, evaluation", "idx": 2, "soal": [{"lv": 1, "q": "An assumption in an argument is ...", "o": ["an unstated belief the argument relies on", "a proven fact", "the conclusion", "a statistic"], "a": 0, "p": "It is often hidden."}, {"lv": 1, "q": "Bias means ...", "o": ["a one-sided or unfair perspective", "balanced reporting", "a verified fact", "a footnote"], "a": 0, "p": "Partiality."}, {"lv": 1, "q": "A credible source is usually ...", "o": ["authoritative, transparent and evidence-based", "anonymous and unverified", "a rumour", "a cartoon"], "a": 0, "p": "Reliability matters."}, {"lv": 1, "q": "To evaluate an argument means ...", "o": ["to judge its strengths and weaknesses", "to copy it", "to summarise only", "to ignore it"], "a": 0, "p": "Critical assessment."}, {"lv": 2, "q": "\"Crime has risen since the new mayor took office, so the mayor caused it.\" This is ...", "o": ["a false cause (post hoc) fallacy", "a valid argument", "an analogy", "a statistic"], "a": 0, "p": "Correlation is not causation."}, {"lv": 2, "q": "Which evidence is weakest?", "o": ["a single anecdote from one person", "a large peer-reviewed study", "official statistics", "a meta-analysis"], "a": 0, "p": "Anecdotes are not representative."}, {"lv": 2, "q": "\"Either we ban cars or the planet is doomed.\" This is ...", "o": ["a false dilemma", "a balanced view", "an expert opinion", "a statistic"], "a": 0, "p": "It ignores other options."}, {"lv": 2, "q": "Loaded language is used to ...", "o": ["influence emotions rather than reason", "give neutral facts", "define terms", "cite sources"], "a": 0, "p": "It carries strong connotations."}, {"lv": 3, "q": "An article funded by a sugar company claims sugar is harmless. What should a critical reader consider?", "o": ["possible conflict of interest affecting objectivity", "nothing", "that funding guarantees truth", "the font used"], "a": 0, "p": "Funding can bias findings."}, {"lv": 3, "q": "\"Most successful people wake up early; therefore waking early makes you successful.\" Identify the flaw.", "o": ["it confuses correlation with causation", "it uses too much evidence", "it is a valid deduction", "it has no conclusion"], "a": 0, "p": "Other factors may explain success."}, {"lv": 3, "q": "Which question best tests an argument's reliability?", "o": ["What evidence supports this, and is it representative?", "Is the writer famous?", "Is the text long?", "Does it have pictures?"], "a": 0, "p": "Focus on evidence."}, {"lv": 3, "q": "A writer cites 'experts say' without naming them. Why is this weak?", "o": ["the claim cannot be verified", "it is too specific", "experts are always wrong", "it is too formal"], "a": 0, "p": "Vague appeals to authority."}]}], "2": [{"id": "cam-eng-k2-0", "name": "Plurals and spelling patterns", "desc": "-s, -es, common patterns", "idx": 0, "soal": [{"lv": 1, "q": "What is the plural of \"cat\"?", "o": ["cates", "cats", "caties", "cat"], "a": 1, "p": "Most nouns add -s."}, {"lv": 1, "q": "What is the plural of \"box\"?", "o": ["boxs", "boxes", "boxies", "box"], "a": 1, "p": "Nouns ending in -x add -es."}, {"lv": 1, "q": "What is the plural of \"bus\"?", "o": ["buss", "buses", "busies", "bus"], "a": 1, "p": "Nouns ending in -s add -es."}, {"lv": 1, "q": "What is the plural of \"dog\"?", "o": ["dogs", "doges", "dogies", "doggs"], "a": 0, "p": "Add -s."}, {"lv": 2, "q": "What is the plural of \"baby\"?", "o": ["babys", "babyes", "babies", "babis"], "a": 2, "p": "Consonant + y: change y to i and add -es."}, {"lv": 2, "q": "What is the plural of \"dish\"?", "o": ["dishs", "dishes", "dishies", "dish"], "a": 1, "p": "Nouns ending in -sh add -es."}, {"lv": 2, "q": "Which word is spelled correctly?", "o": ["churchs", "churches", "churchies", "churchis"], "a": 1, "p": "Nouns ending in -ch add -es."}, {"lv": 2, "q": "What is the plural of \"toy\"?", "o": ["toies", "toys", "toyes", "toy"], "a": 1, "p": "Vowel + y: just add -s."}, {"lv": 3, "q": "What is the plural of \"child\"?", "o": ["childs", "childes", "children", "childrens"], "a": 2, "p": "\"Child\" is irregular: children."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["I saw three mouses.", "I saw three mice.", "I saw three mices.", "I saw three mouse."], "a": 1, "p": "\"Mouse\" is irregular: mice."}, {"lv": 3, "q": "Which word follows the same spelling pattern as \"lunch → lunches\"?", "o": ["bench → benches", "car → cars", "pony → ponies", "foot → feet"], "a": 0, "p": "Both end in -ch and add -es."}, {"lv": 3, "q": "Choose the correct plural for \"tooth\".", "o": ["tooths", "teeth", "toothes", "teeths"], "a": 1, "p": "\"Tooth\" is irregular: teeth."}]}, {"id": "cam-eng-k2-1", "name": "Adjectives", "desc": "Describing words", "idx": 1, "soal": [{"lv": 1, "q": "Which word is an adjective (describing word)?", "o": ["run", "happy", "table", "quickly"], "a": 1, "p": "\"Happy\" describes a noun."}, {"lv": 1, "q": "Find the adjective: \"The red ball bounced.\"", "o": ["The", "red", "ball", "bounced"], "a": 1, "p": "\"Red\" describes the ball."}, {"lv": 1, "q": "Which adjective describes something that is not big?", "o": ["tall", "huge", "small", "wide"], "a": 2, "p": "\"Small\" is the opposite of big."}, {"lv": 1, "q": "Find the adjective: \"I have a fluffy kitten.\"", "o": ["I", "have", "fluffy", "kitten"], "a": 2, "p": "\"Fluffy\" describes the kitten."}, {"lv": 2, "q": "Choose the best adjective: \"The ___ elephant walked slowly.\"", "o": ["enormous", "quickly", "jump", "sing"], "a": 0, "p": "\"Enormous\" is an adjective describing the elephant."}, {"lv": 2, "q": "Which sentence has TWO adjectives?", "o": ["The dog barked.", "The small brown dog barked.", "The dog ran fast.", "Dogs bark."], "a": 1, "p": "\"Small\" and \"brown\" both describe the dog."}, {"lv": 2, "q": "What is the opposite of \"hot\"?", "o": ["warm", "cold", "sunny", "wet"], "a": 1, "p": "Hot and cold are opposites."}, {"lv": 2, "q": "Which adjective best describes a lemon's taste?", "o": ["sweet", "sour", "loud", "soft"], "a": 1, "p": "Lemons taste sour."}, {"lv": 3, "q": "Which sentence uses an adjective correctly?", "o": ["She is a quickly girl.", "She is a clever girl.", "She is a run girl.", "She is a girl slowly."], "a": 1, "p": "\"Clever\" is an adjective; \"quickly\" and \"slowly\" are adverbs."}, {"lv": 3, "q": "Choose the best adjective to make the sentence more exciting: \"We saw a ___ storm.\"", "o": ["nice", "terrible", "good", "okay"], "a": 1, "p": "\"Terrible\" gives a strong, vivid picture."}, {"lv": 3, "q": "Which word is NOT an adjective?", "o": ["shiny", "jump", "tiny", "noisy"], "a": 1, "p": "\"Jump\" is a verb (action word)."}, {"lv": 3, "q": "\"The soup was hot and tasty.\" How many adjectives are there?", "o": ["1", "2", "3", "0"], "a": 1, "p": "\"Hot\" and \"tasty\" are adjectives."}]}, {"id": "cam-eng-k2-2", "name": "Reading short stories", "desc": "Characters and events", "idx": 2, "soal": [{"lv": 1, "q": "Read: \"Tom has a red kite. He flies it in the park.\" What colour is Tom's kite?", "o": ["blue", "red", "green", "yellow"], "a": 1, "p": "The text says Tom has a red kite."}, {"lv": 1, "q": "Read: \"Tom has a red kite. He flies it in the park.\" Where does Tom fly his kite?", "o": ["at school", "in the park", "at the beach", "in his house"], "a": 1, "p": "He flies it in the park."}, {"lv": 1, "q": "The people or animals in a story are called the ...", "o": ["setting", "characters", "title", "ending"], "a": 1, "p": "Characters are who the story is about."}, {"lv": 1, "q": "Where a story happens is called the ...", "o": ["setting", "character", "author", "page"], "a": 0, "p": "The setting is the place and time of a story."}, {"lv": 2, "q": "Read: \"Mia lost her teddy. She looked under her bed. Then she looked in the garden. At last, she found it in the car.\" Where did Mia find her teddy?", "o": ["under the bed", "in the garden", "in the car", "at school"], "a": 2, "p": "\"At last, she found it in the car.\""}, {"lv": 2, "q": "In the story above, where did Mia look FIRST?", "o": ["in the car", "under her bed", "in the garden", "in the kitchen"], "a": 1, "p": "She looked under her bed first."}, {"lv": 2, "q": "Read: \"Sam's eyes filled with tears when his ice cream fell on the ground.\" How did Sam feel?", "o": ["happy", "sad", "angry", "excited"], "a": 1, "p": "Eyes filled with tears show he was sad."}, {"lv": 2, "q": "Which is the BEGINNING of a story?", "o": ["And they all lived happily ever after.", "Once upon a time, there was a little fox.", "In the end, the fox went home.", "The fox said goodbye."], "a": 1, "p": "\"Once upon a time\" is a typical story opening."}, {"lv": 3, "q": "Read: \"The sky turned dark. Big drops began to fall. Lina opened her umbrella.\" What was happening?", "o": ["It was snowing.", "It was starting to rain.", "It was a sunny day.", "It was night-time."], "a": 1, "p": "Dark sky, falling drops and an umbrella all point to rain."}, {"lv": 3, "q": "Read: \"Ben shared his lunch with Ali, who had forgotten his.\" What kind of person is Ben?", "o": ["kind", "lazy", "rude", "scared"], "a": 0, "p": "Sharing food with someone in need shows kindness."}, {"lv": 3, "q": "What usually happens in the middle of a story?", "o": ["the characters are introduced only", "a problem happens", "the story ends", "the title is written"], "a": 1, "p": "The middle usually has a problem or event."}, {"lv": 3, "q": "Read: \"Anna practised the piano every day. At the concert, everyone clapped loudly for her.\" Why did everyone clap?", "o": ["She played well because she practised.", "She was late.", "She forgot the music.", "She did not play."], "a": 0, "p": "Her daily practice helped her play well, so people clapped."}]}], "3": [{"id": "cam-eng-k3-0", "name": "Punctuation", "desc": "Capitals, commas, question and exclamation marks", "idx": 0, "soal": [{"lv": 1, "q": "Which sentence is punctuated correctly?", "o": ["where is my bag.", "Where is my bag?", "where is my bag!", "Where is my bag,"], "a": 1, "p": "Start with a capital letter and end a question with a question mark."}, {"lv": 1, "q": "Which word needs a capital letter?", "o": ["dog", "london", "table", "happy"], "a": 1, "p": "Names of places are proper nouns: London."}, {"lv": 1, "q": "Which punctuation mark ends a sentence that shows strong feeling?", "o": ["full stop", "comma", "exclamation mark", "question mark"], "a": 2, "p": "An exclamation mark shows strong feeling: Watch out!"}, {"lv": 1, "q": "Which sentence ends correctly?", "o": ["I like apples?", "I like apples.", "I like apples,", "I like apples"], "a": 1, "p": "A statement ends with a full stop."}, {"lv": 2, "q": "Where should the commas go? \"I bought eggs milk bread and jam.\"", "o": ["I bought eggs, milk, bread and jam.", "I, bought eggs milk bread and jam.", "I bought, eggs, milk, bread, and, jam.", "I bought eggs milk, bread and, jam."], "a": 0, "p": "Commas separate items in a list."}, {"lv": 2, "q": "Which words in this sentence need capital letters? \"on monday, sam went to paris.\"", "o": ["only On", "On, Monday, Sam, Paris", "Monday and Paris only", "Sam only"], "a": 1, "p": "The first word of a sentence, days, names and places all need capital letters."}, {"lv": 2, "q": "Which sentence is a question?", "o": ["What a lovely day!", "Can you help me?", "Please sit down.", "I am hungry."], "a": 1, "p": "It asks something and ends with a question mark."}, {"lv": 2, "q": "Choose the correct punctuation: \"Stop ___ The road is busy.\"", "o": [".", "!", ",", "?"], "a": 1, "p": "It is a warning, so use an exclamation mark."}, {"lv": 3, "q": "Which sentence is correctly punctuated?", "o": ["My friends Ali, Bea and Cara came to my party.", "My friends, Ali Bea and Cara came to my party", "my friends Ali, Bea, and, Cara came to my party.", "My friends Ali Bea and Cara came, to my party?"], "a": 0, "p": "Capital letters, commas in the list, and a full stop at the end."}, {"lv": 3, "q": "How many capital letters are needed? \"in july, maya and i visited cairo.\"", "o": ["3", "4", "5", "2"], "a": 2, "p": "In, July, Maya, I, Cairo = 5 capitals."}, {"lv": 3, "q": "Which sentence should end with a question mark?", "o": ["I wonder if it will rain", "Will it rain tomorrow", "It might rain", "Tell me about the rain"], "a": 1, "p": "\"Will it rain tomorrow\" is a direct question."}, {"lv": 3, "q": "Why do we use commas in lists?", "o": ["to separate the items clearly", "to end a sentence", "to show a question", "to show strong feeling"], "a": 0, "p": "Commas separate items so the list is easy to read."}]}, {"id": "cam-eng-k3-1", "name": "Past tense verbs", "desc": "Regular and irregular", "idx": 1, "soal": [{"lv": 1, "q": "What is the past tense of \"walk\"?", "o": ["walking", "walked", "walks", "walken"], "a": 1, "p": "Regular verbs add -ed."}, {"lv": 1, "q": "What is the past tense of \"play\"?", "o": ["plaied", "played", "playd", "plays"], "a": 1, "p": "Add -ed: played."}, {"lv": 1, "q": "What is the past tense of \"go\"?", "o": ["goed", "went", "gone", "going"], "a": 1, "p": "\"Go\" is irregular: went."}, {"lv": 1, "q": "Yesterday, I ___ my homework.", "o": ["do", "did", "doing", "does"], "a": 1, "p": "The past tense of \"do\" is \"did\"."}, {"lv": 2, "q": "What is the past tense of \"hop\"?", "o": ["hoped", "hopped", "hopd", "hoping"], "a": 1, "p": "Short vowel + single consonant: double it, then add -ed."}, {"lv": 2, "q": "What is the past tense of \"carry\"?", "o": ["carryed", "carried", "carryd", "carries"], "a": 1, "p": "Consonant + y: change y to i, then add -ed."}, {"lv": 2, "q": "Last week, we ___ a film at the cinema.", "o": ["see", "seen", "saw", "seeing"], "a": 2, "p": "The past tense of \"see\" is \"saw\"."}, {"lv": 2, "q": "Which verb is in the past tense?", "o": ["eat", "ate", "eating", "eats"], "a": 1, "p": "\"Ate\" is the past tense of \"eat\"."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["She buyed a new dress.", "She bought a new dress.", "She buy a new dress yesterday.", "She buying a new dress."], "a": 1, "p": "\"Buy\" is irregular: bought."}, {"lv": 3, "q": "Change to the past: \"Tom runs to school and catches the bus.\"", "o": ["Tom ran to school and caught the bus.", "Tom runned to school and catched the bus.", "Tom ran to school and catches the bus.", "Tom running to school and caught the bus."], "a": 0, "p": "run → ran; catch → caught."}, {"lv": 3, "q": "Which group contains only irregular past tense verbs?", "o": ["jumped, played, kicked", "swam, wrote, flew", "cooked, sang, walked", "danced, talked, ran"], "a": 1, "p": "swim → swam, write → wrote, fly → flew."}, {"lv": 3, "q": "\"The dog ___ the ball and ___ back.\" Choose the correct pair.", "o": ["catched, comed", "caught, came", "caught, comed", "catch, came"], "a": 1, "p": "catch → caught; come → came."}]}, {"id": "cam-eng-k3-2", "name": "Understanding fiction", "desc": "Setting, character, plot", "idx": 2, "soal": [{"lv": 1, "q": "Fiction is a story that is ...", "o": ["true facts", "made up (imagined)", "a list of instructions", "a dictionary"], "a": 1, "p": "Fiction comes from the writer's imagination."}, {"lv": 1, "q": "The plot of a story is ...", "o": ["where it happens", "what happens in it", "who wrote it", "the title"], "a": 1, "p": "The plot is the series of events."}, {"lv": 1, "q": "The main character is ...", "o": ["the most important person or animal in the story", "the place in the story", "the last word", "the author"], "a": 0, "p": "The story is mainly about the main character."}, {"lv": 1, "q": "Which is a setting?", "o": ["a dark forest", "a brave knight", "a happy ending", "a big problem"], "a": 0, "p": "A setting is where and when a story happens."}, {"lv": 2, "q": "Read: \"Zara crept into the old house. The floor creaked. A cold wind whistled through the broken window.\" What kind of mood is created?", "o": ["funny", "spooky", "happy", "boring"], "a": 1, "p": "Creaking floors and cold wind create a spooky mood."}, {"lv": 2, "q": "In a story, a problem is usually solved in the ...", "o": ["beginning", "middle", "ending", "title"], "a": 2, "p": "Stories usually resolve the problem at the end."}, {"lv": 2, "q": "Read: \"Leo always helped his neighbours carry their shopping.\" What does this tell us about Leo?", "o": ["He is helpful.", "He is lazy.", "He is rude.", "He is greedy."], "a": 0, "p": "His actions show he is helpful."}, {"lv": 2, "q": "Which sentence is from a fairy tale?", "o": ["Mix the flour and eggs.", "Once upon a time, a princess lived in a tall tower.", "The Earth goes around the Sun.", "Turn left at the shop."], "a": 1, "p": "Fairy tales often begin with \"Once upon a time\"."}, {"lv": 3, "q": "Read: \"Max stared at the broken vase. His heart pounded. 'Mum will be home soon,' he whispered.\" How does Max feel?", "o": ["excited", "worried", "bored", "proud"], "a": 1, "p": "A pounding heart and whispering show worry about being in trouble."}, {"lv": 3, "q": "Why might an author describe a setting in detail?", "o": ["to help readers picture the place and feel the mood", "to make the story shorter", "to tell readers the answers", "to list facts"], "a": 0, "p": "Detailed settings help readers imagine the story."}, {"lv": 3, "q": "Read: \"The fox tricked the crow into dropping its cheese.\" What word best describes the fox?", "o": ["honest", "clever but sly", "shy", "silly"], "a": 1, "p": "Tricking someone shows the fox is cunning (sly)."}, {"lv": 3, "q": "Which event is MOST likely the climax (most exciting point) of a story?", "o": ["The children wake up.", "The dragon attacks the village and the hero must fight it.", "They eat breakfast.", "They walk to school."], "a": 1, "p": "The climax is the most exciting turning point."}]}], "4": [{"id": "cam-eng-k4-0", "name": "Conjunctions and complex sentences", "desc": "and, but, because, although", "idx": 0, "soal": [{"lv": 1, "q": "Which word is a conjunction?", "o": ["and", "dog", "happy", "run"], "a": 0, "p": "Conjunctions join words or clauses."}, {"lv": 1, "q": "\"I wanted to play outside ___ it was raining.\" Choose the conjunction.", "o": ["and", "but", "so", "or"], "a": 1, "p": "\"But\" shows contrast."}, {"lv": 1, "q": "\"I was hungry, ___ I ate a sandwich.\"", "o": ["so", "but", "or", "although"], "a": 0, "p": "\"So\" shows a result."}, {"lv": 1, "q": "\"Would you like tea ___ juice?\"", "o": ["but", "or", "because", "so"], "a": 1, "p": "\"Or\" gives a choice."}, {"lv": 2, "q": "\"We stayed inside ___ it was very cold.\"", "o": ["because", "but", "or", "although"], "a": 0, "p": "\"Because\" gives a reason."}, {"lv": 2, "q": "\"___ it was late, the children kept reading.\"", "o": ["Because", "Although", "So", "And"], "a": 1, "p": "\"Although\" shows a contrast between two ideas."}, {"lv": 2, "q": "Which sentence is a complex sentence?", "o": ["I ran.", "I ran and jumped.", "When the bell rang, the children ran outside.", "The children ran."], "a": 2, "p": "It has a subordinate clause (When the bell rang) and a main clause."}, {"lv": 2, "q": "Which conjunction shows time?", "o": ["because", "when", "but", "or"], "a": 1, "p": "\"When\" tells us about time."}, {"lv": 3, "q": "Join the sentences: \"The road was icy. The bus drove slowly.\"", "o": ["The road was icy, but the bus drove slowly.", "Because the road was icy, the bus drove slowly.", "The road was icy or the bus drove slowly.", "Although the road was icy, the bus drove slowly."], "a": 1, "p": "The icy road is the reason for driving slowly."}, {"lv": 3, "q": "Which sentence uses \"although\" correctly?", "o": ["Although he was tired, he finished the race.", "Although he was tired, so he finished the race.", "He was tired although.", "Although and he finished."], "a": 0, "p": "\"Although\" introduces a contrasting clause; do not add \"so\"."}, {"lv": 3, "q": "Identify the subordinate clause: \"If it is sunny tomorrow, we will go to the beach.\"", "o": ["we will go to the beach", "If it is sunny tomorrow", "to the beach", "tomorrow we will"], "a": 1, "p": "The subordinate clause begins with \"if\" and cannot stand alone."}, {"lv": 3, "q": "Which conjunction best completes: \"You must wear a helmet ___ you ride your bike.\"", "o": ["whenever", "but", "or", "although"], "a": 0, "p": "\"Whenever\" means every time."}]}, {"id": "cam-eng-k4-1", "name": "Synonyms and antonyms", "desc": "Word meanings", "idx": 1, "soal": [{"lv": 1, "q": "What is a synonym for \"big\"?", "o": ["tiny", "large", "short", "thin"], "a": 1, "p": "Synonyms have the same or similar meaning."}, {"lv": 1, "q": "What is an antonym for \"happy\"?", "o": ["glad", "sad", "cheerful", "joyful"], "a": 1, "p": "Antonyms have opposite meanings."}, {"lv": 1, "q": "What is a synonym for \"quick\"?", "o": ["slow", "fast", "lazy", "late"], "a": 1, "p": "Quick and fast mean the same."}, {"lv": 1, "q": "What is the antonym of \"empty\"?", "o": ["full", "bare", "clear", "hollow"], "a": 0, "p": "Empty is the opposite of full."}, {"lv": 2, "q": "Which word is a synonym for \"brave\"?", "o": ["courageous", "afraid", "timid", "weak"], "a": 0, "p": "Courageous means brave."}, {"lv": 2, "q": "Which word is an antonym for \"ancient\"?", "o": ["old", "modern", "aged", "historic"], "a": 1, "p": "Ancient means very old; modern means new."}, {"lv": 2, "q": "\"The giant was enormous.\" Which word could replace \"enormous\"?", "o": ["huge", "small", "kind", "quick"], "a": 0, "p": "Enormous and huge both mean very big."}, {"lv": 2, "q": "Which pair are antonyms?", "o": ["shout – yell", "begin – start", "rough – smooth", "small – little"], "a": 2, "p": "Rough and smooth are opposites."}, {"lv": 3, "q": "Which synonym for \"said\" best shows that someone was very angry?", "o": ["whispered", "shouted", "mumbled", "giggled"], "a": 1, "p": "\"Shouted\" suggests anger and loudness."}, {"lv": 3, "q": "\"The soup was scalding.\" What is the best antonym for \"scalding\"?", "o": ["boiling", "freezing", "warm", "steaming"], "a": 1, "p": "Scalding means extremely hot; freezing means extremely cold."}, {"lv": 3, "q": "Which word is NOT a synonym for \"look\"?", "o": ["glance", "stare", "peer", "listen"], "a": 3, "p": "Listen is about hearing, not seeing."}, {"lv": 3, "q": "Choose the word that best replaces \"nice\" to make the sentence more precise: \"We had a nice meal.\"", "o": ["delicious", "fine", "ok", "thing"], "a": 0, "p": "\"Delicious\" describes a meal more precisely."}]}, {"id": "cam-eng-k4-2", "name": "Non-fiction texts", "desc": "Instructions, reports, features", "idx": 2, "soal": [{"lv": 1, "q": "Non-fiction texts give ...", "o": ["made-up stories", "facts and information", "only poems", "only jokes"], "a": 1, "p": "Non-fiction is factual."}, {"lv": 1, "q": "Which is a non-fiction text?", "o": ["a fairy tale", "an encyclopedia entry about whales", "a fable", "a fantasy novel"], "a": 1, "p": "Encyclopedias give facts."}, {"lv": 1, "q": "Instructions usually use ...", "o": ["bossy (imperative) verbs like 'mix' and 'cut'", "rhyming words", "speech marks", "past tense stories"], "a": 0, "p": "Instructions tell you what to do."}, {"lv": 1, "q": "What is the purpose of a glossary?", "o": ["to explain the meaning of special words", "to list chapters", "to tell a story", "to show the price"], "a": 0, "p": "A glossary explains key words."}, {"lv": 2, "q": "Where would you look to find which page a topic is on?", "o": ["the index", "the title", "the front cover picture", "the glossary"], "a": 0, "p": "The index lists topics with page numbers."}, {"lv": 2, "q": "Which feature helps readers find sections in a report quickly?", "o": ["subheadings", "rhymes", "dialogue", "characters"], "a": 0, "p": "Subheadings divide the text into sections."}, {"lv": 2, "q": "A non-chronological report about tigers would most likely include ...", "o": ["a dragon character", "facts about tigers' habitat and diet", "a recipe for cake", "a poem about the sea"], "a": 1, "p": "Reports give organised facts about a topic."}, {"lv": 2, "q": "Why do instructions often use numbered steps?", "o": ["to show the order to follow", "to make the text longer", "to tell a story", "to rhyme"], "a": 0, "p": "Numbers show the sequence."}, {"lv": 3, "q": "Which sentence is a fact, not an opinion?", "o": ["Elephants are the best animals.", "Elephants are the largest land animals.", "Elephants are boring.", "Everyone loves elephants."], "a": 1, "p": "It can be checked and proved."}, {"lv": 3, "q": "A writer wants to show how a volcano erupts step by step. Which text feature is most useful?", "o": ["a labelled diagram", "a rhyme", "a list of characters", "a joke"], "a": 0, "p": "Diagrams with labels explain processes clearly."}, {"lv": 3, "q": "Which sentence would fit best in an instruction text about planting a seed?", "o": ["Once upon a time, a seed dreamed of growing.", "Place the seed 2 cm deep in the soil.", "Seeds are amazing and beautiful.", "I planted a seed last year."], "a": 1, "p": "Instructions use clear, imperative sentences."}, {"lv": 3, "q": "What is the main difference between a newspaper report and a story?", "o": ["A newspaper report is about real events, a story can be imagined.", "A story always has headlines.", "Reports always have dragons.", "There is no difference."], "a": 0, "p": "Reports inform about real events; stories may be fiction."}]}], "5": [{"id": "cam-eng-k5-0", "name": "Paragraphs and main ideas", "desc": "Topic sentences and supporting details", "idx": 0, "soal": [{"lv": 1, "q": "A paragraph is ...", "o": ["a single word", "a group of sentences about one main idea", "a list of letters", "a title"], "a": 1, "p": "Paragraphs organise writing into ideas."}, {"lv": 1, "q": "The topic sentence usually ...", "o": ["ends the story", "introduces the main idea of a paragraph", "is a question only", "lists facts"], "a": 1, "p": "Topic sentences tell the reader what the paragraph is about."}, {"lv": 1, "q": "Why do writers start a new paragraph?", "o": ["for a new idea, time, place or speaker", "every two words", "when they run out of ink", "never"], "a": 0, "p": "New paragraphs signal a change."}, {"lv": 1, "q": "Supporting details ...", "o": ["give more information about the main idea", "change the topic", "are always questions", "are titles"], "a": 0, "p": "Details explain or give examples."}, {"lv": 2, "q": "\"Cats make great pets. They are clean, quiet and easy to care for. Many cats also enjoy cuddles.\" What is the main idea?", "o": ["Cats are noisy.", "Cats make great pets.", "Cats like milk.", "Cats are hard to care for."], "a": 1, "p": "The first sentence states the main idea."}, {"lv": 2, "q": "Which sentence does NOT belong in a paragraph about healthy eating?", "o": ["Fruit and vegetables give us vitamins.", "Drinking water keeps us hydrated.", "My favourite football team won yesterday.", "Too much sugar can harm our teeth."], "a": 2, "p": "Football is off-topic."}, {"lv": 2, "q": "Which word best links two paragraphs about past and present?", "o": ["Nowadays", "Banana", "Quickly", "Blue"], "a": 0, "p": "\"Nowadays\" signals a change in time."}, {"lv": 2, "q": "Where is the topic sentence usually found?", "o": ["at the beginning of the paragraph", "only in the title", "in the middle of a word", "nowhere"], "a": 0, "p": "It usually opens the paragraph."}, {"lv": 3, "q": "\"Bees are vital for farming. Without them, many crops would not be pollinated. As a result, food prices would rise.\" What is the purpose of the last sentence?", "o": ["to show a consequence", "to change the topic", "to ask a question", "to introduce a character"], "a": 0, "p": "\"As a result\" shows a consequence."}, {"lv": 3, "q": "Which is the best topic sentence for a paragraph about the dangers of the sun?", "o": ["The sun is very far away.", "Spending too long in strong sunlight can harm your skin and eyes.", "I like summer.", "Sunflowers are yellow."], "a": 1, "p": "It introduces the main idea about danger."}, {"lv": 3, "q": "A paragraph lists three reasons for recycling. Which conclusion sentence fits best?", "o": ["For these reasons, everyone should recycle.", "Once upon a time.", "Recycling bins are green.", "I ate lunch."], "a": 0, "p": "It sums up the reasons."}, {"lv": 3, "q": "Which pair of paragraph openers shows a contrast?", "o": ["First... Then...", "On one hand... On the other hand...", "Firstly... Secondly...", "Once... Twice..."], "a": 1, "p": "These phrases present contrasting ideas."}]}, {"id": "cam-eng-k5-1", "name": "Direct and reported speech", "desc": "Speech marks and reporting", "idx": 1, "soal": [{"lv": 1, "q": "Which sentence uses direct speech?", "o": ["Tom said that he was tired.", "\"I am tired,\" said Tom.", "Tom told us he was tired.", "Tom was tired."], "a": 1, "p": "Direct speech uses the speaker's exact words in speech marks."}, {"lv": 1, "q": "What punctuation surrounds direct speech?", "o": ["brackets", "speech marks (inverted commas)", "full stops", "hyphens"], "a": 1, "p": "Speech marks show spoken words."}, {"lv": 1, "q": "Which sentence is reported speech?", "o": ["\"Let's go,\" said Ana.", "Ana said that they should go.", "\"Go!\" shouted Ana.", "\"Where?\" asked Ana."], "a": 1, "p": "Reported speech retells what was said without speech marks."}, {"lv": 1, "q": "Each new speaker in a story starts on a ...", "o": ["new line", "same line", "new page", "new chapter"], "a": 0, "p": "A new speaker starts a new line."}, {"lv": 2, "q": "Choose the correctly punctuated sentence.", "o": ["\"I love pizza\" said Mia.", "\"I love pizza,\" said Mia.", "\"I love pizza\", said Mia", "I love pizza, \"said Mia.\""], "a": 1, "p": "Put a comma inside the speech marks before the reporting clause."}, {"lv": 2, "q": "Change to reported speech: \"I am hungry,\" said Ben.", "o": ["Ben said that he was hungry.", "Ben said that I am hungry.", "Ben says I was hungry.", "Ben said, he is hungry I."], "a": 0, "p": "Change I → he and am → was."}, {"lv": 2, "q": "\"Where is my coat?\" asked Lily. What punctuation ends the spoken words?", "o": ["full stop", "question mark", "comma", "exclamation mark"], "a": 1, "p": "The spoken words are a question."}, {"lv": 2, "q": "Change to reported speech: \"We will win,\" said the coach.", "o": ["The coach said that they would win.", "The coach said that we will win.", "The coach said they wins.", "The coach says we would won."], "a": 0, "p": "will → would; we → they."}, {"lv": 3, "q": "Change to direct speech: Sara told her mum that she had finished her homework.", "o": ["\"I have finished my homework,\" Sara told her mum.", "\"She had finished her homework,\" Sara told her mum.", "\"I finished her homework,\" Sara told.", "Sara told \"her mum finished homework.\""], "a": 0, "p": "In direct speech Sara uses I and my, and the present perfect."}, {"lv": 3, "q": "Which sentence is correctly punctuated?", "o": ["\"Look out!\" shouted Dad, \"the car is coming.\"", "\"Look out!\" shouted Dad. \"The car is coming.\"", "\"Look out! shouted Dad\" The car is coming.", "Look out! \"shouted Dad\" the car is coming."], "a": 1, "p": "Two separate sentences of speech: the second starts with a capital letter."}, {"lv": 3, "q": "Change to reported speech: \"Can you help me?\" Jo asked Kim.", "o": ["Jo asked Kim if she could help her.", "Jo asked Kim can you help me.", "Jo asked Kim that could help.", "Jo asked, \"Kim could help.\""], "a": 0, "p": "Reported questions use if/whether with statement word order."}, {"lv": 3, "q": "Why do authors use direct speech in stories?", "o": ["to bring characters to life and show their personality", "to make the story shorter", "to list facts", "to remove all feelings"], "a": 0, "p": "Dialogue shows how characters speak and feel."}]}, {"id": "cam-eng-k5-2", "name": "Figurative language", "desc": "Similes, metaphors, personification", "idx": 2, "soal": [{"lv": 1, "q": "\"The snow was as white as a sheet.\" This is a ...", "o": ["metaphor", "simile", "personification", "rhyme"], "a": 1, "p": "A simile compares using 'as' or 'like'."}, {"lv": 1, "q": "\"The classroom was a zoo.\" This is a ...", "o": ["simile", "metaphor", "fact", "question"], "a": 1, "p": "A metaphor says something IS something else."}, {"lv": 1, "q": "\"The wind whispered through the trees.\" This is ...", "o": ["personification", "simile", "alliteration", "a fact"], "a": 0, "p": "Giving human actions to non-human things is personification."}, {"lv": 1, "q": "Which is a simile?", "o": ["He runs like a cheetah.", "He is a cheetah.", "He runs.", "Cheetahs are fast."], "a": 0, "p": "It uses 'like' to compare."}, {"lv": 2, "q": "\"Her smile was sunshine.\" What does this metaphor suggest?", "o": ["Her smile was warm and bright.", "Her smile was hot.", "She was outside.", "She was sad."], "a": 0, "p": "The metaphor suggests warmth and happiness."}, {"lv": 2, "q": "\"The old car coughed and groaned up the hill.\" This shows the car ...", "o": ["was new and fast", "was struggling", "was happy", "was flying"], "a": 1, "p": "Coughed and groaned are personification suggesting struggle."}, {"lv": 2, "q": "Which sentence uses alliteration?", "o": ["Silly snakes slither slowly.", "The dog barked.", "It was cold.", "She smiled like the sun."], "a": 0, "p": "Repeated initial 's' sounds."}, {"lv": 2, "q": "\"I've told you a million times!\" This is ...", "o": ["hyperbole (exaggeration)", "simile", "personification", "a fact"], "a": 0, "p": "It exaggerates for effect."}, {"lv": 3, "q": "\"The city never sleeps.\" What does this mean?", "o": ["The city is busy at all hours.", "People in the city are tired.", "The city has no beds.", "The city is quiet at night."], "a": 0, "p": "Personification suggesting constant activity."}, {"lv": 3, "q": "Why might a writer describe a storm as 'an angry giant'?", "o": ["to make the storm feel powerful and frightening", "to show it was small", "to show it was calm", "to give facts about rain"], "a": 0, "p": "The metaphor creates a strong image of power."}, {"lv": 3, "q": "Which line uses a metaphor rather than a simile?", "o": ["Time is a thief.", "She sang like a bird.", "He was as brave as a lion.", "The baby slept like a log."], "a": 0, "p": "No 'like' or 'as': time is directly called a thief."}, {"lv": 3, "q": "\"The stars danced in the night sky.\" What effect does this create?", "o": ["Stars seem lively and twinkling.", "Stars are falling.", "Stars are cold.", "It is daytime."], "a": 0, "p": "Dancing suggests movement and liveliness."}]}], "6": [{"id": "cam-eng-k6-0", "name": "Active and passive voice", "desc": "Changing sentence voice", "idx": 0, "soal": [{"lv": 1, "q": "Which sentence is in the active voice?", "o": ["The cake was eaten by Sam.", "Sam ate the cake.", "The cake was eaten.", "The cake is being eaten."], "a": 1, "p": "In the active voice the subject does the action."}, {"lv": 1, "q": "Which sentence is in the passive voice?", "o": ["The dog chased the ball.", "The ball was chased by the dog.", "The dog runs.", "Dogs love balls."], "a": 1, "p": "Passive: the object becomes the subject."}, {"lv": 1, "q": "The passive voice uses a form of 'be' plus ...", "o": ["the past participle", "-ing", "the base verb", "an adjective"], "a": 0, "p": "For example, was + eaten."}, {"lv": 1, "q": "\"The letter was written by Mia.\" Who did the action?", "o": ["the letter", "Mia", "nobody", "the reader"], "a": 1, "p": "\"By Mia\" shows the doer."}, {"lv": 2, "q": "Change to passive: \"The chef cooked the meal.\"", "o": ["The meal was cooked by the chef.", "The meal cooked the chef.", "The chef was cooked by the meal.", "The meal is cook by chef."], "a": 0, "p": "Object → subject; was + cooked."}, {"lv": 2, "q": "Change to active: \"The window was broken by the boys.\"", "o": ["The boys broke the window.", "The window broke the boys.", "The boys were broken.", "The window has broken."], "a": 0, "p": "The doer becomes the subject."}, {"lv": 2, "q": "Why might a writer use the passive voice in a science report?", "o": ["to focus on the action, not who did it", "to make it funny", "to add characters", "to use speech"], "a": 0, "p": "For example: The water was heated."}, {"lv": 2, "q": "Change to passive: \"People speak English all over the world.\"", "o": ["English is spoken all over the world.", "English speaks people.", "English was spoke.", "People are spoken English."], "a": 0, "p": "is + spoken; the agent 'people' can be left out."}, {"lv": 3, "q": "Change to passive: \"The council will build a new library.\"", "o": ["A new library will be built by the council.", "A new library will build the council.", "A new library is build by the council.", "The council will be built."], "a": 0, "p": "will + be + built."}, {"lv": 3, "q": "Which sentence is passive?", "o": ["They are painting the hall.", "The hall is being painted.", "The hall looks bright.", "Painters paint halls."], "a": 1, "p": "is being + past participle."}, {"lv": 3, "q": "\"Mistakes were made.\" Why might someone use this passive sentence?", "o": ["to avoid saying who made the mistakes", "to name the person responsible", "to tell a story", "to describe weather"], "a": 0, "p": "The passive can hide the doer."}, {"lv": 3, "q": "Change to active: \"The match has been won by our team.\"", "o": ["Our team has won the match.", "Our team was won.", "The match has won our team.", "Our team wins the match by."], "a": 0, "p": "has been won → has won."}]}, {"id": "cam-eng-k6-1", "name": "Persuasive writing", "desc": "Techniques and features", "idx": 1, "soal": [{"lv": 1, "q": "The purpose of persuasive writing is to ...", "o": ["entertain with a story", "convince the reader to agree or act", "give instructions", "describe a place"], "a": 1, "p": "Persuasive writing tries to change opinions or actions."}, {"lv": 1, "q": "Which is a persuasive sentence?", "o": ["The park opens at 9 a.m.", "You must visit our amazing park today!", "The park has trees.", "I went to the park."], "a": 1, "p": "It urges the reader to act."}, {"lv": 1, "q": "A rhetorical question is ...", "o": ["a question that does not expect an answer", "a question in a quiz", "a maths question", "a question with two answers"], "a": 0, "p": "Used to make the reader think, e.g. Don't you want a cleaner world?"}, {"lv": 1, "q": "Which word is emotive (makes you feel strongly)?", "o": ["heartbreaking", "table", "Tuesday", "seven"], "a": 0, "p": "Emotive words create feelings."}, {"lv": 2, "q": "\"9 out of 10 dentists recommend Sparkle toothpaste.\" This technique is ...", "o": ["using statistics/expert opinion", "a simile", "a rhyme", "a question"], "a": 0, "p": "Facts and experts make claims sound reliable."}, {"lv": 2, "q": "Which is the strongest persuasive opening?", "o": ["Some people like dogs.", "Imagine a world where every child has clean water.", "Water is wet.", "I have a dog."], "a": 1, "p": "It engages the reader's imagination."}, {"lv": 2, "q": "\"Act now before it's too late!\" This creates a sense of ...", "o": ["urgency", "boredom", "humour", "calm"], "a": 0, "p": "It pushes the reader to act quickly."}, {"lv": 2, "q": "Why do persuasive writers use 'you'?", "o": ["to speak directly to the reader", "to describe themselves", "to avoid the reader", "to tell a story"], "a": 0, "p": "Direct address makes it personal."}, {"lv": 3, "q": "Which sentence uses the 'rule of three'?", "o": ["Our school is safe, friendly and exciting.", "Our school is good.", "Our school is big and blue.", "Our school opened in 1990."], "a": 0, "p": "Three adjectives together are memorable."}, {"lv": 3, "q": "A writer argues for a longer playtime. Which is the BEST counter-argument to address?", "o": ["Some say it reduces learning time, but exercise actually helps concentration.", "Playtime is fun.", "I like football.", "The bell is loud."], "a": 0, "p": "It addresses an opposing view and rebuts it."}, {"lv": 3, "q": "Which ending is most effective for a persuasive leaflet?", "o": ["Join us today and make a difference!", "That is all.", "The end.", "I don't know."], "a": 0, "p": "A call to action motivates the reader."}, {"lv": 3, "q": "\"Surely no one wants to see our beautiful beaches covered in plastic?\" Which techniques are used?", "o": ["rhetorical question and emotive language", "simile and rhyme", "instructions", "a list of facts"], "a": 0, "p": "A question with emotive words such as 'beautiful'."}]}, {"id": "cam-eng-k6-2", "name": "Inference in reading", "desc": "Reading between the lines", "idx": 2, "soal": [{"lv": 1, "q": "Inference means ...", "o": ["copying the text", "working out what the writer suggests using clues", "reading quickly", "counting words"], "a": 1, "p": "We 'read between the lines'."}, {"lv": 1, "q": "\"Jake slammed the door and stomped upstairs.\" How does Jake feel?", "o": ["happy", "angry", "sleepy", "excited"], "a": 1, "p": "Slamming and stomping show anger."}, {"lv": 1, "q": "\"Ella wrapped her scarf tighter and her breath made clouds.\" What is the weather like?", "o": ["hot", "cold", "rainy", "windy and hot"], "a": 1, "p": "Visible breath means it is cold."}, {"lv": 1, "q": "\"The children cheered as the final whistle blew.\" Which is most likely?", "o": ["Their team won.", "They were bored.", "They were scared.", "It was raining."], "a": 0, "p": "Cheering suggests a win."}, {"lv": 2, "q": "\"Grandpa's hands shook as he opened the letter. A tear rolled down his cheek.\" What can we infer?", "o": ["The letter contained emotional news.", "Grandpa was angry.", "The letter was a bill.", "Grandpa was laughing."], "a": 0, "p": "Shaking and tears suggest strong emotion."}, {"lv": 2, "q": "\"Mia checked the clock for the tenth time and tapped her foot.\" Mia is probably ...", "o": ["impatient", "asleep", "relaxed", "hungry"], "a": 0, "p": "Repeated checking and tapping show impatience."}, {"lv": 2, "q": "\"The shelves were empty and dust covered the counter.\" The shop is probably ...", "o": ["busy and new", "closed or abandoned", "full of customers", "opening today"], "a": 1, "p": "Empty shelves and dust suggest no one uses it."}, {"lv": 2, "q": "\"Leo hid his report card behind his back.\" What might this suggest?", "o": ["He is proud of it.", "He may have bad grades.", "He lost it.", "He has no report."], "a": 1, "p": "Hiding suggests he does not want it seen."}, {"lv": 3, "q": "\"Despite the storm, the lighthouse keeper climbed the stairs again.\" What does this suggest about him?", "o": ["He is dedicated to his duty.", "He is lazy.", "He is afraid of heights.", "He likes storms."], "a": 0, "p": "Climbing despite danger shows dedication."}, {"lv": 3, "q": "\"The house smelled of fresh bread and the table was set for twelve.\" What is most likely about to happen?", "o": ["a large family meal or celebration", "a fire", "a holiday abroad", "a football match"], "a": 0, "p": "Many places and food suggest a gathering."}, {"lv": 3, "q": "Why do authors often show feelings rather than state them?", "o": ["to let readers infer and feel more involved", "to make texts shorter", "because they forgot", "to give instructions"], "a": 0, "p": "Showing engages readers."}, {"lv": 3, "q": "\"Amira's smile didn't reach her eyes as she congratulated the winner.\" What can we infer?", "o": ["She was not truly happy for the winner.", "She was delighted.", "She was the winner.", "She was laughing."], "a": 0, "p": "A smile that doesn't reach the eyes suggests it is forced."}]}], "7": [{"id": "cam-eng-k7-0", "name": "Narrative techniques", "desc": "Viewpoint, tension, dialogue", "idx": 0, "soal": [{"lv": 1, "q": "A first-person narrator uses ...", "o": ["he/she", "I/we", "you", "they only"], "a": 1, "p": "First person: I and we."}, {"lv": 1, "q": "Dialogue in a story is ...", "o": ["the setting", "the words characters speak", "the title", "a list of facts"], "a": 1, "p": "Dialogue shows conversation."}, {"lv": 1, "q": "Tension in a story makes readers ...", "o": ["bored", "want to know what happens next", "close the book", "fall asleep"], "a": 1, "p": "Tension creates suspense."}, {"lv": 1, "q": "A third-person narrator uses ...", "o": ["I and me", "he, she, they", "you only", "we only"], "a": 1, "p": "Third person describes characters from outside."}, {"lv": 2, "q": "Which technique builds tension?", "o": ["short sentences", "long lists of food", "happy endings", "facts about weather only"], "a": 0, "p": "Short sentences increase pace and suspense."}, {"lv": 2, "q": "\"I crept towards the door. My heart pounded.\" Which viewpoint is this?", "o": ["first person", "second person", "third person", "no viewpoint"], "a": 0, "p": "\"I\" means first person."}, {"lv": 2, "q": "A 'cliffhanger' is ...", "o": ["an ending that leaves the reader in suspense", "a mountain setting", "a happy ending", "a list of characters"], "a": 0, "p": "It keeps readers wanting more."}, {"lv": 2, "q": "Why might a writer start a story in the middle of the action?", "o": ["to grab the reader's attention immediately", "to confuse the author", "to make it shorter", "to avoid characters"], "a": 0, "p": "In medias res hooks readers."}, {"lv": 3, "q": "\"Silence. Then a scream.\" What effect do these fragments create?", "o": ["sudden shock and tension", "calm and peace", "humour", "a list of facts"], "a": 0, "p": "Fragments create drama."}, {"lv": 3, "q": "What is the advantage of a third-person omniscient narrator?", "o": ["can reveal the thoughts of many characters", "can only see one character", "cannot describe settings", "must use 'I'"], "a": 0, "p": "Omniscient means all-knowing."}, {"lv": 3, "q": "A flashback is used to ...", "o": ["show events from the past", "predict the future only", "list characters", "end the story"], "a": 0, "p": "It gives background information."}, {"lv": 3, "q": "Which sentence uses 'show, don't tell' best?", "o": ["She was nervous.", "Her hands trembled as she gripped the microphone.", "She felt nervous.", "Nervous was she."], "a": 1, "p": "Actions show the feeling without naming it."}]}, {"id": "cam-eng-k7-1", "name": "Clauses and sentence types", "desc": "Simple, compound, complex", "idx": 1, "soal": [{"lv": 1, "q": "A simple sentence has ...", "o": ["one main clause", "two main clauses", "no verb", "only questions"], "a": 0, "p": "For example: The cat slept."}, {"lv": 1, "q": "Which is a compound sentence?", "o": ["I ran.", "I ran and she walked.", "Because I ran.", "Running fast."], "a": 1, "p": "Two main clauses joined by 'and'."}, {"lv": 1, "q": "A clause must contain ...", "o": ["a verb", "a comma", "a question mark", "an adjective"], "a": 0, "p": "Clauses have a subject and a verb."}, {"lv": 1, "q": "Which is a complex sentence?", "o": ["I laughed.", "Although it rained, we played outside.", "We played and laughed.", "Play outside."], "a": 1, "p": "It has a subordinate clause and a main clause."}, {"lv": 2, "q": "Identify the main clause: \"When the bell rang, the pupils left.\"", "o": ["When the bell rang", "the pupils left", "the bell", "rang"], "a": 1, "p": "It can stand alone."}, {"lv": 2, "q": "Which conjunction creates a subordinate clause?", "o": ["and", "but", "because", "or"], "a": 2, "p": "Subordinating conjunctions include because, although, when."}, {"lv": 2, "q": "\"The boy who won the race smiled.\" The relative clause is ...", "o": ["the boy", "who won the race", "smiled", "the race smiled"], "a": 1, "p": "It adds information about the boy."}, {"lv": 2, "q": "Which is a sentence fragment?", "o": ["The dog barked loudly.", "Because the dog barked.", "The dog barked, and the cat ran.", "Dogs bark."], "a": 1, "p": "It is a subordinate clause on its own."}, {"lv": 3, "q": "Combine as one complex sentence: \"She was tired. She finished her homework.\"", "o": ["Although she was tired, she finished her homework.", "She was tired, she finished her homework.", "She was tired and. She finished.", "Tired she, homework finished."], "a": 0, "p": "\"Although\" links contrasting ideas correctly."}, {"lv": 3, "q": "Which sentence is a comma splice (error)?", "o": ["I like tea, but he likes coffee.", "I like tea, he likes coffee.", "I like tea; he likes coffee.", "I like tea. He likes coffee."], "a": 1, "p": "Two main clauses joined only by a comma."}, {"lv": 3, "q": "What type of sentence is: \"Because the road was closed, we took a detour, and we arrived late.\"", "o": ["compound-complex", "simple", "fragment", "compound only"], "a": 0, "p": "It has two main clauses and a subordinate clause."}, {"lv": 3, "q": "Why might a writer use a mix of sentence types?", "o": ["to vary rhythm and keep readers engaged", "to confuse readers", "to save paper", "because it is required by law"], "a": 0, "p": "Variety improves style and pace."}]}, {"id": "cam-eng-k7-2", "name": "Formal and informal register", "desc": "Choosing the right tone", "idx": 2, "soal": [{"lv": 1, "q": "Which greeting is most formal?", "o": ["Hey!", "Dear Sir or Madam,", "Hi mate,", "Yo!"], "a": 1, "p": "Formal letters use Dear Sir or Madam."}, {"lv": 1, "q": "Which is informal language?", "o": ["I would be grateful if you could reply.", "Gonna see ya later!", "Yours faithfully", "I am writing to enquire"], "a": 1, "p": "Slang and contractions are informal."}, {"lv": 1, "q": "Register means ...", "o": ["the level of formality in language", "a list of names", "a type of punctuation", "the title of a book"], "a": 0, "p": "We choose register to suit audience and purpose."}, {"lv": 1, "q": "Which situation needs formal language?", "o": ["a text to your best friend", "a job application letter", "a birthday card to your brother", "a chat with classmates"], "a": 1, "p": "Job applications are formal."}, {"lv": 2, "q": "Choose the more formal version of \"Can I get a refund?\"", "o": ["Gimme my money back.", "I would like to request a refund.", "Refund now!", "Can I has refund?"], "a": 1, "p": "Polite, complete phrasing is formal."}, {"lv": 2, "q": "Which closing matches 'Dear Mr Smith'?", "o": ["Yours sincerely", "Yours faithfully", "Cheers", "Love"], "a": 0, "p": "Use 'sincerely' when you know the name."}, {"lv": 2, "q": "Which word is too informal for a school report?", "o": ["significant", "awesome", "consequently", "analyse"], "a": 1, "p": "\"Awesome\" is casual."}, {"lv": 2, "q": "Formal writing usually avoids ...", "o": ["contractions such as don't and can't", "full sentences", "correct spelling", "paragraphs"], "a": 0, "p": "Write 'do not' instead of 'don't'."}, {"lv": 3, "q": "Rewrite formally: \"The food was really bad and loads of people got sick.\"", "o": ["The food was of poor quality and many people became unwell.", "The food was rubbish and tons got ill.", "Food bad, people sick.", "The food was super bad, lol."], "a": 0, "p": "Formal vocabulary replaces slang."}, {"lv": 3, "q": "Why would a writer use informal register in a blog for teenagers?", "o": ["to sound friendly and relatable to the audience", "because it is a legal document", "to confuse readers", "to meet exam rules"], "a": 0, "p": "Register should match the audience."}, {"lv": 3, "q": "Which sentence mixes registers inappropriately in a formal complaint?", "o": ["I am writing to express my dissatisfaction.", "I was well gutted when the parcel didn't arrive.", "I would appreciate a prompt response.", "Please find enclosed my receipt."], "a": 1, "p": "\"Well gutted\" is slang."}, {"lv": 3, "q": "Which is the best opening for a formal letter to a newspaper?", "o": ["I am writing to express my concern about the closure of the local library.", "Guess what, the library's closing!", "Hiya editor!", "Libraries rock."], "a": 0, "p": "Clear, polite and formal."}]}], "8": [{"id": "cam-eng-k8-0", "name": "Writer's purpose and audience", "desc": "Inform, persuade, entertain", "idx": 0, "soal": [{"lv": 1, "q": "The three main purposes of writing are often summed up as ...", "o": ["inform, persuade, entertain", "read, write, spell", "start, middle, end", "past, present, future"], "a": 0, "p": "These are the common purposes."}, {"lv": 1, "q": "A leaflet about road safety for children is mainly written to ...", "o": ["inform and advise", "entertain with a story", "sell a car", "describe a dream"], "a": 0, "p": "It gives safety information."}, {"lv": 1, "q": "The audience of a text is ...", "o": ["the people it is written for", "the author", "the title", "the setting"], "a": 0, "p": "Writers adapt to their audience."}, {"lv": 1, "q": "A comic adventure story is mainly written to ...", "o": ["entertain", "inform", "instruct", "complain"], "a": 0, "p": "Stories entertain."}, {"lv": 2, "q": "Which feature suggests a text is written for young children?", "o": ["simple words and bright pictures", "complex technical terms", "footnotes and references", "long paragraphs"], "a": 0, "p": "Simple language suits young readers."}, {"lv": 2, "q": "An advert says: 'Don't miss out – grab yours today!' Its purpose is to ...", "o": ["persuade", "inform only", "entertain", "instruct"], "a": 0, "p": "It urges buying."}, {"lv": 2, "q": "Why might a writer use technical vocabulary?", "o": ["The audience is expert in the subject.", "To confuse beginners.", "To entertain toddlers.", "Because they forgot simple words."], "a": 0, "p": "Experts understand technical terms."}, {"lv": 2, "q": "A travel guide aims mainly to ...", "o": ["inform and persuade readers to visit", "argue against travel", "tell a fairy tale", "give a science experiment"], "a": 0, "p": "It describes places attractively."}, {"lv": 3, "q": "A charity letter describes a hungry child, then gives facts and asks for donations. What are its purposes?", "o": ["to inform and persuade", "to entertain only", "to instruct how to cook", "to describe a holiday"], "a": 0, "p": "Facts inform; the request persuades."}, {"lv": 3, "q": "How does a writer's purpose affect sentence choice in a thriller?", "o": ["Short, punchy sentences build tension to entertain.", "Long lists of facts.", "Formal letter phrases.", "Numbered instructions."], "a": 0, "p": "Pace suits the purpose."}, {"lv": 3, "q": "A government website about tax uses formal, clear language and headings. Who is the audience?", "o": ["adult taxpayers needing information", "toddlers", "poets", "cartoon fans"], "a": 0, "p": "Formal and clear writing suits adults seeking information."}, {"lv": 3, "q": "Which change would make a science article suitable for 8-year-olds?", "o": ["simplify vocabulary and add explanations", "add more jargon", "remove all pictures", "use longer sentences"], "a": 0, "p": "Simplifying suits younger readers."}]}, {"id": "cam-eng-k8-1", "name": "Advanced punctuation", "desc": "Semicolons, colons, dashes", "idx": 1, "soal": [{"lv": 1, "q": "Which punctuation mark introduces a list?", "o": ["colon", "comma", "hyphen", "apostrophe"], "a": 0, "p": "For example: You need: pens, paper and glue."}, {"lv": 1, "q": "A semicolon can join ...", "o": ["two closely related main clauses", "a word and a number", "a question and an answer only", "two letters"], "a": 0, "p": "For example: It rained; we stayed inside."}, {"lv": 1, "q": "Which sentence uses a dash correctly?", "o": ["I opened the box – it was empty!", "I – opened the box it was empty.", "I opened – the – box.", "– I opened the box"], "a": 0, "p": "A dash adds a dramatic pause or extra information."}, {"lv": 1, "q": "Brackets are used to ...", "o": ["add extra information", "end a sentence", "show possession", "start a question"], "a": 0, "p": "For example: My uncle (a pilot) visited."}, {"lv": 2, "q": "Choose the correct semicolon use.", "o": ["I love pizza; my sister prefers pasta.", "I love; pizza and pasta.", "I; love pizza.", "I love pizza; and pasta."], "a": 0, "p": "Two related independent clauses."}, {"lv": 2, "q": "Which sentence uses a colon correctly?", "o": ["She had one goal: to win the gold medal.", "She had: one goal to win.", "She: had one goal.", "She had one: goal."], "a": 0, "p": "A colon introduces an explanation."}, {"lv": 2, "q": "Semicolons can separate list items that ...", "o": ["already contain commas", "are single words", "are numbers only", "are questions"], "a": 0, "p": "For example: Paris, France; Rome, Italy; Cairo, Egypt."}, {"lv": 2, "q": "Which sentence needs an apostrophe for possession?", "o": ["The dogs bone was buried.", "The dogs are barking.", "I have two dogs.", "Dogs run fast."], "a": 0, "p": "It should be dog's bone."}, {"lv": 3, "q": "Which sentence is correctly punctuated?", "o": ["The results were clear: the experiment had failed; we needed a new plan.", "The results were clear; the experiment: had failed.", "The results: were clear the experiment had failed.", "The results were clear, the experiment had failed, we needed; a new plan."], "a": 0, "p": "The colon explains; the semicolon links related clauses."}, {"lv": 3, "q": "Why might a writer use a pair of dashes instead of commas?", "o": ["to make the extra information more dramatic or emphatic", "to end the sentence", "to show a question", "because commas are wrong"], "a": 0, "p": "Dashes add emphasis."}, {"lv": 3, "q": "Which is correct?", "o": ["The children's toys were everywhere.", "The childrens' toys were everywhere.", "The childrens toys were everywhere.", "The children toy's were everywhere."], "a": 0, "p": "\"Children\" is already plural, so add 's."}, {"lv": 3, "q": "Identify the error: \"Its a lovely day; the sun is shining.\"", "o": ["\"Its\" should be \"It's\"", "the semicolon is wrong", "\"shining\" is misspelled", "there is no error"], "a": 0, "p": "It's = it is."}]}, {"id": "cam-eng-k8-2", "name": "Poetry analysis", "desc": "Imagery, rhythm, structure", "idx": 2, "soal": [{"lv": 1, "q": "A group of lines in a poem is called a ...", "o": ["paragraph", "stanza", "chapter", "clause"], "a": 1, "p": "Stanzas are poetic paragraphs."}, {"lv": 1, "q": "Words that end with the same sound are said to ...", "o": ["rhyme", "contrast", "repeat", "alliterate"], "a": 0, "p": "For example: cat and hat."}, {"lv": 1, "q": "Imagery in poetry means ...", "o": ["language that creates pictures in the reader's mind", "the title of a poem", "the number of lines", "the poet's name"], "a": 0, "p": "It appeals to the senses."}, {"lv": 1, "q": "Onomatopoeia is ...", "o": ["a word that imitates a sound", "a long poem", "a type of rhyme", "a question"], "a": 0, "p": "For example: buzz, crash."}, {"lv": 2, "q": "\"The moon was a ghostly galleon.\" This is a ...", "o": ["metaphor", "simile", "onomatopoeia", "rhyme"], "a": 0, "p": "It says the moon IS a galleon."}, {"lv": 2, "q": "A regular beat in a poem is called its ...", "o": ["rhythm", "stanza", "title", "theme"], "a": 0, "p": "Rhythm is the pattern of stressed syllables."}, {"lv": 2, "q": "Repetition in a poem is often used to ...", "o": ["emphasise an idea or feeling", "make it shorter", "confuse readers", "remove meaning"], "a": 0, "p": "Repeated lines stress importance."}, {"lv": 2, "q": "Enjambment means ...", "o": ["a sentence runs on to the next line without a pause", "every line ends with a full stop", "the poem rhymes", "the poem has no title"], "a": 0, "p": "It creates flow or tension."}, {"lv": 3, "q": "A poem about war uses short lines, harsh sounds like 'crack' and 'thud', and no rhyme. What mood does it create?", "o": ["violent and tense", "peaceful and gentle", "funny", "romantic"], "a": 0, "p": "Harsh sounds and short lines create tension."}, {"lv": 3, "q": "What is the effect of a poem changing from present to past tense in its last stanza?", "o": ["It may suggest memory or loss.", "It has no effect.", "It makes the poem rhyme.", "It shows the poet made an error."], "a": 0, "p": "Tense changes can signal reflection."}, {"lv": 3, "q": "Why might a poet use the sea as an extended metaphor for life?", "o": ["to explore ideas such as calm and stormy times", "to give facts about oceans", "to list fish", "to make the poem longer"], "a": 0, "p": "The sea's changes mirror life's ups and downs."}, {"lv": 3, "q": "The theme of a poem is ...", "o": ["its central message or idea", "its rhyme scheme", "its number of stanzas", "its title only"], "a": 0, "p": "Themes are big ideas such as love or loss."}]}], "9": [{"id": "cam-eng-k9-0", "name": "Argumentative writing", "desc": "Claims, evidence, counter-arguments", "idx": 0, "soal": [{"lv": 1, "q": "An argumentative essay presents ...", "o": ["a clear position supported by evidence", "a fairy tale", "a recipe", "a diary entry"], "a": 0, "p": "It argues for a viewpoint."}, {"lv": 1, "q": "A counter-argument is ...", "o": ["an opposing view that the writer addresses", "the conclusion", "the title", "a fact about the writer"], "a": 0, "p": "Addressing it strengthens the argument."}, {"lv": 1, "q": "Which is evidence?", "o": ["A 2024 study found that 60% of teens sleep less than 8 hours.", "I think teens are lazy.", "Sleep is boring.", "Everyone hates mornings."], "a": 0, "p": "Statistics from a study are evidence."}, {"lv": 1, "q": "The thesis statement usually appears in the ...", "o": ["introduction", "conclusion only", "title only", "bibliography"], "a": 0, "p": "It states the main claim early."}, {"lv": 2, "q": "Which phrase introduces a rebuttal?", "o": ["However, this view overlooks...", "Once upon a time...", "Firstly, gather ingredients...", "In my dream..."], "a": 0, "p": "It responds to an opposing view."}, {"lv": 2, "q": "Which is the strongest claim for an essay on banning junk food in schools?", "o": ["Banning junk food in schools would improve students' health and concentration.", "Junk food exists.", "Some food is tasty.", "I had chips yesterday."], "a": 0, "p": "Clear, arguable and specific."}, {"lv": 2, "q": "Why should a writer cite reliable sources?", "o": ["to make the argument credible", "to make it longer", "to confuse readers", "to avoid evidence"], "a": 0, "p": "Credible evidence persuades."}, {"lv": 2, "q": "Which connective adds a further point?", "o": ["Furthermore", "However", "Nevertheless", "Although"], "a": 0, "p": "Furthermore adds."}, {"lv": 3, "q": "Which is a logical fallacy?", "o": ["Everyone is doing it, so it must be right.", "Data shows a 20% drop in accidents.", "Experts agree after a 5-year study.", "The evidence suggests a link."], "a": 0, "p": "This is the bandwagon fallacy."}, {"lv": 3, "q": "What makes a conclusion effective in argumentative writing?", "o": ["It restates the thesis and leaves a strong final impression.", "It introduces a new unrelated topic.", "It only lists facts.", "It ends mid-sentence."], "a": 0, "p": "It reinforces the argument."}, {"lv": 3, "q": "A writer says, 'Some argue uniforms limit self-expression; however, they reduce bullying based on clothing.' This shows ...", "o": ["acknowledging and rebutting a counter-argument", "a narrative hook", "a simile", "a summary"], "a": 0, "p": "Concession followed by rebuttal."}, {"lv": 3, "q": "Which evidence would most strengthen the claim 'Homework should be limited'?", "o": ["Research linking excessive homework to stress and poor sleep", "A student's favourite colour", "The number of pencils sold", "A poem about school"], "a": 0, "p": "Relevant research supports the claim."}]}, {"id": "cam-eng-k9-1", "name": "Language devices and their effects", "desc": "Analysing word choice", "idx": 1, "soal": [{"lv": 1, "q": "Alliteration is ...", "o": ["repetition of the same starting sound", "a comparison using 'like'", "exaggeration", "a question"], "a": 0, "p": "For example: big bold bears."}, {"lv": 1, "q": "Hyperbole is ...", "o": ["deliberate exaggeration", "a sound word", "a quiet tone", "a list"], "a": 0, "p": "For example: I'm starving to death."}, {"lv": 1, "q": "Emotive language aims to ...", "o": ["make the reader feel strong emotions", "give instructions", "list facts neutrally", "confuse"], "a": 0, "p": "Words like 'devastating' stir feelings."}, {"lv": 1, "q": "A rhetorical question ...", "o": ["does not expect an answer", "needs a written answer", "is a maths problem", "is a quiz"], "a": 0, "p": "It makes the reader think."}, {"lv": 2, "q": "\"The crowd roared like a hungry lion.\" The effect is to show the crowd was ...", "o": ["very loud and excited", "silent", "sleeping", "small"], "a": 0, "p": "The simile suggests power and noise."}, {"lv": 2, "q": "What is the effect of the word 'crept' instead of 'walked'?", "o": ["It suggests secrecy or caution.", "It suggests speed.", "It suggests happiness.", "No effect."], "a": 0, "p": "Word choice shapes meaning."}, {"lv": 2, "q": "\"Bang! The door slammed.\" Which device is 'Bang'?", "o": ["onomatopoeia", "metaphor", "personification", "simile"], "a": 0, "p": "It imitates a sound."}, {"lv": 2, "q": "Which word has the most negative connotation?", "o": ["stubborn", "determined", "persistent", "firm"], "a": 0, "p": "Stubborn suggests unreasonable."}, {"lv": 3, "q": "\"The city was a beast that swallowed dreams.\" How does this metaphor present the city?", "o": ["as dangerous and destructive", "as kind", "as small", "as beautiful"], "a": 0, "p": "A beast that swallows suggests threat."}, {"lv": 3, "q": "Why might a writer use a list of three short sentences: 'He ran. He hid. He waited.'?", "o": ["to build tension and pace", "to slow the story", "to add humour", "to give facts"], "a": 0, "p": "Short sentences quicken the pace."}, {"lv": 3, "q": "Analyse: \"The sun smiled down on the meadow.\" What mood is created?", "o": ["warm and cheerful", "dark and gloomy", "angry", "cold"], "a": 0, "p": "Personification creates warmth."}, {"lv": 3, "q": "Which is the best analytical sentence about word choice?", "o": ["The verb 'shattered' suggests sudden, violent destruction, emphasising the character's shock.", "The writer uses words.", "It is a good sentence.", "I like this word."], "a": 0, "p": "It names the word, explains the effect and links to meaning."}]}, {"id": "cam-eng-k9-2", "name": "Summary skills", "desc": "Selecting key points", "idx": 2, "soal": [{"lv": 1, "q": "A summary should be ...", "o": ["shorter than the original and include key points", "longer than the original", "a copy of the text", "only your opinion"], "a": 0, "p": "Concise and focused on main points."}, {"lv": 1, "q": "Which should be left OUT of a summary?", "o": ["minor examples and details", "main ideas", "key facts", "the main argument"], "a": 0, "p": "Summaries remove less important details."}, {"lv": 1, "q": "Summaries should be written ...", "o": ["mainly in your own words", "with every quote copied", "as a poem", "in bullet emojis"], "a": 0, "p": "Paraphrasing shows understanding."}, {"lv": 1, "q": "The first step in summarising is to ...", "o": ["read and identify the main ideas", "write the conclusion first", "count the words", "draw pictures"], "a": 0, "p": "Understanding comes first."}, {"lv": 2, "q": "Text: \"Bees pollinate crops. Without bees, foods like apples and almonds would be scarce. Bee numbers are falling due to pesticides.\" Best summary?", "o": ["Bees are vital pollinators, but pesticides are reducing their numbers, threatening food supplies.", "Apples are tasty.", "Bees sting people.", "Almonds grow on trees."], "a": 0, "p": "It captures all key points concisely."}, {"lv": 2, "q": "Which is a good technique for summarising?", "o": ["combining similar ideas into one sentence", "adding new opinions", "repeating each sentence", "adding unrelated facts"], "a": 0, "p": "Merging ideas saves words."}, {"lv": 2, "q": "Why should you avoid copying long phrases in a summary?", "o": ["It does not show understanding and is not concise.", "It is too short.", "It is always wrong grammar.", "It is funny."], "a": 0, "p": "Own words demonstrate comprehension."}, {"lv": 2, "q": "Replace the list 'apples, pears, bananas and grapes' with a more concise word.", "o": ["fruit", "food items like apples", "things", "objects"], "a": 0, "p": "A general term condenses lists."}, {"lv": 3, "q": "A 300-word article must be summarised in about 80 words. What should you prioritise?", "o": ["main argument and supporting key points", "every example and quote", "the author's biography", "the title only"], "a": 0, "p": "Keep the core ideas."}, {"lv": 3, "q": "Which sentence is the most concise?", "o": ["The meeting was cancelled due to bad weather.", "Due to the fact that the weather was bad, the meeting was cancelled by them.", "The meeting, which had been planned, was cancelled because the weather was not good at all.", "Bad weather, which was very bad, cancelled it."], "a": 0, "p": "Fewest words, same meaning."}, {"lv": 3, "q": "When summarising an argument, you should ...", "o": ["represent the writer's view accurately without adding your own opinion", "argue against it", "change the conclusion", "add jokes"], "a": 0, "p": "Summaries must be objective."}, {"lv": 3, "q": "Which detail is LEAST important in summarising a report on climate change effects?", "o": ["The reporter's favourite coffee shop", "Rising sea levels", "More extreme weather", "Melting ice caps"], "a": 0, "p": "It is irrelevant to the main topic."}]}]}, "math": {"1": [{"id": "cam-math-k1-0", "name": "Counting and numbers to 20", "desc": "Count, read, write and compare numbers", "idx": 0, "soal": [{"lv": 1, "q": "How many stars are there if you count from 1 to 5? (1, 2, 3, 4, 5)", "o": ["3", "4", "5", "6"], "a": 2, "p": "Counting the numbers sequentially: 1, 2, 3, 4, 5 gives a total of 5."}, {"lv": 1, "q": "Which number comes right after 7?", "o": ["6", "7", "8", "9"], "a": 2, "p": "When counting forward, the number that comes after 7 is 8."}, {"lv": 1, "q": "What is the number word for '10'?", "o": ["Eight", "Nine", "Ten", "Eleven"], "a": 2, "p": "The digit 10 is read and written in words as 'ten'."}, {"lv": 1, "q": "Which group has fewer items?", "o": ["3 apples", "5 apples", "Both are equal", "None"], "a": 0, "p": "3 is less than 5, so 3 apples is the smaller amount."}, {"lv": 2, "q": "Which number is greater: 12 or 15?", "o": ["12", "15", "They are equal", "Cannot be compared"], "a": 1, "p": "When comparing numbers up to 20, 15 comes after 12, so 15 is greater."}, {"lv": 2, "q": "Count backward: 15, 14, 13, ... What is the next number?", "o": ["11", "12", "14", "16"], "a": 1, "p": "Counting backward from 15: 15, 14, 13, 12."}, {"lv": 2, "q": "How is the number 14 written in words?", "o": ["Fourteen", "Forty", "Four", "Forteen"], "a": 0, "p": "The number 14 is correctly spelled as 'fourteen'."}, {"lv": 2, "q": "Which number is between 8 and 10?", "o": ["7", "9", "11", "12"], "a": 1, "p": "The number that sits directly between 8 and 10 is 9."}, {"lv": 3, "q": "Arrange these numbers from smallest to largest: 17, 9, 14, 4.", "o": ["17, 14, 9, 4", "4, 9, 14, 17", "4, 14, 9, 17", "9, 4, 14, 17"], "a": 1, "p": "Comparing all numbers, the correct ascending order is 4, 9, 14, and 17."}, {"lv": 3, "q": "Which number is less than 13 but greater than 11?", "o": ["10", "12", "14", "15"], "a": 1, "p": "The number that is strictly between 11 and 13 is 12."}, {"lv": 3, "q": "What is the missing number in this sequence: 16, 17, __, 19, 20?", "o": ["15", "18", "21", "22"], "a": 1, "p": "The sequence increases by 1 each time, so the missing number between 17 and 19 is 18."}, {"lv": 3, "q": "If you have twenty candies and give away some, which number represents twenty?", "o": ["12", "20", "2", "10"], "a": 1, "p": "The number word 'twenty' translates to the numeral 20."}]}, {"id": "cam-math-k1-1", "name": "Addition and subtraction within 20", "desc": "Number bonds and simple problems", "idx": 1, "soal": [{"lv": 1, "q": "What is 3 + 4?", "o": ["6", "7", "8", "5"], "a": 1, "p": "Count on 4 from 3: 4, 5, 6, 7."}, {"lv": 1, "q": "What is 9 − 2?", "o": ["6", "8", "7", "11"], "a": 2, "p": "Count back 2 from 9: 8, 7."}, {"lv": 1, "q": "What is 5 + 5?", "o": ["10", "9", "11", "55"], "a": 0, "p": "5 and 5 make 10 (a number bond to 10)."}, {"lv": 1, "q": "What is 6 − 6?", "o": ["12", "1", "6", "0"], "a": 3, "p": "Taking away all 6 leaves nothing: 0."}, {"lv": 2, "q": "Which pair of numbers makes 10?", "o": ["4 and 5", "3 and 7", "2 and 9", "6 and 5"], "a": 1, "p": "3 + 7 = 10."}, {"lv": 2, "q": "What is 8 + 7?", "o": ["14", "15", "16", "13"], "a": 1, "p": "8 + 2 = 10, then 10 + 5 = 15."}, {"lv": 2, "q": "What is 13 − 4?", "o": ["9", "8", "10", "7"], "a": 0, "p": "13 − 3 = 10, then 10 − 1 = 9."}, {"lv": 2, "q": "What is the missing number? 6 + ___ = 11", "o": ["4", "6", "5", "17"], "a": 2, "p": "11 − 6 = 5."}, {"lv": 3, "q": "Sam has 7 apples. He gets 6 more, then eats 2. How many apples does he have now?", "o": ["11", "13", "15", "9"], "a": 0, "p": "7 + 6 = 13, then 13 − 2 = 11."}, {"lv": 3, "q": "There are 18 birds on a tree. 9 fly away. How many birds are left?", "o": ["8", "9", "10", "27"], "a": 1, "p": "18 − 9 = 9."}, {"lv": 3, "q": "Mia has 12 stickers. Leo has 5 fewer than Mia. How many stickers does Leo have?", "o": ["17", "6", "7", "8"], "a": 2, "p": "12 − 5 = 7."}, {"lv": 3, "q": "Which number sentence is TRUE?", "o": ["9 + 6 = 16", "14 − 7 = 6", "8 + 8 = 16", "20 − 5 = 16"], "a": 2, "p": "8 + 8 = 16. The others are wrong (15, 7, 15)."}]}, {"id": "cam-math-k1-2", "name": "2D shapes", "desc": "Names and properties of flat shapes", "idx": 2, "soal": [{"lv": 1, "q": "Which shape is round and has no straight sides or corners?", "o": ["Square", "Triangle", "Circle", "Rectangle"], "a": 2, "p": "A circle is a flat shape that is completely round with no straight sides or corners."}, {"lv": 1, "q": "How many sides does a triangle have?", "o": ["2", "3", "4", "5"], "a": 1, "p": "A triangle always has 3 straight sides and 3 corners."}, {"lv": 1, "q": "Which of these shapes has four equal straight sides?", "o": ["Rectangle", "Circle", "Square", "Triangle"], "a": 2, "p": "A square is a 2D shape with four straight sides of equal length."}, {"lv": 1, "q": "What do we call the corners of a flat 2D shape?", "o": ["Vertices", "Curves", "Edges", "Faces"], "a": 0, "p": "The corners where straight sides meet on a 2D shape are called vertices (or a vertex)."}, {"lv": 2, "q": "How many corners does a rectangle have?", "o": ["3", "4", "5", "0"], "a": 1, "p": "A rectangle has 4 straight sides and 4 corners."}, {"lv": 2, "q": "Which statement is true about a rectangle compared to a square?", "o": ["A rectangle has all equal sides.", "A rectangle has opposite sides of equal length.", "A rectangle has no corners.", "A rectangle has 3 sides."], "a": 1, "p": "Unlike a square which has 4 equal sides, a rectangle has opposite sides that are equal in length."}, {"lv": 2, "q": "Which 2D shape has zero straight sides and zero corners?", "o": ["Square", "Rectangle", "Circle", "Triangle"], "a": 2, "p": "A circle is curved all the way around, so it has 0 straight sides and 0 corners."}, {"lv": 2, "q": "If you count the total number of sides on a square and a triangle together, how many sides are there?", "o": ["6", "7", "8", "9"], "a": 1, "p": "A square has 4 sides and a triangle has 3 sides. 4 + 3 = 7 sides in total."}, {"lv": 3, "q": "I am a 2D shape with fewer than 4 sides. I have pointy corners. What shape could I be?", "o": ["Square", "Circle", "Triangle", "Rectangle"], "a": 2, "p": "A triangle has 3 sides, which is fewer than 4, and it has 3 corners (vertices)."}, {"lv": 3, "q": "Sam has 2 squares and 1 triangle. How many total corners do these shapes have altogether?", "o": ["10", "11", "12", "9"], "a": 1, "p": "Each square has 4 corners (2 squares = 8 corners). A triangle has 3 corners. 8 + 3 = 11 corners in total."}, {"lv": 3, "q": "Which group of shapes all have 4 straight sides?", "o": ["Square, triangle, circle", "Square, rectangle", "Circle, triangle", "Triangle, rectangle"], "a": 1, "p": "Both squares and rectangles are four-sided flat shapes (quadrilaterals)."}, {"lv": 3, "q": "Emma draws a shape with 4 corners and 4 straight sides. Two sides are long and two sides are short. What shape did she draw?", "o": ["Circle", "Triangle", "Square", "Rectangle"], "a": 3, "p": "A rectangle has 4 straight sides and 4 corners, with opposite sides being equal (two long and two short)."}]}], "10": [{"id": "cam-math-k10-0", "name": "Algebraic manipulation and factorising", "desc": "Expanding brackets, factorising", "idx": 0, "soal": [{"lv": 1, "q": "Expand 4(2x − 3).", "o": ["8x − 12", "8x − 3", "6x − 7", "8x + 12"], "a": 0, "p": "Multiply each term by 4."}, {"lv": 1, "q": "Factorise 6x + 9.", "o": ["3(2x + 3)", "6(x + 9)", "3(2x + 9)", "9(x + 6)"], "a": 0, "p": "The HCF is 3."}, {"lv": 1, "q": "Expand (x + 2)(x + 3).", "o": ["x² + 5x + 6", "x² + 6x + 5", "x² + 6", "2x + 5"], "a": 0, "p": "x² + 3x + 2x + 6."}, {"lv": 1, "q": "Factorise x² + 5x.", "o": ["x(x + 5)", "5(x + 1)", "x(5x)", "(x + 5)²"], "a": 0, "p": "Take out the common factor x."}, {"lv": 2, "q": "Factorise x² + 7x + 12.", "o": ["(x + 3)(x + 4)", "(x + 6)(x + 2)", "(x + 12)(x + 1)", "(x − 3)(x − 4)"], "a": 0, "p": "3 × 4 = 12 and 3 + 4 = 7."}, {"lv": 2, "q": "Expand (x − 5)².", "o": ["x² − 10x + 25", "x² − 25", "x² + 25", "x² − 5x + 25"], "a": 0, "p": "(x − 5)(x − 5)."}, {"lv": 2, "q": "Factorise x² − 49.", "o": ["(x − 7)(x + 7)", "(x − 7)²", "(x − 49)(x + 1)", "x(x − 49)"], "a": 0, "p": "Difference of two squares."}, {"lv": 2, "q": "Factorise 2x² + 8x.", "o": ["2x(x + 4)", "2(x² + 8x)", "x(2x + 4)", "8x(x + 2)"], "a": 0, "p": "The HCF is 2x."}, {"lv": 3, "q": "Factorise 2x² + 7x + 3.", "o": ["(2x + 1)(x + 3)", "(2x + 3)(x + 1)", "(x + 7)(2x + 3)", "(2x − 1)(x − 3)"], "a": 0, "p": "2x² + 6x + x + 3 = 2x(x + 3) + 1(x + 3)."}, {"lv": 3, "q": "Simplify (x² − 9)/(x + 3).", "o": ["x − 3", "x + 3", "x − 9", "x² − 3"], "a": 0, "p": "(x − 3)(x + 3)/(x + 3) = x − 3."}, {"lv": 3, "q": "Factorise x² − x − 20.", "o": ["(x − 5)(x + 4)", "(x + 5)(x − 4)", "(x − 10)(x + 2)", "(x − 20)(x + 1)"], "a": 0, "p": "−5 × 4 = −20 and −5 + 4 = −1."}, {"lv": 3, "q": "Expand and simplify (2x + 1)(x − 4) − x².", "o": ["x² − 7x − 4", "x² − 4", "3x² − 7x − 4", "x² + 7x − 4"], "a": 0, "p": "2x² − 8x + x − 4 − x² = x² − 7x − 4."}]}, {"id": "cam-math-k10-1", "name": "Simultaneous equations", "desc": "Elimination and substitution", "idx": 1, "soal": [{"lv": 1, "q": "Solve: x + y = 10 and x − y = 2.", "o": ["x = 6, y = 4", "x = 4, y = 6", "x = 5, y = 5", "x = 8, y = 2"], "a": 0, "p": "Add the equations: 2x = 12 → x = 6, y = 4."}, {"lv": 1, "q": "Solve: y = 3 and x + y = 7.", "o": ["x = 4", "x = 10", "x = 3", "x = 21"], "a": 0, "p": "x = 7 − 3."}, {"lv": 1, "q": "Which method adds or subtracts equations to remove a variable?", "o": ["elimination", "substitution", "factorising", "expanding"], "a": 0, "p": "Elimination removes one variable."}, {"lv": 1, "q": "Solve: 2x = 8 and y = x + 1.", "o": ["x = 4, y = 5", "x = 8, y = 9", "x = 2, y = 3", "x = 4, y = 3"], "a": 0, "p": "x = 4, then y = 5."}, {"lv": 2, "q": "Solve: 2x + y = 11 and x + y = 7.", "o": ["x = 4, y = 3", "x = 3, y = 4", "x = 5, y = 1", "x = 2, y = 5"], "a": 0, "p": "Subtract: x = 4; then y = 3."}, {"lv": 2, "q": "Solve: y = 2x and x + y = 12.", "o": ["x = 4, y = 8", "x = 6, y = 6", "x = 8, y = 4", "x = 3, y = 9"], "a": 0, "p": "x + 2x = 12 → x = 4."}, {"lv": 2, "q": "Solve: 3x + 2y = 16 and x − 2y = 0.", "o": ["x = 4, y = 2", "x = 2, y = 4", "x = 0, y = 8", "x = 6, y = −1"], "a": 0, "p": "Add: 4x = 16 → x = 4; y = 2."}, {"lv": 2, "q": "Two numbers add to 20 and differ by 6. What are they?", "o": ["13 and 7", "14 and 6", "12 and 8", "10 and 10"], "a": 0, "p": "x + y = 20, x − y = 6 → x = 13."}, {"lv": 3, "q": "Solve: 2x + 3y = 13 and 3x + 2y = 12.", "o": ["x = 2, y = 3", "x = 3, y = 2", "x = 1, y = 4", "x = 5, y = 1"], "a": 0, "p": "×3 and ×2 then subtract: 5y = 15 → y = 3; x = 2."}, {"lv": 3, "q": "3 apples and 2 pears cost $1.30. 1 apple and 2 pears cost $0.70. What does one apple cost?", "o": ["$0.30", "$0.20", "$0.25", "$0.40"], "a": 0, "p": "Subtract: 2 apples = $0.60."}, {"lv": 3, "q": "Solve: y = x² and y = x + 2.", "o": ["(2, 4) and (−1, 1)", "(1, 1) and (2, 2)", "(2, 4) only", "(−2, 4) and (1, 1)"], "a": 0, "p": "x² − x − 2 = 0 → (x − 2)(x + 1) = 0."}, {"lv": 3, "q": "Tickets: adults $8, children $5. 10 tickets cost $68. How many adult tickets?", "o": ["6", "4", "5", "8"], "a": 0, "p": "a + c = 10; 8a + 5c = 68 → 3a = 18 → a = 6."}]}, {"id": "cam-math-k10-2", "name": "Trigonometry", "desc": "Sine, cosine, tangent in right-angled triangles", "idx": 2, "soal": [{"lv": 1, "q": "In a right-angled triangle, sin θ = ...", "o": ["opposite / hypotenuse", "adjacent / hypotenuse", "opposite / adjacent", "hypotenuse / opposite"], "a": 0, "p": "SOH."}, {"lv": 1, "q": "tan θ = ...", "o": ["opposite / adjacent", "adjacent / opposite", "opposite / hypotenuse", "adjacent / hypotenuse"], "a": 0, "p": "TOA."}, {"lv": 1, "q": "cos 60° = ...", "o": ["0.5", "1", "0", "√3/2"], "a": 0, "p": "A standard value."}, {"lv": 1, "q": "sin 30° = ...", "o": ["0.5", "√3/2", "1", "0"], "a": 0, "p": "A standard value."}, {"lv": 2, "q": "The hypotenuse is 10 cm and the angle is 30°. Find the opposite side.", "o": ["5 cm", "8.66 cm", "10 cm", "20 cm"], "a": 0, "p": "10 × sin 30° = 5."}, {"lv": 2, "q": "The adjacent side is 8 cm and the angle is 45°. Find the opposite side.", "o": ["8 cm", "4 cm", "11.3 cm", "5.66 cm"], "a": 0, "p": "tan 45° = 1, so opposite = 8."}, {"lv": 2, "q": "Opposite = 6 and hypotenuse = 12. Find θ.", "o": ["30°", "60°", "45°", "90°"], "a": 0, "p": "sin θ = 0.5 → θ = 30°."}, {"lv": 2, "q": "The adjacent side is 5 and the hypotenuse is 10. Find θ.", "o": ["60°", "30°", "45°", "50°"], "a": 0, "p": "cos θ = 0.5 → θ = 60°."}, {"lv": 3, "q": "A ladder makes a 70° angle with the ground and reaches 6 m up a wall. How long is the ladder? (sin 70° ≈ 0.94)", "o": ["6.38 m", "5.64 m", "2.05 m", "17.5 m"], "a": 0, "p": "L = 6 ÷ 0.94 ≈ 6.38 m."}, {"lv": 3, "q": "From 50 m away, the angle of elevation to the top of a tower is 40°. How tall is it? (tan 40° ≈ 0.84)", "o": ["42 m", "59.5 m", "38.3 m", "32.1 m"], "a": 0, "p": "50 × 0.84 = 42 m."}, {"lv": 3, "q": "In a right-angled triangle, the opposite side is 7 and the adjacent side is 7. What is the angle?", "o": ["45°", "30°", "60°", "90°"], "a": 0, "p": "tan θ = 1 → 45°."}, {"lv": 3, "q": "A plane climbs at 15° for 2000 m along its path. What height does it gain? (sin 15° ≈ 0.259)", "o": ["518 m", "1932 m", "7722 m", "259 m"], "a": 0, "p": "2000 × 0.259 = 518 m."}]}], "11": [{"id": "cam-math-k11-0", "name": "Quadratic equations", "desc": "Factorising, formula, completing the square", "idx": 0, "soal": [{"lv": 1, "q": "Solve x² = 25.", "o": ["x = 5 or x = −5", "x = 5 only", "x = 12.5", "x = 625"], "a": 0, "p": "Both 5² and (−5)² equal 25."}, {"lv": 1, "q": "Solve (x − 3)(x + 2) = 0.", "o": ["x = 3 or x = −2", "x = −3 or x = 2", "x = 3 or x = 2", "x = 6"], "a": 0, "p": "Set each bracket to zero."}, {"lv": 1, "q": "Solve x² − 5x = 0.", "o": ["x = 0 or x = 5", "x = 5 only", "x = −5", "x = 0 only"], "a": 0, "p": "x(x − 5) = 0."}, {"lv": 1, "q": "The quadratic formula is x = ...", "o": ["(−b ± √(b² − 4ac)) / 2a", "(b ± √(b² + 4ac)) / 2a", "−b / 2a", "(−b ± √(b² − 4ac)) / a"], "a": 0, "p": "This is the standard formula."}, {"lv": 2, "q": "Solve x² + 6x + 8 = 0.", "o": ["x = −2 or x = −4", "x = 2 or x = 4", "x = −2 or x = 4", "x = −8 or x = 1"], "a": 0, "p": "(x + 2)(x + 4) = 0."}, {"lv": 2, "q": "Solve x² − 9x + 20 = 0.", "o": ["x = 4 or x = 5", "x = −4 or x = −5", "x = 2 or x = 10", "x = 4 or x = −5"], "a": 0, "p": "(x − 4)(x − 5) = 0."}, {"lv": 2, "q": "How many real roots does x² + 4 = 0 have?", "o": ["none", "one", "two", "four"], "a": 0, "p": "x² = −4 has no real solutions."}, {"lv": 2, "q": "Write x² + 6x + 1 in the form (x + p)² + q.", "o": ["(x + 3)² − 8", "(x + 3)² + 1", "(x + 6)² − 35", "(x + 3)² + 8"], "a": 0, "p": "(x + 3)² = x² + 6x + 9, so subtract 8."}, {"lv": 3, "q": "Solve 2x² − 3x − 5 = 0.", "o": ["x = 2.5 or x = −1", "x = −2.5 or x = 1", "x = 5 or x = −1", "x = 1.5 or x = −1"], "a": 0, "p": "(2x − 5)(x + 1) = 0."}, {"lv": 3, "q": "Solve x² − 4x − 1 = 0, giving answers to 2 d.p.", "o": ["x = 4.24 or x = −0.24", "x = 2.24 or x = −2.24", "x = 4.00 or x = 1.00", "x = 3.73 or x = 0.27"], "a": 0, "p": "x = (4 ± √20)/2 = 2 ± √5."}, {"lv": 3, "q": "The discriminant of 3x² + 2x + 5 is ...", "o": ["−56, so there are no real roots", "56, so there are two roots", "0, so there is one root", "−4"], "a": 0, "p": "b² − 4ac = 4 − 60 = −56."}, {"lv": 3, "q": "A rectangle has length (x + 3) and width x. Its area is 40. Find x.", "o": ["5", "8", "−8", "4"], "a": 0, "p": "x² + 3x − 40 = 0 → (x + 8)(x − 5) = 0 → x = 5 (length must be positive)."}]}, {"id": "cam-math-k11-1", "name": "Functions and graphs", "desc": "Composite and inverse functions, gradients", "idx": 1, "soal": [{"lv": 1, "q": "If f(x) = 2x + 3, what is f(4)?", "o": ["11", "9", "14", "24"], "a": 0, "p": "2 × 4 + 3 = 11."}, {"lv": 1, "q": "What is the gradient of y = 5x − 2?", "o": ["5", "−2", "2", "−5"], "a": 0, "p": "y = mx + c, so m = 5."}, {"lv": 1, "q": "Where does y = 3x + 7 cross the y-axis?", "o": ["(0, 7)", "(7, 0)", "(0, 3)", "(3, 0)"], "a": 0, "p": "The y-intercept is c = 7."}, {"lv": 1, "q": "If g(x) = x², what is g(−3)?", "o": ["9", "−9", "6", "−6"], "a": 0, "p": "(−3)² = 9."}, {"lv": 2, "q": "If f(x) = 3x − 1, find f⁻¹(x).", "o": ["(x + 1)/3", "3x + 1", "(x − 1)/3", "1/(3x − 1)"], "a": 0, "p": "Swap x and y and rearrange."}, {"lv": 2, "q": "f(x) = x + 2 and g(x) = 3x. What is fg(x)?", "o": ["3x + 2", "3x + 6", "x + 6", "3x²"], "a": 0, "p": "fg(x) = f(3x) = 3x + 2."}, {"lv": 2, "q": "What is the gradient of the line through (1, 2) and (3, 10)?", "o": ["4", "8", "2", "0.25"], "a": 0, "p": "(10 − 2)/(3 − 1) = 4."}, {"lv": 2, "q": "Which line is parallel to y = 2x + 1?", "o": ["y = 2x − 5", "y = −2x + 1", "y = x + 2", "y = ½x"], "a": 0, "p": "Parallel lines have the same gradient."}, {"lv": 3, "q": "f(x) = 2x − 3 and g(x) = x². Find gf(2).", "o": ["1", "5", "−1", "16"], "a": 0, "p": "f(2) = 1; g(1) = 1."}, {"lv": 3, "q": "Find the gradient of y = x² at x = 3.", "o": ["6", "9", "3", "2"], "a": 0, "p": "dy/dx = 2x, so 6."}, {"lv": 3, "q": "Which value must be excluded from the domain of f(x) = 1/(x − 4)?", "o": ["x = 4", "x = 0", "x = −4", "x = 1"], "a": 0, "p": "Division by zero."}, {"lv": 3, "q": "What is the equation of the line perpendicular to y = 2x + 3 passing through (0, 1)?", "o": ["y = −½x + 1", "y = 2x + 1", "y = −2x + 1", "y = ½x + 1"], "a": 0, "p": "The perpendicular gradient is −1/2."}]}, {"id": "cam-math-k11-2", "name": "Vectors and transformations", "desc": "Column vectors, translations, reflections", "idx": 2, "soal": [{"lv": 1, "q": "Add the vectors (2, 3) + (4, −1).", "o": ["(6, 2)", "(8, −3)", "(2, 4)", "(6, 4)"], "a": 0, "p": "Add the components."}, {"lv": 1, "q": "A translation by the vector (3, −2) moves a point ...", "o": ["3 right and 2 down", "3 left and 2 up", "2 right and 3 down", "3 up and 2 right"], "a": 0, "p": "The top number is horizontal, the bottom is vertical."}, {"lv": 1, "q": "Reflect (2, 5) in the x-axis.", "o": ["(2, −5)", "(−2, 5)", "(5, 2)", "(−2, −5)"], "a": 0, "p": "The y-coordinate changes sign."}, {"lv": 1, "q": "What is 3 × (1, 4)?", "o": ["(3, 12)", "(4, 7)", "(3, 4)", "(1, 12)"], "a": 0, "p": "Multiply each component."}, {"lv": 2, "q": "What is the magnitude of the vector (3, 4)?", "o": ["5", "7", "12", "25"], "a": 0, "p": "√(9 + 16)."}, {"lv": 2, "q": "Rotate (1, 0) by 90° anticlockwise about the origin.", "o": ["(0, 1)", "(0, −1)", "(−1, 0)", "(1, 1)"], "a": 0, "p": "(x, y) → (−y, x)."}, {"lv": 2, "q": "An enlargement with scale factor 2 about the origin maps (3, 1) to ...", "o": ["(6, 2)", "(5, 3)", "(1.5, 0.5)", "(3, 2)"], "a": 0, "p": "Multiply the coordinates by 2."}, {"lv": 2, "q": "Reflect (4, 1) in the line y = x.", "o": ["(1, 4)", "(−4, 1)", "(4, −1)", "(−1, −4)"], "a": 0, "p": "Swap the coordinates."}, {"lv": 3, "q": "If a = (2, 1) and b = (−1, 3), find 2a − b.", "o": ["(5, −1)", "(3, 5)", "(1, −1)", "(5, 1)"], "a": 0, "p": "(4, 2) − (−1, 3) = (5, −1)."}, {"lv": 3, "q": "A shape is enlarged by scale factor 3. How does its area change?", "o": ["It is multiplied by 9.", "It is multiplied by 3.", "It is multiplied by 6.", "It is unchanged."], "a": 0, "p": "Area scales by k²."}, {"lv": 3, "q": "OA = (2, 5) and OB = (6, 1). Find the vector AB.", "o": ["(4, −4)", "(8, 6)", "(−4, 4)", "(4, 4)"], "a": 0, "p": "AB = OB − OA."}, {"lv": 3, "q": "Which single transformation maps (x, y) to (−x, −y)?", "o": ["rotation of 180° about the origin", "reflection in the x-axis", "reflection in y = x", "translation"], "a": 0, "p": "Both coordinates change sign."}]}], "12": [{"id": "cam-math-k12-0", "name": "Differentiation", "desc": "Derivatives, tangents, stationary points", "idx": 0, "soal": [{"lv": 1, "q": "Differentiate y = x³.", "o": ["3x²", "x²", "3x³", "x⁴/4"], "a": 0, "p": "Bring down the power and subtract 1."}, {"lv": 1, "q": "Differentiate y = 5x.", "o": ["5", "5x", "x", "0"], "a": 0, "p": "The derivative of kx is k."}, {"lv": 1, "q": "Differentiate y = 7.", "o": ["0", "7", "7x", "1"], "a": 0, "p": "Constants differentiate to 0."}, {"lv": 1, "q": "dy/dx represents ...", "o": ["the gradient of the curve", "the area under the curve", "the y-intercept", "the maximum value"], "a": 0, "p": "The rate of change."}, {"lv": 2, "q": "Differentiate y = 4x² − 3x + 2.", "o": ["8x − 3", "8x + 2", "4x − 3", "8x² − 3"], "a": 0, "p": "Term by term."}, {"lv": 2, "q": "Find the gradient of y = x² + 2x at x = 3.", "o": ["8", "15", "6", "11"], "a": 0, "p": "dy/dx = 2x + 2 = 8."}, {"lv": 2, "q": "Differentiate y = 1/x.", "o": ["−1/x²", "1/x²", "ln x", "−x"], "a": 0, "p": "x⁻¹ → −x⁻²."}, {"lv": 2, "q": "Differentiate y = √x.", "o": ["1/(2√x)", "2√x", "√x/2", "1/√x"], "a": 0, "p": "x^(1/2) → ½x^(−1/2)."}, {"lv": 3, "q": "Find the x-coordinate of the stationary point of y = x² − 6x + 5.", "o": ["3", "−3", "6", "5"], "a": 0, "p": "2x − 6 = 0 → x = 3."}, {"lv": 3, "q": "For y = x³ − 3x, which points are stationary?", "o": ["x = 1 and x = −1", "x = 0 only", "x = 3", "x = √3"], "a": 0, "p": "3x² − 3 = 0 → x = ±1."}, {"lv": 3, "q": "Find the equation of the tangent to y = x² at (2, 4).", "o": ["y = 4x − 4", "y = 2x", "y = 4x + 4", "y = x + 2"], "a": 0, "p": "Gradient 4: y − 4 = 4(x − 2)."}, {"lv": 3, "q": "For y = x³ − 3x, the stationary point at x = 1 is a ...", "o": ["minimum", "maximum", "point of inflection", "intercept"], "a": 0, "p": "d²y/dx² = 6x = 6 > 0, so it is a minimum."}]}, {"id": "cam-math-k12-1", "name": "Integration", "desc": "Indefinite and definite integrals, area", "idx": 1, "soal": [{"lv": 1, "q": "∫ 2x dx = ...", "o": ["x² + c", "2x² + c", "2 + c", "x + c"], "a": 0, "p": "Raise the power by 1 and divide by the new power."}, {"lv": 1, "q": "∫ 5 dx = ...", "o": ["5x + c", "5 + c", "0", "x⁵ + c"], "a": 0, "p": "The integral of a constant k is kx."}, {"lv": 1, "q": "Why do we add '+ c' to an indefinite integral?", "o": ["because the constant of integration is unknown", "for decoration", "to make it larger", "c is the gradient"], "a": 0, "p": "Differentiating removes constants."}, {"lv": 1, "q": "∫ x³ dx = ...", "o": ["x⁴/4 + c", "3x² + c", "x⁴ + c", "4x⁴ + c"], "a": 0, "p": "Power rule."}, {"lv": 2, "q": "Evaluate ∫₀² 3x² dx.", "o": ["8", "12", "6", "4"], "a": 0, "p": "[x³] from 0 to 2 = 8."}, {"lv": 2, "q": "∫ (6x² + 4x) dx = ...", "o": ["2x³ + 2x² + c", "12x + 4 + c", "6x³ + 4x² + c", "3x³ + 2x² + c"], "a": 0, "p": "Integrate each term."}, {"lv": 2, "q": "Evaluate ∫₁³ 2x dx.", "o": ["8", "9", "6", "4"], "a": 0, "p": "[x²] from 1 to 3 = 9 − 1."}, {"lv": 2, "q": "∫ x⁻² dx = ...", "o": ["−x⁻¹ + c", "x⁻¹ + c", "−2x⁻³ + c", "ln x + c"], "a": 0, "p": "x⁻¹ / (−1)."}, {"lv": 3, "q": "Find the area between y = x² and the x-axis from x = 0 to x = 3.", "o": ["9", "27", "3", "6"], "a": 0, "p": "[x³/3] from 0 to 3 = 9."}, {"lv": 3, "q": "dy/dx = 4x − 1 and the curve passes through (1, 3). Find y.", "o": ["y = 2x² − x + 2", "y = 2x² − x", "y = 4x² − x + 3", "y = 2x² + 2"], "a": 0, "p": "y = 2x² − x + c; 3 = 2 − 1 + c → c = 2."}, {"lv": 3, "q": "Evaluate ∫₁⁴ √x dx.", "o": ["14/3", "7", "16/3", "2"], "a": 0, "p": "[(2/3)x^(3/2)] from 1 to 4 = 16/3 − 2/3 = 14/3."}, {"lv": 3, "q": "Why does ∫₋₁¹ x³ dx = 0?", "o": ["The areas above and below the x-axis cancel out.", "x³ is always zero.", "The limits are equal.", "Integration fails."], "a": 0, "p": "x³ is an odd function."}]}, {"id": "cam-math-k12-2", "name": "Coordinate geometry and circles", "desc": "Straight lines and circle equations", "idx": 2, "soal": [{"lv": 1, "q": "What is the gradient of the line through (0, 0) and (2, 6)?", "o": ["3", "6", "2", "1/3"], "a": 0, "p": "6 ÷ 2 = 3."}, {"lv": 1, "q": "What is the midpoint of (2, 4) and (6, 8)?", "o": ["(4, 6)", "(8, 12)", "(3, 5)", "(4, 4)"], "a": 0, "p": "Average the coordinates."}, {"lv": 1, "q": "A circle has equation x² + y² = 25. What is its radius?", "o": ["5", "25", "12.5", "√5"], "a": 0, "p": "r² = 25."}, {"lv": 1, "q": "The centre of (x − 3)² + (y + 2)² = 16 is ...", "o": ["(3, −2)", "(−3, 2)", "(3, 2)", "(16, 0)"], "a": 0, "p": "Signs are opposite inside the brackets."}, {"lv": 2, "q": "What is the distance between (1, 1) and (4, 5)?", "o": ["5", "7", "25", "√7"], "a": 0, "p": "√(9 + 16)."}, {"lv": 2, "q": "Find the equation of the line with gradient 2 through (1, 3).", "o": ["y = 2x + 1", "y = 2x + 3", "y = x + 2", "y = 2x − 1"], "a": 0, "p": "y − 3 = 2(x − 1)."}, {"lv": 2, "q": "Lines with gradients m₁ and m₂ are perpendicular if ...", "o": ["m₁ × m₂ = −1", "m₁ = m₂", "m₁ + m₂ = 0", "m₁ × m₂ = 1"], "a": 0, "p": "Negative reciprocals."}, {"lv": 2, "q": "Write the equation of the circle with centre (1, 2) and radius 3.", "o": ["(x − 1)² + (y − 2)² = 9", "(x + 1)² + (y + 2)² = 9", "(x − 1)² + (y − 2)² = 3", "x² + y² = 9"], "a": 0, "p": "Standard form."}, {"lv": 3, "q": "Find the centre and radius of x² + y² − 6x + 4y − 3 = 0.", "o": ["centre (3, −2), radius 4", "centre (−3, 2), radius 4", "centre (3, −2), radius 16", "centre (6, −4), radius 3"], "a": 0, "p": "(x − 3)² + (y + 2)² = 16."}, {"lv": 3, "q": "A tangent touches the circle x² + y² = 25 at (3, 4). What is its gradient?", "o": ["−3/4", "4/3", "3/4", "−4/3"], "a": 0, "p": "The radius gradient is 4/3; the tangent is perpendicular."}, {"lv": 3, "q": "Does the point (5, 5) lie inside, on or outside the circle x² + y² = 36?", "o": ["outside", "inside", "on", "cannot tell"], "a": 0, "p": "25 + 25 = 50 > 36."}, {"lv": 3, "q": "Find the perpendicular bisector of the segment from (0, 0) to (4, 2).", "o": ["y = −2x + 5", "y = 2x − 3", "y = ½x", "y = −½x + 2"], "a": 0, "p": "Midpoint (2, 1), gradient −2: y − 1 = −2(x − 2)."}]}], "2": [{"id": "cam-math-k2-0", "name": "Place value to 100", "desc": "Tens and ones", "idx": 0, "soal": [{"lv": 1, "q": "In the number 47, what does the digit 4 stand for?", "o": ["4 ones", "4 tens", "4 hundreds", "47 tens"], "a": 1, "p": "4 is in the tens place, so it means 40."}, {"lv": 1, "q": "Which number is 6 tens and 3 ones?", "o": ["36", "63", "9", "603"], "a": 1, "p": "6 tens = 60, plus 3 ones = 63."}, {"lv": 1, "q": "Which number is bigger: 58 or 85?", "o": ["58", "85", "They are equal", "Cannot tell"], "a": 1, "p": "85 has 8 tens; 58 has only 5 tens."}, {"lv": 1, "q": "What is 10 more than 34?", "o": ["35", "44", "24", "134"], "a": 1, "p": "Adding 10 increases the tens digit by 1: 44."}, {"lv": 2, "q": "Which number is 72 written in tens and ones?", "o": ["7 tens and 2 ones", "2 tens and 7 ones", "72 tens", "70 tens and 2 ones"], "a": 0, "p": "72 = 70 + 2 = 7 tens and 2 ones."}, {"lv": 2, "q": "Put in order from smallest: 39, 93, 19, 91", "o": ["19, 39, 91, 93", "93, 91, 39, 19", "19, 91, 39, 93", "39, 19, 93, 91"], "a": 0, "p": "Compare tens first: 1, 3, 9, 9; then ones for 91 and 93."}, {"lv": 2, "q": "What is 10 less than 60?", "o": ["59", "50", "70", "6"], "a": 1, "p": "60 − 10 = 50."}, {"lv": 2, "q": "Which number is between 45 and 50?", "o": ["44", "51", "48", "54"], "a": 2, "p": "48 comes after 45 and before 50."}, {"lv": 3, "q": "I am a 2-digit number. I have 8 tens. My ones digit is 2 less than my tens digit. What number am I?", "o": ["86", "82", "68", "88"], "a": 0, "p": "Tens = 8, ones = 8 − 2 = 6, so 86."}, {"lv": 3, "q": "What is 4 tens and 15 ones?", "o": ["415", "55", "45", "19"], "a": 1, "p": "40 + 15 = 55."}, {"lv": 3, "q": "Using the digits 3 and 9 once each, what is the largest 2-digit number you can make?", "o": ["39", "93", "12", "99"], "a": 1, "p": "Put the bigger digit in the tens place: 93."}, {"lv": 3, "q": "Ali has 3 bags of 10 marbles and 7 loose marbles. Ben has 36 marbles. Who has more and by how many?", "o": ["Ali, by 1", "Ben, by 1", "They have the same", "Ali, by 7"], "a": 0, "p": "Ali has 30 + 7 = 37, which is 1 more than 36."}]}, {"id": "cam-math-k2-1", "name": "Multiplication as repeated addition", "desc": "Groups and arrays", "idx": 1, "soal": [{"lv": 1, "q": "3 groups of 2 is the same as ...", "o": ["3 + 2", "2 + 2 + 2", "3 + 3 + 3", "32"], "a": 1, "p": "3 groups of 2 means add 2 three times."}, {"lv": 1, "q": "What is 5 + 5 + 5 + 5 written as a multiplication?", "o": ["5 × 5", "4 × 5", "5 × 20", "4 + 5"], "a": 1, "p": "Four groups of 5 = 4 × 5."}, {"lv": 1, "q": "What is 2 × 5?", "o": ["7", "10", "25", "52"], "a": 1, "p": "Two groups of 5 make 10."}, {"lv": 1, "q": "An array has 2 rows with 3 dots in each row. How many dots altogether?", "o": ["5", "6", "23", "8"], "a": 1, "p": "2 × 3 = 6."}, {"lv": 2, "q": "What is 10 × 4?", "o": ["14", "40", "44", "104"], "a": 1, "p": "10 groups of 4 = 40."}, {"lv": 2, "q": "There are 5 cars. Each car has 4 wheels. How many wheels altogether?", "o": ["9", "20", "25", "16"], "a": 1, "p": "5 × 4 = 20."}, {"lv": 2, "q": "Which is the same as 3 × 5?", "o": ["5 × 3", "3 + 5", "35", "5 − 3"], "a": 0, "p": "Multiplication can be done in any order: 3 × 5 = 5 × 3 = 15."}, {"lv": 2, "q": "Count in 2s: 2, 4, 6, 8, ___", "o": ["9", "10", "12", "16"], "a": 1, "p": "Add 2 each time: 8 + 2 = 10."}, {"lv": 3, "q": "A box has 4 rows of cupcakes with 5 in each row. 3 cupcakes are eaten. How many are left?", "o": ["17", "20", "12", "23"], "a": 0, "p": "4 × 5 = 20, then 20 − 3 = 17."}, {"lv": 3, "q": "Socks come in pairs. How many socks are in 7 pairs?", "o": ["9", "14", "72", "12"], "a": 1, "p": "7 × 2 = 14."}, {"lv": 3, "q": "Which is NOT equal to 12?", "o": ["2 × 6", "3 × 4", "10 + 2", "5 × 3"], "a": 3, "p": "5 × 3 = 15, not 12."}, {"lv": 3, "q": "Lily puts 20 pencils into groups of 5. How many groups does she make?", "o": ["4", "5", "15", "100"], "a": 0, "p": "20 shared into groups of 5: 5, 10, 15, 20, which is 4 groups."}]}, {"id": "cam-math-k2-2", "name": "Measuring length and time", "desc": "Centimetres, metres, o'clock and half past", "idx": 2, "soal": [{"lv": 1, "q": "Which unit is best to measure the length of a pencil?", "o": ["metres", "centimetres", "kilograms", "litres"], "a": 1, "p": "A pencil is short, so we use centimetres."}, {"lv": 1, "q": "How many centimetres are in 1 metre?", "o": ["10", "100", "1000", "60"], "a": 1, "p": "1 m = 100 cm."}, {"lv": 1, "q": "The long hand points to 12 and the short hand points to 3. What time is it?", "o": ["12 o'clock", "3 o'clock", "half past 3", "half past 12"], "a": 1, "p": "Long hand on 12 means o'clock; the short hand shows the hour, 3."}, {"lv": 1, "q": "How many minutes are in one hour?", "o": ["30", "60", "100", "24"], "a": 1, "p": "1 hour = 60 minutes."}, {"lv": 2, "q": "The long hand points to 6 and the short hand is between 7 and 8. What time is it?", "o": ["half past 7", "half past 8", "6 o'clock", "7 o'clock"], "a": 0, "p": "Long hand on 6 means half past; the short hand has passed 7."}, {"lv": 2, "q": "A rope is 45 cm long. Another rope is 30 cm long. How much longer is the first rope?", "o": ["75 cm", "15 cm", "25 cm", "5 cm"], "a": 1, "p": "45 − 30 = 15 cm."}, {"lv": 2, "q": "Which is the longest?", "o": ["50 cm", "1 m", "90 cm", "75 cm"], "a": 1, "p": "1 m = 100 cm, which is longer than all the others."}, {"lv": 2, "q": "What time is 1 hour after 4 o'clock?", "o": ["3 o'clock", "5 o'clock", "half past 4", "4 o'clock"], "a": 1, "p": "4 + 1 = 5 o'clock."}, {"lv": 3, "q": "A film starts at 2 o'clock and lasts 2 hours. What time does it end?", "o": ["3 o'clock", "4 o'clock", "half past 2", "12 o'clock"], "a": 1, "p": "2 o'clock + 2 hours = 4 o'clock."}, {"lv": 3, "q": "Ravi's desk is 60 cm long. Two desks are put end to end. How long are they altogether?", "o": ["120 cm", "1 m 60 cm", "62 cm", "600 cm"], "a": 0, "p": "60 + 60 = 120 cm (which is 1 m 20 cm)."}, {"lv": 3, "q": "Lessons start at half past 8. Ana arrives 30 minutes early. What time does she arrive?", "o": ["8 o'clock", "9 o'clock", "half past 7", "half past 9"], "a": 0, "p": "30 minutes before half past 8 is 8 o'clock."}, {"lv": 3, "q": "A ribbon is 1 metre long. 35 cm is cut off. How much is left?", "o": ["65 cm", "75 cm", "135 cm", "35 cm"], "a": 0, "p": "100 − 35 = 65 cm."}]}], "3": [{"id": "cam-math-k3-0", "name": "Numbers to 1000", "desc": "Hundreds, tens, ones; ordering", "idx": 0, "soal": [{"lv": 1, "q": "What is the value of the digit 5 in 352?", "o": ["5", "50", "500", "5000"], "a": 1, "p": "5 is in the tens place, so it is worth 50."}, {"lv": 1, "q": "Which number is three hundred and seven?", "o": ["37", "370", "307", "3007"], "a": 2, "p": "3 hundreds, 0 tens, 7 ones = 307."}, {"lv": 1, "q": "What is 100 more than 245?", "o": ["255", "345", "246", "1245"], "a": 1, "p": "Add 1 to the hundreds digit: 345."}, {"lv": 1, "q": "Which number is the largest?", "o": ["489", "498", "894", "849"], "a": 2, "p": "894 has the most hundreds (8) and then the most tens (9)."}, {"lv": 2, "q": "Put in order, smallest first: 610, 601, 160, 106", "o": ["106, 160, 601, 610", "160, 106, 610, 601", "610, 601, 160, 106", "106, 601, 160, 610"], "a": 0, "p": "Compare hundreds, then tens."}, {"lv": 2, "q": "What is 10 less than 503?", "o": ["493", "513", "403", "502"], "a": 0, "p": "503 − 10 = 493."}, {"lv": 2, "q": "Which number is 7 hundreds, 0 tens and 4 ones?", "o": ["74", "740", "704", "7004"], "a": 2, "p": "700 + 0 + 4 = 704."}, {"lv": 2, "q": "Round 268 to the nearest ten.", "o": ["260", "270", "300", "200"], "a": 1, "p": "The ones digit is 8 (5 or more), so round up to 270."}, {"lv": 3, "q": "Which number is 1 less than 600?", "o": ["599", "601", "590", "500"], "a": 0, "p": "600 − 1 = 599."}, {"lv": 3, "q": "I am a 3-digit number. My hundreds digit is 4, my tens digit is double my hundreds digit, and my ones digit is 1. What am I?", "o": ["481", "418", "841", "248"], "a": 0, "p": "Hundreds 4, tens 8, ones 1 = 481."}, {"lv": 3, "q": "What is the largest 3-digit number you can make using 2, 9 and 5 once each?", "o": ["925", "952", "295", "592"], "a": 1, "p": "Order the digits from largest: 9, 5, 2 → 952."}, {"lv": 3, "q": "A school has 345 pupils. 100 more join in September and 10 leave. How many pupils are there now?", "o": ["435", "455", "445", "345"], "a": 0, "p": "345 + 100 = 445, then 445 − 10 = 435."}]}, {"id": "cam-math-k3-1", "name": "Multiplication and division facts", "desc": "Times tables 2-10", "idx": 1, "soal": [{"lv": 1, "q": "What is 3 × 4?", "o": ["7", "12", "34", "16"], "a": 1, "p": "3 × 4 = 12."}, {"lv": 1, "q": "What is 20 ÷ 5?", "o": ["4", "5", "15", "100"], "a": 0, "p": "5 × 4 = 20, so 20 ÷ 5 = 4."}, {"lv": 1, "q": "What is 10 × 7?", "o": ["17", "70", "77", "107"], "a": 1, "p": "10 × 7 = 70."}, {"lv": 1, "q": "What is 18 ÷ 2?", "o": ["8", "9", "16", "36"], "a": 1, "p": "2 × 9 = 18."}, {"lv": 2, "q": "What is 6 × 8?", "o": ["42", "48", "54", "56"], "a": 1, "p": "6 × 8 = 48."}, {"lv": 2, "q": "What is 56 ÷ 7?", "o": ["7", "8", "9", "6"], "a": 1, "p": "7 × 8 = 56."}, {"lv": 2, "q": "What is 9 × 9?", "o": ["72", "81", "99", "18"], "a": 1, "p": "9 × 9 = 81."}, {"lv": 2, "q": "Which multiplication fact matches 36 ÷ 4 = 9?", "o": ["4 × 9 = 36", "4 + 9 = 13", "36 × 4 = 144", "9 − 4 = 5"], "a": 0, "p": "Division is the inverse of multiplication."}, {"lv": 3, "q": "Pens come in packs of 6. Mrs Lee buys 7 packs. How many pens does she have?", "o": ["13", "42", "36", "48"], "a": 1, "p": "7 × 6 = 42."}, {"lv": 3, "q": "32 children are put into teams of 4. How many teams are there?", "o": ["8", "28", "36", "128"], "a": 0, "p": "32 ÷ 4 = 8."}, {"lv": 3, "q": "A baker puts 45 buns into boxes of 5, then sells 3 boxes. How many boxes are left?", "o": ["9", "6", "42", "8"], "a": 1, "p": "45 ÷ 5 = 9 boxes; 9 − 3 = 6."}, {"lv": 3, "q": "Which number is missing? ___ × 8 = 64", "o": ["6", "7", "8", "9"], "a": 2, "p": "8 × 8 = 64."}]}, {"id": "cam-math-k3-2", "name": "Fractions of shapes and amounts", "desc": "Halves, quarters, thirds", "idx": 2, "soal": [{"lv": 1, "q": "A pizza is cut into 2 equal parts. Each part is ...", "o": ["one half", "one third", "one quarter", "two"], "a": 0, "p": "2 equal parts = halves."}, {"lv": 1, "q": "A shape is cut into 4 equal parts. Each part is ...", "o": ["one half", "one third", "one quarter", "one fifth"], "a": 2, "p": "4 equal parts = quarters."}, {"lv": 1, "q": "What is half of 10?", "o": ["2", "5", "20", "8"], "a": 1, "p": "10 ÷ 2 = 5."}, {"lv": 1, "q": "Which fraction is one third?", "o": ["1/2", "1/3", "1/4", "3/1"], "a": 1, "p": "1/3 means 1 out of 3 equal parts."}, {"lv": 2, "q": "What is one quarter of 12?", "o": ["3", "4", "6", "48"], "a": 0, "p": "12 ÷ 4 = 3."}, {"lv": 2, "q": "What is one third of 15?", "o": ["3", "5", "45", "12"], "a": 1, "p": "15 ÷ 3 = 5."}, {"lv": 2, "q": "A cake is cut into 4 equal slices. 3 slices are eaten. What fraction is eaten?", "o": ["1/4", "3/4", "4/3", "1/3"], "a": 1, "p": "3 out of 4 equal parts = 3/4."}, {"lv": 2, "q": "Which fraction is the same as one half?", "o": ["2/4", "1/4", "3/4", "1/3"], "a": 0, "p": "2/4 = 1/2."}, {"lv": 3, "q": "What is three quarters of 20?", "o": ["5", "15", "10", "60"], "a": 1, "p": "One quarter = 5, so three quarters = 15."}, {"lv": 3, "q": "Which is bigger: 1/3 of 12 or 1/4 of 12?", "o": ["1/3 of 12", "1/4 of 12", "They are equal", "Cannot tell"], "a": 0, "p": "1/3 of 12 = 4; 1/4 of 12 = 3."}, {"lv": 3, "q": "Sara has 24 sweets. She gives half to her brother and one third of what is left to her friend. How many does she keep?", "o": ["8", "12", "4", "6"], "a": 0, "p": "Half of 24 = 12 left; a third of 12 = 4 given away; 12 − 4 = 8."}, {"lv": 3, "q": "A rope is 18 m long. Two thirds of it is used. How many metres are used?", "o": ["6 m", "9 m", "12 m", "27 m"], "a": 2, "p": "One third = 6 m, so two thirds = 12 m."}]}], "4": [{"id": "cam-math-k4-0", "name": "Place value and rounding", "desc": "Numbers to 10 000, rounding", "idx": 0, "soal": [{"lv": 1, "q": "What is the value of the digit 6 in 6435?", "o": ["6", "60", "600", "6000"], "a": 3, "p": "6 is in the thousands place: 6000."}, {"lv": 1, "q": "Which number is four thousand and twenty?", "o": ["420", "4200", "4020", "40020"], "a": 2, "p": "4000 + 20 = 4020."}, {"lv": 1, "q": "Round 47 to the nearest ten.", "o": ["40", "50", "45", "100"], "a": 1, "p": "7 is 5 or more, so round up to 50."}, {"lv": 1, "q": "What is 1000 more than 2350?", "o": ["2450", "3350", "2360", "12350"], "a": 1, "p": "Add 1 to the thousands: 3350."}, {"lv": 2, "q": "Round 3462 to the nearest hundred.", "o": ["3400", "3500", "3460", "3000"], "a": 1, "p": "Look at the tens digit (6): round up to 3500."}, {"lv": 2, "q": "Round 7849 to the nearest thousand.", "o": ["7000", "8000", "7800", "7850"], "a": 1, "p": "Look at the hundreds digit (8): round up to 8000."}, {"lv": 2, "q": "Which number is the smallest?", "o": ["5099", "5909", "5990", "5009"], "a": 3, "p": "5009 has 0 hundreds and 0 tens."}, {"lv": 2, "q": "What is 100 less than 6052?", "o": ["5952", "6042", "6152", "5052"], "a": 0, "p": "6052 − 100 = 5952."}, {"lv": 3, "q": "A number rounded to the nearest hundred is 800. Which could it be?", "o": ["749", "851", "785", "730"], "a": 2, "p": "785 rounds to 800; 749 → 700, 851 → 900, 730 → 700."}, {"lv": 3, "q": "What is the largest whole number that rounds to 2500 when rounded to the nearest hundred?", "o": ["2549", "2550", "2599", "2499"], "a": 0, "p": "2549 rounds down to 2500; 2550 rounds up to 2600."}, {"lv": 3, "q": "A stadium holds 9456 people. About how many is that to the nearest thousand?", "o": ["9000", "10 000", "9500", "9400"], "a": 0, "p": "The hundreds digit is 4, so round down to 9000."}, {"lv": 3, "q": "Which digits make the largest 4-digit even number using 3, 8, 1, 6 once each?", "o": ["8631", "8316", "8613", "6318"], "a": 2, "p": "Use the largest digits first but end with an even digit: 8613."}]}, {"id": "cam-math-k4-1", "name": "Fractions and decimals", "desc": "Equivalent fractions, tenths", "idx": 1, "soal": [{"lv": 1, "q": "What is 3/10 written as a decimal?", "o": ["3.0", "0.3", "0.03", "30"], "a": 1, "p": "3 tenths = 0.3."}, {"lv": 1, "q": "Which fraction is equivalent to 1/2?", "o": ["2/3", "3/6", "1/4", "2/5"], "a": 1, "p": "3/6 simplifies to 1/2."}, {"lv": 1, "q": "What is 0.7 as a fraction?", "o": ["7/100", "7/10", "1/7", "70/10"], "a": 1, "p": "0.7 = 7 tenths = 7/10."}, {"lv": 1, "q": "Which is larger: 0.4 or 0.6?", "o": ["0.4", "0.6", "equal", "cannot tell"], "a": 1, "p": "6 tenths is more than 4 tenths."}, {"lv": 2, "q": "Which fraction is equivalent to 2/3?", "o": ["4/6", "3/4", "2/6", "4/9"], "a": 0, "p": "Multiply top and bottom by 2: 4/6."}, {"lv": 2, "q": "Put in order from smallest: 0.9, 0.2, 0.5, 0.1", "o": ["0.1, 0.2, 0.5, 0.9", "0.9, 0.5, 0.2, 0.1", "0.2, 0.1, 0.5, 0.9", "0.1, 0.5, 0.2, 0.9"], "a": 0, "p": "Compare the tenths digits."}, {"lv": 2, "q": "What is 1/4 + 2/4?", "o": ["3/8", "3/4", "2/4", "1/2"], "a": 1, "p": "Same denominator: add the numerators to get 3/4."}, {"lv": 2, "q": "Which is equal to 1/5?", "o": ["0.5", "0.2", "0.15", "5.0"], "a": 1, "p": "1/5 = 2/10 = 0.2."}, {"lv": 3, "q": "Which fraction is NOT equivalent to 3/4?", "o": ["6/8", "9/12", "12/16", "8/12"], "a": 3, "p": "8/12 = 2/3, not 3/4."}, {"lv": 3, "q": "Sam ate 0.3 of a pizza and Maya ate 4/10. Who ate more?", "o": ["Sam", "Maya", "They ate the same", "Cannot tell"], "a": 1, "p": "4/10 = 0.4, which is more than 0.3."}, {"lv": 3, "q": "What is 1 − 0.6?", "o": ["0.4", "0.6", "1.6", "0.5"], "a": 0, "p": "1 = 10 tenths; 10 − 6 = 4 tenths = 0.4."}, {"lv": 3, "q": "A ribbon is 1 m long. 3/10 is cut off, then another 0.2 m. How much is left?", "o": ["0.5 m", "0.6 m", "0.4 m", "0.1 m"], "a": 0, "p": "0.3 + 0.2 = 0.5 m cut, so 1 − 0.5 = 0.5 m is left."}]}, {"id": "cam-math-k4-2", "name": "Area and perimeter", "desc": "Rectangles and squares", "idx": 2, "soal": [{"lv": 1, "q": "What is the perimeter of a square with sides of 5 cm?", "o": ["10 cm", "20 cm", "25 cm", "15 cm"], "a": 1, "p": "4 × 5 = 20 cm."}, {"lv": 1, "q": "What is the area of a rectangle 4 cm by 3 cm?", "o": ["7 cm²", "12 cm²", "14 cm²", "24 cm²"], "a": 1, "p": "Area = length × width = 12 cm²."}, {"lv": 1, "q": "Perimeter is ...", "o": ["the space inside a shape", "the distance all around the edge of a shape", "the height of a shape", "the number of corners"], "a": 1, "p": "Perimeter is the total length of the boundary."}, {"lv": 1, "q": "Area is measured in ...", "o": ["cm", "square units such as cm²", "kg", "litres"], "a": 1, "p": "Area uses square units."}, {"lv": 2, "q": "What is the perimeter of a rectangle 8 m by 3 m?", "o": ["11 m", "22 m", "24 m", "16 m"], "a": 1, "p": "2 × (8 + 3) = 22 m."}, {"lv": 2, "q": "A square has an area of 36 cm². How long is each side?", "o": ["9 cm", "6 cm", "18 cm", "4 cm"], "a": 1, "p": "6 × 6 = 36."}, {"lv": 2, "q": "A rectangle has an area of 40 cm² and a length of 8 cm. What is its width?", "o": ["5 cm", "32 cm", "48 cm", "4 cm"], "a": 0, "p": "40 ÷ 8 = 5 cm."}, {"lv": 2, "q": "What is the area of a square with sides of 7 m?", "o": ["28 m²", "49 m²", "14 m²", "77 m²"], "a": 1, "p": "7 × 7 = 49 m²."}, {"lv": 3, "q": "A rectangle has a perimeter of 30 cm and a length of 10 cm. What is its width?", "o": ["5 cm", "10 cm", "20 cm", "3 cm"], "a": 0, "p": "2 × (10 + w) = 30 → 10 + w = 15 → w = 5 cm."}, {"lv": 3, "q": "A garden is 12 m long and 5 m wide. Fencing costs $3 per metre. How much does it cost to fence the whole garden?", "o": ["$34", "$102", "$180", "$51"], "a": 1, "p": "Perimeter = 2 × (12 + 5) = 34 m; 34 × $3 = $102."}, {"lv": 3, "q": "Two rectangles: A is 6 cm × 4 cm, B is 8 cm × 3 cm. Which statement is true?", "o": ["They have the same area but different perimeters.", "They have the same perimeter.", "A has a larger area.", "B has a larger area."], "a": 0, "p": "Both areas are 24 cm²; perimeters are 20 cm and 22 cm."}, {"lv": 3, "q": "A floor 5 m by 4 m is covered with square tiles of 1 m². Each tile costs $8. What is the total cost?", "o": ["$20", "$160", "$72", "$180"], "a": 1, "p": "20 tiles × $8 = $160."}]}], "5": [{"id": "cam-math-k5-0", "name": "Multiplying and dividing larger numbers", "desc": "Written methods", "idx": 0, "soal": [{"lv": 1, "q": "What is 34 × 10?", "o": ["340", "3400", "44", "34"], "a": 0, "p": "Multiplying by 10 moves digits one place left."}, {"lv": 1, "q": "What is 600 ÷ 100?", "o": ["60", "6", "600", "0.6"], "a": 1, "p": "Dividing by 100 moves digits two places right."}, {"lv": 1, "q": "What is 25 × 4?", "o": ["100", "29", "80", "125"], "a": 0, "p": "25 × 4 = 100."}, {"lv": 1, "q": "What is 84 ÷ 4?", "o": ["21", "24", "20", "22"], "a": 0, "p": "80 ÷ 4 = 20 and 4 ÷ 4 = 1, so 21."}, {"lv": 2, "q": "What is 123 × 6?", "o": ["728", "738", "748", "638"], "a": 1, "p": "100×6 + 20×6 + 3×6 = 600 + 120 + 18 = 738."}, {"lv": 2, "q": "What is 47 × 23?", "o": ["1081", "1071", "981", "1181"], "a": 0, "p": "47 × 20 = 940 and 47 × 3 = 141; 940 + 141 = 1081."}, {"lv": 2, "q": "What is 945 ÷ 5?", "o": ["189", "199", "179", "190"], "a": 0, "p": "900 ÷ 5 = 180 and 45 ÷ 5 = 9; 189."}, {"lv": 2, "q": "What is 352 ÷ 8?", "o": ["44", "42", "46", "48"], "a": 0, "p": "8 × 44 = 352."}, {"lv": 3, "q": "A school buys 28 boxes of pencils. Each box has 36 pencils. How many pencils altogether?", "o": ["1008", "908", "1018", "998"], "a": 0, "p": "28 × 36 = 28 × 30 + 28 × 6 = 840 + 168 = 1008."}, {"lv": 3, "q": "475 children go on a trip. Each bus holds 45 children. How many buses are needed?", "o": ["10", "11", "12", "9"], "a": 1, "p": "475 ÷ 45 = 10 r 25, so 11 buses are needed."}, {"lv": 3, "q": "What is the remainder when 1000 is divided by 7?", "o": ["5", "6", "3", "1"], "a": 1, "p": "7 × 142 = 994; 1000 − 994 = 6."}, {"lv": 3, "q": "A farmer packs 1260 eggs into trays of 30. Each tray sells for $4. How much money does he get?", "o": ["$168", "$42", "$5040", "$160"], "a": 0, "p": "1260 ÷ 30 = 42 trays; 42 × $4 = $168."}]}, {"id": "cam-math-k5-1", "name": "Fractions, decimals and percentages", "desc": "Converting and comparing", "idx": 1, "soal": [{"lv": 1, "q": "What is 50% as a fraction?", "o": ["1/5", "1/2", "5/10", "1/50"], "a": 1, "p": "50% = 50/100 = 1/2."}, {"lv": 1, "q": "What is 0.25 as a percentage?", "o": ["2.5%", "25%", "0.25%", "250%"], "a": 1, "p": "0.25 = 25/100 = 25%."}, {"lv": 1, "q": "What is 3/4 as a decimal?", "o": ["0.34", "0.75", "0.43", "3.4"], "a": 1, "p": "3/4 = 75/100 = 0.75."}, {"lv": 1, "q": "What does 'percent' mean?", "o": ["out of 10", "out of 100", "out of 1000", "out of 50"], "a": 1, "p": "Per cent means per hundred."}, {"lv": 2, "q": "What is 10% of 80?", "o": ["8", "10", "0.8", "18"], "a": 0, "p": "10% = 1/10; 80 ÷ 10 = 8."}, {"lv": 2, "q": "Which is the largest?", "o": ["0.6", "55%", "1/2", "0.58"], "a": 0, "p": "Convert to percentages: 60%, 55%, 50%, 58%. The largest is 0.6."}, {"lv": 2, "q": "What is 2/5 as a percentage?", "o": ["25%", "40%", "20%", "52%"], "a": 1, "p": "2/5 = 4/10 = 40%."}, {"lv": 2, "q": "What is 25% of 120?", "o": ["30", "25", "40", "60"], "a": 0, "p": "25% = 1/4; 120 ÷ 4 = 30."}, {"lv": 3, "q": "A jacket costs $60. It has a 20% discount. What is the new price?", "o": ["$40", "$48", "$12", "$50"], "a": 1, "p": "20% of 60 = 12; 60 − 12 = $48."}, {"lv": 3, "q": "In a class of 25 pupils, 15 are girls. What percentage are boys?", "o": ["40%", "60%", "10%", "15%"], "a": 0, "p": "Boys = 10; 10/25 = 40/100 = 40%."}, {"lv": 3, "q": "Order from smallest: 0.45, 2/5, 48%", "o": ["2/5, 0.45, 48%", "0.45, 2/5, 48%", "48%, 0.45, 2/5", "2/5, 48%, 0.45"], "a": 0, "p": "2/5 = 0.40, then 0.45, then 0.48."}, {"lv": 3, "q": "Sam scored 18 out of 20 in a test. What is his score as a percentage?", "o": ["18%", "80%", "90%", "36%"], "a": 2, "p": "18/20 = 90/100 = 90%."}]}, {"id": "cam-math-k5-2", "name": "Angles and properties of shapes", "desc": "Acute, obtuse, right angles; triangles", "idx": 2, "soal": [{"lv": 1, "q": "An angle smaller than a right angle is called ...", "o": ["obtuse", "acute", "reflex", "straight"], "a": 1, "p": "Acute angles are less than 90°."}, {"lv": 1, "q": "How many degrees are in a right angle?", "o": ["45°", "90°", "180°", "360°"], "a": 1, "p": "A right angle measures 90°."}, {"lv": 1, "q": "An angle between 90° and 180° is ...", "o": ["acute", "obtuse", "right", "reflex"], "a": 1, "p": "Obtuse angles are greater than 90° but less than 180°."}, {"lv": 1, "q": "A triangle with all sides equal is called ...", "o": ["isosceles", "scalene", "equilateral", "right-angled"], "a": 2, "p": "Equilateral means all sides and all angles are equal."}, {"lv": 2, "q": "The angles in a triangle add up to ...", "o": ["90°", "180°", "270°", "360°"], "a": 1, "p": "Angles in any triangle sum to 180°."}, {"lv": 2, "q": "A triangle has angles of 50° and 60°. What is the third angle?", "o": ["70°", "80°", "90°", "110°"], "a": 0, "p": "180 − 50 − 60 = 70°."}, {"lv": 2, "q": "Angles on a straight line add up to ...", "o": ["90°", "180°", "360°", "100°"], "a": 1, "p": "A straight line is 180°."}, {"lv": 2, "q": "An isosceles triangle has ...", "o": ["no equal sides", "two equal sides", "four sides", "three right angles"], "a": 1, "p": "Isosceles triangles have two equal sides and two equal angles."}, {"lv": 3, "q": "An isosceles triangle has one angle of 40° between the two equal sides. What are the other two angles?", "o": ["70° and 70°", "40° and 100°", "60° and 80°", "50° and 90°"], "a": 0, "p": "180 − 40 = 140; 140 ÷ 2 = 70° each."}, {"lv": 3, "q": "Two angles on a straight line: one is 125°. What is the other?", "o": ["55°", "65°", "235°", "45°"], "a": 0, "p": "180 − 125 = 55°."}, {"lv": 3, "q": "Can a triangle have two obtuse angles?", "o": ["Yes, always", "No, because two obtuse angles already add to more than 180°", "Yes, if it is large", "Only in an equilateral triangle"], "a": 1, "p": "Two angles over 90° would sum to over 180°."}, {"lv": 3, "q": "A right-angled triangle has one angle of 35°. What is the other non-right angle?", "o": ["55°", "45°", "65°", "145°"], "a": 0, "p": "180 − 90 − 35 = 55°."}]}], "6": [{"id": "cam-math-k6-0", "name": "Ratio and proportion", "desc": "Simple ratio problems", "idx": 0, "soal": [{"lv": 1, "q": "In a bag there are 3 red and 5 blue marbles. What is the ratio of red to blue?", "o": ["5 : 3", "3 : 5", "3 : 8", "8 : 3"], "a": 1, "p": "Red first, then blue: 3 : 5."}, {"lv": 1, "q": "Simplify the ratio 6 : 9.", "o": ["2 : 3", "3 : 2", "6 : 3", "1 : 3"], "a": 0, "p": "Divide both by 3."}, {"lv": 1, "q": "If 1 pen costs $2, how much do 5 pens cost?", "o": ["$7", "$10", "$2.50", "$12"], "a": 1, "p": "5 × $2 = $10."}, {"lv": 1, "q": "Which ratio is equivalent to 1 : 4?", "o": ["2 : 8", "4 : 1", "2 : 6", "1 : 8"], "a": 0, "p": "Multiply both parts by 2."}, {"lv": 2, "q": "Share 20 sweets in the ratio 1 : 3. How many are in the larger share?", "o": ["5", "15", "10", "16"], "a": 1, "p": "4 parts → 5 each; larger share = 3 × 5 = 15."}, {"lv": 2, "q": "A recipe for 4 people uses 200 g of flour. How much flour for 6 people?", "o": ["300 g", "250 g", "400 g", "1200 g"], "a": 0, "p": "50 g per person × 6 = 300 g."}, {"lv": 2, "q": "The ratio of boys to girls is 2 : 3. There are 12 boys. How many girls?", "o": ["8", "18", "15", "30"], "a": 1, "p": "Each part = 6; girls = 3 × 6 = 18."}, {"lv": 2, "q": "Simplify 24 : 36.", "o": ["2 : 3", "4 : 6", "3 : 4", "6 : 9"], "a": 0, "p": "Divide both by 12."}, {"lv": 3, "q": "Paint is mixed red : white = 2 : 5. To make 28 litres, how much red paint is needed?", "o": ["8 L", "10 L", "20 L", "4 L"], "a": 0, "p": "7 parts = 28 L, 1 part = 4 L, red = 8 L."}, {"lv": 3, "q": "3 notebooks cost $4.50. How much do 7 notebooks cost?", "o": ["$10.50", "$9.00", "$12.00", "$31.50"], "a": 0, "p": "1 notebook = $1.50; 7 × $1.50 = $10.50."}, {"lv": 3, "q": "Ali and Ben share $60 in the ratio 3 : 2. How much more does Ali get than Ben?", "o": ["$12", "$24", "$36", "$6"], "a": 0, "p": "1 part = $12; Ali $36, Ben $24; difference $12."}, {"lv": 3, "q": "A map scale is 1 : 50 000. A distance on the map is 4 cm. What is the real distance?", "o": ["2 km", "20 km", "200 m", "0.2 km"], "a": 0, "p": "4 × 50 000 = 200 000 cm = 2 km."}]}, {"id": "cam-math-k6-1", "name": "Order of operations", "desc": "Brackets and BIDMAS", "idx": 1, "soal": [{"lv": 1, "q": "What is 2 + 3 × 4?", "o": ["20", "14", "24", "9"], "a": 1, "p": "Multiply first: 3 × 4 = 12, then 2 + 12 = 14."}, {"lv": 1, "q": "What is (2 + 3) × 4?", "o": ["14", "20", "24", "9"], "a": 1, "p": "Brackets first: 5 × 4 = 20."}, {"lv": 1, "q": "What is 10 − 6 ÷ 2?", "o": ["2", "7", "8", "5"], "a": 1, "p": "Divide first: 6 ÷ 2 = 3, then 10 − 3 = 7."}, {"lv": 1, "q": "In BIDMAS, what does the B stand for?", "o": ["Big", "Brackets", "Before", "Bottom"], "a": 1, "p": "Brackets come first."}, {"lv": 2, "q": "What is 18 ÷ 3 + 2 × 5?", "o": ["40", "16", "20", "13"], "a": 1, "p": "6 + 10 = 16."}, {"lv": 2, "q": "What is 3² + 4?", "o": ["10", "13", "49", "25"], "a": 1, "p": "Indices first: 9 + 4 = 13."}, {"lv": 2, "q": "What is (8 − 3)²?", "o": ["25", "61", "10", "55"], "a": 0, "p": "Brackets: 5, then 5² = 25."}, {"lv": 2, "q": "What is 20 − 4 × 3 + 1?", "o": ["49", "9", "7", "13"], "a": 1, "p": "4 × 3 = 12; 20 − 12 + 1 = 9."}, {"lv": 3, "q": "Where should brackets go to make 4 + 6 × 2 = 20 true?", "o": ["(4 + 6) × 2", "4 + (6 × 2)", "4 + 6 × (2)", "No brackets needed"], "a": 0, "p": "(4 + 6) × 2 = 10 × 2 = 20."}, {"lv": 3, "q": "What is 50 − (6 + 4)² ÷ 4?", "o": ["25", "10", "0", "12.5"], "a": 0, "p": "(10)² = 100; 100 ÷ 4 = 25; 50 − 25 = 25."}, {"lv": 3, "q": "Which expression equals 24?", "o": ["3 + 5 × 3", "(3 + 5) × 3", "3 × 5 + 3", "3 + 5 + 3"], "a": 1, "p": "(8) × 3 = 24."}, {"lv": 3, "q": "What is 2 × (3 + 4)² − 10?", "o": ["88", "40", "186", "90"], "a": 0, "p": "7² = 49; 2 × 49 = 98; 98 − 10 = 88."}]}, {"id": "cam-math-k6-2", "name": "Area, volume and coordinates", "desc": "Triangles, cuboids, four quadrants", "idx": 2, "soal": [{"lv": 1, "q": "What is the volume of a cuboid 2 cm × 3 cm × 4 cm?", "o": ["9 cm³", "24 cm³", "12 cm³", "20 cm³"], "a": 1, "p": "Volume = l × w × h = 24 cm³."}, {"lv": 1, "q": "The area of a triangle is ...", "o": ["base × height", "½ × base × height", "base + height", "2 × base × height"], "a": 1, "p": "A triangle is half of a rectangle."}, {"lv": 1, "q": "In the coordinate (3, 5), what is the x-coordinate?", "o": ["5", "3", "8", "15"], "a": 1, "p": "The first number is x."}, {"lv": 1, "q": "Volume is measured in ...", "o": ["cm", "cm²", "cm³", "kg"], "a": 2, "p": "Cubic units measure space."}, {"lv": 2, "q": "What is the area of a triangle with base 10 cm and height 6 cm?", "o": ["60 cm²", "30 cm²", "16 cm²", "36 cm²"], "a": 1, "p": "½ × 10 × 6 = 30 cm²."}, {"lv": 2, "q": "A cube has edges of 5 cm. What is its volume?", "o": ["25 cm³", "125 cm³", "15 cm³", "150 cm³"], "a": 1, "p": "5 × 5 × 5 = 125 cm³."}, {"lv": 2, "q": "In which quadrant is the point (−2, 4)?", "o": ["first", "second", "third", "fourth"], "a": 1, "p": "Negative x, positive y: second quadrant (top-left)."}, {"lv": 2, "q": "A point at (4, 1) is translated 3 left and 2 up. Where is it now?", "o": ["(1, 3)", "(7, 3)", "(1, −1)", "(7, −1)"], "a": 0, "p": "x: 4 − 3 = 1; y: 1 + 2 = 3."}, {"lv": 3, "q": "A tank 50 cm × 40 cm × 30 cm is full of water. How many litres does it hold? (1 litre = 1000 cm³)", "o": ["60 L", "600 L", "6 L", "6000 L"], "a": 0, "p": "50 × 40 × 30 = 60 000 cm³ = 60 L."}, {"lv": 3, "q": "A square has corners at (1, 1), (4, 1), (4, 4). Where is the fourth corner?", "o": ["(1, 4)", "(4, 1)", "(0, 4)", "(1, 5)"], "a": 0, "p": "The missing corner shares x with (1, 1) and y with (4, 4)."}, {"lv": 3, "q": "A triangle has area 24 cm² and base 8 cm. What is its height?", "o": ["3 cm", "6 cm", "12 cm", "4 cm"], "a": 1, "p": "½ × 8 × h = 24 → 4h = 24 → h = 6 cm."}, {"lv": 3, "q": "A cuboid has volume 120 cm³, length 6 cm and width 5 cm. What is its height?", "o": ["4 cm", "20 cm", "10 cm", "3 cm"], "a": 0, "p": "6 × 5 = 30; 120 ÷ 30 = 4 cm."}]}], "7": [{"id": "cam-math-k7-0", "name": "Integers and powers", "desc": "Negative numbers, squares, cubes, roots", "idx": 0, "soal": [{"lv": 1, "q": "What is −3 + 7?", "o": ["−10", "4", "10", "−4"], "a": 1, "p": "Start at −3 and move 7 to the right: 4."}, {"lv": 1, "q": "What is 5²?", "o": ["10", "25", "7", "52"], "a": 1, "p": "5 × 5 = 25."}, {"lv": 1, "q": "What is √49?", "o": ["7", "24.5", "9", "14"], "a": 0, "p": "7 × 7 = 49."}, {"lv": 1, "q": "Which is the coldest temperature?", "o": ["−2 °C", "−8 °C", "0 °C", "3 °C"], "a": 1, "p": "−8 is the smallest number."}, {"lv": 2, "q": "What is −6 × −4?", "o": ["−24", "24", "−10", "10"], "a": 1, "p": "Negative × negative = positive."}, {"lv": 2, "q": "What is 2³?", "o": ["6", "8", "9", "5"], "a": 1, "p": "2 × 2 × 2 = 8."}, {"lv": 2, "q": "What is −15 ÷ 3?", "o": ["5", "−5", "−45", "45"], "a": 1, "p": "Negative ÷ positive = negative."}, {"lv": 2, "q": "What is 4 − (−5)?", "o": ["−1", "9", "1", "−9"], "a": 1, "p": "Subtracting a negative is the same as adding: 4 + 5 = 9."}, {"lv": 3, "q": "The temperature was −4 °C at night and rose by 11 °C. What is the new temperature?", "o": ["7 °C", "−15 °C", "15 °C", "−7 °C"], "a": 0, "p": "−4 + 11 = 7."}, {"lv": 3, "q": "What is ∛64?", "o": ["4", "8", "16", "21.3"], "a": 0, "p": "4 × 4 × 4 = 64."}, {"lv": 3, "q": "Which is the value of (−2)³ + 3²?", "o": ["1", "17", "−17", "−1"], "a": 0, "p": "−8 + 9 = 1."}, {"lv": 3, "q": "Between which two whole numbers does √50 lie?", "o": ["6 and 7", "7 and 8", "8 and 9", "24 and 25"], "a": 1, "p": "7² = 49 and 8² = 64."}]}, {"id": "cam-math-k7-1", "name": "Expressions and equations", "desc": "Simplifying and solving linear equations", "idx": 1, "soal": [{"lv": 1, "q": "Simplify 3x + 5x.", "o": ["8x", "15x", "8x²", "35x"], "a": 0, "p": "Add like terms."}, {"lv": 1, "q": "Solve x + 7 = 12.", "o": ["5", "19", "84", "7"], "a": 0, "p": "x = 12 − 7 = 5."}, {"lv": 1, "q": "If a = 4, what is 3a?", "o": ["7", "12", "34", "1"], "a": 1, "p": "3 × 4 = 12."}, {"lv": 1, "q": "Solve 4x = 20.", "o": ["5", "16", "24", "80"], "a": 0, "p": "x = 20 ÷ 4."}, {"lv": 2, "q": "Simplify 5a + 3b − 2a + b.", "o": ["3a + 4b", "7a + 4b", "3a + 2b", "8ab"], "a": 0, "p": "5a − 2a = 3a; 3b + b = 4b."}, {"lv": 2, "q": "Solve 2x + 3 = 15.", "o": ["6", "9", "7.5", "4"], "a": 0, "p": "2x = 12, so x = 6."}, {"lv": 2, "q": "Expand 3(x + 4).", "o": ["3x + 4", "3x + 12", "x + 12", "3x + 7"], "a": 1, "p": "Multiply each term by 3."}, {"lv": 2, "q": "If y = 2x − 1 and x = 5, what is y?", "o": ["9", "11", "10", "4"], "a": 0, "p": "2 × 5 − 1 = 9."}, {"lv": 3, "q": "Solve 5x − 4 = 3x + 10.", "o": ["7", "3", "14", "−7"], "a": 0, "p": "2x = 14, so x = 7."}, {"lv": 3, "q": "Solve 3(x − 2) = 18.", "o": ["8", "4", "6", "20"], "a": 0, "p": "x − 2 = 6, so x = 8."}, {"lv": 3, "q": "The perimeter of a rectangle with length (x + 3) and width x is 26. Find x.", "o": ["5", "10", "6.5", "4"], "a": 0, "p": "2(2x + 3) = 26 → 4x + 6 = 26 → x = 5."}, {"lv": 3, "q": "I think of a number, double it and subtract 7. The answer is 21. What is my number?", "o": ["14", "7", "28", "10.5"], "a": 0, "p": "2n − 7 = 21 → 2n = 28 → n = 14."}]}, {"id": "cam-math-k7-2", "name": "Statistics: averages and charts", "desc": "Mean, median, mode, range", "idx": 2, "soal": [{"lv": 1, "q": "What is the mode of 3, 5, 5, 7, 9?", "o": ["5", "7", "29", "3"], "a": 0, "p": "The mode is the most frequent value."}, {"lv": 1, "q": "What is the range of 2, 8, 4, 10?", "o": ["8", "6", "10", "2"], "a": 0, "p": "10 − 2 = 8."}, {"lv": 1, "q": "What is the median of 1, 3, 4, 8, 9?", "o": ["4", "5", "3", "8"], "a": 0, "p": "The middle value when ordered."}, {"lv": 1, "q": "What is the mean of 2, 4, 6?", "o": ["4", "12", "6", "3"], "a": 0, "p": "(2 + 4 + 6) ÷ 3 = 4."}, {"lv": 2, "q": "What is the mean of 5, 7, 8, 10, 10?", "o": ["8", "10", "40", "7"], "a": 0, "p": "Sum = 40; 40 ÷ 5 = 8."}, {"lv": 2, "q": "What is the median of 6, 2, 9, 4?", "o": ["5", "6", "4", "6.5"], "a": 0, "p": "Ordered: 2, 4, 6, 9; median = (4 + 6) ÷ 2 = 5."}, {"lv": 2, "q": "Which chart is best to show how a plant's height changes over time?", "o": ["line graph", "pie chart", "pictogram of colours", "Venn diagram"], "a": 0, "p": "Line graphs show change over time."}, {"lv": 2, "q": "In a pie chart, a sector of 90° represents what fraction of the whole?", "o": ["1/2", "1/4", "1/3", "1/9"], "a": 1, "p": "90 ÷ 360 = 1/4."}, {"lv": 3, "q": "The mean of four numbers is 6. Three of them are 4, 5 and 9. What is the fourth?", "o": ["6", "8", "4", "24"], "a": 0, "p": "Total = 24; 24 − 18 = 6."}, {"lv": 3, "q": "Which average is most affected by one very large value?", "o": ["mean", "median", "mode", "none"], "a": 0, "p": "The mean uses every value, so an extreme value changes it."}, {"lv": 3, "q": "In a class survey of 30 pupils, 12 chose football. What angle is football's sector in a pie chart?", "o": ["144°", "120°", "12°", "72°"], "a": 0, "p": "12/30 × 360 = 144°."}, {"lv": 3, "q": "The mean of 5 numbers is 8. One number is removed and the mean of the remaining 4 numbers is 7. Which number was removed?", "o": ["12", "8", "1", "15"], "a": 0, "p": "Total before = 40; total after = 28; removed number = 40 − 28 = 12."}]}], "8": [{"id": "cam-math-k8-0", "name": "Fractions, decimals and percentages", "desc": "Percentage change, operations with fractions", "idx": 0, "soal": [{"lv": 1, "q": "What is 1/2 + 1/4?", "o": ["2/6", "3/4", "1/6", "2/4"], "a": 1, "p": "1/2 = 2/4; 2/4 + 1/4 = 3/4."}, {"lv": 1, "q": "What is 20% of 150?", "o": ["30", "20", "15", "300"], "a": 0, "p": "10% = 15, so 20% = 30."}, {"lv": 1, "q": "What is 2/3 × 3/5?", "o": ["2/5", "5/8", "6/8", "9/10"], "a": 0, "p": "Multiply tops and bottoms: 6/15 = 2/5."}, {"lv": 1, "q": "What is 0.35 as a percentage?", "o": ["3.5%", "35%", "0.35%", "350%"], "a": 1, "p": "Multiply by 100."}, {"lv": 2, "q": "A price rises from $40 to $50. What is the percentage increase?", "o": ["10%", "20%", "25%", "50%"], "a": 2, "p": "Increase 10; 10/40 = 25%."}, {"lv": 2, "q": "What is 3/4 ÷ 1/2?", "o": ["3/8", "1 1/2", "2/3", "1 1/4"], "a": 1, "p": "Multiply by the reciprocal: 3/4 × 2 = 6/4 = 1 1/2."}, {"lv": 2, "q": "Increase 80 by 15%.", "o": ["92", "95", "68", "120"], "a": 0, "p": "15% of 80 = 12; 80 + 12 = 92."}, {"lv": 2, "q": "What is 2 1/3 − 1 1/2?", "o": ["5/6", "1 1/6", "1/6", "1 5/6"], "a": 0, "p": "7/3 − 3/2 = 14/6 − 9/6 = 5/6."}, {"lv": 3, "q": "A laptop costs $800. Its value decreases by 25% in the first year. What is it worth after one year?", "o": ["$600", "$200", "$775", "$640"], "a": 0, "p": "25% of 800 = 200; 800 − 200 = 600."}, {"lv": 3, "q": "A population of 2000 increases by 10% each year. What is it after 2 years?", "o": ["2400", "2420", "2200", "2020"], "a": 1, "p": "2000 × 1.1 = 2200; 2200 × 1.1 = 2420."}, {"lv": 3, "q": "A shirt is sold for $36 after a 10% discount. What was the original price?", "o": ["$39.60", "$40", "$32.40", "$46"], "a": 1, "p": "90% = 36, so 100% = 40."}, {"lv": 3, "q": "Which is the largest?", "o": ["5/8", "0.62", "63%", "0.6"], "a": 2, "p": "5/8 = 0.625; 63% = 0.63 is largest."}]}, {"id": "cam-math-k8-1", "name": "Linear equations and inequalities", "desc": "Solving and representing", "idx": 1, "soal": [{"lv": 1, "q": "Solve x − 5 = 9.", "o": ["4", "14", "45", "−4"], "a": 1, "p": "x = 9 + 5."}, {"lv": 1, "q": "Which inequality means 'x is greater than 3'?", "o": ["x < 3", "x > 3", "x ≤ 3", "x = 3"], "a": 1, "p": "> means greater than."}, {"lv": 1, "q": "Solve 3x = 27.", "o": ["9", "24", "30", "81"], "a": 0, "p": "27 ÷ 3 = 9."}, {"lv": 1, "q": "Which number satisfies x < 2?", "o": ["2", "3", "1", "5"], "a": 2, "p": "1 is less than 2."}, {"lv": 2, "q": "Solve 4x − 7 = 13.", "o": ["5", "1.5", "6", "4"], "a": 0, "p": "4x = 20, x = 5."}, {"lv": 2, "q": "Solve 2x + 5 > 11.", "o": ["x > 3", "x > 8", "x < 3", "x > 16"], "a": 0, "p": "2x > 6 → x > 3."}, {"lv": 2, "q": "Solve x/4 + 2 = 5.", "o": ["12", "28", "3", "0.75"], "a": 0, "p": "x/4 = 3 → x = 12."}, {"lv": 2, "q": "List the integers that satisfy −2 < x ≤ 1.", "o": ["−1, 0, 1", "−2, −1, 0, 1", "−1, 0", "0, 1"], "a": 0, "p": "−2 is excluded and 1 is included."}, {"lv": 3, "q": "Solve 3(2x − 1) = 2(x + 5).", "o": ["13/4", "13/8", "2", "−13/4"], "a": 0, "p": "6x − 3 = 2x + 10 → 4x = 13 → x = 13/4."}, {"lv": 3, "q": "Solve 5 − 2x ≥ 11.", "o": ["x ≤ −3", "x ≥ −3", "x ≤ 3", "x ≥ 3"], "a": 0, "p": "−2x ≥ 6 → x ≤ −3 (the sign flips when dividing by a negative)."}, {"lv": 3, "q": "Two consecutive numbers add up to 47. What is the smaller number?", "o": ["23", "24", "22", "21"], "a": 0, "p": "n + n + 1 = 47 → n = 23."}, {"lv": 3, "q": "A taxi charges $3 plus $2 per km. A ride costs $19. How many km?", "o": ["8", "9.5", "11", "7"], "a": 0, "p": "3 + 2k = 19 → k = 8."}]}, {"id": "cam-math-k8-2", "name": "Area and volume of 3D shapes", "desc": "Prisms and cylinders", "idx": 2, "soal": [{"lv": 1, "q": "The volume of a prism is ...", "o": ["area of cross-section × length", "length × 2", "perimeter × height", "base + height"], "a": 0, "p": "V = A × l."}, {"lv": 1, "q": "What is the formula for the volume of a cylinder?", "o": ["πr²h", "2πr", "πd", "r²h"], "a": 0, "p": "Area of circle × height."}, {"lv": 1, "q": "A cube has side 3 cm. What is its surface area?", "o": ["27 cm²", "54 cm²", "9 cm²", "18 cm²"], "a": 1, "p": "6 faces × 9 cm² = 54 cm²."}, {"lv": 1, "q": "A triangular prism has a cross-section area of 10 cm² and length 6 cm. What is its volume?", "o": ["60 cm³", "16 cm³", "30 cm³", "600 cm³"], "a": 0, "p": "10 × 6 = 60 cm³."}, {"lv": 2, "q": "A cylinder has radius 3 cm and height 10 cm. What is its volume? (π ≈ 3.14)", "o": ["94.2 cm³", "282.6 cm³", "188.4 cm³", "90 cm³"], "a": 1, "p": "3.14 × 9 × 10 = 282.6 cm³."}, {"lv": 2, "q": "What is the surface area of a cuboid 2 cm × 3 cm × 4 cm?", "o": ["24 cm²", "52 cm²", "26 cm²", "48 cm²"], "a": 1, "p": "2(6 + 8 + 12) = 52 cm²."}, {"lv": 2, "q": "A prism's cross-section is a rectangle 4 cm × 5 cm and it is 12 cm long. Its volume is ...", "o": ["240 cm³", "21 cm³", "120 cm³", "480 cm³"], "a": 0, "p": "20 × 12 = 240 cm³."}, {"lv": 2, "q": "How many cm³ are in 1 litre?", "o": ["100", "1000", "10", "10 000"], "a": 1, "p": "1 L = 1000 cm³."}, {"lv": 3, "q": "A cylindrical tank has diameter 2 m and height 3 m. Approximately how much water does it hold? (π ≈ 3.14)", "o": ["9.42 m³", "37.68 m³", "18.84 m³", "6 m³"], "a": 0, "p": "r = 1; 3.14 × 1 × 3 = 9.42 m³."}, {"lv": 3, "q": "A triangular prism has a right-angled triangle cross-section with legs 6 cm and 8 cm, and length 10 cm. What is its volume?", "o": ["480 cm³", "240 cm³", "140 cm³", "24 cm³"], "a": 1, "p": "Area = ½ × 6 × 8 = 24; 24 × 10 = 240 cm³."}, {"lv": 3, "q": "The curved surface area of a cylinder (r = 5 cm, h = 10 cm) is ... (π ≈ 3.14)", "o": ["314 cm²", "157 cm²", "785 cm²", "471 cm²"], "a": 0, "p": "2πrh = 2 × 3.14 × 5 × 10 = 314 cm²."}, {"lv": 3, "q": "A cube has volume 125 cm³. What is its total surface area?", "o": ["150 cm²", "125 cm²", "25 cm²", "100 cm²"], "a": 0, "p": "Side = 5 cm; 6 × 25 = 150 cm²."}]}], "9": [{"id": "cam-math-k9-0", "name": "Indices and standard form", "desc": "Laws of indices, standard form", "idx": 0, "soal": [{"lv": 1, "q": "Simplify 3⁴ × 3².", "o": ["3⁶", "3⁸", "9⁶", "3²"], "a": 0, "p": "Add the powers when multiplying."}, {"lv": 1, "q": "Simplify 5⁷ ÷ 5³.", "o": ["5⁴", "5¹⁰", "1⁴", "5²¹"], "a": 0, "p": "Subtract the powers when dividing."}, {"lv": 1, "q": "What is 10⁰?", "o": ["0", "1", "10", "undefined"], "a": 1, "p": "Any non-zero number to the power 0 is 1."}, {"lv": 1, "q": "Write 3000 in standard form.", "o": ["3 × 10³", "30 × 10²", "3 × 10⁴", "0.3 × 10⁴"], "a": 0, "p": "3000 = 3 × 1000."}, {"lv": 2, "q": "Simplify (2³)².", "o": ["2⁵", "2⁶", "4⁶", "2⁹"], "a": 1, "p": "Multiply the powers."}, {"lv": 2, "q": "What is 2⁻³?", "o": ["−8", "1/8", "−6", "8"], "a": 1, "p": "A negative power means a reciprocal: 1/2³."}, {"lv": 2, "q": "Write 0.00045 in standard form.", "o": ["4.5 × 10⁻⁴", "45 × 10⁻⁵", "4.5 × 10⁴", "4.5 × 10⁻³"], "a": 0, "p": "Move the decimal 4 places right."}, {"lv": 2, "q": "What is (3 × 10⁴) × (2 × 10³)?", "o": ["6 × 10⁷", "6 × 10¹²", "5 × 10⁷", "6 × 10¹"], "a": 0, "p": "3 × 2 = 6; 10⁴ × 10³ = 10⁷."}, {"lv": 3, "q": "What is (8 × 10⁶) ÷ (4 × 10⁻²)?", "o": ["2 × 10⁸", "2 × 10⁴", "32 × 10⁴", "2 × 10⁻⁸"], "a": 0, "p": "8 ÷ 4 = 2; 10⁶ ÷ 10⁻² = 10⁸."}, {"lv": 3, "q": "What is 16^(1/2)?", "o": ["8", "4", "32", "1/16"], "a": 1, "p": "Power ½ means square root."}, {"lv": 3, "q": "Simplify (x³y²)².", "o": ["x⁶y⁴", "x⁵y⁴", "x⁶y²", "x⁹y⁴"], "a": 0, "p": "Double each power."}, {"lv": 3, "q": "The Earth's mass is about 6 × 10²⁴ kg; the Moon's is about 7.3 × 10²² kg. Roughly how many times heavier is the Earth?", "o": ["about 82", "about 8", "about 820", "about 0.8"], "a": 0, "p": "6 × 10²⁴ ÷ 7.3 × 10²² ≈ 0.82 × 10² ≈ 82."}]}, {"id": "cam-math-k9-1", "name": "Pythagoras' theorem", "desc": "Right-angled triangles", "idx": 1, "soal": [{"lv": 1, "q": "Pythagoras' theorem applies to which triangles?", "o": ["right-angled", "equilateral only", "all triangles", "obtuse only"], "a": 0, "p": "a² + b² = c² for right-angled triangles."}, {"lv": 1, "q": "In a right-angled triangle, the longest side is the ...", "o": ["hypotenuse", "base", "height", "median"], "a": 0, "p": "It is opposite the right angle."}, {"lv": 1, "q": "The sides of a right-angled triangle are 3 cm and 4 cm. What is the hypotenuse?", "o": ["5 cm", "7 cm", "12 cm", "25 cm"], "a": 0, "p": "9 + 16 = 25; √25 = 5."}, {"lv": 1, "q": "Which set of numbers can be the sides of a right-angled triangle?", "o": ["6, 8, 10", "2, 3, 4", "5, 5, 5", "1, 2, 4"], "a": 0, "p": "36 + 64 = 100."}, {"lv": 2, "q": "Find the hypotenuse when the shorter sides are 5 cm and 12 cm.", "o": ["13 cm", "17 cm", "√119 cm", "60 cm"], "a": 0, "p": "25 + 144 = 169; √169 = 13."}, {"lv": 2, "q": "The hypotenuse is 10 cm and one side is 6 cm. Find the other side.", "o": ["8 cm", "4 cm", "√136 cm", "16 cm"], "a": 0, "p": "100 − 36 = 64; √64 = 8."}, {"lv": 2, "q": "A ladder 5 m long leans against a wall with its foot 3 m from the wall. How high up the wall does it reach?", "o": ["4 m", "2 m", "8 m", "√34 m"], "a": 0, "p": "25 − 9 = 16; √16 = 4 m."}, {"lv": 2, "q": "What is the length of the diagonal of a square with side 1 m?", "o": ["√2 m", "2 m", "1 m", "0.5 m"], "a": 0, "p": "1 + 1 = 2; √2 ≈ 1.41 m."}, {"lv": 3, "q": "Find the distance between the points (1, 2) and (4, 6).", "o": ["5", "7", "√7", "25"], "a": 0, "p": "Δx = 3, Δy = 4; √(9 + 16) = 5."}, {"lv": 3, "q": "A rectangle is 8 cm by 15 cm. How long is its diagonal?", "o": ["17 cm", "23 cm", "√161 cm", "12 cm"], "a": 0, "p": "64 + 225 = 289; √289 = 17."}, {"lv": 3, "q": "A ship sails 9 km north then 12 km east. How far is it from its start?", "o": ["15 km", "21 km", "3 km", "√63 km"], "a": 0, "p": "81 + 144 = 225; √225 = 15 km."}, {"lv": 3, "q": "Is a triangle with sides 7, 24 and 25 right-angled?", "o": ["Yes, because 7² + 24² = 25²", "No", "Only if it is isosceles", "Cannot tell"], "a": 0, "p": "49 + 576 = 625 = 25²."}]}, {"id": "cam-math-k9-2", "name": "Probability", "desc": "Combined events and expected outcomes", "idx": 2, "soal": [{"lv": 1, "q": "A fair coin is flipped. What is the probability of heads?", "o": ["1/2", "1", "0", "1/4"], "a": 0, "p": "1 out of 2 equally likely outcomes."}, {"lv": 1, "q": "A fair die is rolled. What is P(6)?", "o": ["1/6", "1/2", "6", "1/3"], "a": 0, "p": "1 out of 6 outcomes."}, {"lv": 1, "q": "Probability is always between ...", "o": ["0 and 1", "1 and 10", "−1 and 1", "0 and 100 only"], "a": 0, "p": "0 = impossible, 1 = certain."}, {"lv": 1, "q": "If P(rain) = 0.3, what is P(no rain)?", "o": ["0.7", "0.3", "1.3", "0"], "a": 0, "p": "1 − 0.3 = 0.7."}, {"lv": 2, "q": "A bag has 3 red and 7 blue balls. What is P(red)?", "o": ["3/10", "3/7", "7/10", "1/3"], "a": 0, "p": "3 out of 10."}, {"lv": 2, "q": "A die is rolled. What is P(even number)?", "o": ["1/2", "1/3", "2/3", "1/6"], "a": 0, "p": "2, 4, 6 → 3/6 = 1/2."}, {"lv": 2, "q": "Two coins are flipped. What is P(two heads)?", "o": ["1/4", "1/2", "1/3", "2/4"], "a": 0, "p": "HH, HT, TH, TT → 1/4."}, {"lv": 2, "q": "A spinner has P(red) = 0.25. It is spun 200 times. About how many reds are expected?", "o": ["50", "25", "100", "75"], "a": 0, "p": "0.25 × 200 = 50."}, {"lv": 3, "q": "Two dice are rolled. What is the probability that the total is 7?", "o": ["1/6", "1/12", "7/36", "1/36"], "a": 0, "p": "6 outcomes out of 36 give 7."}, {"lv": 3, "q": "A bag has 4 red and 6 green balls. One ball is taken and NOT replaced, then another is taken. What is P(both red)?", "o": ["2/15", "4/25", "16/100", "1/5"], "a": 0, "p": "4/10 × 3/9 = 12/90 = 2/15."}, {"lv": 3, "q": "A coin is flipped and a die is rolled. What is P(heads and a number greater than 4)?", "o": ["1/6", "1/3", "1/12", "1/2"], "a": 0, "p": "1/2 × 2/6 = 1/6."}, {"lv": 3, "q": "Events A and B are mutually exclusive. P(A) = 0.2 and P(B) = 0.45. What is P(A or B)?", "o": ["0.65", "0.09", "0.25", "0.35"], "a": 0, "p": "For mutually exclusive events, add: 0.2 + 0.45."}]}]}, "sci": {"1": [{"id": "cam-sci-k1-0", "name": "Living things and the senses", "desc": "Humans and animals, five senses", "idx": 0, "soal": [{"lv": 1, "q": "Which body part do humans use to see things around them?", "o": ["Ears", "Eyes", "Nose", "Hands"], "a": 1, "p": "Humans use their eyes for the sense of sight to see objects, shapes, and colors."}, {"lv": 1, "q": "Which part of the body is used for hearing sounds?", "o": ["Mouth", "Ears", "Skin", "Nose"], "a": 1, "p": "Ears are the sensory organs used for the sense of hearing."}, {"lv": 1, "q": "How many main human senses are there?", "o": ["Three", "Four", "Five", "Six"], "a": 2, "p": "Humans have five senses: sight, hearing, smell, taste, and touch."}, {"lv": 1, "q": "Which body part do you use to smell a flower?", "o": ["Nose", "Tongue", "Eyes", "Foot"], "a": 0, "p": "The nose is used for the sense of smell."}, {"lv": 2, "q": "Which sense do you use when you eat an apple and taste its sweetness?", "o": ["Sight", "Taste", "Hearing", "Smell"], "a": 1, "p": "The tongue is the organ used for the sense of taste."}, {"lv": 2, "q": "Which body part gives you the sense of touch so you know if something is soft or hard?", "o": ["Skin", "Hair", "Teeth", "Ears"], "a": 0, "p": "Skin covers our body and provides the sense of touch."}, {"lv": 2, "q": "If you listen to music playing on a radio, which two senses are you most likely using together?", "o": ["Hearing and sight", "Taste and smell", "Touch and taste", "Smell and hearing"], "a": 0, "p": "You hear the music with your ears and can also see the radio with your eyes."}, {"lv": 2, "q": "Why are our senses important to us?", "o": ["They help us explore and understand the world around us safely.", "They only let us sleep better.", "They change the color of our eyes.", "They make us grow taller."], "a": 0, "p": "Our senses provide vital information about our environment to help us navigate and stay safe."}, {"lv": 3, "q": "If someone covers your eyes, which sense can help you recognize a ringing telephone?", "o": ["Sight", "Hearing", "Taste", "Smell"], "a": 1, "p": "Even without sight, your sense of hearing allows you to detect the sound of the telephone."}, {"lv": 3, "q": "Which animal body part is typically used by dogs to track scents much better than humans can?", "o": ["Their long tail", "Their sensitive nose", "Their sharp claws", "Their large ears"], "a": 1, "p": "Dogs have a very powerful sense of smell using their sensitive nose."}, {"lv": 3, "q": "Match the action to the correct sense: Touching a hot mug of milk.", "o": ["Sight", "Hearing", "Touch", "Taste"], "a": 2, "p": "Feeling the temperature of the mug requires the sense of touch through the skin."}, {"lv": 3, "q": "Which statement is true about living things and their senses?", "o": ["Only humans have senses, animals do not.", "Humans and many animals use their senses to find food and stay safe.", "Senses are only used during nighttime.", "We only have one sense."], "a": 1, "p": "Both humans and animals rely on their senses to interact with the environment, find food, and avoid danger."}]}, {"id": "cam-sci-k1-1", "name": "Materials and their properties", "desc": "Wood, metal, plastic, fabric", "idx": 1, "soal": [{"lv": 1, "q": "Which material is a window usually made of?", "o": ["wood", "glass", "wool", "paper"], "a": 1, "p": "Glass is transparent, so we can see through windows."}, {"lv": 1, "q": "Which object is made of metal?", "o": ["a spoon", "a T-shirt", "a pencil eraser", "a paper bag"], "a": 0, "p": "Many spoons are made of metal such as steel."}, {"lv": 1, "q": "Which material is soft?", "o": ["stone", "wool", "metal", "glass"], "a": 1, "p": "Wool is soft; we use it to make warm clothes."}, {"lv": 1, "q": "A wooden table is made from ...", "o": ["trees", "rocks", "oil", "sand"], "a": 0, "p": "Wood comes from trees."}, {"lv": 2, "q": "Which material is best for making a raincoat?", "o": ["paper", "cotton", "plastic", "wool"], "a": 2, "p": "Plastic is waterproof, so it keeps the rain out."}, {"lv": 2, "q": "Which material is transparent (you can see through it)?", "o": ["wood", "metal", "clear glass", "brick"], "a": 2, "p": "Clear glass lets light through, so it is transparent."}, {"lv": 2, "q": "Why are saucepans usually made of metal?", "o": ["Metal is soft.", "Metal is strong and heat passes through it easily.", "Metal is see-through.", "Metal floats on water."], "a": 1, "p": "Metal conducts heat well and is strong, so it is good for cooking."}, {"lv": 2, "q": "Which material is bendy (flexible)?", "o": ["a rubber band", "a glass bottle", "a brick", "a stone"], "a": 0, "p": "Rubber can bend and stretch."}, {"lv": 3, "q": "Why would a chocolate teapot be a bad idea?", "o": ["Chocolate is too heavy.", "Chocolate melts when hot tea is poured in.", "Chocolate is see-through.", "Chocolate is made of metal."], "a": 1, "p": "Hot liquid would melt the chocolate."}, {"lv": 3, "q": "Sara wants to build a strong house that will not blow down in the wind. Which material is best?", "o": ["straw", "paper", "bricks", "cotton"], "a": 2, "p": "Bricks are strong and heavy, so they stand up to wind."}, {"lv": 3, "q": "Which group contains only materials that are waterproof?", "o": ["plastic, rubber, glass", "paper, cotton, wool", "wood, paper, plastic", "fabric, sponge, rubber"], "a": 0, "p": "Plastic, rubber and glass do not let water through."}, {"lv": 3, "q": "Tom tests which material soaks up the most water. Which material will soak up the MOST?", "o": ["plastic", "a kitchen sponge", "metal foil", "glass"], "a": 1, "p": "A sponge has many holes that soak up water; it is absorbent."}]}, {"id": "cam-sci-k1-2", "name": "Forces: pushes and pulls", "desc": "Moving and changing shape", "idx": 2, "soal": [{"lv": 1, "q": "What do you apply to open a door that says 'Push'?", "o": ["A pull", "A push", "A twist", "A lift"], "a": 1, "p": "A push is a force that moves something away from you, which is used to open a push door."}, {"lv": 1, "q": "When you pull a toy wagon towards you, what kind of force are you using?", "o": ["A push", "A pull", "A jump", "A spin"], "a": 1, "p": "A pull is a force that brings an object closer to you."}, {"lv": 1, "q": "Which of these actions uses a push?", "o": ["Kicking a football", "Pulling a drawer open", "Pulling a rope in tug-of-war", "Lifting a heavy bag"], "a": 0, "p": "Kicking a football involves pushing it away with your foot."}, {"lv": 1, "q": "What does a force do to an object?", "o": ["It can make it move, stop, or change shape.", "It only makes it change color.", "It only makes it heavier.", "It does nothing."], "a": 0, "p": "Forces can make stationary objects move, slow down moving objects, stop them, or change their shape."}, {"lv": 2, "q": "If you squeeze a soft sponge with your hands, what does the force do?", "o": ["It changes the shape of the sponge.", "It makes the sponge fly.", "It makes the sponge disappear.", "It cools the sponge down."], "a": 0, "p": "Applying a pushing force by squeezing changes the shape of a soft object like a sponge."}, {"lv": 2, "q": "What happens when you roll a toy car and then gently press your hand in front of it?", "o": ["The car speeds up.", "The car slows down and stops.", "The car changes color.", "The car floats."], "a": 1, "p": "Applying a force against the direction of motion slows down and stops the car."}, {"lv": 2, "q": "Which action is an example of pulling?", "o": ["Closing a drawer", "Opening a drawer", "Pressing a computer key", "Pedaling a bicycle forward"], "a": 1, "p": "Opening a drawer requires pulling it towards you."}, {"lv": 2, "q": "Why do things move when we push or pull them?", "o": ["Because pushes and pulls are forces that can cause movement.", "Because objects want to run away.", "Because the air pushes us.", "Because of magic."], "a": 0, "p": "Pushes and pulls are forces that cause objects to start moving."}, {"lv": 3, "q": "Look at a game of tug-of-war. Both teams are pulling the rope in opposite directions. What kind of force are they using?", "o": ["Pushing force", "Pulling force", "No force at all", "Blowing force"], "a": 1, "p": "Tug-of-war relies entirely on pulling forces exerted by each team."}, {"lv": 3, "q": "If you push a swing when it is moving away from you, what happens to the swing?", "o": ["It goes faster and higher.", "It stops immediately.", "It turns into a slide.", "It gets heavier."], "a": 0, "p": "Adding a push in the direction the swing is moving makes it go faster and higher."}, {"lv": 3, "q": "Which of these materials will change shape most easily when you apply a pushing force with your fingers?", "o": ["A solid wooden block", "A metal spoon", "A piece of modelling clay", "A glass marble"], "a": 2, "p": "Modelling clay is soft and easily changes shape when squeezed or pushed."}, {"lv": 3, "q": "What happens when you kick a moving football in the same direction it is rolling?", "o": ["The ball speeds up.", "The ball stops immediately.", "The ball turns into a square.", "The ball disappears."], "a": 0, "p": "Applying a force in the direction of travel increases the speed of the object."}]}], "10": [{"id": "cam-sci-k10-0", "name": "Biology: Transport in plants and animals", "desc": "Xylem, phloem, heart and vessels", "idx": 0, "soal": [{"lv": 1, "q": "Xylem transports ...", "o": ["water and minerals", "sugars", "blood", "oxygen in animals"], "a": 0, "p": "Xylem carries water up from the roots."}, {"lv": 1, "q": "Phloem transports ...", "o": ["sugars (sucrose) and amino acids", "water only", "minerals only", "carbon dioxide"], "a": 0, "p": "This is called translocation."}, {"lv": 1, "q": "The blood vessel that carries blood from the heart to the body is the ...", "o": ["aorta", "vena cava", "pulmonary vein", "capillary"], "a": 0, "p": "The aorta is the main artery."}, {"lv": 1, "q": "Transpiration is ...", "o": ["loss of water vapour from leaves", "uptake of sugar", "movement of blood", "photosynthesis"], "a": 0, "p": "Water evaporates through stomata."}, {"lv": 2, "q": "Which factor increases the rate of transpiration?", "o": ["high temperature", "high humidity", "no wind", "darkness"], "a": 0, "p": "Warmth increases evaporation."}, {"lv": 2, "q": "Root hair cells are adapted for absorption because they have ...", "o": ["a large surface area", "chloroplasts", "a thick cuticle", "no cell membrane"], "a": 0, "p": "A long extension increases the surface area."}, {"lv": 2, "q": "Which vessel carries deoxygenated blood to the lungs?", "o": ["pulmonary artery", "pulmonary vein", "aorta", "vena cava"], "a": 0, "p": "An exception: an artery carrying deoxygenated blood."}, {"lv": 2, "q": "Valves in the heart and veins ...", "o": ["prevent backflow of blood", "make blood", "carry oxygen", "pump air"], "a": 0, "p": "They keep flow in one direction."}, {"lv": 3, "q": "Coronary heart disease is caused by ...", "o": ["fatty deposits blocking coronary arteries", "too much water", "white blood cells", "excess oxygen"], "a": 0, "p": "It reduces blood supply to the heart muscle."}, {"lv": 3, "q": "A potometer measures ...", "o": ["the rate of water uptake by a plant", "heart rate", "blood pressure", "light intensity"], "a": 0, "p": "It approximates transpiration rate."}, {"lv": 3, "q": "Why do arteries have thick, elastic walls?", "o": ["to withstand and maintain high blood pressure", "to absorb nutrients", "to allow diffusion", "to store blood"], "a": 0, "p": "Blood leaves the heart under high pressure."}, {"lv": 3, "q": "Why does wilting occur on a hot, windy day?", "o": ["The rate of transpiration exceeds the rate of water uptake.", "Too much water is absorbed.", "Photosynthesis increases.", "Phloem stops working."], "a": 0, "p": "Cells lose turgor."}]}, {"id": "cam-sci-k10-1", "name": "Chemistry: Acids, bases and salts", "desc": "pH, neutralisation, indicators", "idx": 1, "soal": [{"lv": 1, "q": "An acid has a pH ...", "o": ["less than 7", "of 7", "greater than 7", "of 14"], "a": 0, "p": "Acids have pH < 7."}, {"lv": 1, "q": "Acid + base → ?", "o": ["salt + water", "hydrogen only", "oxygen", "metal"], "a": 0, "p": "Neutralisation."}, {"lv": 1, "q": "Which is an alkali?", "o": ["sodium hydroxide", "hydrochloric acid", "sulfuric acid", "vinegar"], "a": 0, "p": "A soluble base."}, {"lv": 1, "q": "Universal indicator in a neutral solution turns ...", "o": ["green", "red", "purple", "yellow"], "a": 0, "p": "pH 7 is green."}, {"lv": 2, "q": "Hydrochloric acid + sodium hydroxide → ?", "o": ["sodium chloride + water", "sodium + chlorine", "hydrogen + oxygen", "sodium hydrogen"], "a": 0, "p": "This forms a salt and water."}, {"lv": 2, "q": "Which salt is made from sulfuric acid?", "o": ["a sulfate", "a chloride", "a nitrate", "a carbonate"], "a": 0, "p": "Sulfuric acid gives sulfates."}, {"lv": 2, "q": "Metal carbonate + acid → salt + water + ?", "o": ["carbon dioxide", "hydrogen", "oxygen", "nitrogen"], "a": 0, "p": "Fizzing shows CO₂."}, {"lv": 2, "q": "Acids in solution produce which ion?", "o": ["H⁺", "OH⁻", "Na⁺", "Cl⁻"], "a": 0, "p": "H⁺ ions make solutions acidic."}, {"lv": 3, "q": "How would you make pure, dry copper(II) sulfate crystals from copper(II) oxide?", "o": ["Add excess oxide to warm sulfuric acid, filter, evaporate and crystallise.", "Mix oxide with water and boil dry.", "Add copper to water.", "Heat copper sulfate strongly."], "a": 0, "p": "Use an insoluble base with acid, then filter and crystallise."}, {"lv": 3, "q": "The ionic equation for neutralisation is ...", "o": ["H⁺ + OH⁻ → H₂O", "Na⁺ + Cl⁻ → NaCl", "H₂ + O₂ → H₂O", "OH⁻ → O₂"], "a": 0, "p": "Spectator ions cancel."}, {"lv": 3, "q": "Why is titration used to make soluble salts from an alkali?", "o": ["to find the exact volumes needed for complete neutralisation", "to heat the solution", "to make gas", "to remove water"], "a": 0, "p": "Excess alkali cannot be filtered off."}, {"lv": 3, "q": "A weak acid differs from a strong acid because it ...", "o": ["only partially ionises in water", "is always more dilute", "has a higher pH regardless of concentration", "does not react"], "a": 0, "p": "Strength refers to the degree of ionisation."}]}, {"id": "cam-sci-k10-2", "name": "Physics: Motion, forces and energy", "desc": "Newton's laws, work, power", "idx": 2, "soal": [{"lv": 1, "q": "Newton's first law says an object stays at rest or constant velocity unless ...", "o": ["acted on by a resultant force", "it is heavy", "it is cold", "it is moving"], "a": 0, "p": "This is inertia."}, {"lv": 1, "q": "F = m × a. What is the unit of force?", "o": ["newton", "joule", "watt", "pascal"], "a": 0, "p": "1 N = 1 kg m/s²."}, {"lv": 1, "q": "Work done = ...", "o": ["force × distance", "mass × speed", "power × force", "force ÷ time"], "a": 0, "p": "W = F × d."}, {"lv": 1, "q": "Power is the rate of ...", "o": ["doing work (energy transfer)", "speed change", "force", "mass"], "a": 0, "p": "P = W / t."}, {"lv": 2, "q": "A 2 kg mass accelerates at 3 m/s². What is the resultant force?", "o": ["6 N", "1.5 N", "5 N", "0.67 N"], "a": 0, "p": "F = 2 × 3."}, {"lv": 2, "q": "A force of 50 N moves a box 4 m. How much work is done?", "o": ["200 J", "12.5 J", "54 J", "46 J"], "a": 0, "p": "W = 50 × 4."}, {"lv": 2, "q": "A motor does 600 J of work in 20 s. What is its power?", "o": ["30 W", "12 000 W", "580 W", "620 W"], "a": 0, "p": "P = 600 ÷ 20."}, {"lv": 2, "q": "What is the kinetic energy of a 4 kg object moving at 5 m/s?", "o": ["50 J", "20 J", "100 J", "10 J"], "a": 0, "p": "½ × 4 × 25 = 50 J."}, {"lv": 3, "q": "A 1000 kg car accelerates from 0 to 20 m/s in 10 s. What is the resultant force?", "o": ["2000 N", "200 N", "20 000 N", "10 000 N"], "a": 0, "p": "a = 2 m/s²; F = 1000 × 2."}, {"lv": 3, "q": "A 5 kg mass is lifted 3 m (g = 10 N/kg). What gravitational potential energy is gained?", "o": ["150 J", "15 J", "50 J", "1.5 J"], "a": 0, "p": "mgh = 5 × 10 × 3."}, {"lv": 3, "q": "Momentum of a 3 kg ball moving at 4 m/s is ...", "o": ["12 kg m/s", "7 kg m/s", "0.75 kg m/s", "48 kg m/s"], "a": 0, "p": "p = mv."}, {"lv": 3, "q": "A 2 kg ball falls from 5 m (g = 10 N/kg). Ignoring air resistance, what is its speed just before impact?", "o": ["10 m/s", "5 m/s", "100 m/s", "20 m/s"], "a": 0, "p": "mgh = ½mv² → 100 = v² → v = 10."}]}], "11": [{"id": "cam-sci-k11-0", "name": "Biology: Inheritance and DNA", "desc": "Genetic crosses, mitosis, meiosis", "idx": 0, "soal": [{"lv": 1, "q": "Mitosis produces ...", "o": ["two genetically identical cells", "four different cells", "gametes", "one cell"], "a": 0, "p": "It is used for growth and repair."}, {"lv": 1, "q": "Meiosis produces ...", "o": ["gametes with half the number of chromosomes", "identical body cells", "two cells", "skin cells only"], "a": 0, "p": "It is needed for sexual reproduction."}, {"lv": 1, "q": "An allele that is always expressed when present is ...", "o": ["dominant", "recessive", "mutant", "neutral"], "a": 0, "p": "Dominant alleles show in the phenotype."}, {"lv": 1, "q": "The genetic makeup of an organism (e.g. Bb) is its ...", "o": ["genotype", "phenotype", "gene pool", "karyotype"], "a": 0, "p": "The phenotype is the observable trait."}, {"lv": 2, "q": "Bb × bb. What proportion of the offspring show the recessive phenotype?", "o": ["50%", "25%", "75%", "0%"], "a": 0, "p": "Bb, Bb, bb, bb → 2/4."}, {"lv": 2, "q": "An organism with two identical alleles (BB or bb) is ...", "o": ["homozygous", "heterozygous", "a mutant", "diploid only"], "a": 0, "p": "Homo = same."}, {"lv": 2, "q": "DNA bases pair as ...", "o": ["A–T and C–G", "A–C and T–G", "A–G and C–T", "A–A and T–T"], "a": 0, "p": "Complementary base pairing."}, {"lv": 2, "q": "Why is meiosis important?", "o": ["It halves chromosome number and creates variation.", "It repairs skin.", "It makes identical cells.", "It digests food."], "a": 0, "p": "Fertilisation then restores the diploid number."}, {"lv": 3, "q": "In humans, blood group alleles IA and IB are codominant. A parent IAIO and a parent IBIO could have a child with blood group ...", "o": ["A, B, AB or O", "only AB", "only A or B", "only O"], "a": 0, "p": "Possible genotypes: IAIB, IAIO, IBIO, IOIO."}, {"lv": 3, "q": "A test cross of a tall plant (T?) with a short plant (tt) gives all tall offspring. The tall parent is ...", "o": ["homozygous dominant (TT)", "heterozygous (Tt)", "homozygous recessive (tt)", "cannot be determined"], "a": 0, "p": "If it were Tt, about half the offspring would be short."}, {"lv": 3, "q": "A sex-linked recessive condition affects more males than females because ...", "o": ["males have only one X chromosome", "males have two X chromosomes", "females have a Y chromosome", "it is caused by diet"], "a": 0, "p": "One recessive allele on X is enough in males."}, {"lv": 3, "q": "Which process produces genetic variation during meiosis?", "o": ["independent assortment and crossing over", "binary fission", "mitosis only", "osmosis"], "a": 0, "p": "Both shuffle alleles."}]}, {"id": "cam-sci-k11-1", "name": "Chemistry: Organic chemistry", "desc": "Alkanes, alkenes, alcohols", "idx": 1, "soal": [{"lv": 1, "q": "Alkanes have the general formula ...", "o": ["CₙH₂ₙ₊₂", "CₙH₂ₙ", "CₙH₂ₙ₊₁OH", "CₙHₙ"], "a": 0, "p": "They are saturated hydrocarbons."}, {"lv": 1, "q": "Alkenes contain a ...", "o": ["C=C double bond", "C≡C triple bond", "–OH group", "–COOH group"], "a": 0, "p": "Alkenes are unsaturated."}, {"lv": 1, "q": "Ethanol belongs to which family?", "o": ["alcohols", "alkanes", "alkenes", "carboxylic acids"], "a": 0, "p": "It has an –OH group."}, {"lv": 1, "q": "Methane's formula is ...", "o": ["CH₄", "C₂H₆", "C₂H₄", "CH₃OH"], "a": 0, "p": "The simplest alkane."}, {"lv": 2, "q": "Which test distinguishes an alkene from an alkane?", "o": ["bromine water decolourises with an alkene", "limewater turns milky", "a glowing splint relights", "litmus turns blue"], "a": 0, "p": "Addition across C=C."}, {"lv": 2, "q": "Ethene + steam (with a catalyst) → ?", "o": ["ethanol", "ethane", "ethanoic acid", "methane"], "a": 0, "p": "Hydration of ethene."}, {"lv": 2, "q": "Complete combustion of an alkane produces ...", "o": ["carbon dioxide and water", "carbon monoxide only", "hydrogen", "soot only"], "a": 0, "p": "With plenty of oxygen."}, {"lv": 2, "q": "Cracking is used to ...", "o": ["break long-chain hydrocarbons into shorter, more useful ones", "join molecules", "make water", "remove oxygen"], "a": 0, "p": "Produces fuels and alkenes."}, {"lv": 3, "q": "What is the formula of propene?", "o": ["C₃H₆", "C₃H₈", "C₃H₇OH", "C₂H₄"], "a": 0, "p": "CₙH₂ₙ with n = 3."}, {"lv": 3, "q": "Addition polymerisation of ethene forms ...", "o": ["poly(ethene)", "ethanol", "ethane", "polyester"], "a": 0, "p": "Many monomers join."}, {"lv": 3, "q": "Isomers have the same ...", "o": ["molecular formula but different structures", "structure and formula", "boiling point always", "mass number only"], "a": 0, "p": "For example, butane and methylpropane."}, {"lv": 3, "q": "Ethanol made by fermentation needs ...", "o": ["yeast, glucose, warmth and no oxygen", "high pressure and a catalyst", "UV light", "bromine"], "a": 0, "p": "Anaerobic yeast at about 30–40 °C."}]}, {"id": "cam-sci-k11-2", "name": "Physics: Electricity and magnetism", "desc": "Electromagnetic induction, motors", "idx": 2, "soal": [{"lv": 1, "q": "An electric current produces a ...", "o": ["magnetic field", "sound wave", "light ray", "gravity field"], "a": 0, "p": "As shown by Oersted's experiment."}, {"lv": 1, "q": "An electromagnet can be made stronger by ...", "o": ["increasing the current", "using a plastic core", "reducing the coils", "using a copper core"], "a": 0, "p": "More current and more turns help."}, {"lv": 1, "q": "Electromagnetic induction produces ...", "o": ["a voltage (EMF)", "light", "heat only", "friction"], "a": 0, "p": "When a conductor cuts magnetic field lines."}, {"lv": 1, "q": "A transformer works with ...", "o": ["alternating current (a.c.)", "direct current only", "batteries only", "static charge"], "a": 0, "p": "A changing field is needed."}, {"lv": 2, "q": "In a motor, a current-carrying coil in a magnetic field experiences ...", "o": ["a force that makes it turn", "no force", "a voltage only", "heat only"], "a": 0, "p": "This is the motor effect."}, {"lv": 2, "q": "Fleming's left-hand rule gives the direction of the ...", "o": ["force on a current-carrying wire", "induced current", "magnetic field of Earth", "voltage"], "a": 0, "p": "Used for motors."}, {"lv": 2, "q": "How can the induced voltage in a generator be increased?", "o": ["spin it faster", "spin it slower", "use fewer coils", "use a weaker magnet"], "a": 0, "p": "A faster rate of change gives more EMF."}, {"lv": 2, "q": "A step-up transformer ...", "o": ["increases voltage", "decreases voltage", "makes d.c.", "stores energy"], "a": 0, "p": "More turns on the secondary coil."}, {"lv": 3, "q": "A transformer has 100 primary turns and 500 secondary turns. The input is 20 V. What is the output?", "o": ["100 V", "4 V", "20 V", "520 V"], "a": 0, "p": "Vs/Vp = Ns/Np → 20 × 5."}, {"lv": 3, "q": "Why is electricity transmitted at high voltage?", "o": ["to reduce current and energy lost as heat in cables", "to make it faster", "because homes need high voltage", "to increase resistance"], "a": 0, "p": "P = I²R loss is smaller."}, {"lv": 3, "q": "In a 100% efficient transformer, Vp = 240 V, Ip = 0.5 A and Vs = 12 V. Find Is.", "o": ["10 A", "0.025 A", "5 A", "20 A"], "a": 0, "p": "VpIp = VsIs → 120 = 12 × Is."}, {"lv": 3, "q": "A magnet is pushed into a coil, then held still. What happens to the induced current?", "o": ["It flows while the magnet moves, then stops.", "It flows constantly.", "It never flows.", "It reverses continuously."], "a": 0, "p": "A changing field is needed."}]}], "12": [{"id": "cam-sci-k12-0", "name": "Physics: Kinematics and dynamics", "desc": "SUVAT equations, momentum", "idx": 0, "soal": [{"lv": 1, "q": "Which SUVAT equation has no time (t)?", "o": ["v² = u² + 2as", "v = u + at", "s = ut + ½at²", "s = ½(u + v)t"], "a": 0, "p": "It links v, u, a and s."}, {"lv": 1, "q": "Acceleration is the rate of change of ...", "o": ["velocity", "distance", "mass", "force"], "a": 0, "p": "a = Δv/Δt."}, {"lv": 1, "q": "Momentum = ...", "o": ["mass × velocity", "mass × acceleration", "force × distance", "½mv²"], "a": 0, "p": "p = mv."}, {"lv": 1, "q": "Newton's third law says ...", "o": ["every action has an equal and opposite reaction", "F = ma", "objects stay at rest", "energy is conserved"], "a": 0, "p": "Force pairs act on different objects."}, {"lv": 2, "q": "A car accelerates from 10 m/s to 30 m/s in 5 s. What is its acceleration?", "o": ["4 m/s²", "8 m/s²", "2 m/s²", "6 m/s²"], "a": 0, "p": "(30 − 10)/5."}, {"lv": 2, "q": "An object starts from rest with a = 2 m/s². How far does it go in 4 s?", "o": ["16 m", "8 m", "32 m", "4 m"], "a": 0, "p": "s = ½ × 2 × 16."}, {"lv": 2, "q": "A ball is dropped from rest. What is its speed after falling 20 m? (g = 10 m/s²)", "o": ["20 m/s", "10 m/s", "200 m/s", "40 m/s"], "a": 0, "p": "v² = 2 × 10 × 20 = 400."}, {"lv": 2, "q": "Impulse is equal to ...", "o": ["change in momentum", "change in energy", "mass × distance", "power"], "a": 0, "p": "FΔt = Δp."}, {"lv": 3, "q": "A 2 kg ball at 3 m/s collides with and sticks to a stationary 1 kg ball. What is their common velocity?", "o": ["2 m/s", "3 m/s", "1 m/s", "6 m/s"], "a": 0, "p": "6 = 3v → v = 2 m/s."}, {"lv": 3, "q": "A projectile is launched horizontally at 15 m/s from a height of 45 m. How far does it travel horizontally? (g = 10 m/s²)", "o": ["45 m", "30 m", "90 m", "15 m"], "a": 0, "p": "t = √(2 × 45/10) = 3 s; 15 × 3 = 45 m."}, {"lv": 3, "q": "In an elastic collision, which quantities are conserved?", "o": ["momentum and kinetic energy", "momentum only", "kinetic energy only", "neither"], "a": 0, "p": "Elastic means no KE is lost."}, {"lv": 3, "q": "A 1500 kg car brakes from 20 m/s to rest over 40 m. What is the average braking force?", "o": ["7500 N", "750 N", "30 000 N", "15 000 N"], "a": 0, "p": "a = 400/80 = 5 m/s²; F = 1500 × 5."}]}, {"id": "cam-sci-k12-1", "name": "Chemistry: Chemical energetics", "desc": "Enthalpy changes, Hess's law", "idx": 1, "soal": [{"lv": 1, "q": "An exothermic reaction ...", "o": ["releases energy to the surroundings", "absorbs energy", "has ΔH > 0", "makes surroundings colder"], "a": 0, "p": "ΔH is negative."}, {"lv": 1, "q": "An endothermic reaction has ΔH that is ...", "o": ["positive", "negative", "zero", "undefined"], "a": 0, "p": "Energy is taken in."}, {"lv": 1, "q": "Combustion of fuels is ...", "o": ["exothermic", "endothermic", "neither", "only nuclear"], "a": 0, "p": "It releases heat."}, {"lv": 1, "q": "Standard conditions for enthalpy are ...", "o": ["298 K and 100 kPa", "0 K and 1 atm", "373 K and 50 kPa", "any temperature"], "a": 0, "p": "25 °C and 1 bar."}, {"lv": 2, "q": "Bond breaking is ...", "o": ["endothermic", "exothermic", "neither", "always fast"], "a": 0, "p": "Energy is needed to break bonds."}, {"lv": 2, "q": "q = mcΔT. Heating 100 g of water by 10 °C (c = 4.18 J g⁻¹ K⁻¹) needs ...", "o": ["4180 J", "418 J", "41.8 J", "41 800 J"], "a": 0, "p": "100 × 4.18 × 10."}, {"lv": 2, "q": "Hess's law states that ...", "o": ["the enthalpy change is independent of the route taken", "energy is created", "reactions are always exothermic", "rate depends on temperature"], "a": 0, "p": "Conservation of energy."}, {"lv": 2, "q": "The standard enthalpy of formation of an element in its standard state is ...", "o": ["0", "positive", "negative", "100 kJ/mol"], "a": 0, "p": "By definition."}, {"lv": 3, "q": "Bonds broken require 1000 kJ; bonds formed release 1300 kJ. What is ΔH?", "o": ["−300 kJ", "+300 kJ", "−2300 kJ", "+2300 kJ"], "a": 0, "p": "ΔH = broken − formed."}, {"lv": 3, "q": "ΔHf: CO₂ = −394, H₂O = −286, CH₄ = −75 kJ/mol. Find ΔHc of CH₄ (CH₄ + 2O₂ → CO₂ + 2H₂O).", "o": ["−891 kJ/mol", "−605 kJ/mol", "−755 kJ/mol", "+891 kJ/mol"], "a": 0, "p": "(−394 − 572) − (−75) = −891."}, {"lv": 3, "q": "Why are calorimetry values often less exothermic than data-book values?", "o": ["heat loss to the surroundings and incomplete combustion", "too much fuel", "thermometers read high", "water boils"], "a": 0, "p": "Energy escapes."}, {"lv": 3, "q": "In an energy profile, a catalyst ...", "o": ["lowers the activation energy but does not change ΔH", "changes ΔH", "raises the activation energy", "makes the reaction endothermic"], "a": 0, "p": "It provides an alternative route."}]}, {"id": "cam-sci-k12-2", "name": "Biology: Cell membranes and transport", "desc": "Diffusion, osmosis, active transport", "idx": 2, "soal": [{"lv": 1, "q": "The cell membrane structure is described as ...", "o": ["the fluid mosaic model", "the lock and key model", "the double helix", "the Bohr model"], "a": 0, "p": "A phospholipid bilayer with proteins."}, {"lv": 1, "q": "Diffusion is the net movement of particles ...", "o": ["from high to low concentration", "from low to high concentration", "using ATP", "only in plants"], "a": 0, "p": "Passive movement."}, {"lv": 1, "q": "Osmosis is the movement of ...", "o": ["water across a partially permeable membrane", "glucose by active transport", "ions using ATP", "proteins"], "a": 0, "p": "From high to low water potential."}, {"lv": 1, "q": "Active transport requires ...", "o": ["ATP and carrier proteins", "no energy", "only water", "light"], "a": 0, "p": "It moves substances against a gradient."}, {"lv": 2, "q": "Phospholipid tails are ...", "o": ["hydrophobic", "hydrophilic", "charged", "made of protein"], "a": 0, "p": "They point inward, away from water."}, {"lv": 2, "q": "Facilitated diffusion uses ...", "o": ["channel or carrier proteins without ATP", "ATP", "vesicles only", "cholesterol"], "a": 0, "p": "Passive movement via proteins."}, {"lv": 2, "q": "A plant cell in pure water becomes ...", "o": ["turgid", "plasmolysed", "lysed", "shrunken"], "a": 0, "p": "Water enters and the wall prevents bursting."}, {"lv": 2, "q": "Which factor increases the rate of diffusion?", "o": ["larger surface area", "thicker membrane", "lower temperature", "smaller concentration gradient"], "a": 0, "p": "Fick's law."}, {"lv": 3, "q": "Animal cells placed in a solution with lower water potential will ...", "o": ["lose water and shrink (crenate)", "gain water and burst", "stay the same", "divide"], "a": 0, "p": "Water moves out by osmosis."}, {"lv": 3, "q": "Why does cholesterol matter in membranes?", "o": ["It regulates fluidity and stability.", "It carries oxygen.", "It makes ATP.", "It digests proteins."], "a": 0, "p": "It stabilises the bilayer."}, {"lv": 3, "q": "Endocytosis is ...", "o": ["bulk uptake of material by membrane folding into vesicles", "diffusion of oxygen", "osmosis of water", "release of hormones"], "a": 0, "p": "For example, phagocytosis."}, {"lv": 3, "q": "Why do small cells exchange substances efficiently?", "o": ["They have a large surface area to volume ratio.", "They have more DNA.", "They are always round.", "They have no membrane."], "a": 0, "p": "Distances are short relative to surface."}]}], "2": [{"id": "cam-sci-k2-0", "name": "Plants: growth and needs", "desc": "Water, light, seeds", "idx": 0, "soal": [{"lv": 1, "q": "What do plants need to grow?", "o": ["water and light", "sweets", "darkness only", "plastic"], "a": 0, "p": "Plants need water, light, air and suitable warmth to grow."}, {"lv": 1, "q": "What grows from a seed?", "o": ["a rock", "a new plant", "a bird", "a cloud"], "a": 1, "p": "A seed contains a tiny plant that can grow."}, {"lv": 1, "q": "Which part of a plant takes in water from the soil?", "o": ["flower", "roots", "leaves", "fruit"], "a": 1, "p": "Roots take in water and hold the plant in the soil."}, {"lv": 1, "q": "What colour are most leaves?", "o": ["blue", "green", "black", "white"], "a": 1, "p": "Leaves are green because they contain chlorophyll."}, {"lv": 2, "q": "A plant is kept in a dark cupboard for two weeks. What will happen?", "o": ["It will grow tall, strong and green.", "It will turn pale and weak.", "It will grow flowers faster.", "Nothing will change."], "a": 1, "p": "Without light, plants cannot make food and turn pale and weak."}, {"lv": 2, "q": "Which part of the plant makes food using sunlight?", "o": ["roots", "stem", "leaves", "seeds"], "a": 2, "p": "Leaves use sunlight to make food."}, {"lv": 2, "q": "What does the stem of a plant do?", "o": ["makes seeds", "holds the plant up and carries water", "takes in sunlight only", "attracts insects"], "a": 1, "p": "The stem supports the plant and carries water from the roots."}, {"lv": 2, "q": "Which is the correct order for a plant's growth?", "o": ["seed → seedling → adult plant", "adult plant → seed → seedling", "seedling → seed → flower", "flower → seed → root"], "a": 0, "p": "A seed germinates into a seedling, which grows into an adult plant."}, {"lv": 3, "q": "Amy plants two seeds. She waters Seed A every day but never waters Seed B. Both are in sunlight. What is she testing?", "o": ["whether plants need light", "whether plants need water", "whether plants need soil", "whether plants need music"], "a": 1, "p": "Only the water is changed, so she is testing if plants need water."}, {"lv": 3, "q": "A plant on a windowsill bends towards the window. Why?", "o": ["It is looking for water.", "It grows towards the light.", "The wind pushes it.", "It is too cold."], "a": 1, "p": "Plants grow towards light to get more for making food."}, {"lv": 3, "q": "Which plant will grow best?", "o": ["in the dark with no water", "in sunlight with some water", "in sunlight with no water", "in a freezer with water"], "a": 1, "p": "Plants need both light and water, and suitable warmth."}, {"lv": 3, "q": "Why does a plant wilt (droop) on a hot day if not watered?", "o": ["It has too much water.", "It is losing water and has not got enough.", "It has too much light.", "Its flowers are too heavy."], "a": 1, "p": "Without enough water, the plant cannot stay firm and droops."}]}, {"id": "cam-sci-k2-1", "name": "Habitats", "desc": "Where animals and plants live", "idx": 1, "soal": [{"lv": 1, "q": "A habitat is ...", "o": ["a type of food", "the place where an animal or plant lives", "a kind of weather", "a baby animal"], "a": 1, "p": "A habitat provides food, water and shelter for living things."}, {"lv": 1, "q": "Where does a fish live?", "o": ["in a tree", "in water", "in the desert", "underground"], "a": 1, "p": "Fish live in water habitats such as ponds, rivers and oceans."}, {"lv": 1, "q": "Which animal lives in a very cold, icy habitat?", "o": ["camel", "polar bear", "monkey", "lion"], "a": 1, "p": "Polar bears live in the Arctic."}, {"lv": 1, "q": "Which animal often lives under logs and stones?", "o": ["woodlouse", "eagle", "shark", "giraffe"], "a": 0, "p": "Woodlice like dark, damp places under logs and stones."}, {"lv": 2, "q": "Why do camels live well in the desert?", "o": ["They can go a long time without drinking water.", "They have thick fur for snow.", "They breathe underwater.", "They eat only fish."], "a": 0, "p": "Camels are suited to dry, hot habitats."}, {"lv": 2, "q": "What does a habitat give an animal?", "o": ["food, water and shelter", "only toys", "only sunshine", "nothing"], "a": 0, "p": "A habitat meets an animal's needs."}, {"lv": 2, "q": "Which animal lives in a rainforest?", "o": ["penguin", "orangutan", "polar bear", "camel"], "a": 1, "p": "Orangutans live in the rainforests of Borneo and Sumatra."}, {"lv": 2, "q": "A frog can live both in water and on land. Which habitat suits it best?", "o": ["a desert", "a pond", "a glacier", "a cave with no water"], "a": 1, "p": "A pond has water and land around it."}, {"lv": 3, "q": "A woodland is cut down. What will most likely happen to the squirrels that lived there?", "o": ["They will have more food.", "They will lose their homes and food.", "Nothing will happen.", "They will start living in the sea."], "a": 1, "p": "Removing the trees destroys their habitat."}, {"lv": 3, "q": "Why do fish have gills?", "o": ["to fly", "to breathe underwater", "to dig holes", "to keep warm"], "a": 1, "p": "Gills take oxygen from water."}, {"lv": 3, "q": "Which animal is NOT suited to living in the ocean?", "o": ["dolphin", "octopus", "rabbit", "crab"], "a": 2, "p": "Rabbits live on land and cannot breathe underwater."}, {"lv": 3, "q": "Why might a polar bear find it hard to live in a hot desert?", "o": ["Its thick fur would make it too hot.", "It cannot walk on sand.", "It cannot see in sunlight.", "It only eats plants."], "a": 0, "p": "Thick fur is suited to cold places, not hot ones."}]}, {"id": "cam-sci-k2-2", "name": "Light and dark", "desc": "Light sources and shadows", "idx": 2, "soal": [{"lv": 1, "q": "Which of these is a light source?", "o": ["the Moon", "the Sun", "a mirror", "a book"], "a": 1, "p": "The Sun gives out its own light. The Moon only reflects sunlight."}, {"lv": 1, "q": "What do we need to be able to see things?", "o": ["light", "darkness", "sound", "wind"], "a": 0, "p": "We need light to see."}, {"lv": 1, "q": "A shadow forms when ...", "o": ["light passes through glass", "an object blocks light", "it is completely dark", "we close our eyes"], "a": 1, "p": "Light cannot pass through the object, leaving a dark area: a shadow."}, {"lv": 1, "q": "Which of these is NOT a light source?", "o": ["a torch", "a candle flame", "a mirror", "a lamp"], "a": 2, "p": "A mirror only reflects light; it does not make it."}, {"lv": 2, "q": "When is your shadow longest on a sunny day?", "o": ["at midday", "early morning or late afternoon", "at night", "it is always the same"], "a": 1, "p": "When the Sun is low in the sky, shadows are long."}, {"lv": 2, "q": "Which material will make the darkest shadow?", "o": ["clear glass", "cardboard", "tracing paper", "clear plastic"], "a": 1, "p": "Cardboard is opaque and blocks all the light."}, {"lv": 2, "q": "Why is it hard to see in a dark room?", "o": ["There is no light to enter our eyes.", "Our eyes are closed.", "Objects disappear in the dark.", "It is too quiet."], "a": 0, "p": "We see when light enters our eyes."}, {"lv": 2, "q": "A torch is moved closer to a toy. What happens to the toy's shadow on the wall?", "o": ["It gets bigger.", "It gets smaller.", "It disappears.", "It changes colour."], "a": 0, "p": "A light source closer to the object makes a larger shadow."}, {"lv": 3, "q": "Why should you never look directly at the Sun?", "o": ["It is too far away.", "Its light is so strong it can damage your eyes.", "It makes you sleepy.", "It is cold."], "a": 1, "p": "Strong sunlight can harm the eyes."}, {"lv": 3, "q": "At midday, the Sun is high in the sky. What will a tree's shadow be like?", "o": ["very long", "short", "no shadow at all ever", "blue"], "a": 1, "p": "A high Sun makes short shadows."}, {"lv": 3, "q": "Which object lets SOME light through (translucent)?", "o": ["a wooden door", "tissue paper", "a metal tray", "a brick wall"], "a": 1, "p": "Tissue paper is translucent: some light passes through."}, {"lv": 3, "q": "Ben's shadow points west in the morning. Where is the Sun?", "o": ["in the west", "in the east", "directly overhead", "under the ground"], "a": 1, "p": "Shadows point away from the light source; the Sun rises in the east."}]}], "3": [{"id": "cam-sci-k3-0", "name": "Human body: skeleton and muscles", "desc": "Bones and movement", "idx": 0, "soal": [{"lv": 1, "q": "What is the skeleton made of?", "o": ["muscles", "bones", "skin", "blood"], "a": 1, "p": "The skeleton is made of bones."}, {"lv": 1, "q": "Which bones protect the brain?", "o": ["ribs", "skull", "spine", "pelvis"], "a": 1, "p": "The skull protects the brain."}, {"lv": 1, "q": "What helps our bones move?", "o": ["muscles", "hair", "nails", "teeth"], "a": 0, "p": "Muscles pull on bones to move them."}, {"lv": 1, "q": "Which bones protect the heart and lungs?", "o": ["skull", "ribs", "finger bones", "leg bones"], "a": 1, "p": "The ribcage protects the heart and lungs."}, {"lv": 2, "q": "What is the backbone also called?", "o": ["skull", "spine", "ribcage", "kneecap"], "a": 1, "p": "The backbone is the spine, made of vertebrae."}, {"lv": 2, "q": "Which is NOT a job of the skeleton?", "o": ["support the body", "protect organs", "help movement", "digest food"], "a": 3, "p": "Digestion is done by the digestive system."}, {"lv": 2, "q": "Where two bones meet, there is a ...", "o": ["muscle", "joint", "vein", "nerve"], "a": 1, "p": "Joints such as elbows and knees let bones move."}, {"lv": 2, "q": "Muscles move bones by ...", "o": ["pushing only", "pulling (contracting)", "melting", "growing longer"], "a": 1, "p": "Muscles can only pull, by contracting."}, {"lv": 3, "q": "When you bend your arm, the biceps muscle ...", "o": ["relaxes and gets longer", "contracts and gets shorter", "stays the same", "turns into bone"], "a": 1, "p": "The biceps contracts to bend the elbow; the triceps relaxes."}, {"lv": 3, "q": "Why do muscles work in pairs?", "o": ["Because one can only pull, so another is needed to pull the bone back", "Because they are too weak alone", "So they can push together", "They do not work in pairs"], "a": 0, "p": "One muscle bends a joint and the other straightens it."}, {"lv": 3, "q": "Which animal has NO skeleton of bones inside its body?", "o": ["dog", "fish", "earthworm", "bird"], "a": 2, "p": "Earthworms have no bones."}, {"lv": 3, "q": "Why is it important to eat food with calcium, such as milk?", "o": ["It helps build strong bones and teeth.", "It makes hair longer.", "It stops us sleeping.", "It makes muscles turn into bones."], "a": 0, "p": "Calcium is needed for healthy bones and teeth."}]}, {"id": "cam-sci-k3-1", "name": "Magnets", "desc": "Attract and repel, magnetic materials", "idx": 1, "soal": [{"lv": 1, "q": "Which object will a magnet attract?", "o": ["a plastic spoon", "an iron nail", "a wooden block", "a paper clip made of plastic"], "a": 1, "p": "Magnets attract iron."}, {"lv": 1, "q": "The ends of a magnet are called ...", "o": ["poles", "sides", "tops", "points"], "a": 0, "p": "Every magnet has a north and a south pole."}, {"lv": 1, "q": "Two north poles placed together will ...", "o": ["attract", "repel (push apart)", "stick forever", "melt"], "a": 1, "p": "Like poles repel."}, {"lv": 1, "q": "A north pole and a south pole placed together will ...", "o": ["attract", "repel", "do nothing", "glow"], "a": 0, "p": "Unlike poles attract."}, {"lv": 2, "q": "Which material is magnetic?", "o": ["copper", "aluminium", "steel", "gold"], "a": 2, "p": "Steel contains iron, so it is magnetic."}, {"lv": 2, "q": "Which of these is NOT attracted by a magnet?", "o": ["an iron key", "a steel pin", "an aluminium can", "a nickel coin"], "a": 2, "p": "Aluminium is a metal but is not magnetic."}, {"lv": 2, "q": "Where is a bar magnet strongest?", "o": ["in the middle", "at the poles", "all over equally", "nowhere"], "a": 1, "p": "A magnet's force is strongest at its poles."}, {"lv": 2, "q": "A magnet can attract a paper clip through ...", "o": ["a thin sheet of paper", "nothing at all", "only air", "only metal"], "a": 0, "p": "Magnetic force can pass through thin non-magnetic materials."}, {"lv": 3, "q": "Lucy wants to test which magnet is strongest. What is the fairest test?", "o": ["Count how many paper clips each magnet can hold in a chain.", "Look at the colour of each magnet.", "Weigh each magnet.", "Drop each magnet on the floor."], "a": 0, "p": "Counting the paper clips held measures strength fairly."}, {"lv": 3, "q": "A magnet is used to separate a mixture. Which mixture can it separate?", "o": ["sand and salt", "iron filings and sand", "sugar and water", "rice and beans"], "a": 1, "p": "Only the iron filings are attracted."}, {"lv": 3, "q": "Not all metals are magnetic. Which statement is correct?", "o": ["All metals are magnetic.", "Only iron, nickel, cobalt and things containing them are magnetic.", "Plastic is magnetic.", "Gold is magnetic."], "a": 1, "p": "Only a few metals are magnetic."}, {"lv": 3, "q": "A fridge door holds a magnet. What can we say about the door?", "o": ["It contains a magnetic metal such as iron or steel.", "It is made of wood.", "It is made of plastic only.", "It is made of glass."], "a": 0, "p": "Magnets stick to magnetic materials such as steel."}]}, {"id": "cam-sci-k3-2", "name": "Rocks and soils", "desc": "Types and uses", "idx": 2, "soal": [{"lv": 1, "q": "Soil is made from tiny pieces of rock mixed with ...", "o": ["plastic", "dead plants and animals (humus), water and air", "sugar", "metal"], "a": 1, "p": "Soil contains rock particles, humus, water and air."}, {"lv": 1, "q": "Which rock is often used for building walls?", "o": ["granite", "chalk dust", "sand", "clay pot"], "a": 0, "p": "Granite is hard and strong."}, {"lv": 1, "q": "Which soil holds the MOST water?", "o": ["sandy soil", "clay soil", "gravel", "small stones"], "a": 1, "p": "Clay has tiny particles that hold water."}, {"lv": 1, "q": "Which of these is a type of rock?", "o": ["marble", "rubber", "glass bottle", "plastic"], "a": 0, "p": "Marble is a natural rock."}, {"lv": 2, "q": "Water drains through which soil fastest?", "o": ["clay", "sand", "mud", "peat"], "a": 1, "p": "Sand has large particles with big gaps between them."}, {"lv": 2, "q": "Why is chalk not a good rock for building?", "o": ["It is very hard.", "It is soft and wears away easily.", "It is waterproof.", "It is magnetic."], "a": 1, "p": "Chalk is soft and crumbly."}, {"lv": 2, "q": "A fossil is ...", "o": ["a type of soil", "the remains or traces of a living thing preserved in rock", "a kind of magnet", "a melted rock"], "a": 1, "p": "Fossils form over millions of years in rock."}, {"lv": 2, "q": "Which rock is permeable (lets water soak through)?", "o": ["slate", "granite", "sandstone", "marble"], "a": 2, "p": "Sandstone has gaps that let water soak in."}, {"lv": 3, "q": "Why is slate used for roofs?", "o": ["It is impermeable and splits into thin flat sheets.", "It is soft and absorbent.", "It is magnetic.", "It is see-through."], "a": 0, "p": "Slate does not let water through and splits into thin pieces."}, {"lv": 3, "q": "Amir pours the same amount of water through three soils. Which observation shows the soil with the best drainage?", "o": ["The most water comes through quickly.", "No water comes through.", "The soil turns blue.", "The water gets hotter."], "a": 0, "p": "Good drainage means water passes through quickly."}, {"lv": 3, "q": "Why do gardeners add compost to soil?", "o": ["to add nutrients from decayed plants", "to make the soil magnetic", "to make it harder", "to stop plants growing"], "a": 0, "p": "Compost adds humus and nutrients."}, {"lv": 3, "q": "Which is the BEST explanation for why many fossils are found in sedimentary rock?", "o": ["Layers of mud and sand buried the remains and slowly turned into rock.", "Volcanoes melt animals into rock.", "Fossils grow inside rocks.", "Magnets pull bones into rocks."], "a": 0, "p": "Sedimentary rock forms from layers that can bury and preserve remains."}]}], "4": [{"id": "cam-sci-k4-0", "name": "Living things and their environment", "desc": "Adaptation and food chains", "idx": 0, "soal": [{"lv": 1, "q": "A food chain shows ...", "o": ["what an animal looks like", "who eats whom", "where animals sleep", "how plants drink"], "a": 1, "p": "A food chain shows how energy passes as food from one living thing to another."}, {"lv": 1, "q": "Food chains usually start with a ...", "o": ["green plant", "lion", "human", "rock"], "a": 0, "p": "Green plants make their own food: they are producers."}, {"lv": 1, "q": "An animal that eats only plants is called a ...", "o": ["carnivore", "herbivore", "omnivore", "predator"], "a": 1, "p": "Herbivores eat plants."}, {"lv": 1, "q": "An animal that hunts other animals for food is called a ...", "o": ["prey", "predator", "producer", "plant"], "a": 1, "p": "A predator hunts prey."}, {"lv": 2, "q": "In the food chain grass → rabbit → fox, the rabbit is ...", "o": ["a producer", "a prey and a consumer", "a top predator", "a decomposer"], "a": 1, "p": "The rabbit eats grass (consumer) and is eaten by the fox (prey)."}, {"lv": 2, "q": "Why does a polar bear have white fur?", "o": ["to camouflage in the snow", "to stay cool", "to scare other bears", "to swim faster"], "a": 0, "p": "White fur helps it blend in when hunting."}, {"lv": 2, "q": "A cactus has spines instead of leaves. This adaptation helps it ...", "o": ["lose more water", "save water and protect itself from animals", "grow taller quickly", "make more flowers"], "a": 1, "p": "Spines reduce water loss and deter animals."}, {"lv": 2, "q": "What would happen to foxes if all the rabbits disappeared?", "o": ["Foxes would have more food.", "Foxes would have less food and might decrease.", "Nothing would change.", "Foxes would start eating grass only."], "a": 1, "p": "Their food source is gone."}, {"lv": 3, "q": "In the chain: leaf → caterpillar → bird → hawk, which is the top predator?", "o": ["leaf", "caterpillar", "bird", "hawk"], "a": 3, "p": "The hawk is not eaten by anything in this chain."}, {"lv": 3, "q": "Many birds have been poisoned in a woodland. What is most likely to happen to the caterpillars?", "o": ["They will decrease.", "They will increase because fewer birds eat them.", "They will turn into birds.", "They will stay exactly the same."], "a": 1, "p": "Fewer predators means more prey survive."}, {"lv": 3, "q": "Why do ducks have webbed feet?", "o": ["to climb trees", "to swim well in water", "to dig holes", "to keep warm in snow"], "a": 1, "p": "Webbed feet act like paddles."}, {"lv": 3, "q": "Which is the best definition of an adaptation?", "o": ["a feature that helps a living thing survive in its habitat", "a type of food", "the place where an animal lives", "a baby animal"], "a": 0, "p": "Adaptations help organisms survive where they live."}]}, {"id": "cam-sci-k4-1", "name": "Electricity and circuits", "desc": "Components, conductors and insulators", "idx": 1, "soal": [{"lv": 1, "q": "Which of these is an electrical conductor?", "o": ["plastic", "copper", "wood", "rubber"], "a": 1, "p": "Metals such as copper let electricity flow."}, {"lv": 1, "q": "What does a battery (cell) do in a circuit?", "o": ["stops the current", "provides energy to push the current", "makes light only", "makes sound"], "a": 1, "p": "The cell is the power source."}, {"lv": 1, "q": "Which of these is an insulator?", "o": ["iron", "aluminium foil", "plastic", "steel"], "a": 2, "p": "Plastic does not let electricity through."}, {"lv": 1, "q": "A circuit must be ___ for a bulb to light.", "o": ["broken", "complete", "half open", "wet"], "a": 1, "p": "Electricity flows only in a complete loop."}, {"lv": 2, "q": "What does a switch do?", "o": ["makes the bulb brighter", "opens or closes the circuit", "stores electricity", "changes the bulb's colour"], "a": 1, "p": "Opening the switch breaks the circuit; closing it completes it."}, {"lv": 2, "q": "Why are electrical wires covered in plastic?", "o": ["to make them look nice", "because plastic is an insulator and keeps us safe", "to make electricity flow faster", "to make them heavier"], "a": 1, "p": "Plastic insulation prevents electric shocks."}, {"lv": 2, "q": "What happens if you add a second cell to a circuit with one bulb?", "o": ["The bulb gets dimmer.", "The bulb gets brighter.", "The bulb goes out.", "Nothing changes."], "a": 1, "p": "More cells give more energy, so the bulb is brighter."}, {"lv": 2, "q": "Which object would complete a circuit if placed in a gap?", "o": ["a rubber eraser", "a metal key", "a plastic ruler", "a wooden pencil"], "a": 1, "p": "Metal conducts electricity."}, {"lv": 3, "q": "A circuit has one cell and two bulbs in a line. A third bulb is added in the same line. What happens to the bulbs?", "o": ["They all get brighter.", "They all get dimmer.", "Only the new bulb lights.", "They go off."], "a": 1, "p": "The same energy is shared between more bulbs."}, {"lv": 3, "q": "Why is it dangerous to use electrical appliances with wet hands?", "o": ["Water can conduct electricity and cause a shock.", "Water makes appliances stop working forever.", "Water is an insulator.", "Hands get cold."], "a": 0, "p": "Impure water conducts electricity."}, {"lv": 3, "q": "A bulb does not light even though the circuit looks complete. What is a possible reason?", "o": ["The bulb is broken or the cell is flat.", "The wires are too shiny.", "The switch is closed.", "The room is bright."], "a": 0, "p": "A broken bulb or flat cell stops the circuit working."}, {"lv": 3, "q": "Which material would be best for the handle of a screwdriver used by an electrician?", "o": ["copper", "steel", "hard plastic", "aluminium"], "a": 2, "p": "Plastic is an insulator and protects the user."}]}, {"id": "cam-sci-k4-2", "name": "Sound", "desc": "Vibrations, pitch and volume", "idx": 2, "soal": [{"lv": 1, "q": "Sounds are made when objects ...", "o": ["vibrate", "freeze", "melt", "glow"], "a": 0, "p": "All sounds are caused by vibrations."}, {"lv": 1, "q": "Which part of the body detects sound?", "o": ["eyes", "ears", "nose", "tongue"], "a": 1, "p": "Ears detect sound vibrations."}, {"lv": 1, "q": "A loud sound has a large ...", "o": ["volume", "colour", "smell", "shape"], "a": 0, "p": "Volume is how loud or quiet a sound is."}, {"lv": 1, "q": "Pitch means how ___ a sound is.", "o": ["high or low", "loud or quiet", "fast or slow", "hot or cold"], "a": 0, "p": "Pitch is how high or low a sound is."}, {"lv": 2, "q": "How does sound travel from a drum to your ear?", "o": ["through vibrations in the air", "through light", "through magnets", "it does not travel"], "a": 0, "p": "Vibrations pass through the air particles."}, {"lv": 2, "q": "A short guitar string makes a ___ pitch than a long string.", "o": ["lower", "higher", "same", "quieter"], "a": 1, "p": "Shorter strings vibrate faster, giving a higher pitch."}, {"lv": 2, "q": "How can you make a drum sound louder?", "o": ["hit it harder", "hit it more softly", "cover it with a blanket", "put it in water"], "a": 0, "p": "Bigger vibrations make a louder sound."}, {"lv": 2, "q": "Sound CANNOT travel through ...", "o": ["air", "water", "a vacuum (empty space)", "wood"], "a": 2, "p": "Sound needs particles to travel."}, {"lv": 3, "q": "Why do sounds get quieter as you move away from them?", "o": ["The vibrations spread out and get weaker.", "The sound changes pitch.", "Sound stops in the air.", "Your ears get smaller."], "a": 0, "p": "Sound energy spreads out with distance."}, {"lv": 3, "q": "Bottles are filled with different amounts of water and blown across the top. Which gives the highest pitch?", "o": ["the bottle with the most water (least air)", "the empty bottle", "all the same", "the bottle with half water"], "a": 0, "p": "A shorter column of air vibrates faster, giving a higher pitch."}, {"lv": 3, "q": "Why do workers at airports wear ear defenders?", "o": ["to block loud sounds that can damage hearing", "to keep warm", "to hear better", "to make sounds louder"], "a": 0, "p": "Very loud sounds can damage the ears."}, {"lv": 3, "q": "A tight elastic band is plucked, then loosened and plucked again. What happens to the pitch?", "o": ["It gets higher.", "It gets lower.", "It stays the same.", "There is no sound."], "a": 1, "p": "A looser band vibrates more slowly, giving a lower pitch."}]}], "5": [{"id": "cam-sci-k5-0", "name": "Life cycles of plants and animals", "desc": "Pollination, germination, metamorphosis", "idx": 0, "soal": [{"lv": 1, "q": "What is the first stage in the life cycle of a frog?", "o": ["tadpole", "egg (frogspawn)", "froglet", "adult frog"], "a": 1, "p": "Frogs start as eggs (frogspawn)."}, {"lv": 1, "q": "Pollination is the transfer of ...", "o": ["water to roots", "pollen from the stamen to the stigma", "seeds to soil", "leaves to stems"], "a": 1, "p": "Pollen moves from male to female parts of the flower."}, {"lv": 1, "q": "Germination is when ...", "o": ["a seed starts to grow", "a flower dies", "a fruit ripens", "a leaf falls"], "a": 0, "p": "The seed begins to sprout."}, {"lv": 1, "q": "Which animal goes through complete metamorphosis?", "o": ["butterfly", "dog", "human", "cat"], "a": 0, "p": "Egg → caterpillar → pupa → adult butterfly."}, {"lv": 2, "q": "Which is the correct order for a butterfly?", "o": ["egg → caterpillar → pupa → adult", "egg → pupa → caterpillar → adult", "caterpillar → egg → adult → pupa", "pupa → egg → adult → caterpillar"], "a": 0, "p": "This is complete metamorphosis."}, {"lv": 2, "q": "Which helps pollination by carrying pollen?", "o": ["bees", "rocks", "worms underground", "clouds"], "a": 0, "p": "Insects such as bees carry pollen between flowers."}, {"lv": 2, "q": "What do seeds need to germinate?", "o": ["water, warmth and air", "only light", "only soil", "darkness and cold"], "a": 0, "p": "Most seeds need water, warmth and oxygen; light is not usually required."}, {"lv": 2, "q": "Why do some plants have brightly coloured, scented flowers?", "o": ["to attract insects for pollination", "to scare animals away", "to keep warm", "to store water"], "a": 0, "p": "Colour and scent attract pollinators."}, {"lv": 3, "q": "Why do plants such as dandelions have seeds with fluffy 'parachutes'?", "o": ["so the wind can carry the seeds far away", "so animals can eat them", "to keep them warm", "to help them sink"], "a": 0, "p": "Wind dispersal spreads seeds away from the parent plant."}, {"lv": 3, "q": "A grasshopper goes egg → nymph → adult. This is called ...", "o": ["complete metamorphosis", "incomplete metamorphosis", "germination", "pollination"], "a": 1, "p": "There is no pupa stage, so it is incomplete metamorphosis."}, {"lv": 3, "q": "Why is it useful for seeds to be dispersed away from the parent plant?", "o": ["to reduce competition for light, water and space", "so they can be eaten", "so they stay cold", "it is not useful"], "a": 0, "p": "Seedlings growing far away do not compete with the parent."}, {"lv": 3, "q": "After fertilisation in a flower, which part usually develops into the fruit?", "o": ["the petals", "the ovary", "the stem", "the roots"], "a": 1, "p": "The ovary becomes the fruit and the ovules become seeds."}]}, {"id": "cam-sci-k5-1", "name": "Earth and space", "desc": "Sun, Earth, Moon, day and night", "idx": 1, "soal": [{"lv": 1, "q": "What causes day and night?", "o": ["The Sun moves around the Earth.", "The Earth spins on its axis.", "The Moon covers the Sun.", "Clouds block the Sun."], "a": 1, "p": "The Earth rotates once every 24 hours."}, {"lv": 1, "q": "How long does the Earth take to orbit the Sun?", "o": ["1 day", "1 month", "about 1 year (365 days)", "1 week"], "a": 2, "p": "One orbit takes about 365¼ days."}, {"lv": 1, "q": "The Moon orbits ...", "o": ["the Sun only", "the Earth", "Mars", "nothing"], "a": 1, "p": "The Moon is Earth's natural satellite."}, {"lv": 1, "q": "The Sun is a ...", "o": ["planet", "star", "moon", "comet"], "a": 1, "p": "The Sun is a star."}, {"lv": 2, "q": "Why does the Sun appear to move across the sky during the day?", "o": ["because the Earth rotates", "because the Sun orbits the Earth", "because the clouds move", "because the Moon pushes it"], "a": 0, "p": "The Earth's rotation makes the Sun appear to move."}, {"lv": 2, "q": "In which direction does the Sun appear to rise?", "o": ["north", "south", "east", "west"], "a": 2, "p": "The Sun rises in the east and sets in the west."}, {"lv": 2, "q": "Why can we see the Moon?", "o": ["It makes its own light.", "It reflects light from the Sun.", "It is on fire.", "It reflects light from Earth's lamps."], "a": 1, "p": "The Moon is not a light source; it reflects sunlight."}, {"lv": 2, "q": "About how long does the Moon take to orbit the Earth?", "o": ["24 hours", "about 28 days", "365 days", "7 days"], "a": 1, "p": "It takes about a month (27–29 days)."}, {"lv": 3, "q": "When it is daytime in London, it is night-time in parts of Australia. Why?", "o": ["Australia faces away from the Sun at that time as the Earth rotates.", "Australia is closer to the Moon.", "The Sun is smaller there.", "Australia has no Sun."], "a": 0, "p": "Different sides of the Earth face the Sun at different times."}, {"lv": 3, "q": "Why does the Moon seem to change shape (phases)?", "o": ["We see different amounts of its sunlit side as it orbits the Earth.", "It actually changes shape.", "Clouds cover parts of it.", "The Earth's shadow always covers it."], "a": 0, "p": "Phases depend on how much of the lit half faces us."}, {"lv": 3, "q": "The Earth's axis is tilted. This tilt causes ...", "o": ["day and night", "the seasons", "the phases of the Moon", "tides only"], "a": 1, "p": "The tilt changes how directly sunlight hits each hemisphere, causing seasons."}, {"lv": 3, "q": "Which is the correct order from smallest to largest?", "o": ["Moon, Earth, Sun", "Earth, Moon, Sun", "Sun, Earth, Moon", "Moon, Sun, Earth"], "a": 0, "p": "The Moon is smaller than the Earth, which is much smaller than the Sun."}]}, {"id": "cam-sci-k5-2", "name": "Light and shadows", "desc": "Reflection and how shadows form", "idx": 2, "soal": [{"lv": 1, "q": "Light travels in ...", "o": ["curves", "straight lines", "circles", "zigzags only"], "a": 1, "p": "Light travels in straight lines."}, {"lv": 1, "q": "A mirror ___ light.", "o": ["absorbs all", "reflects", "creates", "stops being"], "a": 1, "p": "Mirrors reflect light."}, {"lv": 1, "q": "An opaque object ...", "o": ["lets all light through", "lets some light through", "does not let light through", "makes light"], "a": 2, "p": "Opaque objects block light and form shadows."}, {"lv": 1, "q": "Which surface reflects light best?", "o": ["a shiny mirror", "a black cloth", "a wooden board", "a brick"], "a": 0, "p": "Smooth, shiny surfaces reflect light well."}, {"lv": 2, "q": "How do we see objects that are not light sources?", "o": ["Light reflects off them into our eyes.", "Our eyes send out light.", "They glow in the dark.", "Sound helps us see them."], "a": 0, "p": "Reflected light enters our eyes."}, {"lv": 2, "q": "Why does a shadow have the same shape as the object?", "o": ["because light travels in straight lines and is blocked by the object", "because shadows are copies", "because light bends around objects", "because mirrors make them"], "a": 0, "p": "Straight-line light is blocked by the outline of the object."}, {"lv": 2, "q": "A periscope uses ___ to let you see over a wall.", "o": ["two mirrors", "two magnets", "a battery", "a lens only"], "a": 0, "p": "Two mirrors reflect light around corners."}, {"lv": 2, "q": "A light ray hits a mirror at an angle of 30° to the normal. What is the angle of reflection?", "o": ["60°", "30°", "90°", "15°"], "a": 1, "p": "Angle of incidence = angle of reflection."}, {"lv": 3, "q": "Why does an object's shadow get longer in the evening?", "o": ["The Sun is lower in the sky, so light hits at a smaller angle.", "The object grows.", "The Sun is closer.", "Light travels more slowly."], "a": 0, "p": "A low light source makes longer shadows."}, {"lv": 3, "q": "A torch shines on a ball. The ball is moved closer to the wall (further from the torch). What happens to the shadow?", "o": ["It gets smaller and sharper.", "It gets bigger.", "It disappears.", "It doubles."], "a": 0, "p": "Moving the object away from the light and towards the screen makes the shadow smaller."}, {"lv": 3, "q": "Why do cyclists wear reflective strips at night?", "o": ["They reflect light from car headlights so drivers can see them.", "They make light themselves.", "They keep cyclists warm.", "They absorb light."], "a": 0, "p": "Reflective materials send light back to its source."}, {"lv": 3, "q": "Which material would make the clearest shadow?", "o": ["transparent glass", "translucent paper", "opaque metal", "clear water"], "a": 2, "p": "Opaque materials block all light."}]}], "6": [{"id": "cam-sci-k6-0", "name": "Human body systems", "desc": "Digestive, circulatory, respiratory", "idx": 0, "soal": [{"lv": 1, "q": "Which organ pumps blood around the body?", "o": ["lungs", "heart", "stomach", "brain"], "a": 1, "p": "The heart pumps blood."}, {"lv": 1, "q": "Where is food mainly digested and absorbed?", "o": ["small intestine", "lungs", "heart", "kidneys"], "a": 0, "p": "Nutrients are absorbed in the small intestine."}, {"lv": 1, "q": "Which gas do we breathe in that our body needs?", "o": ["carbon dioxide", "oxygen", "nitrogen only", "helium"], "a": 1, "p": "Cells need oxygen."}, {"lv": 1, "q": "The lungs are part of the ___ system.", "o": ["digestive", "respiratory", "skeletal", "circulatory"], "a": 1, "p": "The respiratory system is for breathing."}, {"lv": 2, "q": "What do blood vessels called arteries do?", "o": ["carry blood away from the heart", "carry blood to the heart", "digest food", "make oxygen"], "a": 0, "p": "Arteries carry blood away from the heart."}, {"lv": 2, "q": "Which is the correct order of the digestive system?", "o": ["mouth → oesophagus → stomach → small intestine → large intestine", "mouth → stomach → oesophagus → large intestine", "stomach → mouth → small intestine", "mouth → lungs → stomach"], "a": 0, "p": "Food passes along this route."}, {"lv": 2, "q": "Why does your heart rate increase when you exercise?", "o": ["Muscles need more oxygen and glucose.", "The heart gets tired.", "You are digesting food.", "Your lungs stop."], "a": 0, "p": "More blood is pumped to deliver oxygen to muscles."}, {"lv": 2, "q": "What gas do we breathe out more of?", "o": ["oxygen", "carbon dioxide", "hydrogen", "helium"], "a": 1, "p": "Carbon dioxide is a waste product of respiration."}, {"lv": 3, "q": "How are the circulatory and respiratory systems linked?", "o": ["Blood collects oxygen in the lungs and carries it to cells.", "They are not linked.", "The stomach sends air to the heart.", "The brain pumps blood."], "a": 0, "p": "Oxygen enters the blood in the lungs."}, {"lv": 3, "q": "Why does the small intestine have a long, folded lining?", "o": ["to give a large surface area for absorbing nutrients", "to make food move faster", "to store air", "to pump blood"], "a": 0, "p": "More surface area means more absorption."}, {"lv": 3, "q": "Which habit is MOST likely to damage the lungs?", "o": ["smoking", "drinking water", "eating fruit", "sleeping well"], "a": 0, "p": "Smoking damages the airways and lungs."}, {"lv": 3, "q": "Veins carry blood back to the heart. Why do they have valves?", "o": ["to stop blood flowing backwards", "to make blood red", "to digest food", "to make oxygen"], "a": 0, "p": "Valves keep blood flowing in one direction."}]}, {"id": "cam-sci-k6-1", "name": "Classification of living things", "desc": "Keys and groups", "idx": 1, "soal": [{"lv": 1, "q": "Animals with a backbone are called ...", "o": ["invertebrates", "vertebrates", "plants", "fungi"], "a": 1, "p": "Vertebrates have a backbone."}, {"lv": 1, "q": "Which group has feathers?", "o": ["mammals", "birds", "fish", "reptiles"], "a": 1, "p": "Only birds have feathers."}, {"lv": 1, "q": "Which animal is a mammal?", "o": ["shark", "whale", "frog", "snake"], "a": 1, "p": "Whales breathe air and feed young on milk."}, {"lv": 1, "q": "An animal without a backbone is ...", "o": ["a vertebrate", "an invertebrate", "a mammal", "a bird"], "a": 1, "p": "Invertebrates have no backbone, e.g. insects."}, {"lv": 2, "q": "How many legs do insects have?", "o": ["4", "6", "8", "10"], "a": 1, "p": "Insects have 6 legs; spiders have 8."}, {"lv": 2, "q": "Which group has dry, scaly skin and lays eggs on land?", "o": ["amphibians", "reptiles", "fish", "mammals"], "a": 1, "p": "Reptiles, e.g. lizards and snakes."}, {"lv": 2, "q": "A frog lives in water when young and on land as an adult. It is ...", "o": ["a reptile", "an amphibian", "a fish", "a mammal"], "a": 1, "p": "Amphibians live both in water and on land."}, {"lv": 2, "q": "What is a classification key used for?", "o": ["to identify living things by answering questions", "to open a lock", "to measure temperature", "to count animals"], "a": 0, "p": "Keys sort organisms by features."}, {"lv": 3, "q": "A key asks: 'Does it have 8 legs?' Yes → spider. No → 'Does it have wings?' Yes → bee. No → ant. Which animal has no wings and 6 legs?", "o": ["spider", "bee", "ant", "beetle"], "a": 2, "p": "Not 8 legs, no wings → ant."}, {"lv": 3, "q": "A bat flies but feeds its young on milk and has fur. It is classified as ...", "o": ["a bird", "a mammal", "an insect", "a reptile"], "a": 1, "p": "Fur and milk are mammal features."}, {"lv": 3, "q": "Why is a spider NOT an insect?", "o": ["It has 8 legs and 2 body parts.", "It has a backbone.", "It has feathers.", "It lives in water."], "a": 0, "p": "Insects have 6 legs and 3 body parts."}, {"lv": 3, "q": "Which feature would best separate fish from all other vertebrates?", "o": ["gills for breathing underwater throughout life", "having a backbone", "laying eggs", "having eyes"], "a": 0, "p": "Fish breathe with gills for their whole life."}]}, {"id": "cam-sci-k6-2", "name": "Forces and motion", "desc": "Friction, gravity, air resistance", "idx": 2, "soal": [{"lv": 1, "q": "Gravity pulls objects ...", "o": ["upwards", "towards the centre of the Earth", "sideways", "nowhere"], "a": 1, "p": "Gravity pulls objects down towards Earth."}, {"lv": 1, "q": "Friction is a force that ...", "o": ["speeds things up", "slows things down when surfaces rub", "makes things float", "makes light"], "a": 1, "p": "Friction opposes motion."}, {"lv": 1, "q": "Forces are measured in ...", "o": ["kilograms", "newtons", "metres", "litres"], "a": 1, "p": "The unit of force is the newton (N)."}, {"lv": 1, "q": "Air resistance acts on ...", "o": ["objects moving through air", "objects in space only", "only stationary objects", "only water"], "a": 0, "p": "Air pushes against moving objects."}, {"lv": 2, "q": "Why does a parachute fall slowly?", "o": ["Its large surface area increases air resistance.", "It has no weight.", "Gravity stops.", "It is magnetic."], "a": 0, "p": "A large canopy catches more air."}, {"lv": 2, "q": "Which surface gives the MOST friction for a toy car?", "o": ["ice", "carpet", "smooth glass", "polished wood"], "a": 1, "p": "Rough surfaces give more friction."}, {"lv": 2, "q": "What is the weight of a 2 kg bag on Earth? (Take g = 10 N/kg)", "o": ["2 N", "20 N", "12 N", "0.2 N"], "a": 1, "p": "Weight = mass × g = 20 N."}, {"lv": 2, "q": "Why do cars have streamlined shapes?", "o": ["to reduce air resistance", "to increase friction", "to look heavy", "to slow down"], "a": 0, "p": "Streamlining lets air flow smoothly."}, {"lv": 3, "q": "A box is pushed with 50 N to the right; friction is 20 N to the left. What is the resultant force?", "o": ["70 N right", "30 N right", "30 N left", "0 N"], "a": 1, "p": "50 − 20 = 30 N to the right."}, {"lv": 3, "q": "Why is friction useful when walking?", "o": ["It stops our shoes slipping on the ground.", "It makes us faster in space.", "It removes gravity.", "It is never useful."], "a": 0, "p": "Grip comes from friction."}, {"lv": 3, "q": "An astronaut's mass is 60 kg on Earth. What is her mass on the Moon?", "o": ["10 kg", "60 kg", "600 kg", "0 kg"], "a": 1, "p": "Mass does not change; weight does."}, {"lv": 3, "q": "Two forces on a hanging apple are balanced. What happens to the apple?", "o": ["It stays still.", "It falls.", "It rises.", "It spins."], "a": 0, "p": "Balanced forces mean no change in motion."}]}], "7": [{"id": "cam-sci-k7-0", "name": "Cells and organisms", "desc": "Plant and animal cells, microscopes", "idx": 0, "soal": [{"lv": 1, "q": "What is the basic unit of all living things?", "o": ["atom", "cell", "organ", "tissue"], "a": 1, "p": "All living things are made of cells."}, {"lv": 1, "q": "Which structure controls the activities of the cell?", "o": ["nucleus", "cell wall", "vacuole", "cytoplasm"], "a": 0, "p": "The nucleus contains genetic material."}, {"lv": 1, "q": "Which structure is found in plant cells but NOT animal cells?", "o": ["cell membrane", "chloroplast", "nucleus", "cytoplasm"], "a": 1, "p": "Chloroplasts carry out photosynthesis."}, {"lv": 1, "q": "Which instrument is used to see cells?", "o": ["telescope", "microscope", "thermometer", "periscope"], "a": 1, "p": "Cells are too small to see without a microscope."}, {"lv": 2, "q": "What is the job of the cell membrane?", "o": ["controls what enters and leaves the cell", "makes food", "gives the cell its green colour", "stores DNA"], "a": 0, "p": "It is selectively permeable."}, {"lv": 2, "q": "Put in order from smallest: organ, cell, tissue, organ system", "o": ["cell, tissue, organ, organ system", "tissue, cell, organ, organ system", "organ, cell, tissue, organ system", "cell, organ, tissue, organ system"], "a": 0, "p": "Cells form tissues, which form organs, which form systems."}, {"lv": 2, "q": "Where do most chemical reactions take place in a cell?", "o": ["cytoplasm", "cell wall", "nucleus only", "vacuole"], "a": 0, "p": "The cytoplasm is a jelly-like substance where reactions happen."}, {"lv": 2, "q": "What does the cell wall do in plant cells?", "o": ["supports and strengthens the cell", "makes energy", "controls the cell", "absorbs light"], "a": 0, "p": "It is made of cellulose and gives support."}, {"lv": 3, "q": "A cell has a nucleus, cell membrane, cytoplasm, cell wall and chloroplasts. It is most likely from ...", "o": ["a leaf", "a human cheek", "a muscle", "blood"], "a": 0, "p": "Chloroplasts and a cell wall mean a plant cell from a leaf."}, {"lv": 3, "q": "Why do root hair cells NOT have chloroplasts?", "o": ["They are underground with no light for photosynthesis.", "They are animal cells.", "They are too small.", "They have no nucleus."], "a": 0, "p": "No light reaches roots."}, {"lv": 3, "q": "A microscope has an eyepiece lens of ×10 and an objective lens of ×40. What is the total magnification?", "o": ["×50", "×400", "×4", "×30"], "a": 1, "p": "10 × 40 = 400."}, {"lv": 3, "q": "Why are red blood cells specialised without a nucleus?", "o": ["to make more room to carry oxygen", "to swim faster", "to make food", "to fight germs"], "a": 0, "p": "More space for haemoglobin."}]}, {"id": "cam-sci-k7-1", "name": "Particles and states of matter", "desc": "Solids, liquids, gases, changes of state", "idx": 1, "soal": [{"lv": 1, "q": "In which state are particles packed closely in a regular pattern?", "o": ["solid", "liquid", "gas", "plasma"], "a": 0, "p": "Solid particles vibrate in fixed positions."}, {"lv": 1, "q": "Which state has particles that are far apart and move quickly in all directions?", "o": ["solid", "liquid", "gas", "ice"], "a": 2, "p": "Gas particles are widely spaced."}, {"lv": 1, "q": "Melting is the change from ...", "o": ["liquid to gas", "solid to liquid", "gas to liquid", "liquid to solid"], "a": 1, "p": "Melting turns a solid into a liquid."}, {"lv": 1, "q": "What is the boiling point of pure water at sea level?", "o": ["0 °C", "50 °C", "100 °C", "212 °C"], "a": 2, "p": "Water boils at 100 °C."}, {"lv": 2, "q": "Why can liquids flow?", "o": ["Particles can slide past each other.", "Particles are fixed.", "There are no particles.", "Particles are very far apart."], "a": 0, "p": "Liquid particles touch but can move around."}, {"lv": 2, "q": "Condensation is ...", "o": ["gas turning into liquid", "solid turning into gas", "liquid turning into solid", "solid turning into liquid"], "a": 0, "p": "Water vapour condenses on cold surfaces."}, {"lv": 2, "q": "Why can gases be compressed easily?", "o": ["There is a lot of space between particles.", "Particles are touching.", "Particles do not move.", "Gases have no mass."], "a": 0, "p": "Particles can be pushed closer together."}, {"lv": 2, "q": "What happens to particles when a substance is heated?", "o": ["They move faster.", "They get bigger.", "They stop moving.", "They disappear."], "a": 0, "p": "Heating gives particles more energy."}, {"lv": 3, "q": "Why does the smell of perfume spread across a room?", "o": ["Gas particles diffuse from high to low concentration.", "The perfume melts.", "Light carries it.", "The room cools down."], "a": 0, "p": "Diffusion spreads particles."}, {"lv": 3, "q": "Sublimation is the change from ...", "o": ["solid directly to gas", "gas to liquid", "liquid to solid", "solid to liquid"], "a": 0, "p": "Dry ice sublimes."}, {"lv": 3, "q": "Why does the temperature stay at 0 °C while ice is melting?", "o": ["Energy is used to break bonds between particles, not to raise temperature.", "The thermometer is broken.", "Ice stops absorbing heat.", "Water is magic."], "a": 0, "p": "Energy goes into changing state."}, {"lv": 3, "q": "Why does a balloon get bigger on a hot day?", "o": ["Gas particles move faster and push harder on the walls.", "The rubber shrinks.", "More air enters by itself.", "Particles get bigger."], "a": 0, "p": "Higher particle speed means more pressure."}]}, {"id": "cam-sci-k7-2", "name": "Energy", "desc": "Energy stores and transfers", "idx": 2, "soal": [{"lv": 1, "q": "Which is a renewable energy resource?", "o": ["coal", "solar", "oil", "natural gas"], "a": 1, "p": "Solar energy will not run out."}, {"lv": 1, "q": "Energy is measured in ...", "o": ["newtons", "joules", "watts", "kilograms"], "a": 1, "p": "The unit of energy is the joule (J)."}, {"lv": 1, "q": "A moving car has which energy store?", "o": ["kinetic", "chemical only", "elastic", "nuclear"], "a": 0, "p": "Moving objects have kinetic energy."}, {"lv": 1, "q": "Food stores energy as ...", "o": ["chemical energy", "sound energy", "kinetic energy", "light energy"], "a": 0, "p": "Food contains chemical energy."}, {"lv": 2, "q": "A ball held high above the ground has energy stored as ...", "o": ["gravitational potential energy", "sound energy", "electrical energy", "thermal energy only"], "a": 0, "p": "Height gives gravitational potential energy."}, {"lv": 2, "q": "In a torch, energy is transferred from ...", "o": ["chemical (battery) to light and thermal", "light to chemical", "kinetic to nuclear", "sound to light"], "a": 0, "p": "The battery's chemical store powers the bulb."}, {"lv": 2, "q": "The law of conservation of energy says that energy ...", "o": ["can be created", "cannot be created or destroyed, only transferred", "always disappears", "is only in food"], "a": 1, "p": "Total energy stays the same."}, {"lv": 2, "q": "A stretched rubber band stores ___ energy.", "o": ["elastic potential", "kinetic", "light", "nuclear"], "a": 0, "p": "Stretched or squashed objects store elastic energy."}, {"lv": 3, "q": "A light bulb transfers 100 J of electrical energy into 20 J of light. How much is wasted as heat?", "o": ["80 J", "120 J", "20 J", "100 J"], "a": 0, "p": "100 − 20 = 80 J."}, {"lv": 3, "q": "What is the efficiency of a device that gives 30 J of useful energy from 120 J input?", "o": ["25%", "30%", "90%", "40%"], "a": 0, "p": "30/120 = 0.25 = 25%."}, {"lv": 3, "q": "Why are fossil fuels described as non-renewable?", "o": ["They take millions of years to form and will run out.", "They are made by the Sun each day.", "They can be reused forever.", "They are made of plastic."], "a": 0, "p": "They cannot be replaced in a human lifetime."}, {"lv": 3, "q": "A ball is dropped. As it falls, which energy change happens?", "o": ["gravitational potential → kinetic", "kinetic → chemical", "sound → potential", "light → kinetic"], "a": 0, "p": "Height decreases and speed increases."}]}], "8": [{"id": "cam-sci-k8-0", "name": "Respiration and circulation", "desc": "Aerobic respiration, heart and blood", "idx": 0, "soal": [{"lv": 1, "q": "Aerobic respiration uses glucose and ...", "o": ["oxygen", "carbon dioxide", "nitrogen", "water only"], "a": 0, "p": "Glucose + oxygen → carbon dioxide + water (+ energy)."}, {"lv": 1, "q": "Where does aerobic respiration mainly take place in cells?", "o": ["mitochondria", "nucleus", "cell wall", "chloroplast"], "a": 0, "p": "Mitochondria release energy."}, {"lv": 1, "q": "Which blood cells carry oxygen?", "o": ["red blood cells", "white blood cells", "platelets", "plasma"], "a": 0, "p": "Red cells contain haemoglobin."}, {"lv": 1, "q": "How many chambers does the human heart have?", "o": ["2", "3", "4", "6"], "a": 2, "p": "Two atria and two ventricles."}, {"lv": 2, "q": "What is the word equation for aerobic respiration?", "o": ["glucose + oxygen → carbon dioxide + water", "carbon dioxide + water → glucose + oxygen", "glucose → lactic acid", "oxygen + water → glucose"], "a": 0, "p": "Energy is released."}, {"lv": 2, "q": "What do white blood cells do?", "o": ["fight infection", "carry oxygen", "clot blood", "carry food"], "a": 0, "p": "They defend against microbes."}, {"lv": 2, "q": "Why is the left ventricle wall thicker than the right?", "o": ["It pumps blood all around the body at high pressure.", "It pumps blood to the lungs only.", "It stores oxygen.", "It is a valve."], "a": 0, "p": "The body circuit needs more force."}, {"lv": 2, "q": "Which blood vessels have thin walls and allow exchange of substances?", "o": ["capillaries", "arteries", "veins", "the aorta"], "a": 0, "p": "Capillary walls are one cell thick."}, {"lv": 3, "q": "During hard exercise, muscles may respire anaerobically. What is produced?", "o": ["lactic acid", "oxygen", "chlorophyll", "starch"], "a": 0, "p": "Glucose → lactic acid, with less energy."}, {"lv": 3, "q": "Why do we breathe heavily after a race?", "o": ["to repay the oxygen debt and remove lactic acid", "to cool the lungs", "to digest food", "to make blood thicker"], "a": 0, "p": "Extra oxygen breaks down lactic acid."}, {"lv": 3, "q": "Where does blood go after leaving the right ventricle?", "o": ["to the lungs", "to the body", "to the left atrium directly", "to the brain only"], "a": 0, "p": "Pulmonary artery → lungs."}, {"lv": 3, "q": "Why is it called a 'double circulation' system?", "o": ["Blood passes through the heart twice in one complete circuit.", "There are two hearts.", "Blood flows in two directions at once.", "There are two lungs."], "a": 0, "p": "One circuit to the lungs and one to the body."}]}, {"id": "cam-sci-k8-1", "name": "Chemical reactions", "desc": "Word equations, reactants and products", "idx": 1, "soal": [{"lv": 1, "q": "In a chemical reaction, the starting substances are called ...", "o": ["products", "reactants", "catalysts", "mixtures"], "a": 1, "p": "Reactants turn into products."}, {"lv": 1, "q": "Which is a sign of a chemical reaction?", "o": ["a gas is given off", "ice melting", "sugar dissolving", "water boiling"], "a": 0, "p": "New substances form, e.g. a gas."}, {"lv": 1, "q": "Burning is a reaction with ...", "o": ["oxygen", "nitrogen", "helium", "water"], "a": 0, "p": "Combustion uses oxygen."}, {"lv": 1, "q": "Rusting needs iron, water and ...", "o": ["oxygen", "salt only", "carbon dioxide", "sand"], "a": 0, "p": "Iron + water + oxygen → rust."}, {"lv": 2, "q": "Write the word equation for magnesium burning in oxygen.", "o": ["magnesium + oxygen → magnesium oxide", "magnesium → oxygen", "magnesium oxide → magnesium + oxygen", "magnesium + water → oxygen"], "a": 0, "p": "Metal + oxygen → metal oxide."}, {"lv": 2, "q": "Acid + alkali → ?", "o": ["salt + water", "metal + gas", "oxygen + hydrogen", "rust"], "a": 0, "p": "This is neutralisation."}, {"lv": 2, "q": "Which is a physical change, NOT a chemical reaction?", "o": ["melting chocolate", "baking a cake", "burning paper", "rusting a nail"], "a": 0, "p": "Melting can be reversed and makes no new substance."}, {"lv": 2, "q": "What gas is produced when a metal reacts with an acid?", "o": ["hydrogen", "oxygen", "carbon dioxide", "nitrogen"], "a": 0, "p": "Metal + acid → salt + hydrogen."}, {"lv": 3, "q": "The mass of reactants is 50 g. What is the total mass of products in a closed container?", "o": ["50 g", "less than 50 g", "more than 50 g", "0 g"], "a": 0, "p": "Mass is conserved."}, {"lv": 3, "q": "Which test confirms carbon dioxide?", "o": ["It turns limewater milky.", "It relights a glowing splint.", "It makes a squeaky pop.", "It bleaches litmus."], "a": 0, "p": "CO₂ turns limewater cloudy."}, {"lv": 3, "q": "Hydrogen is tested with a lit splint. What happens?", "o": ["squeaky pop", "relights", "goes green", "nothing"], "a": 0, "p": "Hydrogen burns with a pop."}, {"lv": 3, "q": "Calcium carbonate + hydrochloric acid → calcium chloride + water + ?", "o": ["carbon dioxide", "hydrogen", "oxygen", "chlorine"], "a": 0, "p": "Carbonates react with acids to give CO₂."}]}, {"id": "cam-sci-k8-2", "name": "Speed and motion", "desc": "Speed = distance / time, graphs", "idx": 2, "soal": [{"lv": 1, "q": "What is the formula for speed?", "o": ["distance × time", "distance ÷ time", "time ÷ distance", "distance + time"], "a": 1, "p": "Speed = distance / time."}, {"lv": 1, "q": "What is the speed of a car that travels 100 km in 2 hours?", "o": ["50 km/h", "200 km/h", "102 km/h", "98 km/h"], "a": 0, "p": "100 ÷ 2 = 50."}, {"lv": 1, "q": "A unit for speed is ...", "o": ["m/s", "kg", "N", "J"], "a": 0, "p": "Metres per second."}, {"lv": 1, "q": "On a distance–time graph, a horizontal line means the object is ...", "o": ["stationary", "speeding up", "moving fast", "slowing down"], "a": 0, "p": "Distance is not changing."}, {"lv": 2, "q": "A runner covers 400 m in 80 s. What is the speed?", "o": ["5 m/s", "320 m/s", "0.2 m/s", "4.8 m/s"], "a": 0, "p": "400 ÷ 80 = 5 m/s."}, {"lv": 2, "q": "How far does a cyclist travel in 3 h at 15 km/h?", "o": ["45 km", "5 km", "18 km", "12 km"], "a": 0, "p": "d = s × t = 45 km."}, {"lv": 2, "q": "How long does it take to travel 240 km at 60 km/h?", "o": ["4 hours", "3 hours", "14 400 hours", "0.25 hours"], "a": 0, "p": "t = d ÷ s = 4 h."}, {"lv": 2, "q": "On a distance–time graph, a steeper line means ...", "o": ["faster speed", "slower speed", "stationary", "going backwards"], "a": 0, "p": "A steeper gradient means greater speed."}, {"lv": 3, "q": "A train travels 120 km in 1.5 hours, then 80 km in 0.5 hours. What is its average speed?", "o": ["100 km/h", "80 km/h", "160 km/h", "90 km/h"], "a": 0, "p": "Total 200 km in 2 h = 100 km/h."}, {"lv": 3, "q": "Convert 36 km/h into m/s.", "o": ["10 m/s", "36 m/s", "3.6 m/s", "100 m/s"], "a": 0, "p": "36 000 m ÷ 3600 s = 10 m/s."}, {"lv": 3, "q": "A car goes 30 m/s for 20 s, then stops for 10 s. What is its average speed over the 30 s?", "o": ["20 m/s", "30 m/s", "15 m/s", "600 m/s"], "a": 0, "p": "Distance = 600 m; 600 ÷ 30 = 20 m/s."}, {"lv": 3, "q": "Which statement about relative speed is correct? Two cars drive towards each other at 50 km/h and 70 km/h.", "o": ["They approach each other at 120 km/h.", "They approach each other at 20 km/h.", "They approach each other at 60 km/h.", "They never meet."], "a": 0, "p": "Speeds add when moving towards each other."}]}], "9": [{"id": "cam-sci-k9-0", "name": "Genetics and inheritance", "desc": "DNA, genes, variation", "idx": 0, "soal": [{"lv": 1, "q": "DNA is found mainly in the ...", "o": ["nucleus", "cell wall", "vacuole", "membrane"], "a": 0, "p": "Chromosomes in the nucleus contain DNA."}, {"lv": 1, "q": "A section of DNA that codes for a characteristic is a ...", "o": ["gene", "cell", "organ", "tissue"], "a": 0, "p": "Genes control inherited features."}, {"lv": 1, "q": "How many chromosomes are in a normal human body cell?", "o": ["23", "46", "48", "92"], "a": 1, "p": "23 pairs = 46."}, {"lv": 1, "q": "Differences between members of the same species are called ...", "o": ["variation", "evolution", "mutation only", "classification"], "a": 0, "p": "Variation can be genetic or environmental."}, {"lv": 2, "q": "Which is an example of environmental variation?", "o": ["a scar", "eye colour", "blood group", "natural hair colour"], "a": 0, "p": "Scars are caused by the environment, not genes."}, {"lv": 2, "q": "How many chromosomes are in a human egg or sperm cell?", "o": ["23", "46", "12", "92"], "a": 0, "p": "Gametes have half the number."}, {"lv": 2, "q": "Which is an example of continuous variation?", "o": ["height", "blood group", "tongue rolling", "eye colour type"], "a": 0, "p": "Height has a range of values."}, {"lv": 2, "q": "Who first described DNA's double helix structure (with help from Franklin's data)?", "o": ["Watson and Crick", "Newton and Darwin", "Mendel and Pasteur", "Einstein and Curie"], "a": 0, "p": "In 1953, using Rosalind Franklin's X-ray images."}, {"lv": 3, "q": "In pea plants, tall (T) is dominant over short (t). What fraction of the offspring of Tt × Tt are expected to be short?", "o": ["1/4", "1/2", "3/4", "0"], "a": 0, "p": "TT, Tt, Tt, tt → 1 in 4 is tt."}, {"lv": 3, "q": "A child's sex is determined by ...", "o": ["the sperm carrying X or Y", "the egg carrying Y", "the mother only", "diet"], "a": 0, "p": "Eggs always carry X; sperm carry X or Y."}, {"lv": 3, "q": "Why do identical twins have the same genes?", "o": ["They come from one fertilised egg that split.", "They share a birthday.", "They eat the same food.", "They come from two eggs."], "a": 0, "p": "One zygote divides into two embryos."}, {"lv": 3, "q": "A mutation is ...", "o": ["a random change in DNA", "a type of cell", "a learned behaviour", "always harmful"], "a": 0, "p": "Mutations can be harmful, neutral or helpful."}]}, {"id": "cam-sci-k9-1", "name": "The periodic table and bonding", "desc": "Groups, periods, ionic and covalent", "idx": 1, "soal": [{"lv": 1, "q": "Elements in the same group of the periodic table have the same number of ...", "o": ["electrons in the outer shell", "neutrons", "protons", "atoms"], "a": 0, "p": "That is why they react similarly."}, {"lv": 1, "q": "The rows of the periodic table are called ...", "o": ["groups", "periods", "families", "columns"], "a": 1, "p": "Rows are periods; columns are groups."}, {"lv": 1, "q": "Group 1 elements are called ...", "o": ["alkali metals", "halogens", "noble gases", "transition metals"], "a": 0, "p": "For example, lithium and sodium."}, {"lv": 1, "q": "Which group contains the unreactive noble gases?", "o": ["Group 0 (18)", "Group 1", "Group 7", "Group 2"], "a": 0, "p": "For example, helium and neon."}, {"lv": 2, "q": "Ionic bonding happens between ...", "o": ["a metal and a non-metal", "two non-metals", "two noble gases", "two metals only"], "a": 0, "p": "Electrons are transferred."}, {"lv": 2, "q": "Covalent bonding involves ...", "o": ["sharing electrons", "transferring electrons", "losing protons", "sharing neutrons"], "a": 0, "p": "Non-metals share pairs of electrons."}, {"lv": 2, "q": "A sodium atom loses one electron. What ion forms?", "o": ["Na⁺", "Na⁻", "Na²⁺", "Na"], "a": 0, "p": "Losing a negative electron gives +1."}, {"lv": 2, "q": "Which compound has covalent bonds?", "o": ["water (H₂O)", "sodium chloride", "magnesium oxide", "potassium bromide"], "a": 0, "p": "H and O are both non-metals."}, {"lv": 3, "q": "Why does reactivity increase down Group 1?", "o": ["The outer electron is further from the nucleus and is lost more easily.", "Atoms get smaller.", "There are fewer electrons.", "Protons are lost."], "a": 0, "p": "Weaker attraction means the outer electron is lost more easily."}, {"lv": 3, "q": "Chlorine gains an electron to form Cl⁻. Why?", "o": ["to get a full outer shell", "to lose mass", "to become a metal", "to become radioactive"], "a": 0, "p": "Gaining one electron gives 8 in the outer shell."}, {"lv": 3, "q": "Magnesium (Group 2) reacts with oxygen. What is the formula of magnesium oxide?", "o": ["MgO", "Mg₂O", "MgO₂", "Mg₂O₃"], "a": 0, "p": "Mg²⁺ and O²⁻ combine 1 : 1."}, {"lv": 3, "q": "Why do ionic compounds have high melting points?", "o": ["Strong electrostatic forces between oppositely charged ions", "Weak forces between molecules", "They contain no bonds", "They are gases"], "a": 0, "p": "Lots of energy is needed to break the lattice."}]}, {"id": "cam-sci-k9-2", "name": "Electricity: current and voltage", "desc": "Series and parallel, Ohm's law", "idx": 2, "soal": [{"lv": 1, "q": "Current is measured in ...", "o": ["volts", "amperes", "ohms", "watts"], "a": 1, "p": "Current (I) is measured in amps (A)."}, {"lv": 1, "q": "Voltage is measured with a ...", "o": ["voltmeter", "ammeter", "thermometer", "newton meter"], "a": 0, "p": "A voltmeter is placed in parallel."}, {"lv": 1, "q": "Ohm's law is ...", "o": ["V = I × R", "V = I + R", "R = V × I", "I = V × R"], "a": 0, "p": "Voltage = current × resistance."}, {"lv": 1, "q": "In a series circuit, the current is ...", "o": ["the same everywhere", "different in each component", "zero", "doubled"], "a": 0, "p": "There is only one path."}, {"lv": 2, "q": "What current flows through a 6 Ω resistor with 12 V across it?", "o": ["2 A", "72 A", "0.5 A", "18 A"], "a": 0, "p": "I = V/R = 12/6."}, {"lv": 2, "q": "Two 4 Ω resistors are in series. The total resistance is ...", "o": ["8 Ω", "2 Ω", "16 Ω", "4 Ω"], "a": 0, "p": "Series: add."}, {"lv": 2, "q": "In a parallel circuit, the voltage across each branch is ...", "o": ["the same as the supply", "split equally", "zero", "doubled"], "a": 0, "p": "Each branch gets the full voltage."}, {"lv": 2, "q": "If one bulb breaks in a series circuit, the other bulbs ...", "o": ["go out", "get brighter", "stay the same", "flash"], "a": 0, "p": "The single path is broken."}, {"lv": 3, "q": "Two 6 Ω resistors are connected in parallel. What is the total resistance?", "o": ["3 Ω", "12 Ω", "6 Ω", "36 Ω"], "a": 0, "p": "1/R = 1/6 + 1/6 = 1/3 → R = 3 Ω."}, {"lv": 3, "q": "A 9 V battery is connected to resistors of 2 Ω and 1 Ω in series. What is the voltage across the 2 Ω resistor?", "o": ["6 V", "3 V", "9 V", "4.5 V"], "a": 0, "p": "I = 9/3 = 3 A; V = 3 × 2 = 6 V."}, {"lv": 3, "q": "A current of 0.5 A flows through a lamp for 60 s. How much charge flows?", "o": ["30 C", "120 C", "0.0083 C", "60 C"], "a": 0, "p": "Q = I × t = 0.5 × 60."}, {"lv": 3, "q": "Why are household appliances connected in parallel?", "o": ["Each gets the full voltage and can be switched independently.", "To save wire.", "So all go off together.", "To reduce voltage."], "a": 0, "p": "Parallel circuits allow independent control."}]}]}}, "sgp": {"eng": {"1": [{"id": "sgp-eng-k1-0", "name": "Phonics and sight words", "desc": "Reading simple words", "idx": 0, "soal": [{"lv": 1, "q": "Which word begins with the 'b' sound?", "o": ["ball", "doll", "cat", "sun"], "a": 0, "p": "Ball starts with b."}, {"lv": 1, "q": "Which word rhymes with 'cat'?", "o": ["hat", "cup", "dog", "pen"], "a": 0, "p": "Cat and hat end with -at."}, {"lv": 1, "q": "Which is a sight word?", "o": ["the", "elephant", "xylophone", "kangaroo"], "a": 0, "p": "'The' is a common sight word."}, {"lv": 1, "q": "What is the first sound in 'fish'?", "o": ["f", "i", "s", "sh"], "a": 0, "p": "Fish begins with f."}, {"lv": 2, "q": "Which word has the 'sh' sound?", "o": ["ship", "sip", "hip", "tip"], "a": 0, "p": "Ship starts with sh."}, {"lv": 2, "q": "Which word has the long 'a' sound?", "o": ["cake", "cat", "cap", "can"], "a": 0, "p": "The magic e makes 'a' long."}, {"lv": 2, "q": "Blend the sounds: c-a-t", "o": ["cat", "cot", "cut", "act"], "a": 0, "p": "c + a + t = cat."}, {"lv": 2, "q": "Which word rhymes with 'pig'?", "o": ["wig", "pin", "pot", "peg"], "a": 0, "p": "Pig and wig end with -ig."}, {"lv": 3, "q": "Which word has the 'ch' sound?", "o": ["chair", "share", "car", "hair"], "a": 0, "p": "Chair begins with ch."}, {"lv": 3, "q": "Which word is spelled correctly?", "o": ["said", "sed", "siad", "saed"], "a": 0, "p": "'Said' is a tricky sight word."}, {"lv": 3, "q": "How many sounds are in 'frog'?", "o": ["4", "3", "5", "2"], "a": 0, "p": "f-r-o-g."}, {"lv": 3, "q": "Which word has the same vowel sound as 'boat'?", "o": ["coat", "cot", "cut", "cat"], "a": 0, "p": "Both have the long 'o' sound (oa)."}]}, {"id": "sgp-eng-k1-1", "name": "Nouns and articles", "desc": "a, an, the", "idx": 1, "soal": [{"lv": 1, "q": "Which word is a noun?", "o": ["apple", "run", "big", "quickly"], "a": 0, "p": "A noun names a thing."}, {"lv": 1, "q": "Choose the correct article: ___ egg", "o": ["an", "a", "the a", "two"], "a": 0, "p": "Use 'an' before a vowel sound."}, {"lv": 1, "q": "Choose the correct article: ___ dog", "o": ["a", "an", "a an", "some an"], "a": 0, "p": "Use 'a' before a consonant sound."}, {"lv": 1, "q": "Which word names a person?", "o": ["teacher", "jump", "red", "happy"], "a": 0, "p": "Teacher is a noun."}, {"lv": 2, "q": "I saw ___ elephant at the zoo.", "o": ["an", "a", "two", "these"], "a": 0, "p": "Elephant starts with a vowel sound."}, {"lv": 2, "q": "___ sun is very hot.", "o": ["The", "A", "An", "Some"], "a": 0, "p": "There is only one sun, so we use 'the'."}, {"lv": 2, "q": "Which is a naming word for a place?", "o": ["school", "sing", "tall", "slowly"], "a": 0, "p": "School is a place."}, {"lv": 2, "q": "She ate ___ orange.", "o": ["an", "a", "the an", "two"], "a": 0, "p": "Orange starts with a vowel sound."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["I have an umbrella.", "I have a umbrella.", "I have an book.", "I have a apple."], "a": 0, "p": "an + umbrella."}, {"lv": 3, "q": "We need ___ hour to finish.", "o": ["an", "a", "the a", "some"], "a": 0, "p": "'Hour' starts with a vowel sound (silent h)."}, {"lv": 3, "q": "Which sentence uses 'the' correctly?", "o": ["Please close the door.", "Please close the a door.", "Please close an door.", "Please close a the door."], "a": 0, "p": "We mean a specific door."}, {"lv": 3, "q": "How many nouns are in: 'The cat sat on the mat'?", "o": ["2", "1", "3", "4"], "a": 0, "p": "Cat and mat."}]}, {"id": "sgp-eng-k1-2", "name": "Simple sentences", "desc": "Word order and punctuation", "idx": 2, "soal": [{"lv": 1, "q": "Which is a complete sentence?", "o": ["The dog runs.", "the dog", "runs fast", "dog the"], "a": 0, "p": "It has a subject and a verb."}, {"lv": 1, "q": "A sentence begins with a ...", "o": ["capital letter", "full stop", "comma", "small letter"], "a": 0, "p": "Always start with a capital."}, {"lv": 1, "q": "A telling sentence ends with a ...", "o": ["full stop", "comma", "capital letter", "dash"], "a": 0, "p": "Use a full stop."}, {"lv": 1, "q": "Put the words in order: cat / The / sleeps.", "o": ["The cat sleeps.", "Cat the sleeps.", "Sleeps the cat.", "The sleeps cat."], "a": 0, "p": "Subject first, then the verb."}, {"lv": 2, "q": "In the sentence 'i like to play.', which letter must be a capital?", "o": ["the word i", "the p in play", "the l in like", "no letter"], "a": 0, "p": "The word I is always a capital letter, and it also starts the sentence."}, {"lv": 2, "q": "Which sentence asks a question?", "o": ["Where is my hat?", "My hat is red.", "Find my hat.", "I lost my hat."], "a": 0, "p": "It ends with a question mark."}, {"lv": 2, "q": "Put in order: birds / The / sing / loudly.", "o": ["The birds sing loudly.", "Birds the sing loudly.", "Loudly the birds sing the.", "Sing the birds loudly."], "a": 0, "p": "Subject, verb, then how."}, {"lv": 2, "q": "Choose the correct ending: 'What is your name ___'", "o": ["?", ".", "!", ","], "a": 0, "p": "It is a question."}, {"lv": 3, "q": "'tom and i went to the park.' Which words need capital letters?", "o": ["Tom and I", "park only", "went and the", "to and the"], "a": 0, "p": "Names and the word 'I' always need capital letters."}, {"lv": 3, "q": "Which is NOT a sentence?", "o": ["Under the big tree.", "The bird flew away.", "I am happy.", "She can swim."], "a": 0, "p": "It has no verb."}, {"lv": 3, "q": "What is missing in this sentence: 'My mother cooks rice'", "o": ["a full stop at the end", "a question mark at the start", "a comma after My", "nothing is missing"], "a": 0, "p": "A telling sentence must end with a full stop."}, {"lv": 3, "q": "Put in order: is / sister / My / tall.", "o": ["My sister is tall.", "Is my sister tall.", "My tall is sister.", "Sister my is tall."], "a": 0, "p": "Subject + verb + describing word."}]}], "10": [{"id": "sgp-eng-k10-0", "name": "Directed writing", "desc": "O-Level situational tasks", "idx": 0, "soal": [{"lv": 1, "q": "Directed (situational) writing tasks provide ...", "o": ["a context, purpose and audience", "only a title", "a poem", "a picture only"], "a": 0, "p": "Task elements."}, {"lv": 1, "q": "A formal report should use ...", "o": ["clear headings and objective language", "slang", "a story opening", "emojis"], "a": 0, "p": "Formal style."}, {"lv": 1, "q": "A speech is delivered to ...", "o": ["listeners", "nobody", "only the writer", "a computer"], "a": 0, "p": "Audience."}, {"lv": 1, "q": "A proposal aims to ...", "o": ["recommend an idea or plan", "tell a fairy tale", "describe a sunset", "list facts only"], "a": 0, "p": "Purpose."}, {"lv": 2, "q": "Which content is MOST relevant in a proposal for a school garden?", "o": ["benefits, cost and plan for maintenance", "your favourite colour", "a story about your pet", "the history of the school bus"], "a": 0, "p": "Relevance."}, {"lv": 2, "q": "Which opening suits a formal speech at a school assembly?", "o": ["Good morning, Principal, teachers and fellow students.", "Hey guys!", "Yo, listen up!", "Once upon a time..."], "a": 0, "p": "Formal greeting."}, {"lv": 2, "q": "Why should you adapt information from the visual stimulus?", "o": ["to show understanding and fit your purpose", "to copy it exactly", "to ignore it", "to make it longer"], "a": 0, "p": "Task requirement."}, {"lv": 2, "q": "Which tone suits an email to a hotel requesting a refund?", "o": ["courteous and firm", "aggressive", "overly casual", "sarcastic"], "a": 0, "p": "Professional."}, {"lv": 3, "q": "Which is the best way to structure a persuasive proposal?", "o": ["introduce the issue, present solutions with reasons, address concerns, conclude with a recommendation", "list random ideas", "start with the conclusion only", "write only one paragraph"], "a": 0, "p": "Logical."}, {"lv": 3, "q": "Which sentence shows awareness of the audience (parents)?", "o": ["As parents, you will appreciate how this programme supports your child's wellbeing.", "Students like games.", "This is cool.", "Teachers decided."], "a": 0, "p": "Directly relevant to the audience."}, {"lv": 3, "q": "Why might you include a counter-argument in a proposal?", "o": ["to anticipate objections and strengthen credibility", "to weaken your proposal", "to fill space", "to confuse readers"], "a": 0, "p": "Persuasive strategy."}, {"lv": 3, "q": "Which closing sentence is most effective for a formal report?", "o": ["In view of the above, it is recommended that the committee approve the plan.", "Bye.", "That's it lah.", "Hope you like it!"], "a": 0, "p": "Formal recommendation."}]}, {"id": "sgp-eng-k10-1", "name": "Continuous writing techniques", "desc": "Narrative and argumentative", "idx": 1, "soal": [{"lv": 1, "q": "Continuous writing includes ...", "o": ["narrative, descriptive and argumentative essays", "only poems", "only emails", "only lists"], "a": 0, "p": "Essay types."}, {"lv": 1, "q": "A good narrative needs ...", "o": ["a clear plot with conflict and resolution", "only facts", "bullet points", "statistics"], "a": 0, "p": "Story structure."}, {"lv": 1, "q": "Which opening is most engaging?", "o": ["The phone rang at 3 a.m.—and nobody ever called at 3 a.m.", "This story is about a phone.", "I will now tell you a story.", "Hello, reader."], "a": 0, "p": "A hook."}, {"lv": 1, "q": "An argumentative essay must have a ...", "o": ["clear stand", "plot twist", "villain", "dialogue"], "a": 0, "p": "Position."}, {"lv": 2, "q": "Which technique builds suspense?", "o": ["delaying information", "giving away the ending at the start", "listing facts", "using only long sentences"], "a": 0, "p": "Withholding."}, {"lv": 2, "q": "Which sentence 'shows' rather than 'tells'?", "o": ["Her hands shook as she unfolded the letter.", "She was nervous.", "She felt scared.", "She was afraid."], "a": 0, "p": "Action shows emotion."}, {"lv": 2, "q": "In an argumentative essay, each body paragraph should ...", "o": ["present one main point with evidence", "contain all points", "be a story", "have no evidence"], "a": 0, "p": "Focus."}, {"lv": 2, "q": "Which is an effective way to end a narrative?", "o": ["a resolution that reflects the character's change", "'and then I woke up'", "a new unrelated conflict", "no ending"], "a": 0, "p": "Closure."}, {"lv": 3, "q": "Why use a flashback in a narrative?", "o": ["to reveal background that explains the present", "to confuse readers", "to make it shorter", "to end the story"], "a": 0, "p": "Depth."}, {"lv": 3, "q": "Which is the strongest topic sentence for an argumentative essay on social media?", "o": ["Social media, while connecting people, often fuels anxiety among teenagers.", "Social media exists.", "I use social media.", "Many apps are social."], "a": 0, "p": "Clear and arguable."}, {"lv": 3, "q": "What makes descriptive writing vivid?", "o": ["sensory details and precise word choice", "lists of facts", "repeating 'nice'", "few details"], "a": 0, "p": "Imagery."}, {"lv": 3, "q": "Which pacing technique slows down a dramatic moment?", "o": ["expanding it with detailed description of thoughts and senses", "using one short sentence", "skipping it", "summarising it"], "a": 0, "p": "Slow-motion effect."}]}, {"id": "sgp-eng-k10-2", "name": "Comprehension: summary and vocabulary", "desc": "O-Level comprehension", "idx": 2, "soal": [{"lv": 1, "q": "A summary answer should be ...", "o": ["concise and in your own words", "copied fully", "full of opinions", "longer than the passage"], "a": 0, "p": "Conciseness."}, {"lv": 1, "q": "'The task was arduous.' 'Arduous' means ...", "o": ["difficult and tiring", "easy", "short", "funny"], "a": 0, "p": "Vocabulary."}, {"lv": 1, "q": "'She gave a candid answer.' 'Candid' means ...", "o": ["honest and frank", "secret", "false", "rude"], "a": 0, "p": "Vocabulary."}, {"lv": 1, "q": "When summarising, avoid ...", "o": ["repetition and examples", "main points", "key ideas", "clarity"], "a": 0, "p": "Remove extras."}, {"lv": 2, "q": "'The ruins were a poignant reminder of the war.' 'Poignant' means ...", "o": ["deeply moving and sad", "funny", "new", "colourful"], "a": 0, "p": "Evokes sadness."}, {"lv": 2, "q": "'His explanation was lucid.' 'Lucid' means ...", "o": ["clear and easy to understand", "confusing", "long", "angry"], "a": 0, "p": "Clarity."}, {"lv": 2, "q": "Which paraphrase of 'The company's profits plummeted' is best?", "o": ["The company's profits fell sharply.", "The company profits plummeted down.", "The profits plummeted the company.", "The company grew."], "a": 0, "p": "Accurate rewording."}, {"lv": 2, "q": "A summary question asks for 'problems faced by the town'. Which point fits?", "o": ["Frequent floods damaged homes.", "The town has a lovely park.", "The mayor likes tea.", "Tourists enjoyed the food."], "a": 0, "p": "It is a problem."}, {"lv": 3, "q": "'The CEO's speech was replete with jargon.' 'Replete' means ...", "o": ["filled", "empty", "short", "free"], "a": 0, "p": "Full of."}, {"lv": 3, "q": "Which sentence is the most concise summary point?", "o": ["Rising rents forced small shops to close.", "Because rents were rising more and more, many of the small shops had to close down eventually.", "Small shops, due to rent, which rose, closed.", "Rents rose; shops closed; it was sad; many shops."], "a": 0, "p": "Fewest words, clear meaning."}, {"lv": 3, "q": "'The policy was met with scepticism.' 'Scepticism' means ...", "o": ["doubt", "enthusiasm", "anger", "approval"], "a": 0, "p": "Disbelief."}, {"lv": 3, "q": "'The child's tenacity impressed the coach.' 'Tenacity' means ...", "o": ["determination and persistence", "laziness", "speed", "shyness"], "a": 0, "p": "Not giving up."}]}], "11": [{"id": "sgp-eng-k11-0", "name": "Understanding arguments and evidence", "desc": "General Paper skills", "idx": 0, "soal": [{"lv": 1, "q": "In General Paper, a claim is ...", "o": ["a statement the writer argues is true", "a question", "a story", "a quotation only"], "a": 0, "p": "Assertion."}, {"lv": 1, "q": "Evidence supports a claim through ...", "o": ["facts, examples and data", "rhymes", "insults", "jokes"], "a": 0, "p": "Support."}, {"lv": 1, "q": "An assumption is ...", "o": ["an unstated idea an argument depends on", "the conclusion", "a statistic", "a footnote"], "a": 0, "p": "A hidden premise."}, {"lv": 1, "q": "A counter-argument is ...", "o": ["an opposing view", "the thesis", "the title", "a summary"], "a": 0, "p": "The other side."}, {"lv": 2, "q": "\"Since smartphones are everywhere, they must be beneficial.\" What is the flaw?", "o": ["popularity does not prove benefit", "it uses too much data", "it is perfectly logical", "it has a counter-argument"], "a": 0, "p": "Appeal to popularity."}, {"lv": 2, "q": "Which evidence is most convincing for a claim about climate change?", "o": ["peer-reviewed scientific data", "a celebrity tweet", "a personal guess", "an advertisement"], "a": 0, "p": "Credibility."}, {"lv": 2, "q": "What does 'qualifying' a claim mean?", "o": ["limiting it with words such as 'often' or 'in some cases'", "proving it absolutely", "removing evidence", "making it extreme"], "a": 0, "p": "Nuance."}, {"lv": 2, "q": "\"If we allow phones in class, soon students will never study.\" This is ...", "o": ["a slippery slope fallacy", "sound reasoning", "statistical evidence", "a definition"], "a": 0, "p": "Exaggerated chain."}, {"lv": 3, "q": "Which response best evaluates evidence?", "o": ["The study is persuasive but limited, as its sample was confined to one city.", "The study is correct.", "I disagree with studies.", "Studies are boring."], "a": 0, "p": "Balanced evaluation."}, {"lv": 3, "q": "\"Developed nations should lead climate action because they emit the most historically.\" What is the underlying assumption?", "o": ["Those responsible for a problem should bear more responsibility for solving it.", "All nations emit equally.", "Climate change is not real.", "Poor nations emit the most."], "a": 0, "p": "Moral premise."}, {"lv": 3, "q": "Which is a correlation mistaken for causation?", "o": ["Ice cream sales and drownings rise together, so ice cream causes drowning.", "Smoking increases cancer risk according to many studies.", "Exercise improves heart health in trials.", "Vaccines reduce infection in controlled trials."], "a": 0, "p": "Both are linked to hot weather."}, {"lv": 3, "q": "Why should a GP essay consider context (e.g. Singapore vs other societies)?", "o": ["Arguments may apply differently in different societies.", "To make it longer.", "To avoid examples.", "Context never matters."], "a": 0, "p": "Nuanced application."}]}, {"id": "sgp-eng-k11-1", "name": "Essay structure", "desc": "Introduction, body, conclusion", "idx": 1, "soal": [{"lv": 1, "q": "An essay introduction should ...", "o": ["define key terms and state the stand", "end the argument", "list random facts", "contain only a quotation"], "a": 0, "p": "Set up the essay."}, {"lv": 1, "q": "Each body paragraph should focus on ...", "o": ["one main idea", "all ideas", "no idea", "the conclusion"], "a": 0, "p": "Unity."}, {"lv": 1, "q": "A conclusion should ...", "o": ["synthesise arguments and reaffirm the stand", "introduce new arguments", "repeat the introduction exactly", "be one word"], "a": 0, "p": "Closure."}, {"lv": 1, "q": "A topic sentence ...", "o": ["introduces the paragraph's main point", "ends the essay", "is always a question", "lists sources"], "a": 0, "p": "Guide."}, {"lv": 2, "q": "Which is a good GP thesis?", "o": ["While technology enhances learning, over-reliance on it risks eroding critical thinking.", "Technology is technology.", "I like computers.", "Everyone uses phones."], "a": 0, "p": "Nuanced stand."}, {"lv": 2, "q": "Why define key terms in the introduction?", "o": ["to clarify scope and avoid misinterpretation", "to fill words", "to confuse the examiner", "it is not useful"], "a": 0, "p": "Precision."}, {"lv": 2, "q": "Which linking phrase shows contrast between paragraphs?", "o": ["Conversely,", "Furthermore,", "Similarly,", "In addition,"], "a": 0, "p": "Contrast."}, {"lv": 2, "q": "The PEEL structure stands for ...", "o": ["Point, Evidence, Explanation, Link", "Plan, Edit, Erase, Learn", "Paragraph, Essay, End, List", "Point, Example, Ending, Line"], "a": 0, "p": "Paragraph structure."}, {"lv": 3, "q": "What makes an essay coherent?", "o": ["logical progression of ideas with clear links", "random order", "repetition of the same point", "very short paragraphs only"], "a": 0, "p": "Flow."}, {"lv": 3, "q": "Which is an effective way to handle the question 'To what extent...'?", "o": ["weigh both sides and reach a reasoned degree of agreement", "agree completely without reason", "ignore the question", "list examples only"], "a": 0, "p": "Extent requires judgement."}, {"lv": 3, "q": "Why use specific, current examples in a GP essay?", "o": ["to ground arguments in reality and show awareness", "to replace analysis", "to fill space", "they are not needed"], "a": 0, "p": "Credibility."}, {"lv": 3, "q": "Which conclusion is strongest?", "o": ["Ultimately, although X has merits, its costs to Y suggest a more measured approach is wiser.", "In conclusion, that's all.", "This essay was about X.", "I hope you liked it."], "a": 0, "p": "Evaluative."}]}, {"id": "sgp-eng-k11-2", "name": "Vocabulary for General Paper", "desc": "Academic vocabulary", "idx": 2, "soal": [{"lv": 1, "q": "'Ubiquitous' means ...", "o": ["found everywhere", "rare", "ancient", "expensive"], "a": 0, "p": "Omnipresent."}, {"lv": 1, "q": "'Pragmatic' means ...", "o": ["practical and realistic", "idealistic", "lazy", "emotional"], "a": 0, "p": "Practical."}, {"lv": 1, "q": "'Detrimental' means ...", "o": ["harmful", "helpful", "neutral", "hidden"], "a": 0, "p": "Damaging."}, {"lv": 1, "q": "'Advocate' (verb) means ...", "o": ["to publicly support", "to oppose", "to ignore", "to hide"], "a": 0, "p": "Support."}, {"lv": 2, "q": "'The policy had unprecedented effects.' 'Unprecedented' means ...", "o": ["never done or known before", "expected", "minor", "repeated"], "a": 0, "p": "New."}, {"lv": 2, "q": "'Her arguments were cogent.' 'Cogent' means ...", "o": ["clear, logical and convincing", "weak", "emotional", "long"], "a": 0, "p": "Persuasive."}, {"lv": 2, "q": "'The issue is contentious.' 'Contentious' means ...", "o": ["likely to cause disagreement", "agreed by all", "trivial", "old"], "a": 0, "p": "Controversial."}, {"lv": 2, "q": "'He made a tenuous link between the two events.' 'Tenuous' means ...", "o": ["weak or slight", "strong", "obvious", "proven"], "a": 0, "p": "Flimsy."}, {"lv": 3, "q": "'The minister's speech was laden with rhetoric but lacked substance.' 'Rhetoric' here means ...", "o": ["persuasive language that may be insincere", "facts", "humour", "poetry"], "a": 0, "p": "Contextual meaning."}, {"lv": 3, "q": "'Globalisation has engendered cultural homogenisation.' 'Engendered' means ...", "o": ["caused or given rise to", "prevented", "ended", "ignored"], "a": 0, "p": "Produced."}, {"lv": 3, "q": "'The data are anecdotal.' This means the data are ...", "o": ["based on personal accounts rather than systematic research", "statistically rigorous", "fictional", "outdated"], "a": 0, "p": "Limited reliability."}, {"lv": 3, "q": "'A dichotomy between economic growth and conservation' refers to ...", "o": ["a division into two opposing parts", "a perfect agreement", "a statistic", "a solution"], "a": 0, "p": "Two contrasting things."}]}], "12": [{"id": "sgp-eng-k12-0", "name": "Application question skills", "desc": "Applying passage ideas", "idx": 0, "soal": [{"lv": 1, "q": "An application question asks you to ...", "o": ["apply the author's ideas to your own society or context", "copy the passage", "write a story", "summarise only"], "a": 0, "p": "AQ skill."}, {"lv": 1, "q": "In an application answer, you should refer to ...", "o": ["specific points from the passage", "unrelated topics", "only your feelings", "movie plots"], "a": 0, "p": "Textual grounding."}, {"lv": 1, "q": "Evaluation in an AQ means ...", "o": ["judging how far the author's views apply", "copying views", "ignoring views", "listing facts"], "a": 0, "p": "Critical assessment."}, {"lv": 1, "q": "Which context is typically expected in a Singapore AQ?", "o": ["your own society (Singapore)", "Mars", "a fictional kingdom", "ancient Rome only"], "a": 0, "p": "Relevance."}, {"lv": 2, "q": "Which is the best start to an AQ answer?", "o": ["The author's claim that technology isolates people is only partly true in Singapore, where...", "I like technology.", "Technology is everywhere.", "The passage is long."], "a": 0, "p": "It engages the passage with a stance."}, {"lv": 2, "q": "Why should you give specific local examples?", "o": ["to support your evaluation with evidence", "to fill space", "to avoid analysis", "examples are not needed"], "a": 0, "p": "Substantiation."}, {"lv": 2, "q": "Which shows balanced evaluation?", "o": ["While this is true for older Singaporeans, younger ones may differ because...", "This is totally true.", "This is totally false.", "No comment."], "a": 0, "p": "Nuance."}, {"lv": 2, "q": "Which is a weak AQ response?", "o": ["merely repeating the author's points without evaluation", "linking to local policies", "giving reasons and examples", "qualifying the stand"], "a": 0, "p": "No application."}, {"lv": 3, "q": "The author argues that consumerism erodes community. How might you evaluate this for Singapore?", "o": ["Acknowledge consumer culture but note community initiatives such as neighbourhood events that counter it.", "Agree completely without reasons.", "Talk about another country only.", "Summarise the passage."], "a": 0, "p": "Applies and evaluates."}, {"lv": 3, "q": "Which phrase signals a qualified stand?", "o": ["To a large extent...", "Absolutely always...", "Never ever...", "Everyone knows..."], "a": 0, "p": "Degree of agreement."}, {"lv": 3, "q": "Why should you choose two or three of the author's points rather than all of them?", "o": ["to allow depth of evaluation within limited time and words", "because more points lose marks", "to avoid reading", "it does not matter"], "a": 0, "p": "Depth over breadth."}, {"lv": 3, "q": "Which ending best concludes an AQ?", "o": ["Overall, while the author's concerns are valid, Singapore's context moderates their impact.", "The end.", "I agree.", "This passage was interesting."], "a": 0, "p": "Evaluative conclusion."}]}, {"id": "sgp-eng-k12-1", "name": "Critical thinking on society issues", "desc": "Evaluating viewpoints", "idx": 1, "soal": [{"lv": 1, "q": "Critical thinking involves ...", "o": ["analysing and evaluating ideas logically", "accepting everything", "memorising only", "ignoring evidence"], "a": 0, "p": "Reasoned judgement."}, {"lv": 1, "q": "A stakeholder is ...", "o": ["someone affected by or involved in an issue", "a type of fence", "a statistic", "a journalist only"], "a": 0, "p": "Perspective."}, {"lv": 1, "q": "Considering multiple perspectives helps you ...", "o": ["form a balanced view", "be biased", "avoid evidence", "be extreme"], "a": 0, "p": "Balance."}, {"lv": 1, "q": "An ethical issue involves questions of ...", "o": ["right and wrong", "colour", "weather", "speed"], "a": 0, "p": "Morality."}, {"lv": 2, "q": "\"Banning cars will solve pollution.\" A critical thinker would say ...", "o": ["it may reduce pollution but has economic and social costs and other sources remain", "it is perfect", "pollution is not real", "cars are not polluting"], "a": 0, "p": "Weighs trade-offs."}, {"lv": 2, "q": "Which question best tests a policy?", "o": ["Who benefits, who bears the costs, and is it sustainable?", "Is it popular online?", "Does it sound nice?", "Is it short?"], "a": 0, "p": "Evaluation criteria."}, {"lv": 2, "q": "Why consider unintended consequences?", "o": ["Policies may produce effects beyond their aims.", "They never happen.", "To make essays shorter.", "To avoid evidence."], "a": 0, "p": "Foresight."}, {"lv": 2, "q": "Which is an example of a trade-off?", "o": ["Economic growth versus environmental protection", "Apples and oranges taste different", "The sun rises", "Rain is wet"], "a": 0, "p": "Competing priorities."}, {"lv": 3, "q": "Should social media platforms be held responsible for misinformation? Which response is most critical?", "o": ["Weigh free speech against harm, consider platform capability and propose proportionate regulation.", "Yes, completely.", "No, never.", "Social media is fun."], "a": 0, "p": "Nuanced."}, {"lv": 3, "q": "Which reasoning error is shown: 'Older generations used less technology and were happier, so technology causes unhappiness.'?", "o": ["confusing correlation with causation and ignoring other factors", "sound inference", "valid statistics", "a definition"], "a": 0, "p": "Confounding factors."}, {"lv": 3, "q": "Why is it important to question the source of information on social issues?", "o": ["Sources may be biased or have vested interests.", "All sources are equal.", "Sources never matter.", "Only famous people are reliable."], "a": 0, "p": "Credibility."}, {"lv": 3, "q": "Which is the most balanced view on ageing populations?", "o": ["It strains healthcare and the workforce but also creates opportunities in silver industries and active ageing.", "It is a disaster.", "It does not matter.", "It only affects Japan."], "a": 0, "p": "Both challenges and opportunities."}]}, {"id": "sgp-eng-k12-2", "name": "Comprehension of complex texts", "desc": "Inference and analysis", "idx": 2, "soal": [{"lv": 1, "q": "Inference requires ...", "o": ["reading beyond the literal meaning", "copying the text", "skipping sentences", "counting words"], "a": 0, "p": "Implicit meaning."}, {"lv": 1, "q": "The tone of a passage reflects ...", "o": ["the writer's attitude", "the font", "the length", "the date"], "a": 0, "p": "Attitude."}, {"lv": 1, "q": "'Irony' is when ...", "o": ["the intended meaning is the opposite of the literal meaning", "a text rhymes", "facts are listed", "a story ends"], "a": 0, "p": "Definition."}, {"lv": 1, "q": "To identify a writer's purpose, you ask ...", "o": ["why the writer wrote this", "how many pages there are", "what font is used", "who printed it"], "a": 0, "p": "Purpose."}, {"lv": 2, "q": "'What a wonderful idea—let's cut library funding during exam season.' The tone is ...", "o": ["sarcastic", "sincere", "neutral", "joyful"], "a": 0, "p": "Ironic praise."}, {"lv": 2, "q": "'The so-called experts' implies the writer ...", "o": ["doubts the experts' authority", "fully trusts them", "is an expert", "is neutral"], "a": 0, "p": "Scare quotes / 'so-called'."}, {"lv": 2, "q": "Why might a writer begin with an anecdote before an argument?", "o": ["to engage readers and humanise the issue", "to avoid the topic", "to fill space", "to confuse"], "a": 0, "p": "Hook."}, {"lv": 2, "q": "A writer uses 'crisis', 'collapse' and 'catastrophe'. The effect is ...", "o": ["a sense of urgency and alarm", "calm reassurance", "humour", "neutrality"], "a": 0, "p": "Emotive diction."}, {"lv": 3, "q": "'Progress, it seems, is measured by how quickly we can forget the past.' What is the writer implying?", "o": ["Modern progress often neglects heritage.", "Progress is always good.", "The past is irrelevant.", "Forgetting is healthy."], "a": 0, "p": "Critical irony."}, {"lv": 3, "q": "What is the function of a concession like 'Admittedly, technology has improved access to information'?", "o": ["to acknowledge a counter-view before rebutting it", "to end the argument", "to change the topic", "to agree completely"], "a": 0, "p": "Rhetorical structure."}, {"lv": 3, "q": "'The city never sleeps, and neither, it seems, do its anxious residents.' What does this suggest?", "o": ["Urban life creates constant stress.", "Residents are energetic.", "The city is quiet.", "People sleep well."], "a": 0, "p": "Implicit criticism."}, {"lv": 3, "q": "Which is the best explanation of a writer's use of rhetorical questions in a complex argument?", "o": ["to provoke reflection and guide readers towards the writer's view", "to ask for answers", "to confuse", "to add facts"], "a": 0, "p": "Persuasive function."}]}], "2": [{"id": "sgp-eng-k2-0", "name": "Verbs and tenses", "desc": "Present and past", "idx": 0, "soal": [{"lv": 1, "q": "Yesterday I ___ to the park.", "o": ["went", "go", "goes", "going"], "a": 0, "p": "Past tense of go."}, {"lv": 1, "q": "She ___ to school every day.", "o": ["walks", "walk", "walked yesterday", "walking"], "a": 0, "p": "Present tense with 'she': walks."}, {"lv": 1, "q": "What is the past tense of 'jump'?", "o": ["jumped", "jumps", "jumping", "jumpt"], "a": 0, "p": "Add -ed."}, {"lv": 1, "q": "They ___ football now.", "o": ["are playing", "played yesterday", "plays", "play yesterday"], "a": 0, "p": "Happening now."}, {"lv": 2, "q": "Last night, we ___ a movie.", "o": ["watched", "watch", "watches", "watching"], "a": 0, "p": "Past tense."}, {"lv": 2, "q": "My father ___ coffee every morning.", "o": ["drinks", "drink", "drank last", "drinking"], "a": 0, "p": "Habit: present simple with 's'."}, {"lv": 2, "q": "What is the past tense of 'eat'?", "o": ["ate", "eated", "eats", "eaten"], "a": 0, "p": "Irregular verb."}, {"lv": 2, "q": "The baby ___ now.", "o": ["is sleeping", "slept", "sleep", "sleeps yesterday"], "a": 0, "p": "Present continuous."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["I saw a rainbow yesterday.", "I see a rainbow yesterday.", "I seeing a rainbow yesterday.", "I seen a rainbow yesterday."], "a": 0, "p": "Past tense: saw."}, {"lv": 3, "q": "Last Sunday, Mum ___ a cake and we ___ it.", "o": ["baked, ate", "bakes, eat", "bake, eated", "baking, ate"], "a": 0, "p": "Both verbs in the past."}, {"lv": 3, "q": "Which verb is in the past tense?", "o": ["wrote", "write", "writes", "writing"], "a": 0, "p": "Write → wrote."}, {"lv": 3, "q": "Tomorrow, we ___ to the zoo.", "o": ["will go", "went", "go yesterday", "gone"], "a": 0, "p": "Future: will + verb."}]}, {"id": "sgp-eng-k2-1", "name": "Adjectives", "desc": "Describing and comparing", "idx": 1, "soal": [{"lv": 1, "q": "Which word describes a noun?", "o": ["tall", "run", "quickly", "eat"], "a": 0, "p": "'Tall' is an adjective."}, {"lv": 1, "q": "The ___ cat is sleeping.", "o": ["fat", "sleepily", "run", "eat"], "a": 0, "p": "Adjective before the noun."}, {"lv": 1, "q": "What is the opposite of 'big'?", "o": ["small", "huge", "tall", "wide"], "a": 0, "p": "Big ↔ small."}, {"lv": 1, "q": "Which adjective describes ice?", "o": ["cold", "hot", "loud", "soft"], "a": 0, "p": "Ice is cold."}, {"lv": 2, "q": "Tom is tall. Ben is ___ than Tom.", "o": ["taller", "tallest", "tall", "more tall"], "a": 0, "p": "Comparing two: -er."}, {"lv": 2, "q": "This is the ___ tree in the park.", "o": ["biggest", "bigger", "big", "more big"], "a": 0, "p": "Comparing many: -est."}, {"lv": 2, "q": "My bag is ___ than yours.", "o": ["heavier", "heavyer", "heaviest", "more heavy"], "a": 0, "p": "y → ier."}, {"lv": 2, "q": "Which word is an adjective?", "o": ["beautiful", "beautifully", "beauty", "beautify"], "a": 0, "p": "Beautiful describes a noun."}, {"lv": 3, "q": "This is the ___ book I have ever read.", "o": ["most interesting", "interestinger", "more interesting", "interestingest"], "a": 0, "p": "Long adjectives use 'most'."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["An elephant is bigger than a dog.", "An elephant is more big than a dog.", "An elephant is biggest than a dog.", "An elephant is big than a dog."], "a": 0, "p": "Use 'bigger than'."}, {"lv": 3, "q": "Which is the comparative form of 'good'?", "o": ["better", "gooder", "best", "more good"], "a": 0, "p": "Irregular: good → better → best."}, {"lv": 3, "q": "Of the three girls, Sara is the ___.", "o": ["fastest", "faster", "fast", "more fast"], "a": 0, "p": "Comparing three: -est."}]}, {"id": "sgp-eng-k2-2", "name": "Short story comprehension", "desc": "Who, what, where", "idx": 2, "soal": [{"lv": 1, "q": "Read: 'Lily has a pet rabbit. It is white.' What colour is the rabbit?", "o": ["white", "brown", "black", "grey"], "a": 0, "p": "The text says it is white."}, {"lv": 1, "q": "Read: 'Ben went to the beach with his dad.' Who went with Ben?", "o": ["his dad", "his mum", "his sister", "his friend"], "a": 0, "p": "His dad."}, {"lv": 1, "q": "Read: 'The cat sat on the mat.' Where did the cat sit?", "o": ["on the mat", "on the bed", "on the chair", "in the box"], "a": 0, "p": "On the mat."}, {"lv": 1, "q": "Read: 'Mei likes apples.' What does Mei like?", "o": ["apples", "bananas", "grapes", "oranges"], "a": 0, "p": "Apples."}, {"lv": 2, "q": "Read: 'After school, Raj played football in the field. He scored two goals.' Where did Raj play?", "o": ["in the field", "at home", "in class", "at the beach"], "a": 0, "p": "In the field."}, {"lv": 2, "q": "In the story above, how many goals did Raj score?", "o": ["two", "one", "three", "none"], "a": 0, "p": "Two goals."}, {"lv": 2, "q": "Read: 'It was raining, so Amy took her umbrella.' Why did Amy take her umbrella?", "o": ["It was raining.", "It was sunny.", "She was cold.", "She liked it."], "a": 0, "p": "Because it was raining."}, {"lv": 2, "q": "Read: 'Grandma baked cookies. The kitchen smelled sweet.' What did Grandma bake?", "o": ["cookies", "bread", "pie", "rice"], "a": 0, "p": "Cookies."}, {"lv": 3, "q": "Read: 'Sam's kite got stuck in a tree. He felt sad. Then his brother climbed up and got it.' How did Sam feel when the kite got stuck?", "o": ["sad", "happy", "angry", "excited"], "a": 0, "p": "The text says he felt sad."}, {"lv": 3, "q": "In the story above, who got the kite back?", "o": ["his brother", "his dad", "Sam", "a friend"], "a": 0, "p": "His brother climbed up."}, {"lv": 3, "q": "Read: 'Nina yawned and rubbed her eyes.' How does Nina probably feel?", "o": ["sleepy", "excited", "hungry", "angry"], "a": 0, "p": "Yawning shows tiredness."}, {"lv": 3, "q": "Read: 'Everyone clapped when Zara finished her song.' What can we guess?", "o": ["Zara sang well.", "Zara was late.", "Nobody listened.", "Zara was sad."], "a": 0, "p": "Clapping suggests a good performance."}]}], "3": [{"id": "sgp-eng-k3-0", "name": "Prepositions", "desc": "Place and time", "idx": 0, "soal": [{"lv": 1, "q": "The cat is ___ the box. (inside)", "o": ["in", "at", "on", "by"], "a": 0, "p": "'In' shows inside."}, {"lv": 1, "q": "The book is ___ the table.", "o": ["on", "in", "at", "under the on"], "a": 0, "p": "On the surface."}, {"lv": 1, "q": "School starts ___ 8 o'clock.", "o": ["at", "on", "in", "by the"], "a": 0, "p": "Use 'at' for clock times."}, {"lv": 1, "q": "My birthday is ___ May.", "o": ["in", "on", "at", "by"], "a": 0, "p": "Use 'in' for months."}, {"lv": 2, "q": "We have PE ___ Monday.", "o": ["on", "in", "at", "by"], "a": 0, "p": "Use 'on' for days."}, {"lv": 2, "q": "The dog is hiding ___ the bed.", "o": ["under", "on", "at", "in to"], "a": 0, "p": "Below the bed."}, {"lv": 2, "q": "The bakery is ___ the bank and the school.", "o": ["between", "among", "under", "on"], "a": 0, "p": "'Between' is used with two things."}, {"lv": 2, "q": "We go swimming ___ the weekend.", "o": ["at", "in", "by", "for the on"], "a": 0, "p": "British usage: at the weekend."}, {"lv": 3, "q": "The children walked ___ the bridge to the other side.", "o": ["across", "along", "between", "at"], "a": 0, "p": "From one side to the other."}, {"lv": 3, "q": "She has lived here ___ 2019.", "o": ["since", "for", "from at", "in since"], "a": 0, "p": "'Since' is used with a starting point."}, {"lv": 3, "q": "The cat jumped ___ the wall into the garden.", "o": ["over", "on", "at", "among"], "a": 0, "p": "Movement above and across."}, {"lv": 3, "q": "The prize was shared ___ the five winners.", "o": ["among", "between", "at", "on"], "a": 0, "p": "'Among' is used with more than two."}]}, {"id": "sgp-eng-k3-1", "name": "Subject-verb agreement", "desc": "Singular and plural", "idx": 1, "soal": [{"lv": 1, "q": "She ___ to school every day.", "o": ["walks", "walk", "walking", "are walking"], "a": 0, "p": "Singular subject + verb with s."}, {"lv": 1, "q": "They ___ happy.", "o": ["are", "is", "am", "be"], "a": 0, "p": "Plural subject + are."}, {"lv": 1, "q": "The dog ___ loudly.", "o": ["barks", "bark", "are barking loud", "barking"], "a": 0, "p": "Singular subject."}, {"lv": 1, "q": "I ___ a student.", "o": ["am", "is", "are", "be"], "a": 0, "p": "I + am."}, {"lv": 2, "q": "My friends ___ football after school.", "o": ["play", "plays", "is playing", "playing"], "a": 0, "p": "Plural subject."}, {"lv": 2, "q": "Each of the boys ___ a book.", "o": ["has", "have", "are having", "having"], "a": 0, "p": "'Each' takes a singular verb."}, {"lv": 2, "q": "The box of apples ___ heavy.", "o": ["is", "are", "were", "be"], "a": 0, "p": "The subject is 'box' (singular)."}, {"lv": 2, "q": "Neither Tom nor Sam ___ here.", "o": ["is", "are", "were", "be"], "a": 0, "p": "Neither…nor with singular subjects takes a singular verb."}, {"lv": 3, "q": "The teacher, together with her pupils, ___ going to the museum.", "o": ["is", "are", "were", "have"], "a": 0, "p": "The main subject is 'teacher'."}, {"lv": 3, "q": "Everyone in the class ___ finished the test.", "o": ["has", "have", "are", "were"], "a": 0, "p": "'Everyone' is singular."}, {"lv": 3, "q": "The news ___ very exciting today.", "o": ["is", "are", "were", "have"], "a": 0, "p": "'News' is uncountable and singular."}, {"lv": 3, "q": "Either the students or the teacher ___ the lights.", "o": ["switches off", "switch off", "are switching off", "have switched off them"], "a": 0, "p": "The verb agrees with the nearer subject: teacher."}]}, {"id": "sgp-eng-k3-2", "name": "Comprehension: main ideas", "desc": "Understanding passages", "idx": 2, "soal": [{"lv": 1, "q": "The main idea of a passage is ...", "o": ["what the passage is mostly about", "a small detail", "the last word", "the title only"], "a": 0, "p": "The central point."}, {"lv": 1, "q": "Read: 'Bees are busy insects. They collect nectar and make honey.' What is the main idea?", "o": ["Bees are busy and make honey.", "Bees are yellow.", "Bees sting.", "Bees sleep."], "a": 0, "p": "It sums up the passage."}, {"lv": 1, "q": "The main idea is often found in the ...", "o": ["first or last sentence of a paragraph", "middle of a word", "picture only", "page number"], "a": 0, "p": "This is the topic sentence."}, {"lv": 1, "q": "Read: 'Water is important. We drink it, cook with it and wash with it.' What is the main idea?", "o": ["Water is important.", "We cook food.", "We wash clothes.", "Water is cold."], "a": 0, "p": "The first sentence."}, {"lv": 2, "q": "Read: 'Trees give us oxygen. They provide shade and homes for animals. Trees are very useful.' Which sentence states the main idea?", "o": ["Trees are very useful.", "Trees give us oxygen.", "They provide shade.", "Homes for animals."], "a": 0, "p": "The last sentence sums up."}, {"lv": 2, "q": "Which is a supporting detail for 'Exercise is good for you'?", "o": ["It makes your heart strong.", "I like ice cream.", "It rained today.", "Cats sleep a lot."], "a": 0, "p": "It supports the main idea."}, {"lv": 2, "q": "Read: 'Sam practised piano every day. He played at the concert and everyone clapped.' What is the main idea?", "o": ["Sam's practice helped him do well at the concert.", "Pianos are big.", "Concerts are long.", "Clapping is loud."], "a": 0, "p": "It connects practice and success."}, {"lv": 2, "q": "A good title for a passage about saving water is ...", "o": ["Every Drop Counts", "My Pet Cat", "A Trip to the Moon", "Fun with Paint"], "a": 0, "p": "It matches the main idea."}, {"lv": 3, "q": "Read: 'Plastic bags pollute our seas. Turtles mistake them for food. Many shops now charge for bags to reduce their use.' What is the main idea?", "o": ["Plastic bags harm the environment, so steps are being taken to reduce them.", "Turtles eat food.", "Shops sell bags.", "The sea is blue."], "a": 0, "p": "It combines the problem and the action."}, {"lv": 3, "q": "Which detail does NOT support the main idea 'Singapore is a clean city'?", "o": ["Singapore has many hawker centres serving food.", "Littering is fined.", "Streets are swept daily.", "Many bins are provided."], "a": 0, "p": "It is about food, not cleanliness."}, {"lv": 3, "q": "Why is finding the main idea useful?", "o": ["It helps you understand and remember the passage.", "It makes reading longer.", "It replaces reading.", "It is never useful."], "a": 0, "p": "It focuses understanding."}, {"lv": 3, "q": "Read: 'Ants work together. Some find food, some guard the nest and others care for the young.' What is the main idea?", "o": ["Ants share jobs and work as a team.", "Ants find food.", "Ants are small.", "Ants live underground."], "a": 0, "p": "The examples support teamwork."}]}], "4": [{"id": "sgp-eng-k4-0", "name": "Conjunctions and connectors", "desc": "Linking ideas", "idx": 0, "soal": [{"lv": 1, "q": "I like tea ___ coffee.", "o": ["and", "but", "because", "so"], "a": 0, "p": "Adding items."}, {"lv": 1, "q": "She was tired, ___ she went to bed.", "o": ["so", "but", "or", "although"], "a": 0, "p": "Result."}, {"lv": 1, "q": "Would you like rice ___ noodles?", "o": ["or", "and", "so", "because"], "a": 0, "p": "Choice."}, {"lv": 1, "q": "He is small ___ strong.", "o": ["but", "so", "or", "because"], "a": 0, "p": "Contrast."}, {"lv": 2, "q": "___ it was raining, we played indoors.", "o": ["Because", "But", "Or", "So"], "a": 0, "p": "Reason at the start."}, {"lv": 2, "q": "She studied hard. ___, she passed the test.", "o": ["As a result", "However", "Instead", "Otherwise"], "a": 0, "p": "Result connector."}, {"lv": 2, "q": "I wanted to go out. ___, it was too late.", "o": ["However", "Therefore", "Because", "And"], "a": 0, "p": "Contrast connector."}, {"lv": 2, "q": "Wear a jacket, ___ you will catch a cold.", "o": ["otherwise", "because", "although", "and so"], "a": 0, "p": "Warning of a consequence."}, {"lv": 3, "q": "___ he was injured, he finished the race.", "o": ["Despite the fact that", "Because of", "So that", "Unless"], "a": 0, "p": "Contrast with a clause."}, {"lv": 3, "q": "You cannot enter ___ you have a ticket.", "o": ["unless", "although", "because", "so"], "a": 0, "p": "Condition."}, {"lv": 3, "q": "Combine: 'Mary was hungry. She did not eat.'", "o": ["Although Mary was hungry, she did not eat.", "Because Mary was hungry, she did not eat.", "Mary was hungry so she did not eat.", "Mary was hungry and so she ate."], "a": 0, "p": "Contrast is needed."}, {"lv": 3, "q": "He saved money ___ he could buy a bicycle.", "o": ["so that", "although", "unless", "but"], "a": 0, "p": "Purpose."}]}, {"id": "sgp-eng-k4-1", "name": "Vocabulary cloze", "desc": "Choosing the right word", "idx": 1, "soal": [{"lv": 1, "q": "The baby is ___. Please be quiet.", "o": ["sleeping", "shouting", "running", "dancing"], "a": 0, "p": "It fits 'be quiet'."}, {"lv": 1, "q": "I ___ my teeth every morning.", "o": ["brush", "comb", "wash up", "paint"], "a": 0, "p": "Collocation: brush your teeth."}, {"lv": 1, "q": "It is very ___ today. Take an umbrella.", "o": ["rainy", "sunny", "dry", "windless"], "a": 0, "p": "The umbrella is the clue."}, {"lv": 1, "q": "The cake ___ delicious.", "o": ["tastes", "hears", "sees", "speaks"], "a": 0, "p": "Taste relates to food."}, {"lv": 2, "q": "The firefighters ___ the people from the burning building.", "o": ["rescued", "rejected", "replied", "removed"], "a": 0, "p": "Saved from danger."}, {"lv": 2, "q": "She was ___ when she won the prize.", "o": ["delighted", "disappointed", "bored", "furious"], "a": 0, "p": "Winning makes one happy."}, {"lv": 2, "q": "The old bridge was ___, so no one was allowed to cross it.", "o": ["unsafe", "beautiful", "colourful", "crowded"], "a": 0, "p": "That is why crossing is not allowed."}, {"lv": 2, "q": "Please ___ the lights when you leave the room.", "o": ["switch off", "switch on", "take off", "turn up"], "a": 0, "p": "To save energy."}, {"lv": 3, "q": "The detective ___ the clues carefully before solving the case.", "o": ["examined", "ignored", "destroyed", "forgot"], "a": 0, "p": "Context: solving."}, {"lv": 3, "q": "Despite the heavy traffic, he arrived ___.", "o": ["punctually", "lately", "slowly", "angrily"], "a": 0, "p": "'Despite' signals contrast: on time."}, {"lv": 3, "q": "The hikers were ___ after walking for ten hours.", "o": ["exhausted", "energetic", "refreshed", "lively"], "a": 0, "p": "Ten hours of walking is tiring."}, {"lv": 3, "q": "The scientist made an important ___ about the planet.", "o": ["discovery", "disguise", "disaster", "display"], "a": 0, "p": "Scientists discover."}]}, {"id": "sgp-eng-k4-2", "name": "Comprehension: sequencing events", "desc": "Order of events", "idx": 2, "soal": [{"lv": 1, "q": "Words like 'first', 'then' and 'finally' show ...", "o": ["order of events", "feelings", "colours", "places"], "a": 0, "p": "Sequence words."}, {"lv": 1, "q": "Read: 'First, Ben woke up. Then he brushed his teeth.' What did Ben do first?", "o": ["woke up", "brushed his teeth", "ate breakfast", "went to school"], "a": 0, "p": "'First' is the clue."}, {"lv": 1, "q": "Which word shows the last event?", "o": ["finally", "first", "next", "then"], "a": 0, "p": "Finally means at the end."}, {"lv": 1, "q": "Read: 'After lunch, Amy read a book.' What did Amy do before reading?", "o": ["had lunch", "slept", "played", "swam"], "a": 0, "p": "'After lunch' means lunch came first."}, {"lv": 2, "q": "Put in order: (1) The seed grew into a plant. (2) Lily planted a seed. (3) The plant flowered.", "o": ["2, 1, 3", "1, 2, 3", "3, 2, 1", "2, 3, 1"], "a": 0, "p": "Plant → grow → flower."}, {"lv": 2, "q": "Read: 'Before going out, Raj put on his shoes.' Which happened first?", "o": ["He put on his shoes.", "He went out.", "Both at the same time.", "Neither."], "a": 0, "p": "'Before' signals the earlier action."}, {"lv": 2, "q": "Read: 'Mei finished her homework. Meanwhile, her brother cooked dinner.' The two events happened ...", "o": ["at the same time", "one after another", "on different days", "never"], "a": 0, "p": "Meanwhile means at the same time."}, {"lv": 2, "q": "Which word could replace 'then'?", "o": ["next", "before", "first", "finally"], "a": 0, "p": "Similar meaning."}, {"lv": 3, "q": "Read: 'The bell rang. The children rushed out. Earlier, the teacher had given them homework.' What happened first?", "o": ["The teacher gave homework.", "The bell rang.", "The children rushed out.", "They went home."], "a": 0, "p": "'Earlier… had given' shows it came before."}, {"lv": 3, "q": "Put in order: (1) They reached the top. (2) They packed their bags. (3) They climbed for three hours. (4) They took photos of the view.", "o": ["2, 3, 1, 4", "3, 2, 1, 4", "2, 1, 3, 4", "1, 2, 3, 4"], "a": 0, "p": "Pack → climb → reach → photos."}, {"lv": 3, "q": "Read: 'By the time the police arrived, the thief had escaped.' Which happened first?", "o": ["The thief escaped.", "The police arrived.", "Both at once.", "Cannot tell."], "a": 0, "p": "Past perfect shows the earlier action."}, {"lv": 3, "q": "Why do writers use time connectives?", "o": ["to help readers follow the order of events", "to make stories rhyme", "to describe colours", "to add characters"], "a": 0, "p": "Clarity of sequence."}]}], "5": [{"id": "sgp-eng-k5-0", "name": "Synthesis and transformation", "desc": "Combining sentences", "idx": 0, "soal": [{"lv": 1, "q": "Combine: 'Tom is tall. Tom is strong.'", "o": ["Tom is tall and strong.", "Tom is tall strong.", "Tom tall is strong.", "Tom and tall is strong."], "a": 0, "p": "Join with 'and'."}, {"lv": 1, "q": "Combine using 'but': 'The bag is old. It is useful.'", "o": ["The bag is old but it is useful.", "The bag is old but useful old.", "But the bag is old useful.", "The bag but is old useful."], "a": 0, "p": "Contrast."}, {"lv": 1, "q": "Combine using 'because': 'I stayed home. I was sick.'", "o": ["I stayed home because I was sick.", "Because I stayed home I was sick.", "I was sick because I stayed home.", "I stayed because home sick."], "a": 0, "p": "The reason follows 'because'."}, {"lv": 1, "q": "Combine using 'who': 'The girl won. She is my sister.'", "o": ["The girl who won is my sister.", "The girl who is won my sister.", "Who won the girl is my sister.", "The girl is who won my sister."], "a": 0, "p": "Relative clause."}, {"lv": 2, "q": "Rewrite using 'Despite': 'Although it rained, they played.'", "o": ["Despite the rain, they played.", "Despite it rained, they played.", "Despite of the rain, they played.", "Despite raining they did not play."], "a": 0, "p": "Despite + noun."}, {"lv": 2, "q": "Rewrite using 'too ... to': 'The box is so heavy that I cannot lift it.'", "o": ["The box is too heavy for me to lift.", "The box is too heavy to lift it.", "The box is to heavy for lift.", "The box is too heavy that I lift."], "a": 0, "p": "too + adjective + to-infinitive."}, {"lv": 2, "q": "Rewrite using 'unless': 'If you do not hurry, you will be late.'", "o": ["Unless you hurry, you will be late.", "Unless you do not hurry, you will be late.", "Unless hurry, you late.", "You will be late unless you do not hurry."], "a": 0, "p": "Unless = if not."}, {"lv": 2, "q": "Rewrite in the passive: 'The cat chased the mouse.'", "o": ["The mouse was chased by the cat.", "The mouse chased the cat.", "The cat was chased by the mouse.", "The mouse is chase by cat."], "a": 0, "p": "Passive voice."}, {"lv": 3, "q": "Combine using 'Not only... but also': 'She sings. She dances.'", "o": ["Not only does she sing but she also dances.", "Not only she sings but also dances she.", "Not only sings she but dances.", "She not only sings but also dance."], "a": 0, "p": "Inversion after 'Not only'."}, {"lv": 3, "q": "Rewrite using 'No sooner': 'As soon as he arrived, it started to rain.'", "o": ["No sooner had he arrived than it started to rain.", "No sooner he arrived then it rained.", "No sooner had he arrived when it rained.", "No sooner did he arrived than it rained."], "a": 0, "p": "No sooner + had + V3 + than."}, {"lv": 3, "q": "Rewrite in reported speech: 'I will help you,' said Mary to John.", "o": ["Mary told John that she would help him.", "Mary told John that I will help you.", "Mary said to John she will helps him.", "Mary told John she would help you."], "a": 0, "p": "Change pronouns and tense."}, {"lv": 3, "q": "Rewrite using 'In spite of': 'He was tired, but he finished the race.'", "o": ["In spite of being tired, he finished the race.", "In spite he was tired, he finished the race.", "In spite of tired, he finished.", "In spite of he being tired, finished."], "a": 0, "p": "In spite of + gerund."}]}, {"id": "sgp-eng-k5-1", "name": "Editing for spelling and grammar", "desc": "Finding and correcting errors", "idx": 1, "soal": [{"lv": 1, "q": "Find the spelling error: 'I recieved a letter.'", "o": ["recieved", "I", "a", "letter"], "a": 0, "p": "Correct: received (i before e except after c)."}, {"lv": 1, "q": "Correct the error: 'She go to school daily.'", "o": ["goes", "going", "gone", "went daily"], "a": 0, "p": "Singular subject: goes."}, {"lv": 1, "q": "Find the spelling error: 'The resturant was full.'", "o": ["resturant", "The", "was", "full"], "a": 0, "p": "Correct: restaurant."}, {"lv": 1, "q": "Correct the error: 'They was happy.'", "o": ["were", "is", "be", "am"], "a": 0, "p": "They + were."}, {"lv": 2, "q": "Correct the error: 'Yesterday he buyed a new bag.'", "o": ["bought", "buys", "buy", "buying"], "a": 0, "p": "Irregular past tense."}, {"lv": 2, "q": "Find the spelling error: 'It was a beautifull day.'", "o": ["beautifull", "It", "was", "day"], "a": 0, "p": "Correct: beautiful."}, {"lv": 2, "q": "Correct the error: 'Each of the girls have a pencil.'", "o": ["has", "having", "are", "were"], "a": 0, "p": "Each is singular."}, {"lv": 2, "q": "Correct the error: 'He is more taller than me.'", "o": ["taller", "most tall", "tallest", "more tall"], "a": 0, "p": "Do not double the comparative."}, {"lv": 3, "q": "Correct the error: 'If I was you, I would apologise.'", "o": ["were", "am", "is", "be"], "a": 0, "p": "Subjunctive: If I were you."}, {"lv": 3, "q": "Find the error: 'Neither of the answers are correct.'", "o": ["are → is", "Neither → None", "answers → answer", "correct → correctly"], "a": 0, "p": "'Neither' takes a singular verb."}, {"lv": 3, "q": "Find the spelling error: 'The government made an anouncement.'", "o": ["anouncement", "government", "made", "an"], "a": 0, "p": "Correct: announcement."}, {"lv": 3, "q": "Correct the error: 'She has been living here since three years.'", "o": ["for", "from", "during", "in"], "a": 0, "p": "'For' is used with a period of time."}]}, {"id": "sgp-eng-k5-2", "name": "Comprehension: inference", "desc": "Implied meaning", "idx": 2, "soal": [{"lv": 1, "q": "Inference means ...", "o": ["using clues to work out what is not directly stated", "copying words", "counting words", "skipping text"], "a": 0, "p": "Reading between the lines."}, {"lv": 1, "q": "'Jane's eyes filled with tears.' How does Jane feel?", "o": ["sad", "happy", "bored", "excited"], "a": 0, "p": "Tears suggest sadness."}, {"lv": 1, "q": "'The ground was wet and there were puddles everywhere.' What happened earlier?", "o": ["It rained.", "It snowed.", "It was sunny.", "There was a fire."], "a": 0, "p": "Puddles come from rain."}, {"lv": 1, "q": "'Ken grabbed his umbrella before leaving.' What can we infer?", "o": ["It might rain.", "It is sunny.", "He is going swimming.", "He is sleepy."], "a": 0, "p": "The umbrella is the clue."}, {"lv": 2, "q": "'Mrs Lim smiled as she read her son's report card.' What can we infer?", "o": ["Her son did well.", "Her son failed.", "She is angry.", "She cannot read."], "a": 0, "p": "Smiling shows pleasure."}, {"lv": 2, "q": "'The shop had a long queue and all the shelves were nearly empty.' The shop is ...", "o": ["very popular", "closed", "new and empty", "unpopular"], "a": 0, "p": "Many buyers."}, {"lv": 2, "q": "'Raj tiptoed past his sleeping baby sister.' Why did he tiptoe?", "o": ["to avoid waking her", "because his feet hurt", "to dance", "because the floor was hot"], "a": 0, "p": "Quiet movement."}, {"lv": 2, "q": "'The dog wagged its tail and jumped up when Sarah came home.' The dog felt ...", "o": ["excited and happy", "scared", "angry", "tired"], "a": 0, "p": "Tail-wagging shows happiness."}, {"lv": 3, "q": "'Despite the cold, Mei refused to wear her brother's old jacket.' What can be inferred?", "o": ["Mei cared more about how she looked than about being warm.", "Mei was hot.", "Mei had no brother.", "The jacket was new."], "a": 0, "p": "Refusal despite the cold suggests pride or style."}, {"lv": 3, "q": "'After the match, the players sat silently in the changing room, heads bowed.' What can be inferred?", "o": ["They lost the match.", "They won easily.", "They were sleeping.", "They were celebrating."], "a": 0, "p": "Silence and bowed heads suggest defeat."}, {"lv": 3, "q": "'Grandpa checked the door lock three times before going to bed.' What does this suggest?", "o": ["He was worried about safety.", "He forgot how to lock it.", "He was playing a game.", "The door was broken."], "a": 0, "p": "Repeated checking shows worry."}, {"lv": 3, "q": "'The classroom fell silent when the principal walked in.' What can be inferred?", "o": ["The pupils respected or feared the principal.", "The principal was invisible.", "The pupils were asleep.", "The principal sang."], "a": 0, "p": "Sudden silence shows respect."}]}], "6": [{"id": "sgp-eng-k6-0", "name": "Relative pronouns and clauses", "desc": "who, which, whose, where", "idx": 0, "soal": [{"lv": 1, "q": "The girl ___ sits next to me is kind.", "o": ["who", "which", "whose", "where"], "a": 0, "p": "'Who' is used for people."}, {"lv": 1, "q": "This is the book ___ I bought yesterday.", "o": ["which", "who", "whose", "where"], "a": 0, "p": "'Which' is used for things."}, {"lv": 1, "q": "That is the house ___ I was born.", "o": ["where", "who", "which", "whose"], "a": 0, "p": "'Where' is used for places."}, {"lv": 1, "q": "The boy ___ bag was lost is crying.", "o": ["whose", "who", "which", "where"], "a": 0, "p": "'Whose' shows possession."}, {"lv": 2, "q": "Combine: 'I met a man. He was a pilot.'", "o": ["I met a man who was a pilot.", "I met a man which was a pilot.", "I met a man whose was a pilot.", "I met a man where was a pilot."], "a": 0, "p": "'Who' for a person."}, {"lv": 2, "q": "Combine: 'This is the café. We had lunch there.'", "o": ["This is the café where we had lunch.", "This is the café who we had lunch.", "This is the café which we had lunch.", "This is the café whose we had lunch."], "a": 0, "p": "A place takes 'where'."}, {"lv": 2, "q": "Combine: 'The dog is barking. It belongs to Tim.'", "o": ["The dog which belongs to Tim is barking.", "The dog who belongs Tim is barking.", "The dog whose belongs to Tim is barking.", "The dog where belongs to Tim is barking."], "a": 0, "p": "A thing takes 'which'."}, {"lv": 2, "q": "The teacher ___ class I am in is very strict.", "o": ["whose", "who", "which", "whom"], "a": 0, "p": "Possession."}, {"lv": 3, "q": "Combine: 'The scientist won a prize. Her research saved lives.'", "o": ["The scientist whose research saved lives won a prize.", "The scientist who research saved lives won a prize.", "The scientist which research saved lives won a prize.", "The scientist where her research saved lives won a prize."], "a": 0, "p": "'Whose' + noun."}, {"lv": 3, "q": "The man to ___ I spoke was helpful.", "o": ["whom", "who", "which", "whose"], "a": 0, "p": "After a preposition, use 'whom'."}, {"lv": 3, "q": "Which sentence uses a relative clause correctly?", "o": ["Singapore, which is an island, is very green.", "Singapore, who is an island, is very green.", "Singapore, whose is an island, is green.", "Singapore, where is an island, is green."], "a": 0, "p": "A non-defining clause with 'which'."}, {"lv": 3, "q": "Combine: 'I visited the museum. The museum was built in 1887.'", "o": ["I visited the museum, which was built in 1887.", "I visited the museum, who was built in 1887.", "I visited the museum where was built in 1887.", "I visited the museum whose built in 1887."], "a": 0, "p": "'Which' for the museum."}]}, {"id": "sgp-eng-k6-1", "name": "Vocabulary in context", "desc": "PSLE-style vocabulary", "idx": 1, "soal": [{"lv": 1, "q": "'The child was elated when she saw the gift.' 'Elated' means ...", "o": ["very happy", "very sad", "bored", "frightened"], "a": 0, "p": "Overjoyed."}, {"lv": 1, "q": "'The old man walked with a limp.' 'Limp' means ...", "o": ["an uneven way of walking due to injury", "a fast run", "a dance", "a jump"], "a": 0, "p": "Uneven gait."}, {"lv": 1, "q": "'She was famished after the long hike.' 'Famished' means ...", "o": ["very hungry", "very tired", "very cold", "very angry"], "a": 0, "p": "Starving."}, {"lv": 1, "q": "'The room was spotless.' 'Spotless' means ...", "o": ["very clean", "very dirty", "very dark", "very small"], "a": 0, "p": "No spots."}, {"lv": 2, "q": "'The team's victory was unanimous, as all judges agreed.' 'Unanimous' means ...", "o": ["agreed by everyone", "doubtful", "very loud", "unfair"], "a": 0, "p": "Fully agreed."}, {"lv": 2, "q": "'He was reluctant to jump into the cold pool.' 'Reluctant' means ...", "o": ["unwilling", "eager", "happy", "quick"], "a": 0, "p": "Hesitant."}, {"lv": 2, "q": "'The detective scrutinised the evidence.' 'Scrutinised' means ...", "o": ["examined closely", "threw away", "ignored", "lost"], "a": 0, "p": "Careful inspection."}, {"lv": 2, "q": "'The thief fled the scene.' 'Fled' means ...", "o": ["ran away", "returned", "slept", "shouted"], "a": 0, "p": "Escaped."}, {"lv": 3, "q": "'Her compassion for the injured bird touched everyone.' 'Compassion' means ...", "o": ["deep care and sympathy", "anger", "fear", "jealousy"], "a": 0, "p": "Kindness towards suffering."}, {"lv": 3, "q": "'The novice climber needed guidance.' 'Novice' means ...", "o": ["a beginner", "an expert", "a guide", "a champion"], "a": 0, "p": "Inexperienced."}, {"lv": 3, "q": "'The rumour spread rapidly through the school.' 'Rapidly' means ...", "o": ["quickly", "slowly", "quietly", "rarely"], "a": 0, "p": "Fast."}, {"lv": 3, "q": "'Despite his meagre salary, he donated to charity.' 'Meagre' means ...", "o": ["small or insufficient", "huge", "generous", "monthly"], "a": 0, "p": "'Despite' signals that it is small."}]}, {"id": "sgp-eng-k6-2", "name": "Comprehension: best answer", "desc": "Open-ended skills in MCQ form", "idx": 2, "soal": [{"lv": 1, "q": "To find the best answer, you should first ...", "o": ["read the question carefully", "guess quickly", "skip the passage", "choose the longest option"], "a": 0, "p": "Understand what is asked."}, {"lv": 1, "q": "Read: 'Lena watered the plants daily, and they grew tall.' Why did the plants grow tall?", "o": ["Lena watered them daily.", "They were plastic.", "It was winter.", "They were in the dark."], "a": 0, "p": "Cause and effect."}, {"lv": 1, "q": "Read: 'Jun forgot his umbrella and got soaked.' What happened?", "o": ["It rained and he got wet.", "He stayed dry.", "It was sunny.", "He bought a new umbrella."], "a": 0, "p": "Soaked means very wet."}, {"lv": 1, "q": "Which answer is best supported by the text: 'The library was silent except for pages turning'?", "o": ["People were reading quietly.", "There was a party.", "The library was closed.", "Music was playing."], "a": 0, "p": "The clues match."}, {"lv": 2, "q": "Read: 'Mr Tan, who never missed a day of work in 30 years, retired today.' What does this show about Mr Tan?", "o": ["He was dedicated and reliable.", "He was often sick.", "He disliked work.", "He was new."], "a": 0, "p": "Thirty years with no absence."}, {"lv": 2, "q": "Read: 'The puppy hid under the table, trembling, as thunder roared.' Why did the puppy hide?", "o": ["It was frightened by the thunder.", "It was playing.", "It was hungry.", "It was cold only."], "a": 0, "p": "Trembling during thunder."}, {"lv": 2, "q": "Which option is the best title for a passage about saving electricity at home?", "o": ["Small Switches, Big Savings", "My Favourite Food", "The Lost Kitten", "A Day at the Zoo"], "a": 0, "p": "It matches the main idea."}, {"lv": 2, "q": "Read: 'Although the shop was small, it was always crowded.' What can we conclude?", "o": ["The shop was popular.", "The shop was empty.", "The shop was closing.", "The shop was new."], "a": 0, "p": "Crowded despite its size."}, {"lv": 3, "q": "Read: 'Ravi stared at the blank page; the essay was due tomorrow, but no ideas came.' How does Ravi feel?", "o": ["anxious and stuck", "relaxed", "excited", "proud"], "a": 0, "p": "A deadline with no ideas."}, {"lv": 3, "q": "Read: 'The villagers rebuilt the bridge themselves rather than wait for help.' What quality do they show?", "o": ["self-reliance", "laziness", "greed", "fear"], "a": 0, "p": "They acted on their own."}, {"lv": 3, "q": "Read: 'Mei apologised to her friend, even though she was not entirely at fault.' What does this suggest about Mei?", "o": ["She values the friendship more than being right.", "She was totally wrong.", "She is rude.", "She dislikes her friend."], "a": 0, "p": "Inference about her values."}, {"lv": 3, "q": "Which option best explains the phrase 'a blessing in disguise'?", "o": ["Something that seems bad at first but turns out good.", "A hidden gift.", "A costume party.", "A bad event that stays bad."], "a": 0, "p": "The meaning of the idiom."}]}], "7": [{"id": "sgp-eng-k7-0", "name": "Grammar: tenses and agreement", "desc": "Accurate verb forms", "idx": 0, "soal": [{"lv": 1, "q": "She ___ to the market yesterday.", "o": ["went", "goes", "go", "gone"], "a": 0, "p": "Simple past."}, {"lv": 1, "q": "They ___ dinner right now.", "o": ["are having", "have had", "had", "has"], "a": 0, "p": "Present continuous."}, {"lv": 1, "q": "I ___ my homework already.", "o": ["have finished", "finish", "finishing", "finishes"], "a": 0, "p": "Present perfect with 'already'."}, {"lv": 1, "q": "He ___ football every Saturday.", "o": ["plays", "play", "played tomorrow", "playing"], "a": 0, "p": "Habitual present."}, {"lv": 2, "q": "By the time we arrived, the film ___.", "o": ["had started", "starts", "has started", "start"], "a": 0, "p": "Past perfect."}, {"lv": 2, "q": "The list of items ___ on the table.", "o": ["is", "are", "were", "have been"], "a": 0, "p": "'List' is singular."}, {"lv": 2, "q": "Neither the teacher nor the students ___ aware of the change.", "o": ["were", "was", "is", "has"], "a": 0, "p": "The verb agrees with the nearer subject (students)."}, {"lv": 2, "q": "She ___ in Singapore since 2015.", "o": ["has lived", "lives", "lived", "is living since"], "a": 0, "p": "Present perfect with 'since'."}, {"lv": 3, "q": "If I ___ more time, I would travel the world.", "o": ["had", "have", "will have", "having"], "a": 0, "p": "Second conditional."}, {"lv": 3, "q": "The committee ___ reached a decision.", "o": ["has", "have", "are", "were"], "a": 0, "p": "Collective noun acting as a unit."}, {"lv": 3, "q": "While I ___ dinner, the phone rang.", "o": ["was cooking", "cooked", "am cooking", "cook"], "a": 0, "p": "Past continuous interrupted."}, {"lv": 3, "q": "Mathematics ___ my favourite subject.", "o": ["is", "are", "were", "have been"], "a": 0, "p": "Subjects ending in -s are singular."}]}, {"id": "sgp-eng-k7-1", "name": "Text types", "desc": "Narrative, expository, persuasive", "idx": 1, "soal": [{"lv": 1, "q": "A narrative text mainly aims to ...", "o": ["tell a story and entertain", "persuade", "give instructions", "explain a process"], "a": 0, "p": "Stories."}, {"lv": 1, "q": "An expository text aims to ...", "o": ["explain or inform", "entertain with fiction", "rhyme", "argue emotionally only"], "a": 0, "p": "Factual explanation."}, {"lv": 1, "q": "A persuasive text tries to ...", "o": ["convince the reader", "describe a dream", "list ingredients", "tell a joke"], "a": 0, "p": "Persuasion."}, {"lv": 1, "q": "Which is usually written in the past tense?", "o": ["a narrative", "a recipe", "a set of rules", "a timetable"], "a": 0, "p": "Stories recount events."}, {"lv": 2, "q": "Which feature is typical of a persuasive text?", "o": ["rhetorical questions", "dialogue between characters", "a rhyme scheme", "numbered steps"], "a": 0, "p": "A persuasive device."}, {"lv": 2, "q": "'How Volcanoes Erupt' is most likely ...", "o": ["an expository text", "a narrative", "a poem", "a persuasive letter"], "a": 0, "p": "It explains."}, {"lv": 2, "q": "Which is the structure of a narrative?", "o": ["orientation, complication, resolution", "thesis, arguments, conclusion", "aim, materials, steps", "title, list, summary"], "a": 0, "p": "Story structure."}, {"lv": 2, "q": "Which sentence suits an expository text?", "o": ["Coral reefs are formed by tiny animals called polyps.", "Save our reefs now!", "Once upon a time a reef...", "I love coral."], "a": 0, "p": "Factual."}, {"lv": 3, "q": "A blog post argues that schools should start later, citing sleep research. It is ...", "o": ["persuasive", "narrative", "procedural", "descriptive poem"], "a": 0, "p": "Argument with evidence."}, {"lv": 3, "q": "Which text type would use technical vocabulary and the passive voice most?", "o": ["scientific explanation", "fairy tale", "personal letter", "advertisement"], "a": 0, "p": "Objective tone."}, {"lv": 3, "q": "Why might a narrative include an expository paragraph?", "o": ["to give background information the reader needs", "to persuade", "to give a recipe", "to confuse"], "a": 0, "p": "Blending text types."}, {"lv": 3, "q": "Which ending best suits a persuasive speech?", "o": ["a strong call to action", "a cliffhanger", "a list of ingredients", "a definition"], "a": 0, "p": "Motivates the audience."}]}, {"id": "sgp-eng-k7-2", "name": "Summary skills", "desc": "Identifying key points", "idx": 2, "soal": [{"lv": 1, "q": "A summary should include ...", "o": ["the key points only", "every detail", "your opinions", "new information"], "a": 0, "p": "Concise."}, {"lv": 1, "q": "Summaries are written ...", "o": ["in your own words as far as possible", "by copying the text", "as a poem", "in bullet emojis"], "a": 0, "p": "Paraphrase."}, {"lv": 1, "q": "What should you leave out of a summary?", "o": ["examples and repetition", "main ideas", "key facts", "the topic"], "a": 0, "p": "Remove minor details."}, {"lv": 1, "q": "A summary is usually ___ than the original.", "o": ["shorter", "longer", "the same length as", "more detailed"], "a": 0, "p": "Condensed."}, {"lv": 2, "q": "Which is the best paraphrase of 'The festival attracted a multitude of visitors'?", "o": ["Many people came to the festival.", "The festival had a multitude.", "Visitors were attracted multitude.", "The festival attracted."], "a": 0, "p": "Plain words, same meaning."}, {"lv": 2, "q": "How can you combine 'Dogs are loyal. Dogs are friendly. Dogs are protective.'?", "o": ["Dogs are loyal, friendly and protective.", "Dogs are loyal. Dogs are friendly.", "Dogs are dogs.", "Loyal friendly dogs protective are."], "a": 0, "p": "Combine the ideas."}, {"lv": 2, "q": "Which word could replace 'apples, oranges and bananas' in a summary?", "o": ["fruit", "items", "food and drink", "colours"], "a": 0, "p": "A general term."}, {"lv": 2, "q": "When summarising, you should first ...", "o": ["identify the main points relevant to the question", "count the words", "write the conclusion", "copy the first paragraph"], "a": 0, "p": "Plan."}, {"lv": 3, "q": "Which is the most concise sentence?", "o": ["Rising costs forced the shop to close.", "Due to the fact that costs were rising, the shop had no choice but to close down.", "The shop, because costs rose, closed, which was due to costs.", "Costs rising was the reason for the shop closing down."], "a": 0, "p": "Fewest words, clear meaning."}, {"lv": 3, "q": "The question asks for 'reasons people recycle'. Which point is irrelevant?", "o": ["Recycling bins come in different colours.", "It reduces waste.", "It conserves resources.", "It protects wildlife."], "a": 0, "p": "Not a reason."}, {"lv": 3, "q": "Why should a summary not include personal opinions?", "o": ["It must represent the original writer's ideas objectively.", "Opinions are always wrong.", "It makes it shorter.", "Opinions are too formal."], "a": 0, "p": "Objectivity."}, {"lv": 3, "q": "A summary has a 80-word limit and your draft is 110 words. Best fix?", "o": ["remove repeated ideas and examples", "use smaller handwriting", "delete the main points", "add more adjectives"], "a": 0, "p": "Cut non-essentials."}]}], "8": [{"id": "sgp-eng-k8-0", "name": "Argumentative writing", "desc": "Thesis, evidence, rebuttal", "idx": 0, "soal": [{"lv": 1, "q": "An argumentative essay needs a clear ...", "o": ["thesis (position)", "plot twist", "rhyme scheme", "dialogue"], "a": 0, "p": "It states the stance."}, {"lv": 1, "q": "Evidence in an argument can include ...", "o": ["statistics and expert opinions", "random jokes", "rhymes", "fictional dragons"], "a": 0, "p": "Support."}, {"lv": 1, "q": "A rebuttal ...", "o": ["responds to and challenges an opposing view", "agrees with everything", "summarises a story", "lists ingredients"], "a": 0, "p": "Counter-argument response."}, {"lv": 1, "q": "Which connective adds a point?", "o": ["Moreover", "However", "Nevertheless", "Despite"], "a": 0, "p": "Addition."}, {"lv": 2, "q": "Which is the strongest thesis?", "o": ["Homework should be limited because excessive amounts harm students' health and learning.", "Homework is a thing.", "Some students do homework.", "I don't know about homework."], "a": 0, "p": "Clear and arguable."}, {"lv": 2, "q": "Why acknowledge the opposing view?", "o": ["It shows fairness and strengthens your credibility.", "It weakens your argument.", "It is required by law.", "To make the essay shorter."], "a": 0, "p": "Balance builds trust."}, {"lv": 2, "q": "Which phrase introduces a counter-argument?", "o": ["Critics may argue that...", "Firstly...", "In conclusion...", "Once upon a time..."], "a": 0, "p": "It signals the opposing view."}, {"lv": 2, "q": "Which is a fact rather than an opinion?", "o": ["Singapore has a land area of about 735 km².", "Singapore is the best city.", "Everyone loves hawker food.", "Singapore is boring."], "a": 0, "p": "It can be verified."}, {"lv": 3, "q": "Which is a weak argument?", "o": ["Everyone thinks so, so it must be true.", "Studies show a 30% drop in accidents.", "Experts recommend it after research.", "Data from 2023 supports this."], "a": 0, "p": "Bandwagon fallacy."}, {"lv": 3, "q": "Which conclusion is most effective?", "o": ["Restating the thesis with a final compelling thought or call to action.", "Introducing a new argument.", "Repeating the introduction word for word.", "Ending with 'That's all.'"], "a": 0, "p": "Strong closure."}, {"lv": 3, "q": "Which body paragraph structure is effective?", "o": ["point, evidence, explanation, link", "evidence only", "opinion only", "a random list"], "a": 0, "p": "PEEL."}, {"lv": 3, "q": "Why use statistics carefully?", "o": ["They must be accurate, relevant and from credible sources.", "They always prove everything.", "They should be invented.", "They are not allowed."], "a": 0, "p": "Credibility."}]}, {"id": "sgp-eng-k8-1", "name": "Editing", "desc": "Grammar and usage errors", "idx": 1, "soal": [{"lv": 1, "q": "Correct the error: 'She don't like spinach.'", "o": ["doesn't", "didn't liked", "not", "isn't"], "a": 0, "p": "She + doesn't."}, {"lv": 1, "q": "Correct the error: 'I seen the movie.'", "o": ["saw", "see", "seeing", "sees"], "a": 0, "p": "Past tense: saw."}, {"lv": 1, "q": "Correct the error: 'Their going to the party.'", "o": ["They're", "There", "Theirs", "Them"], "a": 0, "p": "They're = they are."}, {"lv": 1, "q": "Correct the error: 'Its raining.'", "o": ["It's", "Its'", "It", "Its's"], "a": 0, "p": "It's = it is."}, {"lv": 2, "q": "Correct the error: 'The informations are useful.'", "o": ["The information is useful.", "The informations is useful.", "The information are useful.", "Informations are useful."], "a": 0, "p": "Uncountable noun."}, {"lv": 2, "q": "Correct the error: 'He has went home.'", "o": ["gone", "goes", "going", "go"], "a": 0, "p": "Present perfect: has gone."}, {"lv": 2, "q": "Correct the error: 'Between you and I, it is a secret.'", "o": ["me", "myself", "mine", "my"], "a": 0, "p": "Object pronoun after a preposition."}, {"lv": 2, "q": "Correct the error: 'Less people came this year.'", "o": ["Fewer", "Lesser", "Lots", "Little"], "a": 0, "p": "'Fewer' is used with countable nouns."}, {"lv": 3, "q": "Correct the error: 'Walking to school, the rain started.'", "o": ["While I was walking to school, the rain started.", "Walking to school, the rain was starting.", "The rain started walking to school.", "Walk to school, rain started."], "a": 0, "p": "Dangling modifier."}, {"lv": 3, "q": "Correct the error: 'The number of students have increased.'", "o": ["has", "are", "were", "having"], "a": 0, "p": "'The number' is singular."}, {"lv": 3, "q": "Correct the error: 'He is one of the boys who has won.'", "o": ["have", "had", "having", "is"], "a": 0, "p": "'Who' refers to 'boys', which is plural."}, {"lv": 3, "q": "Correct the error: 'I look forward to meet you.'", "o": ["meeting", "met", "meets", "be meeting"], "a": 0, "p": "Look forward to + V-ing."}]}, {"id": "sgp-eng-k8-2", "name": "Comprehension: writer's purpose", "desc": "Why the writer wrote it", "idx": 2, "soal": [{"lv": 1, "q": "A writer's purpose may be to ...", "o": ["inform, persuade or entertain", "only to rhyme", "only to sell", "always to scare"], "a": 0, "p": "Main purposes."}, {"lv": 1, "q": "A news report's main purpose is to ...", "o": ["inform", "entertain with fiction", "rhyme", "give recipes"], "a": 0, "p": "Facts."}, {"lv": 1, "q": "An advertisement's main purpose is to ...", "o": ["persuade people to buy or act", "tell a fairy tale", "explain science neutrally", "rhyme"], "a": 0, "p": "Persuasion."}, {"lv": 1, "q": "A comic story mainly aims to ...", "o": ["entertain", "persuade", "instruct", "inform"], "a": 0, "p": "Amusement."}, {"lv": 2, "q": "A passage describes a polluted river and ends with 'We must act before it's too late.' The purpose is to ...", "o": ["persuade readers to take action", "entertain", "give directions", "describe a holiday"], "a": 0, "p": "A call to action."}, {"lv": 2, "q": "Why might a writer include a personal anecdote in an article?", "o": ["to engage readers emotionally and make the point relatable", "to confuse readers", "to make it shorter", "to remove facts"], "a": 0, "p": "Human interest."}, {"lv": 2, "q": "A writer uses statistics in an article about obesity. Why?", "o": ["to add credibility to the argument", "to entertain", "to rhyme", "to tell a story"], "a": 0, "p": "Evidence."}, {"lv": 2, "q": "Which tone suits an informative leaflet on dengue prevention?", "o": ["clear and factual", "humorous and silly", "angry", "poetic"], "a": 0, "p": "Clarity."}, {"lv": 3, "q": "A writer describes a new mall with words like 'dazzling' and 'unmissable'. What is the purpose?", "o": ["to persuade readers to visit", "to inform neutrally", "to criticise the mall", "to tell a mystery"], "a": 0, "p": "Positive emotive language."}, {"lv": 3, "q": "Why might a writer use a rhetorical question at the start of an article?", "o": ["to hook the reader and make them think", "to answer a quiz", "to end the article", "to confuse"], "a": 0, "p": "Engagement."}, {"lv": 3, "q": "An article lists both benefits and drawbacks of online learning, then gives a balanced conclusion. Its purpose is to ...", "o": ["inform and help readers evaluate the issue", "sell a laptop", "entertain with jokes", "tell a fairy tale"], "a": 0, "p": "Balanced discussion."}, {"lv": 3, "q": "Why might a writer end with a vivid image rather than a summary?", "o": ["to leave a lasting impression", "to fill space", "to confuse readers", "because summaries are banned"], "a": 0, "p": "Memorable ending."}]}], "9": [{"id": "sgp-eng-k9-0", "name": "Situational writing", "desc": "Formal letters and emails", "idx": 0, "soal": [{"lv": 1, "q": "Situational writing requires you to consider ...", "o": ["purpose, audience and context", "only spelling", "rhyme", "plot twists"], "a": 0, "p": "PAC."}, {"lv": 1, "q": "A formal email to a principal should begin with ...", "o": ["Dear Mr Tan,", "Hey Tan!", "Yo principal,", "Hi there buddy,"], "a": 0, "p": "Formal salutation."}, {"lv": 1, "q": "A formal letter ends with ...", "o": ["Yours sincerely,", "Love,", "Cheers,", "Bye!"], "a": 0, "p": "Formal closing."}, {"lv": 1, "q": "The subject line of an email should be ...", "o": ["brief and clear about the purpose", "very long", "empty", "a joke"], "a": 0, "p": "Clarity."}, {"lv": 2, "q": "You are writing to request the school hall for an event. Which detail is essential?", "o": ["the date, time and purpose of the event", "your favourite food", "a story about your holiday", "the weather last week"], "a": 0, "p": "Relevant information."}, {"lv": 2, "q": "Which tone suits a complaint letter to a company?", "o": ["polite but firm", "rude and angry", "casual and joking", "poetic"], "a": 0, "p": "Effective and respectful."}, {"lv": 2, "q": "Which sentence is appropriate for a formal proposal?", "o": ["I would like to propose a recycling programme for our school.", "Let's do recycling, yeah?", "Recycling is cool lol.", "Whatever, recycle."], "a": 0, "p": "Formal register."}, {"lv": 2, "q": "In situational writing, the 'audience' refers to ...", "o": ["the person or group who will read the text", "the writer", "the school", "the examiner only"], "a": 0, "p": "Target reader."}, {"lv": 3, "q": "Which paragraph order best suits a formal request letter?", "o": ["purpose → details → justification → closing request", "closing → details → purpose", "jokes → purpose → details", "random order"], "a": 0, "p": "Logical structure."}, {"lv": 3, "q": "Your audience is the town council. Which phrase is most appropriate?", "o": ["We respectfully urge the council to consider...", "You guys need to fix this!", "Do it now or else.", "Council, please lah."], "a": 0, "p": "Respectful and persuasive."}, {"lv": 3, "q": "Why must you use information from the stimulus in situational writing?", "o": ["to address the task accurately and completely", "to fill space", "to copy the text", "it is optional"], "a": 0, "p": "Task fulfilment."}, {"lv": 3, "q": "Which is the best closing line for a request email?", "o": ["Thank you for considering my request. I look forward to your reply.", "Reply fast.", "That's all.", "Bye."], "a": 0, "p": "Courteous."}]}, {"id": "sgp-eng-k9-1", "name": "Language for effect", "desc": "Word choice and tone", "idx": 1, "soal": [{"lv": 1, "q": "Tone refers to ...", "o": ["the writer's attitude towards the subject", "the font size", "the number of words", "the title"], "a": 0, "p": "For example, angry or hopeful."}, {"lv": 1, "q": "Which word creates a sinister tone?", "o": ["lurking", "skipping", "giggling", "sparkling"], "a": 0, "p": "Lurking suggests threat."}, {"lv": 1, "q": "Which word creates a cheerful tone?", "o": ["sunny", "gloomy", "dreary", "grim"], "a": 0, "p": "Positive associations."}, {"lv": 1, "q": "Word choice is also called ...", "o": ["diction", "plot", "setting", "structure"], "a": 0, "p": "Diction."}, {"lv": 2, "q": "Compare 'he walked' with 'he stormed'. 'Stormed' suggests ...", "o": ["anger", "happiness", "boredom", "tiredness"], "a": 0, "p": "Forceful movement."}, {"lv": 2, "q": "'The silence was deafening.' This is an example of ...", "o": ["oxymoron", "simile", "alliteration", "onomatopoeia"], "a": 0, "p": "Contradictory terms."}, {"lv": 2, "q": "Why might a writer use short, sharp sentences in an action scene?", "o": ["to create pace and tension", "to slow the reader", "to add humour", "to give facts"], "a": 0, "p": "Pacing."}, {"lv": 2, "q": "'The wind howled like a wolf.' The effect is to make the wind seem ...", "o": ["wild and threatening", "gentle", "warm", "quiet"], "a": 0, "p": "A predatory simile."}, {"lv": 3, "q": "'Hope flickered in her chest like a candle in a storm.' What does this suggest?", "o": ["Her hope is fragile and under threat.", "She is on fire.", "She is very confident.", "She is cold."], "a": 0, "p": "Fragility."}, {"lv": 3, "q": "A writer uses 'cramped', 'peeling' and 'damp' to describe a flat. What impression is created?", "o": ["poverty and discomfort", "luxury", "excitement", "calm"], "a": 0, "p": "Negative connotations."}, {"lv": 3, "q": "Why might a writer shift from a calm to an anxious tone mid-paragraph?", "o": ["to signal a change in situation or mood", "by mistake", "to shorten the text", "to add facts"], "a": 0, "p": "Contrast."}, {"lv": 3, "q": "Which analysis is strongest?", "o": ["The verb 'clawed' personifies the waves, presenting the sea as a predator and heightening danger.", "The waves are big.", "The writer uses a verb.", "I like the sea."], "a": 0, "p": "Precise and explained."}]}, {"id": "sgp-eng-k9-2", "name": "Comprehension: implied meaning", "desc": "Reading critically", "idx": 2, "soal": [{"lv": 1, "q": "Implied meaning is ...", "o": ["suggested but not stated directly", "always stated", "the title", "the dictionary meaning"], "a": 0, "p": "Inference."}, {"lv": 1, "q": "'Her smile froze when she saw the bill.' What is implied?", "o": ["The bill was surprisingly high.", "She was cold.", "She was happy.", "The bill was small."], "a": 0, "p": "Shock."}, {"lv": 1, "q": "'He checked his watch for the fifth time.' He is probably ...", "o": ["impatient or anxious", "relaxed", "asleep", "happy"], "a": 0, "p": "Repeated checking."}, {"lv": 1, "q": "'The fridge was empty except for a bottle of water.' What is implied?", "o": ["The family had little food.", "The fridge was new.", "They love water.", "They just shopped."], "a": 0, "p": "Scarcity."}, {"lv": 2, "q": "'Despite his wealth, he wore the same old coat every winter.' What is implied?", "o": ["He was frugal or sentimental.", "He was poor.", "He had no coat.", "It never snowed."], "a": 0, "p": "Contrast."}, {"lv": 2, "q": "'The teacher raised an eyebrow at Jack's excuse.' This implies she ...", "o": ["doubted his excuse", "believed him fully", "was asleep", "was confused about the lesson"], "a": 0, "p": "Skepticism."}, {"lv": 2, "q": "'The streets, once bustling, now echoed with footsteps.' What is implied?", "o": ["The area has become deserted.", "It is a festival.", "The streets are new.", "It is very noisy."], "a": 0, "p": "Decline."}, {"lv": 2, "q": "'She answered with a curt \"Fine.\"' What is implied?", "o": ["She was annoyed.", "She was delighted.", "She was sleepy.", "She was confused."], "a": 0, "p": "Curt means short and rude."}, {"lv": 3, "q": "'The minister's statement was carefully worded, avoiding any mention of the delay.' What is implied?", "o": ["The minister wanted to avoid blame.", "There was no delay.", "The statement was careless.", "The minister was proud of the delay."], "a": 0, "p": "Evasion."}, {"lv": 3, "q": "'Every photo on the shelf showed the same smiling family—none taken in the last ten years.' What is implied?", "o": ["Something changed in the family a decade ago.", "They dislike cameras.", "The shelf is new.", "They take photos daily."], "a": 0, "p": "Absence suggests change."}, {"lv": 3, "q": "Why do writers use implied meaning rather than stating things directly?", "o": ["to engage readers and create subtlety", "to confuse readers deliberately", "because it is shorter", "to avoid writing"], "a": 0, "p": "Reader involvement."}, {"lv": 3, "q": "'He laughed a little too loudly at the boss's joke.' What is implied?", "o": ["He was trying to please the boss.", "The joke was very funny.", "He was alone.", "He was angry."], "a": 0, "p": "Overdoing it suggests flattery."}]}]}, "math": {"1": [{"id": "sgp-math-k1-0", "name": "Numbers to 100", "desc": "Counting, comparing, ordering", "idx": 0, "soal": [{"lv": 1, "q": "What number comes after 39?", "o": ["38", "40", "49", "30"], "a": 1, "p": "39 + 1 = 40."}, {"lv": 1, "q": "Which number is greater: 56 or 65?", "o": ["56", "65", "They are equal", "Cannot tell"], "a": 1, "p": "65 has more tens."}, {"lv": 1, "q": "Count by tens: 10, 20, 30, ___", "o": ["31", "40", "50", "35"], "a": 1, "p": "Add 10 each time."}, {"lv": 1, "q": "How many tens are in 70?", "o": ["7", "70", "17", "0"], "a": 0, "p": "70 = 7 tens."}, {"lv": 2, "q": "Which number is 1 less than 80?", "o": ["81", "79", "70", "89"], "a": 1, "p": "80 − 1 = 79."}, {"lv": 2, "q": "Arrange from smallest: 47, 74, 44, 77", "o": ["44, 47, 74, 77", "47, 44, 74, 77", "77, 74, 47, 44", "44, 74, 47, 77"], "a": 0, "p": "Compare tens, then ones."}, {"lv": 2, "q": "What number is 5 tens and 8 ones?", "o": ["85", "58", "13", "508"], "a": 1, "p": "50 + 8 = 58."}, {"lv": 2, "q": "Which number is between 62 and 65?", "o": ["61", "63", "66", "56"], "a": 1, "p": "63 comes after 62 and before 65."}, {"lv": 3, "q": "I am more than 40 but less than 50. My ones digit is 3. What number am I?", "o": ["34", "43", "53", "403"], "a": 1, "p": "In the 40s with a 3 in the ones place."}, {"lv": 3, "q": "Ali has 3 bundles of 10 sticks and 6 loose sticks. How many sticks does he have?", "o": ["36", "63", "9", "306"], "a": 0, "p": "30 + 6 = 36."}, {"lv": 3, "q": "What is the largest 2-digit number?", "o": ["90", "99", "100", "98"], "a": 1, "p": "99 is the largest with two digits."}, {"lv": 3, "q": "Which number is 10 more than 83?", "o": ["84", "93", "73", "183"], "a": 1, "p": "83 + 10 = 93."}]}, {"id": "sgp-math-k1-1", "name": "Addition and subtraction", "desc": "Number bonds and word problems", "idx": 1, "soal": [{"lv": 1, "q": "4 + 5 = ?", "o": ["9", "8", "10", "1"], "a": 0, "p": "Count on 5 from 4."}, {"lv": 1, "q": "10 − 3 = ?", "o": ["7", "13", "6", "8"], "a": 0, "p": "Number bond: 3 and 7 make 10."}, {"lv": 1, "q": "Which pair makes 8?", "o": ["3 and 5", "4 and 3", "2 and 5", "6 and 3"], "a": 0, "p": "3 + 5 = 8."}, {"lv": 1, "q": "20 + 10 = ?", "o": ["30", "21", "40", "12"], "a": 0, "p": "2 tens + 1 ten = 3 tens."}, {"lv": 2, "q": "35 + 4 = ?", "o": ["39", "75", "31", "40"], "a": 0, "p": "Add the ones: 5 + 4 = 9."}, {"lv": 2, "q": "48 − 5 = ?", "o": ["43", "53", "42", "44"], "a": 0, "p": "8 − 5 = 3."}, {"lv": 2, "q": "What is the missing number? 7 + ___ = 15", "o": ["8", "7", "22", "9"], "a": 0, "p": "15 − 7 = 8."}, {"lv": 2, "q": "26 + 13 = ?", "o": ["39", "29", "49", "36"], "a": 0, "p": "20 + 10 = 30 and 6 + 3 = 9."}, {"lv": 3, "q": "Mei had 25 stickers. She gave away 8. How many does she have left?", "o": ["17", "33", "18", "23"], "a": 0, "p": "25 − 8 = 17."}, {"lv": 3, "q": "There are 14 boys and 16 girls in a class. How many children are there?", "o": ["30", "20", "2", "32"], "a": 0, "p": "14 + 16 = 30."}, {"lv": 3, "q": "Raju has 9 more marbles than Tom. Tom has 12. How many does Raju have?", "o": ["21", "3", "19", "22"], "a": 0, "p": "12 + 9 = 21."}, {"lv": 3, "q": "A bus had 30 people. 12 got off and 5 got on. How many are on the bus now?", "o": ["23", "13", "47", "18"], "a": 0, "p": "30 − 12 + 5 = 23."}]}, {"id": "sgp-math-k1-2", "name": "Shapes and patterns", "desc": "Basic shapes and repeating patterns", "idx": 2, "soal": [{"lv": 1, "q": "How many sides does a triangle have?", "o": ["3", "4", "5", "0"], "a": 0, "p": "Tri means three."}, {"lv": 1, "q": "Which shape has 4 equal sides?", "o": ["square", "triangle", "circle", "rectangle with unequal sides"], "a": 0, "p": "A square has 4 equal sides."}, {"lv": 1, "q": "A circle has how many corners?", "o": ["0", "1", "4", "2"], "a": 0, "p": "A circle has no corners."}, {"lv": 1, "q": "What comes next? ○ △ ○ △ ○ ___", "o": ["△", "○", "□", "☆"], "a": 0, "p": "The pattern repeats circle, triangle."}, {"lv": 2, "q": "How many corners does a rectangle have?", "o": ["4", "3", "5", "2"], "a": 0, "p": "Rectangles have 4 corners."}, {"lv": 2, "q": "What comes next? 2, 4, 6, 8, ___", "o": ["10", "9", "12", "16"], "a": 0, "p": "Add 2 each time."}, {"lv": 2, "q": "What comes next? red, blue, blue, red, blue, blue, ___", "o": ["red", "blue", "green", "yellow"], "a": 0, "p": "The pattern repeats red, blue, blue."}, {"lv": 2, "q": "Which shape is like a slice of bread cut corner to corner?", "o": ["triangle", "circle", "oval", "star"], "a": 0, "p": "Cutting a square diagonally makes triangles."}, {"lv": 3, "q": "How many triangles do you get if you cut a square along both diagonals?", "o": ["4", "2", "3", "8"], "a": 0, "p": "Two diagonals make 4 triangles."}, {"lv": 3, "q": "What comes next? 5, 10, 15, 20, ___", "o": ["25", "21", "30", "24"], "a": 0, "p": "Add 5 each time."}, {"lv": 3, "q": "A pattern goes □ □ ○ □ □ ○. What is the 9th shape?", "o": ["○", "□", "△", "☆"], "a": 0, "p": "The pattern repeats every 3; the 9th is the 3rd in its group: ○."}, {"lv": 3, "q": "Which shape has the most sides?", "o": ["hexagon", "pentagon", "square", "triangle"], "a": 0, "p": "Hexagons have 6 sides."}]}], "10": [{"id": "sgp-math-k10-0", "name": "Coordinate geometry", "desc": "Gradient, length, equation of a line", "idx": 0, "soal": [{"lv": 1, "q": "Find the gradient of the line through (2, 3) and (6, 11).", "o": ["2", "4", "8", "0.5"], "a": 0, "p": "8/4."}, {"lv": 1, "q": "What is the y-intercept of y = −3x + 7?", "o": ["7", "−3", "3", "−7"], "a": 0, "p": "c = 7."}, {"lv": 1, "q": "Find the midpoint of (−2, 4) and (6, 0).", "o": ["(2, 2)", "(4, 4)", "(2, 4)", "(8, −4)"], "a": 0, "p": "Average the coordinates."}, {"lv": 1, "q": "A horizontal line has gradient ...", "o": ["0", "1", "undefined", "−1"], "a": 0, "p": "No rise."}, {"lv": 2, "q": "Find the length of the line segment from (1, 2) to (7, 10).", "o": ["10", "14", "8", "√28"], "a": 0, "p": "√(36 + 64)."}, {"lv": 2, "q": "Find the equation of the line through (0, −2) with gradient 4.", "o": ["y = 4x − 2", "y = −2x + 4", "y = 4x + 2", "y = x − 2"], "a": 0, "p": "y = mx + c."}, {"lv": 2, "q": "Find the equation of the line through (2, 5) and (4, 9).", "o": ["y = 2x + 1", "y = 2x + 5", "y = 4x − 3", "y = x + 3"], "a": 0, "p": "m = 2; 5 = 4 + c."}, {"lv": 2, "q": "Where does 2x + 3y = 12 cut the x-axis?", "o": ["(6, 0)", "(0, 4)", "(4, 0)", "(0, 6)"], "a": 0, "p": "Set y = 0."}, {"lv": 3, "q": "Lines y = 2x + 1 and y = −x + 7 intersect at ...", "o": ["(2, 5)", "(3, 4)", "(1, 3)", "(6, 1)"], "a": 0, "p": "2x + 1 = −x + 7 → x = 2."}, {"lv": 3, "q": "Points A(1, 1), B(4, 5) and C(7, k) are collinear. Find k.", "o": ["9", "8", "10", "7"], "a": 0, "p": "The gradient is 4/3 throughout: k = 5 + 4."}, {"lv": 3, "q": "Find the area of the triangle with vertices (0, 0), (6, 0) and (0, 4).", "o": ["12", "24", "10", "20"], "a": 0, "p": "½ × 6 × 4."}, {"lv": 3, "q": "Which line is parallel to 3y = 6x − 1?", "o": ["y = 2x + 5", "y = 3x − 1", "y = −2x", "y = ½x"], "a": 0, "p": "Gradient 2."}]}, {"id": "sgp-math-k10-1", "name": "Vectors", "desc": "Vector operations in 2D", "idx": 1, "soal": [{"lv": 1, "q": "Add the column vectors (3, 2) + (1, 5).", "o": ["(4, 7)", "(2, −3)", "(3, 10)", "(4, 3)"], "a": 0, "p": "Add the components."}, {"lv": 1, "q": "Find 2 × (4, −1).", "o": ["(8, −2)", "(6, 1)", "(8, −1)", "(2, −2)"], "a": 0, "p": "Scalar multiplication."}, {"lv": 1, "q": "What is the magnitude of (6, 8)?", "o": ["10", "14", "48", "100"], "a": 0, "p": "√(36 + 64)."}, {"lv": 1, "q": "Vectors (2, 4) and (1, 2) are ...", "o": ["parallel", "perpendicular", "equal", "opposite"], "a": 0, "p": "(2, 4) = 2 × (1, 2)."}, {"lv": 2, "q": "Find (5, 3) − (2, −1).", "o": ["(3, 4)", "(7, 2)", "(3, 2)", "(3, −4)"], "a": 0, "p": "Subtract the components."}, {"lv": 2, "q": "OA = (2, 1) and OB = (5, 5). Find AB.", "o": ["(3, 4)", "(7, 6)", "(−3, −4)", "(3, 6)"], "a": 0, "p": "AB = OB − OA."}, {"lv": 2, "q": "What is |AB| for the vector in the previous question, (3, 4)?", "o": ["5", "7", "25", "12"], "a": 0, "p": "√(9 + 16)."}, {"lv": 2, "q": "If a = (1, 2) and b = (3, −1), find 2a + b.", "o": ["(5, 3)", "(4, 1)", "(5, 5)", "(7, 0)"], "a": 0, "p": "(2, 4) + (3, −1)."}, {"lv": 3, "q": "M is the midpoint of AB, where OA = a and OB = b. Express OM.", "o": ["½(a + b)", "a + b", "b − a", "½(b − a)"], "a": 0, "p": "Midpoint formula."}, {"lv": 3, "q": "PQ = (k, 6) is parallel to (2, 3). Find k.", "o": ["4", "3", "9", "6"], "a": 0, "p": "6/3 = 2, so k = 2 × 2."}, {"lv": 3, "q": "In triangle OAB, OA = a and OB = b. P divides AB in the ratio 1 : 2. Express OP.", "o": ["(2a + b)/3", "(a + 2b)/3", "(a + b)/2", "a + b/3"], "a": 0, "p": "OP = a + ⅓(b − a)."}, {"lv": 3, "q": "Which vector is a unit vector?", "o": ["(0.6, 0.8)", "(1, 1)", "(3, 4)", "(2, 0)"], "a": 0, "p": "√(0.36 + 0.64) = 1."}]}, {"id": "sgp-math-k10-2", "name": "Statistics", "desc": "Mean, median, standard deviation, interpreting data", "idx": 2, "soal": [{"lv": 1, "q": "Find the mean of 4, 7, 9, 10, 10.", "o": ["8", "10", "9", "40"], "a": 0, "p": "40 ÷ 5."}, {"lv": 1, "q": "Find the median of 3, 8, 5, 12, 6.", "o": ["6", "5", "8", "6.8"], "a": 0, "p": "Ordered: 3, 5, 6, 8, 12."}, {"lv": 1, "q": "Find the mode of 2, 3, 3, 5, 7, 3, 8.", "o": ["3", "5", "7", "2"], "a": 0, "p": "Most frequent."}, {"lv": 1, "q": "Find the range of 15, 22, 9, 30.", "o": ["21", "30", "9", "15"], "a": 0, "p": "30 − 9."}, {"lv": 2, "q": "Find the median of 2, 4, 7, 9, 11, 14.", "o": ["8", "7", "9", "7.8"], "a": 0, "p": "(7 + 9)/2."}, {"lv": 2, "q": "The mean of 5 numbers is 12. A sixth number, 18, is added. What is the new mean?", "o": ["13", "15", "12", "14"], "a": 0, "p": "(60 + 18)/6."}, {"lv": 2, "q": "Which measure is most affected by outliers?", "o": ["mean", "median", "mode", "interquartile range"], "a": 0, "p": "It uses all the values."}, {"lv": 2, "q": "A larger standard deviation means the data are ...", "o": ["more spread out", "more clustered", "all equal", "smaller"], "a": 0, "p": "Dispersion."}, {"lv": 3, "q": "Data: 2, 4, 6, 8. What is the standard deviation (population)?", "o": ["√5 ≈ 2.24", "5", "2", "√20"], "a": 0, "p": "Mean 5; deviations² = 9, 1, 1, 9 → variance 5."}, {"lv": 3, "q": "Set A: mean 50, SD 5. Set B: mean 50, SD 15. Which statement is true?", "o": ["Set B is more varied.", "Set A is more varied.", "Both are equally varied.", "Set B has a higher mean."], "a": 0, "p": "SD measures spread."}, {"lv": 3, "q": "The lower quartile is 12 and the upper quartile is 27. What is the interquartile range?", "o": ["15", "39", "27", "12"], "a": 0, "p": "27 − 12."}, {"lv": 3, "q": "Every value in a data set is increased by 5. What happens to the mean and SD?", "o": ["The mean increases by 5; the SD is unchanged.", "Both increase by 5.", "Neither changes.", "The SD increases by 5 only."], "a": 0, "p": "Shifting does not change the spread."}]}], "11": [{"id": "sgp-math-k11-0", "name": "Functions", "desc": "Domain, range, composite, inverse", "idx": 0, "soal": [{"lv": 1, "q": "If f(x) = x² + 1, find f(3).", "o": ["10", "7", "9", "16"], "a": 0, "p": "9 + 1."}, {"lv": 1, "q": "The domain of a function is the set of ...", "o": ["input values", "output values", "gradients", "intercepts"], "a": 0, "p": "Allowed x-values."}, {"lv": 1, "q": "The range of f(x) = x² for real x is ...", "o": ["y ≥ 0", "all real numbers", "y ≤ 0", "y > 1"], "a": 0, "p": "Squares are non-negative."}, {"lv": 1, "q": "If f(x) = 2x and g(x) = x + 3, find gf(1).", "o": ["5", "8", "4", "6"], "a": 0, "p": "f(1) = 2; g(2) = 5."}, {"lv": 2, "q": "Find f⁻¹(x) if f(x) = (x − 4)/3.", "o": ["3x + 4", "3x − 4", "(x + 4)/3", "x/3 + 4"], "a": 0, "p": "Swap and rearrange."}, {"lv": 2, "q": "For f(x) = √(x − 2), the largest possible domain is ...", "o": ["x ≥ 2", "x > 0", "all real x", "x ≤ 2"], "a": 0, "p": "The square root needs a non-negative input."}, {"lv": 2, "q": "Which function is one-to-one for all real x?", "o": ["f(x) = 3x − 1", "f(x) = x²", "f(x) = |x|", "f(x) = cos x"], "a": 0, "p": "A linear function with non-zero gradient."}, {"lv": 2, "q": "f(x) = x² + 2 and g(x) = 2x − 1. Find fg(x).", "o": ["4x² − 4x + 3", "2x² + 3", "4x² + 1", "2x² + 4x + 3"], "a": 0, "p": "(2x − 1)² + 2."}, {"lv": 3, "q": "f(x) = 1/(x − 2), x ≠ 2. Find f⁻¹(x).", "o": ["1/x + 2", "x − 2", "1/(x + 2)", "2 − 1/x"], "a": 0, "p": "y = 1/(x − 2) → x = 1/y + 2."}, {"lv": 3, "q": "The graph of y = f(x) is reflected in the line y = x. It becomes the graph of ...", "o": ["y = f⁻¹(x)", "y = −f(x)", "y = f(−x)", "y = 1/f(x)"], "a": 0, "p": "Property of inverse functions."}, {"lv": 3, "q": "For f(x) = x² − 4x + 7, x ≥ 2, what is the range?", "o": ["f(x) ≥ 3", "f(x) ≥ 7", "f(x) ≥ 0", "all real numbers"], "a": 0, "p": "(x − 2)² + 3, with minimum 3 at x = 2."}, {"lv": 3, "q": "The graph of y = f(x) is transformed to y = f(x − 3) + 2. This is a translation of ...", "o": ["3 units right and 2 units up", "3 left and 2 up", "3 right and 2 down", "2 right and 3 up"], "a": 0, "p": "Horizontal shift is opposite in sign."}]}, {"id": "sgp-math-k11-1", "name": "Differentiation", "desc": "Rules and applications", "idx": 1, "soal": [{"lv": 1, "q": "d/dx (x⁵) = ?", "o": ["5x⁴", "x⁴", "5x⁵", "x⁶/6"], "a": 0, "p": "Power rule."}, {"lv": 1, "q": "d/dx (sin x) = ?", "o": ["cos x", "−cos x", "sin x", "−sin x"], "a": 0, "p": "A standard result."}, {"lv": 1, "q": "d/dx (eˣ) = ?", "o": ["eˣ", "xeˣ⁻¹", "1", "ln x"], "a": 0, "p": "A standard result."}, {"lv": 1, "q": "d/dx (ln x) = ?", "o": ["1/x", "x", "ln x", "eˣ"], "a": 0, "p": "A standard result."}, {"lv": 2, "q": "Differentiate y = (2x + 1)³.", "o": ["6(2x + 1)²", "3(2x + 1)²", "(2x + 1)²", "6x²"], "a": 0, "p": "Chain rule: 3(2x + 1)² × 2."}, {"lv": 2, "q": "Differentiate y = x²eˣ.", "o": ["eˣ(x² + 2x)", "2xeˣ", "x²eˣ", "2x + eˣ"], "a": 0, "p": "Product rule."}, {"lv": 2, "q": "Differentiate y = sin(3x).", "o": ["3cos(3x)", "cos(3x)", "−3cos(3x)", "3sin(3x)"], "a": 0, "p": "Chain rule."}, {"lv": 2, "q": "Differentiate y = ln(x² + 1).", "o": ["2x/(x² + 1)", "1/(x² + 1)", "2x", "ln 2x"], "a": 0, "p": "Chain rule."}, {"lv": 3, "q": "Find the minimum value of y = x² − 6x + 11.", "o": ["2", "11", "3", "−7"], "a": 0, "p": "At x = 3: 9 − 18 + 11 = 2."}, {"lv": 3, "q": "Differentiate y = x/(x + 1).", "o": ["1/(x + 1)²", "x/(x + 1)²", "1", "−1/(x + 1)²"], "a": 0, "p": "Quotient rule: ((x + 1) − x)/(x + 1)²."}, {"lv": 3, "q": "The radius of a circle grows at 2 cm/s. How fast is the area increasing when r = 5 cm?", "o": ["20π cm²/s", "10π cm²/s", "25π cm²/s", "4π cm²/s"], "a": 0, "p": "dA/dt = 2πr × dr/dt."}, {"lv": 3, "q": "A box with a square base of side x and no lid has volume 32 cm³. Which x minimises the surface area?", "o": ["4", "2", "8", "√32"], "a": 0, "p": "S = x² + 128/x; dS/dx = 2x − 128/x² = 0 → x = 4."}]}, {"id": "sgp-math-k11-2", "name": "Sequences and series", "desc": "AP, GP, sigma notation", "idx": 2, "soal": [{"lv": 1, "q": "Find the 10th term of the AP 3, 7, 11, ...", "o": ["39", "43", "40", "35"], "a": 0, "p": "3 + 9 × 4."}, {"lv": 1, "q": "What is the common ratio of the GP 2, 6, 18, ...?", "o": ["3", "4", "2", "6"], "a": 0, "p": "6/2."}, {"lv": 1, "q": "Find Σ (r = 1 to 4) of r.", "o": ["10", "4", "16", "24"], "a": 0, "p": "1 + 2 + 3 + 4."}, {"lv": 1, "q": "Find the 5th term of the GP 1, 2, 4, ...", "o": ["16", "8", "32", "10"], "a": 0, "p": "2⁴."}, {"lv": 2, "q": "Find the sum of the first 20 terms of the AP 5, 8, 11, ...", "o": ["670", "620", "700", "335"], "a": 0, "p": "S = 20/2 × (10 + 19 × 3) = 10 × 67."}, {"lv": 2, "q": "Find the sum to infinity of 8 + 4 + 2 + ...", "o": ["16", "14", "∞", "32"], "a": 0, "p": "a/(1 − r) = 8/0.5."}, {"lv": 2, "q": "For which r does a GP have a sum to infinity?", "o": ["|r| < 1", "r > 1", "r = 1", "any r"], "a": 0, "p": "Convergence condition."}, {"lv": 2, "q": "The 3rd term of an AP is 11 and the 7th is 23. Find the common difference.", "o": ["3", "4", "12", "2"], "a": 0, "p": "4d = 12."}, {"lv": 3, "q": "Find Σ (r = 1 to 10) of (2r + 1).", "o": ["120", "110", "100", "130"], "a": 0, "p": "2 × 55 + 10."}, {"lv": 3, "q": "A GP has first term 81 and sum to infinity 243. Find r.", "o": ["2/3", "1/3", "3/4", "1/2"], "a": 0, "p": "81/(1 − r) = 243 → 1 − r = 1/3."}, {"lv": 3, "q": "Savings start at $100 and increase by $20 each month. What is the total after 12 months?", "o": ["$2520", "$2400", "$1320", "$2640"], "a": 0, "p": "12/2 × (200 + 11 × 20) = 6 × 420."}, {"lv": 3, "q": "How many terms of the AP 2, 5, 8, ... are needed for the sum to exceed 100?", "o": ["9", "8", "10", "7"], "a": 0, "p": "S₈ = 8/2 × (4 + 21) = 100, which does not exceed 100; S₉ = 9/2 × (4 + 24) = 126."}]}], "12": [{"id": "sgp-math-k12-0", "name": "Integration", "desc": "Techniques and applications", "idx": 0, "soal": [{"lv": 1, "q": "∫ cos x dx = ?", "o": ["sin x + c", "−sin x + c", "cos x + c", "tan x + c"], "a": 0, "p": "Standard integral."}, {"lv": 1, "q": "∫ eˣ dx = ?", "o": ["eˣ + c", "xeˣ + c", "eˣ⁺¹ + c", "ln x + c"], "a": 0, "p": "Standard integral."}, {"lv": 1, "q": "∫ 1/x dx = ?", "o": ["ln|x| + c", "x⁻² + c", "1/x² + c", "eˣ + c"], "a": 0, "p": "Standard integral."}, {"lv": 1, "q": "∫ (3x² + 2) dx = ?", "o": ["x³ + 2x + c", "6x + c", "3x³ + 2x + c", "x³ + c"], "a": 0, "p": "Power rule."}, {"lv": 2, "q": "Evaluate ∫₀^π sin x dx.", "o": ["2", "0", "1", "π"], "a": 0, "p": "[−cos x] from 0 to π = 1 + 1."}, {"lv": 2, "q": "∫ e^(2x) dx = ?", "o": ["½e^(2x) + c", "2e^(2x) + c", "e^(2x) + c", "e^x + c"], "a": 0, "p": "Reverse chain rule."}, {"lv": 2, "q": "∫ 2x(x² + 1)⁴ dx = ?", "o": ["(x² + 1)⁵/5 + c", "(x² + 1)⁵ + c", "2(x² + 1)⁵ + c", "x²(x² + 1)⁴ + c"], "a": 0, "p": "Substitute u = x² + 1."}, {"lv": 2, "q": "∫ 1/(2x + 1) dx = ?", "o": ["½ ln|2x + 1| + c", "ln|2x + 1| + c", "2 ln|2x + 1| + c", "1/(2x + 1)² + c"], "a": 0, "p": "Divide by 2."}, {"lv": 3, "q": "∫ x eˣ dx = ?", "o": ["eˣ(x − 1) + c", "xeˣ + c", "eˣ(x + 1) + c", "x²eˣ/2 + c"], "a": 0, "p": "By parts: xeˣ − ∫eˣ dx."}, {"lv": 3, "q": "Find the area enclosed by y = x² and y = 2x.", "o": ["4/3", "8/3", "2", "4"], "a": 0, "p": "∫₀² (2x − x²) dx = 4 − 8/3."}, {"lv": 3, "q": "∫ sin² x dx = ?", "o": ["x/2 − sin(2x)/4 + c", "sin³x/3 + c", "−cos² x + c", "x − cos x + c"], "a": 0, "p": "Use sin² x = (1 − cos 2x)/2."}, {"lv": 3, "q": "The region under y = √x from x = 0 to 4 is rotated 360° about the x-axis. Find the volume.", "o": ["8π", "16π", "4π", "32π/3"], "a": 0, "p": "π∫₀⁴ x dx = π × 8."}]}, {"id": "sgp-math-k12-1", "name": "Complex numbers", "desc": "Cartesian and polar form", "idx": 1, "soal": [{"lv": 1, "q": "i² = ?", "o": ["−1", "1", "i", "0"], "a": 0, "p": "Definition."}, {"lv": 1, "q": "(3 + 2i) + (1 − 5i) = ?", "o": ["4 − 3i", "2 + 7i", "4 + 7i", "3 − 10i"], "a": 0, "p": "Add the real and imaginary parts."}, {"lv": 1, "q": "What is the complex conjugate of 4 − 7i?", "o": ["4 + 7i", "−4 + 7i", "−4 − 7i", "7 − 4i"], "a": 0, "p": "Change the sign of the imaginary part."}, {"lv": 1, "q": "What is the real part of 5 − 2i?", "o": ["5", "−2", "2", "5i"], "a": 0, "p": "Re(z)."}, {"lv": 2, "q": "(2 + i)(3 − i) = ?", "o": ["7 + i", "5 + i", "7 − i", "6 − i"], "a": 0, "p": "6 − 2i + 3i − i² = 7 + i."}, {"lv": 2, "q": "What is |3 + 4i|?", "o": ["5", "7", "25", "1"], "a": 0, "p": "√(9 + 16)."}, {"lv": 2, "q": "Solve z² + 9 = 0.", "o": ["z = ±3i", "z = ±3", "z = 9i", "z = −9"], "a": 0, "p": "z² = −9."}, {"lv": 2, "q": "What is the argument of 1 + i (in radians)?", "o": ["π/4", "π/2", "π", "0"], "a": 0, "p": "tan⁻¹(1)."}, {"lv": 3, "q": "(1 + 2i)/(1 − i) = ?", "o": ["−1/2 + 3i/2", "1/2 + 3i/2", "−1/2 − 3i/2", "3/2 + i/2"], "a": 0, "p": "Multiply by (1 + i)/(1 + i): (−1 + 3i)/2."}, {"lv": 3, "q": "Write 2(cos π/3 + i sin π/3) in Cartesian form.", "o": ["1 + √3 i", "√3 + i", "2 + 2i", "1 + i"], "a": 0, "p": "2 × 1/2 = 1 and 2 × √3/2 = √3."}, {"lv": 3, "q": "If z = 2e^(iπ/6), what is z³?", "o": ["8i", "8", "−8", "6i"], "a": 0, "p": "8e^(iπ/2) = 8i."}, {"lv": 3, "q": "For a real polynomial, if 2 + 3i is a root, which must also be a root?", "o": ["2 − 3i", "−2 + 3i", "3 + 2i", "−2 − 3i"], "a": 0, "p": "Roots come in conjugate pairs."}]}, {"id": "sgp-math-k12-2", "name": "Probability distributions", "desc": "Binomial and normal distribution", "idx": 2, "soal": [{"lv": 1, "q": "In a binomial distribution B(n, p), n is ...", "o": ["the number of trials", "the probability", "the mean", "the variance"], "a": 0, "p": "Fixed number of trials."}, {"lv": 1, "q": "The mean of B(n, p) is ...", "o": ["np", "np(1 − p)", "n/p", "p/n"], "a": 0, "p": "Expectation."}, {"lv": 1, "q": "The normal distribution is ...", "o": ["symmetric and bell-shaped", "skewed right always", "uniform", "discrete"], "a": 0, "p": "Shape."}, {"lv": 1, "q": "For the standard normal distribution Z, the mean and variance are ...", "o": ["0 and 1", "1 and 0", "0 and 0", "1 and 1"], "a": 0, "p": "N(0, 1)."}, {"lv": 2, "q": "X ~ B(10, 0.3). What is E(X)?", "o": ["3", "0.3", "2.1", "7"], "a": 0, "p": "10 × 0.3."}, {"lv": 2, "q": "X ~ B(10, 0.3). What is Var(X)?", "o": ["2.1", "3", "0.21", "7"], "a": 0, "p": "10 × 0.3 × 0.7."}, {"lv": 2, "q": "X ~ B(4, 0.5). Find P(X = 2).", "o": ["0.375", "0.5", "0.25", "0.0625"], "a": 0, "p": "6 × 0.5⁴."}, {"lv": 2, "q": "X ~ N(50, 16). What is the standard deviation?", "o": ["4", "16", "256", "8"], "a": 0, "p": "√16."}, {"lv": 3, "q": "X ~ N(100, 15²). Find the z-score for X = 130.", "o": ["2", "1.5", "30", "0.5"], "a": 0, "p": "(130 − 100)/15."}, {"lv": 3, "q": "About what percentage of a normal distribution lies within ±1 standard deviation of the mean?", "o": ["68%", "95%", "99.7%", "50%"], "a": 0, "p": "The empirical rule."}, {"lv": 3, "q": "A fair coin is tossed 6 times. What is P(exactly 4 heads)?", "o": ["15/64", "6/64", "20/64", "1/16"], "a": 0, "p": "C(6, 4) × (1/2)⁶ = 15/64."}, {"lv": 3, "q": "Which condition is NOT required for a binomial model?", "o": ["The outcomes must be normally distributed.", "A fixed number of trials", "Independent trials", "Constant probability of success"], "a": 0, "p": "That is not a binomial condition."}]}], "2": [{"id": "sgp-math-k2-0", "name": "Multiplication and division", "desc": "Tables of 2, 3, 4, 5 and 10", "idx": 0, "soal": [{"lv": 1, "q": "3 × 5 = ?", "o": ["15", "8", "35", "2"], "a": 0, "p": "3 groups of 5."}, {"lv": 1, "q": "20 ÷ 10 = ?", "o": ["2", "10", "200", "30"], "a": 0, "p": "10 × 2 = 20."}, {"lv": 1, "q": "4 × 2 = ?", "o": ["8", "6", "42", "2"], "a": 0, "p": "4 groups of 2."}, {"lv": 1, "q": "15 ÷ 5 = ?", "o": ["3", "5", "10", "75"], "a": 0, "p": "5 × 3 = 15."}, {"lv": 2, "q": "4 × 4 = ?", "o": ["16", "8", "12", "44"], "a": 0, "p": "4 groups of 4."}, {"lv": 2, "q": "27 ÷ 3 = ?", "o": ["9", "8", "24", "30"], "a": 0, "p": "3 × 9 = 27."}, {"lv": 2, "q": "Which is the same as 5 × 3?", "o": ["3 × 5", "5 + 3", "53", "5 − 3"], "a": 0, "p": "The order can be swapped."}, {"lv": 2, "q": "36 ÷ 4 = ?", "o": ["9", "8", "32", "40"], "a": 0, "p": "4 × 9 = 36."}, {"lv": 3, "q": "There are 5 boxes with 4 cakes in each. How many cakes are there?", "o": ["20", "9", "54", "1"], "a": 0, "p": "5 × 4 = 20."}, {"lv": 3, "q": "24 sweets are shared equally among 3 children. How many does each child get?", "o": ["8", "21", "27", "6"], "a": 0, "p": "24 ÷ 3 = 8."}, {"lv": 3, "q": "A spider has 8 legs. How many legs do 3 spiders have?", "o": ["24", "11", "16", "38"], "a": 0, "p": "3 × 8 = 24."}, {"lv": 3, "q": "Mrs Tan puts 40 pencils into bundles of 10. She gives away 2 bundles. How many bundles are left?", "o": ["2", "4", "38", "30"], "a": 0, "p": "40 ÷ 10 = 4; 4 − 2 = 2."}]}, {"id": "sgp-math-k2-1", "name": "Money", "desc": "Dollars and cents", "idx": 1, "soal": [{"lv": 1, "q": "How many cents are in $1?", "o": ["100", "10", "50", "1000"], "a": 0, "p": "$1 = 100¢."}, {"lv": 1, "q": "Which coin is worth the most?", "o": ["50¢", "20¢", "10¢", "5¢"], "a": 0, "p": "50 cents is the largest."}, {"lv": 1, "q": "$2 + $3 = ?", "o": ["$5", "$6", "$23", "$1"], "a": 0, "p": "2 + 3 = 5."}, {"lv": 1, "q": "Two 20¢ coins make ...", "o": ["40¢", "20¢", "22¢", "$2"], "a": 0, "p": "20 + 20 = 40."}, {"lv": 2, "q": "A pen costs $1.50 and a ruler costs 80¢. What is the total?", "o": ["$2.30", "$1.58", "$2.50", "$9.50"], "a": 0, "p": "150¢ + 80¢ = 230¢."}, {"lv": 2, "q": "Write 350¢ in dollars.", "o": ["$3.50", "$35.00", "$0.35", "$350"], "a": 0, "p": "100¢ = $1."}, {"lv": 2, "q": "Ali has $10. He spends $6.40. How much is left?", "o": ["$3.60", "$4.60", "$4.40", "$16.40"], "a": 0, "p": "$10.00 − $6.40 = $3.60."}, {"lv": 2, "q": "Which is more: $1.05 or 150¢?", "o": ["150¢", "$1.05", "They are equal", "Cannot tell"], "a": 0, "p": "150¢ = $1.50."}, {"lv": 3, "q": "A book costs $4.50. How much do 2 books cost?", "o": ["$9.00", "$8.50", "$6.50", "$4.52"], "a": 0, "p": "$4.50 + $4.50."}, {"lv": 3, "q": "Mei pays $5 for a drink costing $1.20 and a bun costing $0.90. How much change does she get?", "o": ["$2.90", "$2.10", "$3.10", "$7.10"], "a": 0, "p": "$1.20 + $0.90 = $2.10; $5 − $2.10 = $2.90."}, {"lv": 3, "q": "Sam has three 50¢ coins and two $1 notes. How much money does he have?", "o": ["$3.50", "$2.50", "$5.00", "$3.00"], "a": 0, "p": "$1.50 + $2.00."}, {"lv": 3, "q": "A toy costs $8. Jun has saved $5.60. How much more does he need?", "o": ["$2.40", "$3.40", "$2.60", "$13.60"], "a": 0, "p": "$8.00 − $5.60."}]}, {"id": "sgp-math-k2-2", "name": "Fractions", "desc": "Halves, thirds, quarters", "idx": 2, "soal": [{"lv": 1, "q": "A pizza is cut into 2 equal parts. Each part is ...", "o": ["1/2", "1/3", "1/4", "2"], "a": 0, "p": "One half."}, {"lv": 1, "q": "Which fraction means one out of four equal parts?", "o": ["1/4", "4/1", "1/2", "1/3"], "a": 0, "p": "One quarter."}, {"lv": 1, "q": "A cake is cut into 3 equal pieces. Each piece is ...", "o": ["1/3", "1/2", "3/1", "1/4"], "a": 0, "p": "One third."}, {"lv": 1, "q": "Which is bigger: 1/2 or 1/4 of the same pizza?", "o": ["1/2", "1/4", "Same", "Cannot tell"], "a": 0, "p": "Fewer pieces means bigger pieces."}, {"lv": 2, "q": "What fraction is 2 out of 4 equal parts?", "o": ["2/4", "4/2", "1/4", "3/4"], "a": 0, "p": "2/4, which is the same as 1/2."}, {"lv": 2, "q": "Which fraction is the smallest?", "o": ["1/4", "1/3", "1/2", "2/3"], "a": 0, "p": "Quarters are the smallest pieces."}, {"lv": 2, "q": "A bar is cut into 4 equal parts. 3 parts are shaded. What fraction is NOT shaded?", "o": ["1/4", "3/4", "1/3", "4/3"], "a": 0, "p": "1 out of 4."}, {"lv": 2, "q": "1/3 + 1/3 = ?", "o": ["2/3", "2/6", "1/6", "1/3"], "a": 0, "p": "Same-sized parts: 2 thirds."}, {"lv": 3, "q": "Arrange from smallest: 1/2, 1/4, 1/3", "o": ["1/4, 1/3, 1/2", "1/2, 1/3, 1/4", "1/3, 1/4, 1/2", "1/4, 1/2, 1/3"], "a": 0, "p": "The bigger the denominator, the smaller the part."}, {"lv": 3, "q": "What fraction of a whole is left after eating 1/4?", "o": ["3/4", "1/4", "1/2", "4/4"], "a": 0, "p": "1 − 1/4 = 3/4."}, {"lv": 3, "q": "Which pair of fractions are equal?", "o": ["1/2 and 2/4", "1/3 and 1/4", "1/2 and 1/3", "2/3 and 3/4"], "a": 0, "p": "2/4 = 1/2."}, {"lv": 3, "q": "A ribbon is cut into 4 equal pieces. Siti takes 2 pieces. What fraction does she take?", "o": ["1/2", "1/4", "2/2", "1/3"], "a": 0, "p": "2/4 = 1/2."}]}], "3": [{"id": "sgp-math-k3-0", "name": "Addition and subtraction within 10 000", "desc": "Word problems with bar models", "idx": 0, "soal": [{"lv": 1, "q": "2345 + 1000 = ?", "o": ["3345", "2445", "2355", "12345"], "a": 0, "p": "Add 1 to the thousands digit."}, {"lv": 1, "q": "5000 − 2000 = ?", "o": ["3000", "7000", "2000", "300"], "a": 0, "p": "5 thousands − 2 thousands."}, {"lv": 1, "q": "What is 4000 + 300 + 20 + 5?", "o": ["4325", "4352", "43025", "4235"], "a": 0, "p": "Place value."}, {"lv": 1, "q": "1234 + 2111 = ?", "o": ["3345", "3335", "3445", "2345"], "a": 0, "p": "Add each place."}, {"lv": 2, "q": "3756 + 2481 = ?", "o": ["6237", "6137", "5237", "6227"], "a": 0, "p": "Regroup in the tens and hundreds."}, {"lv": 2, "q": "6005 − 1278 = ?", "o": ["4727", "4827", "5727", "4737"], "a": 0, "p": "Regroup across the zeros."}, {"lv": 2, "q": "Find the missing number: ___ + 2450 = 5000", "o": ["2550", "2650", "7450", "3550"], "a": 0, "p": "5000 − 2450."}, {"lv": 2, "q": "8000 − 4567 = ?", "o": ["3433", "4433", "3533", "3443"], "a": 0, "p": "Subtract with regrouping."}, {"lv": 3, "q": "A shop sold 2386 cups in May and 1749 more in June than in May. How many cups were sold in June?", "o": ["4135", "637", "3135", "4125"], "a": 0, "p": "2386 + 1749 = 4135."}, {"lv": 3, "q": "A school has 3200 pupils. 1475 are boys. How many more girls than boys are there?", "o": ["250", "1725", "1475", "175"], "a": 0, "p": "Girls = 1725; 1725 − 1475 = 250."}, {"lv": 3, "q": "Ahmad had $5000. He spent $1860 on a TV and $975 on a fridge. How much money is left?", "o": ["$2165", "$2835", "$3140", "$2265"], "a": 0, "p": "1860 + 975 = 2835; 5000 − 2835 = 2165."}, {"lv": 3, "q": "In a bar model, the whole is 7200 and one part is 2650. What is the other part?", "o": ["4550", "9850", "4650", "5550"], "a": 0, "p": "7200 − 2650."}]}, {"id": "sgp-math-k3-1", "name": "Multiplication and division", "desc": "Tables of 6-9, word problems", "idx": 1, "soal": [{"lv": 1, "q": "6 × 7 = ?", "o": ["42", "48", "36", "13"], "a": 0, "p": "Times table of 6."}, {"lv": 1, "q": "8 × 9 = ?", "o": ["72", "81", "64", "17"], "a": 0, "p": "Times table of 8."}, {"lv": 1, "q": "54 ÷ 6 = ?", "o": ["9", "8", "48", "60"], "a": 0, "p": "6 × 9 = 54."}, {"lv": 1, "q": "7 × 7 = ?", "o": ["49", "14", "42", "56"], "a": 0, "p": "Times table of 7."}, {"lv": 2, "q": "63 ÷ 9 = ?", "o": ["7", "8", "6", "54"], "a": 0, "p": "9 × 7 = 63."}, {"lv": 2, "q": "What is 56 ÷ 8?", "o": ["7", "6", "8", "48"], "a": 0, "p": "8 × 7 = 56."}, {"lv": 2, "q": "What is 9 × 6?", "o": ["54", "56", "45", "63"], "a": 0, "p": "9 × 6 = 54."}, {"lv": 2, "q": "What is the remainder when 50 is divided by 7?", "o": ["1", "2", "7", "0"], "a": 0, "p": "7 × 7 = 49; 50 − 49 = 1."}, {"lv": 3, "q": "A box holds 8 eggs. How many boxes are needed for 70 eggs?", "o": ["9", "8", "10", "62"], "a": 0, "p": "70 ÷ 8 = 8 r 6, so 9 boxes."}, {"lv": 3, "q": "Each bag has 6 oranges. Mrs Lim buys 9 bags and gives away 15 oranges. How many are left?", "o": ["39", "54", "69", "30"], "a": 0, "p": "6 × 9 = 54; 54 − 15 = 39."}, {"lv": 3, "q": "72 children are put into 8 equal groups. How many children are in 3 groups?", "o": ["27", "9", "24", "216"], "a": 0, "p": "72 ÷ 8 = 9; 9 × 3 = 27."}, {"lv": 3, "q": "A pen costs $7. Ravi has $60. What is the greatest number of pens he can buy?", "o": ["8", "9", "7", "53"], "a": 0, "p": "60 ÷ 7 = 8 r 4."}]}, {"id": "sgp-math-k3-2", "name": "Length, mass and volume", "desc": "Units and conversions", "idx": 2, "soal": [{"lv": 1, "q": "How many centimetres are in 1 metre?", "o": ["100", "10", "1000", "60"], "a": 0, "p": "1 m = 100 cm."}, {"lv": 1, "q": "How many grams are in 1 kilogram?", "o": ["1000", "100", "10", "500"], "a": 0, "p": "1 kg = 1000 g."}, {"lv": 1, "q": "How many millilitres are in 1 litre?", "o": ["1000", "100", "10", "500"], "a": 0, "p": "1 ℓ = 1000 ml."}, {"lv": 1, "q": "Which unit is best for the mass of an apple?", "o": ["grams", "kilograms", "litres", "metres"], "a": 0, "p": "An apple is light."}, {"lv": 2, "q": "Convert 3 m 45 cm into cm.", "o": ["345 cm", "3045 cm", "34.5 cm", "3450 cm"], "a": 0, "p": "300 + 45."}, {"lv": 2, "q": "Convert 2 kg 50 g into g.", "o": ["2050 g", "2500 g", "250 g", "2005 g"], "a": 0, "p": "2000 + 50."}, {"lv": 2, "q": "Convert 4250 ml into litres and millilitres.", "o": ["4 ℓ 250 ml", "42 ℓ 50 ml", "425 ℓ", "4 ℓ 25 ml"], "a": 0, "p": "4000 ml = 4 ℓ."}, {"lv": 2, "q": "Which is the longest?", "o": ["1 km", "900 m", "9000 cm", "99 m"], "a": 0, "p": "1 km = 1000 m."}, {"lv": 3, "q": "A bottle holds 1 ℓ 500 ml of juice. 750 ml is poured out. How much is left?", "o": ["750 ml", "1 ℓ 250 ml", "2 ℓ 250 ml", "850 ml"], "a": 0, "p": "1500 − 750 = 750 ml."}, {"lv": 3, "q": "A bag of rice has a mass of 5 kg. 1 kg 200 g is used. What mass is left?", "o": ["3 kg 800 g", "4 kg 800 g", "3 kg 200 g", "6 kg 200 g"], "a": 0, "p": "5000 − 1200 = 3800 g."}, {"lv": 3, "q": "A rope is 6 m long. It is cut into 4 equal pieces. How long is each piece in cm?", "o": ["150 cm", "24 cm", "1.5 cm", "600 cm"], "a": 0, "p": "600 ÷ 4 = 150 cm."}, {"lv": 3, "q": "A box with 3 books has a mass of 2 kg. The empty box is 500 g. What is the mass of one book?", "o": ["500 g", "666 g", "1500 g", "750 g"], "a": 0, "p": "Books = 1500 g; 1500 ÷ 3 = 500 g."}]}], "4": [{"id": "sgp-math-k4-0", "name": "Factors and multiples", "desc": "Common factors and multiples", "idx": 0, "soal": [{"lv": 1, "q": "Which is a factor of 12?", "o": ["4", "5", "7", "24"], "a": 0, "p": "12 ÷ 4 = 3 with no remainder."}, {"lv": 1, "q": "Which is a multiple of 6?", "o": ["18", "16", "20", "9"], "a": 0, "p": "6 × 3 = 18."}, {"lv": 1, "q": "List the factors of 8.", "o": ["1, 2, 4, 8", "1, 8", "2, 4, 6, 8", "8, 16, 24"], "a": 0, "p": "Numbers that divide 8 exactly."}, {"lv": 1, "q": "What are the first three multiples of 5?", "o": ["5, 10, 15", "1, 5, 10", "5, 15, 25", "10, 20, 30"], "a": 0, "p": "5 × 1, 5 × 2, 5 × 3."}, {"lv": 2, "q": "What is a common factor of 12 and 18?", "o": ["6", "4", "9", "36"], "a": 0, "p": "6 divides both."}, {"lv": 2, "q": "What is the lowest common multiple of 4 and 6?", "o": ["12", "24", "2", "10"], "a": 0, "p": "Multiples of 4: 4, 8, 12; multiples of 6: 6, 12."}, {"lv": 2, "q": "Which number has exactly two factors?", "o": ["7", "9", "12", "15"], "a": 0, "p": "7 is prime."}, {"lv": 2, "q": "What is the highest common factor of 16 and 24?", "o": ["8", "4", "2", "48"], "a": 0, "p": "8 is the largest common factor."}, {"lv": 3, "q": "Two lights flash every 6 s and every 8 s. They flash together now. When will they next flash together?", "o": ["after 24 s", "after 14 s", "after 48 s", "after 2 s"], "a": 0, "p": "The LCM of 6 and 8 is 24."}, {"lv": 3, "q": "36 apples and 48 oranges are packed into identical bags with no fruit left over. What is the greatest number of bags?", "o": ["12", "6", "4", "24"], "a": 0, "p": "The HCF of 36 and 48 is 12."}, {"lv": 3, "q": "I am a multiple of 7 between 30 and 40. What am I?", "o": ["35", "32", "36", "38"], "a": 0, "p": "7 × 5 = 35."}, {"lv": 3, "q": "Which number is a common multiple of 3, 4 and 5?", "o": ["60", "30", "40", "45"], "a": 0, "p": "The LCM is 60."}]}, {"id": "sgp-math-k4-1", "name": "Fractions", "desc": "Mixed numbers, improper fractions, fraction of a set", "idx": 1, "soal": [{"lv": 1, "q": "Write 7/4 as a mixed number.", "o": ["1 3/4", "1 1/4", "3 1/4", "7 1/4"], "a": 0, "p": "7 ÷ 4 = 1 r 3."}, {"lv": 1, "q": "Write 2 1/3 as an improper fraction.", "o": ["7/3", "5/3", "6/3", "3/7"], "a": 0, "p": "2 × 3 + 1 = 7."}, {"lv": 1, "q": "What is 1/4 of 20?", "o": ["5", "4", "80", "10"], "a": 0, "p": "20 ÷ 4."}, {"lv": 1, "q": "Which fraction is equivalent to 2/3?", "o": ["4/6", "3/4", "2/6", "6/4"], "a": 0, "p": "Multiply top and bottom by 2."}, {"lv": 2, "q": "What is 3/5 of 30?", "o": ["18", "6", "15", "50"], "a": 0, "p": "30 ÷ 5 × 3."}, {"lv": 2, "q": "1 1/2 + 2 1/4 = ?", "o": ["3 3/4", "3 1/2", "3 2/6", "4 1/4"], "a": 0, "p": "1/2 = 2/4."}, {"lv": 2, "q": "There are 24 pupils. 3/8 of them wear glasses. How many wear glasses?", "o": ["9", "8", "3", "15"], "a": 0, "p": "24 ÷ 8 × 3."}, {"lv": 2, "q": "Which is larger: 5/6 or 7/9?", "o": ["5/6", "7/9", "They are equal", "Cannot tell"], "a": 0, "p": "15/18 vs 14/18."}, {"lv": 3, "q": "Mrs Tan baked 40 cookies. She gave 1/4 to her neighbour and 2/5 of the rest to her friend. How many are left?", "o": ["18", "12", "22", "10"], "a": 0, "p": "Gave 10, left 30; 2/5 of 30 = 12; 30 − 12 = 18."}, {"lv": 3, "q": "A ribbon is 3 m long. 2/3 of it is used. How many cm are left?", "o": ["100 cm", "200 cm", "150 cm", "33 cm"], "a": 0, "p": "1/3 of 300 cm."}, {"lv": 3, "q": "4 3/8 − 1 5/8 = ?", "o": ["2 3/4", "3 1/4", "2 1/4", "3 3/4"], "a": 0, "p": "35/8 − 13/8 = 22/8 = 2 6/8 = 2 3/4."}, {"lv": 3, "q": "What fraction of an hour is 45 minutes?", "o": ["3/4", "4/5", "1/4", "45/100"], "a": 0, "p": "45/60 = 3/4."}]}, {"id": "sgp-math-k4-2", "name": "Decimals", "desc": "Place value, operations", "idx": 2, "soal": [{"lv": 1, "q": "In 3.47, what is the value of the digit 4?", "o": ["4 tenths (0.4)", "4 hundredths", "4 ones", "40"], "a": 0, "p": "The first place after the decimal point is tenths."}, {"lv": 1, "q": "Write 7/10 as a decimal.", "o": ["0.7", "0.07", "7.0", "70"], "a": 0, "p": "Seven tenths."}, {"lv": 1, "q": "Which is the largest?", "o": ["0.9", "0.09", "0.19", "0.099"], "a": 0, "p": "9 tenths is the largest."}, {"lv": 1, "q": "2.5 + 1.2 = ?", "o": ["3.7", "3.5", "4.7", "2.7"], "a": 0, "p": "Add tenths and ones."}, {"lv": 2, "q": "4.6 − 2.85 = ?", "o": ["1.75", "2.25", "1.85", "2.75"], "a": 0, "p": "4.60 − 2.85."}, {"lv": 2, "q": "Round 3.46 to 1 decimal place.", "o": ["3.5", "3.4", "3.0", "4.0"], "a": 0, "p": "The hundredths digit 6 rounds up."}, {"lv": 2, "q": "0.35 × 4 = ?", "o": ["1.4", "1.2", "0.14", "14"], "a": 0, "p": "35 × 4 = 140, so 1.40."}, {"lv": 2, "q": "6.3 ÷ 3 = ?", "o": ["2.1", "2.3", "0.21", "21"], "a": 0, "p": "63 ÷ 3 = 21, so 2.1."}, {"lv": 3, "q": "A pen costs $1.85. Mei buys 4 pens. How much does she pay?", "o": ["$7.40", "$7.20", "$5.85", "$4.40"], "a": 0, "p": "1.85 × 4."}, {"lv": 3, "q": "A 2.4 kg bag of flour is shared equally into 6 containers. What is the mass in each?", "o": ["0.4 kg", "0.6 kg", "4 kg", "0.04 kg"], "a": 0, "p": "2.4 ÷ 6."}, {"lv": 3, "q": "Arrange from smallest: 0.5, 0.45, 0.405, 0.54", "o": ["0.405, 0.45, 0.5, 0.54", "0.45, 0.405, 0.5, 0.54", "0.5, 0.45, 0.54, 0.405", "0.405, 0.5, 0.45, 0.54"], "a": 0, "p": "Compare place by place."}, {"lv": 3, "q": "Ali ran 1.25 km on Monday and 0.8 km more on Tuesday than on Monday. How far did he run in total?", "o": ["3.3 km", "2.05 km", "2.25 km", "3.05 km"], "a": 0, "p": "Tuesday 2.05 km; total 1.25 + 2.05 = 3.3 km."}]}], "5": [{"id": "sgp-math-k5-0", "name": "Fraction word problems", "desc": "Bar model method", "idx": 0, "soal": [{"lv": 1, "q": "What is 2/5 of 40?", "o": ["16", "8", "20", "10"], "a": 0, "p": "40 ÷ 5 × 2."}, {"lv": 1, "q": "Ann has 30 sweets. She eats 1/3 of them. How many does she eat?", "o": ["10", "20", "3", "15"], "a": 0, "p": "30 ÷ 3."}, {"lv": 1, "q": "3/4 of a number is 12. What is the number?", "o": ["16", "9", "4", "36"], "a": 0, "p": "1/4 = 4, so the whole is 16."}, {"lv": 1, "q": "What is 1/2 of 3/4?", "o": ["3/8", "3/2", "1/4", "2/3"], "a": 0, "p": "1/2 × 3/4."}, {"lv": 2, "q": "Ben spent 2/5 of his money and had $36 left. How much did he have at first?", "o": ["$60", "$90", "$54", "$72"], "a": 0, "p": "3/5 = $36 → 1/5 = $12 → 5/5 = $60."}, {"lv": 2, "q": "A tank is 3/8 full. 15 litres more fill it to 3/4. What is the capacity of the tank?", "o": ["40 L", "30 L", "45 L", "60 L"], "a": 0, "p": "3/4 − 3/8 = 3/8 = 15 L → 1/8 = 5 L → 40 L."}, {"lv": 2, "q": "In a class, 3/7 of the pupils are boys. There are 12 boys. How many girls are there?", "o": ["16", "28", "9", "21"], "a": 0, "p": "1/7 = 4; girls = 4/7 = 16."}, {"lv": 2, "q": "Mrs Lee used 2/3 of a 1.5 kg bag of flour. How much flour did she use?", "o": ["1 kg", "0.5 kg", "0.75 kg", "1.25 kg"], "a": 0, "p": "1.5 × 2/3."}, {"lv": 3, "q": "Sam spent 1/4 of his money on a book and 1/3 of the remainder on a pen. He had $30 left. How much did he have at first?", "o": ["$60", "$90", "$48", "$120"], "a": 0, "p": "After the book: 3/4 left; pen = 1/4 of the total; left = 1/2 = $30 → $60."}, {"lv": 3, "q": "A rope is cut so that piece A is 2/5 of the rope. Piece B is 6 m longer than A. Together they make the whole rope. How long is the rope?", "o": ["30 m", "15 m", "20 m", "24 m"], "a": 0, "p": "B = 3/5, and B − A = 1/5 = 6 m → 30 m."}, {"lv": 3, "q": "John gave 1/3 of his marbles to Ali and 1/4 to Bob. He had 50 left. How many did he have at first?", "o": ["120", "100", "150", "84"], "a": 0, "p": "Gave away 7/12, so 5/12 = 50 → 1/12 = 10 → 120."}, {"lv": 3, "q": "A jug holds 2 1/4 litres. Each cup holds 3/8 litre. How many cups can be filled?", "o": ["6", "5", "8", "4"], "a": 0, "p": "9/4 ÷ 3/8 = 9/4 × 8/3 = 6."}]}, {"id": "sgp-math-k5-1", "name": "Ratio", "desc": "Equivalent ratios and word problems", "idx": 1, "soal": [{"lv": 1, "q": "Simplify the ratio 10 : 15.", "o": ["2 : 3", "3 : 2", "1 : 5", "5 : 10"], "a": 0, "p": "Divide both by 5."}, {"lv": 1, "q": "There are 4 red and 6 blue balls. What is the ratio of red to blue?", "o": ["2 : 3", "3 : 2", "4 : 10", "6 : 4"], "a": 0, "p": "4 : 6 = 2 : 3."}, {"lv": 1, "q": "Which ratio is equivalent to 3 : 5?", "o": ["6 : 10", "5 : 3", "3 : 8", "9 : 10"], "a": 0, "p": "Multiply by 2."}, {"lv": 1, "q": "The ratio of cats to dogs is 1 : 2. There are 5 cats. How many dogs?", "o": ["10", "5", "2", "15"], "a": 0, "p": "5 × 2."}, {"lv": 2, "q": "Share $60 between Ali and Ben in the ratio 2 : 3. How much does Ben get?", "o": ["$36", "$24", "$30", "$40"], "a": 0, "p": "5 units = 60 → 1 unit = 12 → Ben 36."}, {"lv": 2, "q": "The ratio of boys to girls is 3 : 4. There are 28 pupils. How many girls?", "o": ["16", "12", "21", "7"], "a": 0, "p": "7 units = 28 → 1 unit = 4 → 16."}, {"lv": 2, "q": "The ratio A : B = 2 : 5 and B : C = 5 : 3. What is A : B : C?", "o": ["2 : 5 : 3", "2 : 3 : 5", "3 : 5 : 2", "5 : 2 : 3"], "a": 0, "p": "B is already 5 in both."}, {"lv": 2, "q": "The ratio of John's money to Mary's is 5 : 2. John has $15 more than Mary. How much does Mary have?", "o": ["$10", "$25", "$15", "$6"], "a": 0, "p": "3 units = 15 → 1 unit = 5 → Mary 10."}, {"lv": 3, "q": "The ratio of red to green beads is 3 : 5. After 12 red beads are added, the ratio becomes 1 : 1. How many green beads are there?", "o": ["30", "18", "12", "20"], "a": 0, "p": "5u − 3u = 12 → u = 6 → green = 30."}, {"lv": 3, "q": "A : B = 3 : 4. B : C = 2 : 5. Find A : C.", "o": ["3 : 10", "3 : 5", "6 : 5", "3 : 8"], "a": 0, "p": "B : C = 4 : 10, so A : B : C = 3 : 4 : 10."}, {"lv": 3, "q": "Tom and Sue had stickers in the ratio 4 : 1. Tom gave Sue 30 stickers and they then had equal numbers. How many did Tom have at first?", "o": ["80", "60", "40", "100"], "a": 0, "p": "The difference 3u = 60 → u = 20 → Tom had 80."}, {"lv": 3, "q": "Orange juice and water are mixed in the ratio 2 : 7. How much juice is in 4.5 litres of the drink?", "o": ["1 L", "0.5 L", "2 L", "3.5 L"], "a": 0, "p": "9 units = 4.5 L → 1 unit = 0.5 L → juice 1 L."}]}, {"id": "sgp-math-k5-2", "name": "Percentage", "desc": "Discount, GST, percentage of a quantity", "idx": 2, "soal": [{"lv": 1, "q": "What is 25% of 80?", "o": ["20", "25", "40", "8"], "a": 0, "p": "1/4 of 80."}, {"lv": 1, "q": "Write 3/5 as a percentage.", "o": ["60%", "35%", "30%", "53%"], "a": 0, "p": "3/5 = 60/100."}, {"lv": 1, "q": "What is 10% of $45?", "o": ["$4.50", "$45", "$0.45", "$10"], "a": 0, "p": "Divide by 10."}, {"lv": 1, "q": "Write 0.07 as a percentage.", "o": ["7%", "70%", "0.7%", "0.07%"], "a": 0, "p": "Multiply by 100."}, {"lv": 2, "q": "A shirt costs $40 with a 15% discount. What is the discount?", "o": ["$6", "$15", "$34", "$4"], "a": 0, "p": "15% of 40."}, {"lv": 2, "q": "A meal costs $50 before GST of 9%. What is the GST amount?", "o": ["$4.50", "$9", "$45.50", "$54.50"], "a": 0, "p": "9% of 50."}, {"lv": 2, "q": "Ali scored 34 out of 40. What is his percentage?", "o": ["85%", "34%", "80%", "75%"], "a": 0, "p": "34/40 = 85/100."}, {"lv": 2, "q": "In a class of 40, 30% wear spectacles. How many do NOT wear spectacles?", "o": ["28", "12", "30", "10"], "a": 0, "p": "70% of 40."}, {"lv": 3, "q": "A bag costs $80. It is sold at 20% off, then GST of 9% is added. What is the final price?", "o": ["$69.76", "$64.00", "$71.20", "$72.00"], "a": 0, "p": "80 × 0.8 = 64; 64 × 1.09 = 69.76."}, {"lv": 3, "q": "After a 25% discount, a watch costs $120. What was the original price?", "o": ["$160", "$150", "$145", "$96"], "a": 0, "p": "75% = 120 → 100% = 160."}, {"lv": 3, "q": "The number of members increased from 250 to 300. What is the percentage increase?", "o": ["20%", "50%", "16.7%", "25%"], "a": 0, "p": "50/250 = 20%."}, {"lv": 3, "q": "40% of the pupils are girls. There are 36 more boys than girls. How many pupils are there?", "o": ["180", "90", "120", "144"], "a": 0, "p": "Boys 60%, so the difference is 20% = 36 → 100% = 180."}]}], "6": [{"id": "sgp-math-k6-0", "name": "Algebra", "desc": "Simple algebraic expressions", "idx": 0, "soal": [{"lv": 1, "q": "Simplify 3a + 4a.", "o": ["7a", "12a", "7a²", "34a"], "a": 0, "p": "Add like terms."}, {"lv": 1, "q": "Find the value of 5n when n = 3.", "o": ["15", "8", "53", "2"], "a": 0, "p": "5 × 3."}, {"lv": 1, "q": "Simplify 6x − 2x.", "o": ["4x", "8x", "4", "3x"], "a": 0, "p": "Subtract like terms."}, {"lv": 1, "q": "Write an expression for 'p more than 9'.", "o": ["9 + p", "9p", "p − 9", "9 − p"], "a": 0, "p": "Add p to 9."}, {"lv": 2, "q": "Simplify 4y + 7 − y + 2.", "o": ["3y + 9", "5y + 9", "3y + 5", "4y + 9"], "a": 0, "p": "4y − y = 3y; 7 + 2 = 9."}, {"lv": 2, "q": "Find the value of 2k + 5 when k = 6.", "o": ["17", "13", "26", "11"], "a": 0, "p": "12 + 5."}, {"lv": 2, "q": "A pen costs $m and a book costs $3 more. What is the total cost of 1 pen and 1 book?", "o": ["$(2m + 3)", "$(m + 3)", "$3m", "$(2m − 3)"], "a": 0, "p": "m + (m + 3)."}, {"lv": 2, "q": "Simplify (12w) ÷ 4.", "o": ["3w", "8w", "48w", "w/3"], "a": 0, "p": "12 ÷ 4 = 3."}, {"lv": 3, "q": "Find the value of (3b + 4)/2 when b = 6.", "o": ["11", "22", "13", "9"], "a": 0, "p": "(18 + 4)/2."}, {"lv": 3, "q": "Ali is x years old. His father is 4 times as old. In 5 years, what is the sum of their ages?", "o": ["5x + 10", "5x + 5", "4x + 10", "5x"], "a": 0, "p": "(x + 5) + (4x + 5)."}, {"lv": 3, "q": "A rectangle is (2y) cm long and y cm wide. What is its perimeter?", "o": ["6y cm", "3y cm", "2y² cm", "4y cm"], "a": 0, "p": "2(2y + y)."}, {"lv": 3, "q": "Simplify 5(a + 2) − 3a.", "o": ["2a + 10", "2a + 2", "8a + 10", "2a + 7"], "a": 0, "p": "5a + 10 − 3a."}]}, {"id": "sgp-math-k6-1", "name": "Speed", "desc": "Distance, time, average speed", "idx": 1, "soal": [{"lv": 1, "q": "Speed = ?", "o": ["distance ÷ time", "distance × time", "time ÷ distance", "distance + time"], "a": 0, "p": "The formula."}, {"lv": 1, "q": "A car travels 120 km in 2 h. What is its speed?", "o": ["60 km/h", "240 km/h", "122 km/h", "30 km/h"], "a": 0, "p": "120 ÷ 2."}, {"lv": 1, "q": "How far does a cyclist go in 3 h at 12 km/h?", "o": ["36 km", "4 km", "15 km", "9 km"], "a": 0, "p": "12 × 3."}, {"lv": 1, "q": "How long does it take to walk 10 km at 5 km/h?", "o": ["2 h", "50 h", "15 h", "0.5 h"], "a": 0, "p": "10 ÷ 5."}, {"lv": 2, "q": "A bus travels 45 km in 45 min. What is its speed in km/h?", "o": ["60 km/h", "45 km/h", "1 km/h", "75 km/h"], "a": 0, "p": "45 min = 0.75 h; 45 ÷ 0.75."}, {"lv": 2, "q": "Convert 72 km/h to m/s.", "o": ["20 m/s", "72 m/s", "7.2 m/s", "200 m/s"], "a": 0, "p": "72 000 ÷ 3600."}, {"lv": 2, "q": "A runner runs 400 m in 80 s. What is her speed in m/s?", "o": ["5", "320", "0.2", "4"], "a": 0, "p": "400 ÷ 80."}, {"lv": 2, "q": "A train leaves at 9.15 a.m. and arrives at 11.45 a.m. It travels 200 km. What is its average speed?", "o": ["80 km/h", "100 km/h", "66.7 km/h", "75 km/h"], "a": 0, "p": "2.5 h; 200 ÷ 2.5."}, {"lv": 3, "q": "Tom drove 90 km at 60 km/h, then 60 km at 40 km/h. What was his average speed for the whole trip?", "o": ["50 km/h", "48 km/h", "52 km/h", "45 km/h"], "a": 0, "p": "Time = 1.5 h + 1.5 h = 3 h; 150 ÷ 3."}, {"lv": 3, "q": "Two cars start at the same place and drive in opposite directions at 50 km/h and 70 km/h. How far apart are they after 2 h?", "o": ["240 km", "40 km", "120 km", "140 km"], "a": 0, "p": "(50 + 70) × 2."}, {"lv": 3, "q": "A cyclist rides at 15 km/h. How many minutes does he take to ride 5 km?", "o": ["20 min", "3 min", "33 min", "75 min"], "a": 0, "p": "5/15 h = 1/3 h = 20 min."}, {"lv": 3, "q": "Car A leaves at 8 a.m. at 60 km/h. Car B leaves the same place at 9 a.m. at 80 km/h on the same road. At what time does B catch up with A?", "o": ["12 p.m.", "11 a.m.", "1 p.m.", "10 a.m."], "a": 0, "p": "A is 60 km ahead; B gains 20 km/h → 3 h after 9 a.m."}]}, {"id": "sgp-math-k6-2", "name": "Circles", "desc": "Area and circumference", "idx": 2, "soal": [{"lv": 1, "q": "The radius is ___ the diameter.", "o": ["half", "double", "equal to", "a quarter of"], "a": 0, "p": "d = 2r."}, {"lv": 1, "q": "Circumference = ?", "o": ["π × diameter", "π × r²", "2 × r", "r × d"], "a": 0, "p": "C = πd."}, {"lv": 1, "q": "Area of a circle = ?", "o": ["π × r²", "π × d", "2πr", "r²"], "a": 0, "p": "A = πr²."}, {"lv": 1, "q": "A circle has a diameter of 10 cm. What is its radius?", "o": ["5 cm", "20 cm", "10 cm", "3.14 cm"], "a": 0, "p": "Half of 10."}, {"lv": 2, "q": "Find the circumference of a circle with diameter 14 cm. (π = 22/7)", "o": ["44 cm", "154 cm", "22 cm", "88 cm"], "a": 0, "p": "22/7 × 14."}, {"lv": 2, "q": "Find the area of a circle with radius 7 cm. (π = 22/7)", "o": ["154 cm²", "44 cm²", "49 cm²", "308 cm²"], "a": 0, "p": "22/7 × 49."}, {"lv": 2, "q": "Find the area of a circle with radius 10 cm. (π = 3.14)", "o": ["314 cm²", "31.4 cm²", "62.8 cm²", "100 cm²"], "a": 0, "p": "3.14 × 100."}, {"lv": 2, "q": "Find the perimeter of a semicircle with diameter 14 cm. (π = 22/7)", "o": ["36 cm", "22 cm", "44 cm", "58 cm"], "a": 0, "p": "Half the circumference (22) + the diameter (14)."}, {"lv": 3, "q": "A quarter circle has radius 14 cm. Find its area. (π = 22/7)", "o": ["154 cm²", "616 cm²", "308 cm²", "77 cm²"], "a": 0, "p": "1/4 × 22/7 × 196."}, {"lv": 3, "q": "A circular garden has a circumference of 88 m. What is its radius? (π = 22/7)", "o": ["14 m", "28 m", "7 m", "44 m"], "a": 0, "p": "d = 88 ÷ 22/7 = 28; r = 14."}, {"lv": 3, "q": "A square of side 14 cm has the largest possible circle cut out of it. What area is left? (π = 22/7)", "o": ["42 cm²", "154 cm²", "196 cm²", "52 cm²"], "a": 0, "p": "196 − 154."}, {"lv": 3, "q": "A wheel of diameter 70 cm rolls 100 complete turns. How far does it travel? (π = 22/7)", "o": ["220 m", "22 m", "2200 m", "154 m"], "a": 0, "p": "C = 220 cm; × 100 = 22 000 cm = 220 m."}]}], "7": [{"id": "sgp-math-k7-0", "name": "Integers and real numbers", "desc": "Negative numbers, primes, HCF and LCM", "idx": 0, "soal": [{"lv": 1, "q": "Which is a prime number?", "o": ["13", "15", "21", "27"], "a": 0, "p": "13 has only the factors 1 and 13."}, {"lv": 1, "q": "What is −8 + 3?", "o": ["−5", "5", "−11", "11"], "a": 0, "p": "Move 3 to the right from −8."}, {"lv": 1, "q": "Which is the smallest?", "o": ["−7", "−2", "0", "3"], "a": 0, "p": "Furthest left on the number line."}, {"lv": 1, "q": "Is √2 rational or irrational?", "o": ["irrational", "rational", "an integer", "a whole number"], "a": 0, "p": "It cannot be written as a fraction."}, {"lv": 2, "q": "Express 72 as a product of prime factors.", "o": ["2³ × 3²", "2² × 3³", "8 × 9", "2 × 36"], "a": 0, "p": "72 = 8 × 9 = 2³ × 3²."}, {"lv": 2, "q": "What is the HCF of 36 and 60?", "o": ["12", "6", "180", "4"], "a": 0, "p": "36 = 2² × 3², 60 = 2² × 3 × 5 → 2² × 3."}, {"lv": 2, "q": "What is the LCM of 12 and 18?", "o": ["36", "6", "216", "72"], "a": 0, "p": "2² × 3²."}, {"lv": 2, "q": "(−4) × (−6) − 10 = ?", "o": ["14", "−34", "34", "−14"], "a": 0, "p": "24 − 10."}, {"lv": 3, "q": "Buses A and B leave a terminal every 12 min and every 15 min. Both leave at 7.00 a.m. When do they next leave together?", "o": ["8.00 a.m.", "7.30 a.m.", "7.27 a.m.", "10.00 a.m."], "a": 0, "p": "LCM = 60 min."}, {"lv": 3, "q": "The temperature at the top of a mountain is −12 °C and at the foot it is 15 °C. What is the difference?", "o": ["27 °C", "3 °C", "−3 °C", "−27 °C"], "a": 0, "p": "15 − (−12)."}, {"lv": 3, "q": "Which is the smallest number divisible by 2, 3, 4, 5 and 6?", "o": ["60", "120", "30", "720"], "a": 0, "p": "LCM = 60."}, {"lv": 3, "q": "Find the largest square tile that can exactly cover a 240 cm × 180 cm floor.", "o": ["60 cm", "30 cm", "20 cm", "120 cm"], "a": 0, "p": "HCF of 240 and 180."}]}, {"id": "sgp-math-k7-1", "name": "Algebraic expressions and linear equations", "desc": "Simplifying and solving", "idx": 1, "soal": [{"lv": 1, "q": "Simplify 2x + 3x − x.", "o": ["4x", "6x", "5x", "4"], "a": 0, "p": "Collect like terms."}, {"lv": 1, "q": "Solve x + 9 = 4.", "o": ["−5", "5", "13", "−13"], "a": 0, "p": "4 − 9."}, {"lv": 1, "q": "Expand 5(x − 2).", "o": ["5x − 10", "5x − 2", "x − 10", "5x + 10"], "a": 0, "p": "Distribute."}, {"lv": 1, "q": "Solve 7x = 42.", "o": ["6", "35", "49", "294"], "a": 0, "p": "42 ÷ 7."}, {"lv": 2, "q": "Simplify 3(2a − 1) − 2(a + 4).", "o": ["4a − 11", "4a + 5", "8a − 11", "4a − 7"], "a": 0, "p": "6a − 3 − 2a − 8."}, {"lv": 2, "q": "Solve 3x − 5 = 2x + 4.", "o": ["9", "−1", "1", "−9"], "a": 0, "p": "x = 9."}, {"lv": 2, "q": "Solve x/3 − 2 = 4.", "o": ["18", "6", "2", "−6"], "a": 0, "p": "x/3 = 6."}, {"lv": 2, "q": "Factorise 12y − 18.", "o": ["6(2y − 3)", "3(4y − 18)", "2(6y − 18)", "6(2y + 3)"], "a": 0, "p": "The HCF is 6."}, {"lv": 3, "q": "Solve (2x + 1)/3 = (x − 1)/2.", "o": ["−5", "5", "1", "−1"], "a": 0, "p": "4x + 2 = 3x − 3 → x = −5."}, {"lv": 3, "q": "The sum of three consecutive integers is 72. What is the largest?", "o": ["25", "24", "23", "26"], "a": 0, "p": "3n + 3 = 72 → n = 23; largest = 25."}, {"lv": 3, "q": "A father is 3 times as old as his son. In 12 years he will be twice as old. How old is the son now?", "o": ["12", "24", "36", "6"], "a": 0, "p": "3s + 12 = 2(s + 12) → s = 12."}, {"lv": 3, "q": "Solve 0.2(x − 5) = 0.5x + 1.", "o": ["−20/3", "20/3", "−2", "6"], "a": 0, "p": "0.2x − 1 = 0.5x + 1 → −0.3x = 2 → x = −20/3."}]}, {"id": "sgp-math-k7-2", "name": "Percentage and ratio problems", "desc": "Rate, ratio, percentage change", "idx": 2, "soal": [{"lv": 1, "q": "Express 0.45 as a percentage.", "o": ["45%", "4.5%", "0.45%", "450%"], "a": 0, "p": "× 100."}, {"lv": 1, "q": "What is 12% of 250?", "o": ["30", "12", "25", "3"], "a": 0, "p": "0.12 × 250."}, {"lv": 1, "q": "A car uses 8 litres of petrol per 100 km. This is an example of a ...", "o": ["rate", "ratio of like quantities only", "percentage", "fraction only"], "a": 0, "p": "A rate compares different units."}, {"lv": 1, "q": "Simplify 0.6 : 1.5.", "o": ["2 : 5", "6 : 5", "3 : 5", "5 : 2"], "a": 0, "p": "6 : 15 = 2 : 5."}, {"lv": 2, "q": "A price increases from $80 to $92. What is the percentage increase?", "o": ["15%", "12%", "13%", "92%"], "a": 0, "p": "12/80."}, {"lv": 2, "q": "Increase $250 by 8%.", "o": ["$270", "$258", "$200", "$268"], "a": 0, "p": "250 × 1.08."}, {"lv": 2, "q": "A typist types 450 words in 9 minutes. What is the rate?", "o": ["50 words/min", "40 words/min", "4050 words/min", "9 words/min"], "a": 0, "p": "450 ÷ 9."}, {"lv": 2, "q": "Divide $120 in the ratio 3 : 5.", "o": ["$45 and $75", "$40 and $80", "$36 and $84", "$60 and $60"], "a": 0, "p": "8 parts → $15 each."}, {"lv": 3, "q": "After a 20% increase, a salary is $3000. What was the original salary?", "o": ["$2500", "$2400", "$3600", "$2800"], "a": 0, "p": "1.2x = 3000."}, {"lv": 3, "q": "A shirt's price is reduced by 10%, then the new price is reduced by a further 10%. What is the overall percentage reduction?", "o": ["19%", "20%", "10%", "21%"], "a": 0, "p": "0.9 × 0.9 = 0.81."}, {"lv": 3, "q": "If 5 machines make 200 items in 4 hours, how many items do 8 machines make in 3 hours (same rate)?", "o": ["240", "320", "160", "200"], "a": 0, "p": "Each machine makes 10 items per hour; 8 × 3 × 10."}, {"lv": 3, "q": "x : y = 3 : 4 and y : z = 6 : 5. Find x : z.", "o": ["9 : 10", "3 : 5", "4 : 5", "1 : 2"], "a": 0, "p": "x : y : z = 9 : 12 : 10."}]}], "8": [{"id": "sgp-math-k8-0", "name": "Expansion and factorisation", "desc": "Algebraic identities", "idx": 0, "soal": [{"lv": 1, "q": "Expand (x + 4)(x + 1).", "o": ["x² + 5x + 4", "x² + 4x + 1", "x² + 5", "2x + 5"], "a": 0, "p": "FOIL."}, {"lv": 1, "q": "Factorise 3x + 12.", "o": ["3(x + 4)", "3(x + 12)", "x(3 + 12)", "12(x + 3)"], "a": 0, "p": "The common factor is 3."}, {"lv": 1, "q": "Expand (a + b)².", "o": ["a² + 2ab + b²", "a² + b²", "a² + ab + b²", "2a + 2b"], "a": 0, "p": "Identity."}, {"lv": 1, "q": "Factorise x² − 16.", "o": ["(x − 4)(x + 4)", "(x − 4)²", "(x − 8)(x + 2)", "x(x − 16)"], "a": 0, "p": "Difference of squares."}, {"lv": 2, "q": "Expand (2x − 3)(x + 5).", "o": ["2x² + 7x − 15", "2x² − 7x − 15", "2x² + 13x − 15", "2x² + 7x + 15"], "a": 0, "p": "2x² + 10x − 3x − 15."}, {"lv": 2, "q": "Factorise x² − 8x + 15.", "o": ["(x − 3)(x − 5)", "(x + 3)(x + 5)", "(x − 15)(x + 1)", "(x − 3)(x + 5)"], "a": 0, "p": "−3 × −5 = 15 and −3 + −5 = −8."}, {"lv": 2, "q": "Expand (x − 6)².", "o": ["x² − 12x + 36", "x² − 36", "x² + 36", "x² − 6x + 36"], "a": 0, "p": "Identity."}, {"lv": 2, "q": "Factorise 4a² − 9b².", "o": ["(2a − 3b)(2a + 3b)", "(4a − 9b)(a + b)", "(2a − 3b)²", "(2a + 3b)²"], "a": 0, "p": "Difference of squares."}, {"lv": 3, "q": "Factorise 6x² + x − 2.", "o": ["(2x − 1)(3x + 2)", "(2x + 1)(3x − 2)", "(6x − 1)(x + 2)", "(3x − 1)(2x + 2)"], "a": 0, "p": "6x² + 4x − 3x − 2."}, {"lv": 3, "q": "Use an algebraic identity to evaluate 102².", "o": ["10 404", "10 204", "10 004", "10 400"], "a": 0, "p": "(100 + 2)² = 10 000 + 400 + 4."}, {"lv": 3, "q": "Use an identity to evaluate 47 × 53.", "o": ["2491", "2500", "2509", "2401"], "a": 0, "p": "(50 − 3)(50 + 3) = 2500 − 9."}, {"lv": 3, "q": "Factorise completely 2x³ − 18x.", "o": ["2x(x − 3)(x + 3)", "2x(x² − 9)", "2(x³ − 9x)", "x(2x − 6)(x + 3)"], "a": 0, "p": "Take out 2x, then use the difference of squares."}]}, {"id": "sgp-math-k8-1", "name": "Simultaneous equations", "desc": "Elimination and substitution", "idx": 1, "soal": [{"lv": 1, "q": "Solve: x + y = 9, x − y = 1.", "o": ["x = 5, y = 4", "x = 4, y = 5", "x = 9, y = 0", "x = 6, y = 3"], "a": 0, "p": "Add: 2x = 10."}, {"lv": 1, "q": "Solve: y = 2 and 3x + y = 11.", "o": ["x = 3", "x = 9", "x = 13/3", "x = 2"], "a": 0, "p": "3x = 9."}, {"lv": 1, "q": "Which method replaces one variable with an expression?", "o": ["substitution", "elimination", "factorisation", "expansion"], "a": 0, "p": "Substitute."}, {"lv": 1, "q": "Solve: x = 2y and x + y = 12.", "o": ["x = 8, y = 4", "x = 4, y = 8", "x = 6, y = 6", "x = 10, y = 2"], "a": 0, "p": "3y = 12."}, {"lv": 2, "q": "Solve: 2x + 3y = 12, x − y = 1.", "o": ["x = 3, y = 2", "x = 2, y = 3", "x = 4, y = 3", "x = 1, y = 0"], "a": 0, "p": "x = y + 1 → 5y + 2 = 12 → y = 2."}, {"lv": 2, "q": "Solve: 4x − y = 7, 2x + y = 5.", "o": ["x = 2, y = 1", "x = 1, y = 2", "x = 3, y = 5", "x = 0, y = 5"], "a": 0, "p": "Add: 6x = 12."}, {"lv": 2, "q": "The sum of two numbers is 30 and their difference is 8. The larger number is ...", "o": ["19", "11", "22", "15"], "a": 0, "p": "2x = 38."}, {"lv": 2, "q": "Solve: 3x + 2y = 7, 3x − y = 1.", "o": ["x = 1, y = 2", "x = 2, y = 1", "x = 3, y = −1", "x = −1, y = 5"], "a": 0, "p": "Subtract: 3y = 6 → y = 2."}, {"lv": 3, "q": "2 pens and 3 books cost $27. 4 pens and 1 book cost $19. Find the price of a book.", "o": ["$7", "$3", "$5", "$4"], "a": 0, "p": "From the second: b = 19 − 4p; 2p + 57 − 12p = 27 → p = 3; b = 7."}, {"lv": 3, "q": "Solve: 5x + 3y = 21, 2x − 5y = −4.", "o": ["x = 3, y = 2", "x = 2, y = 3", "x = 1, y = 5", "x = 4, y = 1/3"], "a": 0, "p": "Check: 15 + 6 = 21; 6 − 10 = −4."}, {"lv": 3, "q": "A farm has hens and goats with 30 heads and 74 legs. How many goats are there?", "o": ["7", "23", "14", "10"], "a": 0, "p": "h + g = 30; 2h + 4g = 74 → 2g = 14."}, {"lv": 3, "q": "The line y = mx + c passes through (1, 5) and (3, 11). Find m and c.", "o": ["m = 3, c = 2", "m = 2, c = 3", "m = 6, c = −1", "m = 3, c = 5"], "a": 0, "p": "m = 6/2 = 3; 5 = 3 + c."}]}, {"id": "sgp-math-k8-2", "name": "Probability", "desc": "Simple and combined events", "idx": 2, "soal": [{"lv": 1, "q": "A fair die is rolled. What is P(3)?", "o": ["1/6", "1/3", "1/2", "3/6"], "a": 0, "p": "1 outcome out of 6."}, {"lv": 1, "q": "The probability of an impossible event is ...", "o": ["0", "1", "0.5", "−1"], "a": 0, "p": "It never happens."}, {"lv": 1, "q": "P(event) + P(not event) = ?", "o": ["1", "0", "0.5", "2"], "a": 0, "p": "Complement rule."}, {"lv": 1, "q": "A bag has 5 red and 5 blue balls. What is P(red)?", "o": ["1/2", "1/5", "5/5", "1/10"], "a": 0, "p": "5/10."}, {"lv": 2, "q": "A letter is chosen at random from 'SINGAPORE'. What is P(vowel)?", "o": ["4/9", "5/9", "3/9", "1/2"], "a": 0, "p": "I, A, O, E: 4 vowels out of 9 letters."}, {"lv": 2, "q": "Two coins are tossed. What is P(at least one head)?", "o": ["3/4", "1/2", "1/4", "1"], "a": 0, "p": "1 − P(TT)."}, {"lv": 2, "q": "A card is drawn from a standard deck of 52. What is P(heart)?", "o": ["1/4", "1/13", "1/2", "13/4"], "a": 0, "p": "13/52."}, {"lv": 2, "q": "The probability that it rains tomorrow is 0.35. What is the probability that it does not rain?", "o": ["0.65", "0.35", "1.35", "0.5"], "a": 0, "p": "1 − 0.35."}, {"lv": 3, "q": "Two dice are rolled. What is P(sum = 8)?", "o": ["5/36", "1/6", "1/9", "8/36"], "a": 0, "p": "(2,6), (3,5), (4,4), (5,3), (6,2)."}, {"lv": 3, "q": "A box has 3 red and 2 green balls. Two are drawn without replacement. What is P(both green)?", "o": ["1/10", "4/25", "2/5", "1/5"], "a": 0, "p": "2/5 × 1/4."}, {"lv": 3, "q": "A spinner lands on red with probability 0.3. It is spun twice. What is P(red both times)?", "o": ["0.09", "0.6", "0.3", "0.9"], "a": 0, "p": "0.3 × 0.3."}, {"lv": 3, "q": "A bag has x red and 6 blue balls. P(red) = 1/3. Find x.", "o": ["3", "2", "6", "9"], "a": 0, "p": "x/(x + 6) = 1/3 → 3x = x + 6 → x = 3."}]}], "9": [{"id": "sgp-math-k9-0", "name": "Quadratic equations", "desc": "Factorisation and formula", "idx": 0, "soal": [{"lv": 1, "q": "Solve x² − 9 = 0.", "o": ["x = 3 or x = −3", "x = 9", "x = 3 only", "x = 81"], "a": 0, "p": "x² = 9."}, {"lv": 1, "q": "Solve (x + 5)(x − 1) = 0.", "o": ["x = −5 or x = 1", "x = 5 or x = −1", "x = 5 or x = 1", "x = −5 only"], "a": 0, "p": "Zero product."}, {"lv": 1, "q": "Solve x² = 4x.", "o": ["x = 0 or x = 4", "x = 4 only", "x = 2", "x = −4"], "a": 0, "p": "x(x − 4) = 0."}, {"lv": 1, "q": "Which is a quadratic equation?", "o": ["x² + 3x − 4 = 0", "3x + 4 = 0", "x³ = 8", "1/x = 2"], "a": 0, "p": "Highest power is 2."}, {"lv": 2, "q": "Solve x² + x − 12 = 0.", "o": ["x = 3 or x = −4", "x = −3 or x = 4", "x = 6 or x = −2", "x = 12"], "a": 0, "p": "(x + 4)(x − 3) = 0."}, {"lv": 2, "q": "Solve 2x² − 8 = 0.", "o": ["x = ±2", "x = ±4", "x = 4", "x = 2 only"], "a": 0, "p": "x² = 4."}, {"lv": 2, "q": "Solve x² − 7x + 10 = 0.", "o": ["x = 2 or x = 5", "x = −2 or x = −5", "x = 10", "x = 7"], "a": 0, "p": "(x − 2)(x − 5)."}, {"lv": 2, "q": "Using the formula, how many real roots does x² + 2x + 5 = 0 have?", "o": ["none", "one", "two", "three"], "a": 0, "p": "b² − 4ac = 4 − 20 < 0."}, {"lv": 3, "q": "Solve 3x² − 5x − 2 = 0.", "o": ["x = 2 or x = −1/3", "x = −2 or x = 1/3", "x = 3 or x = −2", "x = 1 or x = −2/3"], "a": 0, "p": "(3x + 1)(x − 2) = 0."}, {"lv": 3, "q": "Solve x² + 4x − 7 = 0, correct to 2 d.p.", "o": ["x = 1.32 or x = −5.32", "x = 2.32 or x = −3.32", "x = 1.00 or x = −7.00", "x = 3.32 or x = −1.32"], "a": 0, "p": "x = −2 ± √11."}, {"lv": 3, "q": "The product of two consecutive positive integers is 132. Find the smaller integer.", "o": ["11", "12", "10", "13"], "a": 0, "p": "n(n + 1) = 132 → n = 11."}, {"lv": 3, "q": "A rectangle's length is 3 cm more than its width, and its area is 54 cm². Find the width.", "o": ["6 cm", "9 cm", "3 cm", "18 cm"], "a": 0, "p": "w² + 3w − 54 = 0 → (w + 9)(w − 6) = 0."}]}, {"id": "sgp-math-k9-1", "name": "Indices and standard form", "desc": "Laws of indices", "idx": 1, "soal": [{"lv": 1, "q": "Simplify a⁵ × a³.", "o": ["a⁸", "a¹⁵", "a²", "2a⁸"], "a": 0, "p": "Add the indices."}, {"lv": 1, "q": "Simplify b⁹ ÷ b⁴.", "o": ["b⁵", "b¹³", "b³⁶", "b²"], "a": 0, "p": "Subtract the indices."}, {"lv": 1, "q": "What is 7⁰?", "o": ["1", "0", "7", "70"], "a": 0, "p": "Zero index."}, {"lv": 1, "q": "Write 45 000 in standard form.", "o": ["4.5 × 10⁴", "45 × 10³", "4.5 × 10³", "0.45 × 10⁵"], "a": 0, "p": "1 ≤ a < 10."}, {"lv": 2, "q": "Simplify (x³)⁴.", "o": ["x¹²", "x⁷", "x⁸¹", "4x³"], "a": 0, "p": "Multiply the indices."}, {"lv": 2, "q": "Evaluate 3⁻².", "o": ["1/9", "−9", "−6", "9"], "a": 0, "p": "1/3²."}, {"lv": 2, "q": "Evaluate 27^(1/3).", "o": ["3", "9", "1/3", "81"], "a": 0, "p": "Cube root."}, {"lv": 2, "q": "Write 0.000 72 in standard form.", "o": ["7.2 × 10⁻⁴", "72 × 10⁻⁵", "7.2 × 10⁴", "0.72 × 10⁻³"], "a": 0, "p": "Move the point 4 places."}, {"lv": 3, "q": "Evaluate 8^(2/3).", "o": ["4", "16/3", "2", "64"], "a": 0, "p": "(∛8)² = 2² = 4."}, {"lv": 3, "q": "Simplify (2a²b)³ ÷ 4a³b.", "o": ["2a³b²", "2a³b³", "8a³b²", "a³b²/2"], "a": 0, "p": "8a⁶b³ ÷ 4a³b."}, {"lv": 3, "q": "Calculate (6 × 10⁵) × (4 × 10⁻²), giving the answer in standard form.", "o": ["2.4 × 10⁴", "24 × 10³", "2.4 × 10³", "10 × 10³"], "a": 0, "p": "24 × 10³ = 2.4 × 10⁴."}, {"lv": 3, "q": "Solve 2^x = 32.", "o": ["5", "16", "4", "6"], "a": 0, "p": "2⁵ = 32."}]}, {"id": "sgp-math-k9-2", "name": "Trigonometry", "desc": "Trig ratios and Pythagoras", "idx": 2, "soal": [{"lv": 1, "q": "sin θ = ?", "o": ["opposite / hypotenuse", "adjacent / hypotenuse", "opposite / adjacent", "hypotenuse / opposite"], "a": 0, "p": "SOH."}, {"lv": 1, "q": "In a right-angled triangle with legs 6 and 8, the hypotenuse is ...", "o": ["10", "14", "48", "√28"], "a": 0, "p": "Pythagoras."}, {"lv": 1, "q": "tan 45° = ?", "o": ["1", "0", "0.5", "√2"], "a": 0, "p": "Opposite = adjacent."}, {"lv": 1, "q": "cos θ = ?", "o": ["adjacent / hypotenuse", "opposite / hypotenuse", "opposite / adjacent", "hypotenuse / adjacent"], "a": 0, "p": "CAH."}, {"lv": 2, "q": "Find x if sin 30° = x/12.", "o": ["6", "12", "24", "10.4"], "a": 0, "p": "0.5 × 12."}, {"lv": 2, "q": "The hypotenuse is 13 and one side is 5. Find the other side.", "o": ["12", "8", "18", "√194"], "a": 0, "p": "169 − 25 = 144."}, {"lv": 2, "q": "tan θ = 3/4. In a right-angled triangle, what is sin θ?", "o": ["3/5", "4/5", "3/4", "5/3"], "a": 0, "p": "A 3-4-5 triangle."}, {"lv": 2, "q": "Find θ if cos θ = 0.5 (θ is acute).", "o": ["60°", "30°", "45°", "90°"], "a": 0, "p": "Standard angle."}, {"lv": 3, "q": "From the top of a 30 m building, the angle of depression to a car is 35°. How far is the car from the base? (tan 35° ≈ 0.700)", "o": ["42.9 m", "21.0 m", "36.6 m", "17.2 m"], "a": 0, "p": "d = 30 ÷ tan 35° ≈ 42.9 m."}, {"lv": 3, "q": "A 10 m ladder makes an angle of 65° with the ground. How high does it reach? (sin 65° ≈ 0.906)", "o": ["9.06 m", "4.23 m", "10.9 m", "21.4 m"], "a": 0, "p": "10 × sin 65°."}, {"lv": 3, "q": "A ship sails 20 km on a bearing of 090° then 15 km on a bearing of 180°. How far is it from its start?", "o": ["25 km", "35 km", "5 km", "√175 km"], "a": 0, "p": "√(400 + 225)."}, {"lv": 3, "q": "In triangle ABC, angle B = 90°, AB = 7 cm and angle C = 40°. Find BC. (tan 40° ≈ 0.839)", "o": ["8.34 cm", "5.87 cm", "9.14 cm", "4.50 cm"], "a": 0, "p": "tan C = AB/BC → BC = 7/0.839."}]}]}, "sci": {"10": [{"id": "sgp-sci-k10-0", "name": "Physics: Electricity", "desc": "Current, voltage, resistance, power", "idx": 0, "soal": [{"lv": 1, "q": "Current is the rate of flow of ...", "o": ["charge", "energy", "voltage", "resistance"], "a": 0, "p": "I = Q/t."}, {"lv": 1, "q": "The unit of resistance is the ...", "o": ["ohm", "volt", "ampere", "watt"], "a": 0, "p": "Ω."}, {"lv": 1, "q": "Electrical power P = ?", "o": ["V × I", "V ÷ I", "I ÷ V", "V + I"], "a": 0, "p": "Power formula."}, {"lv": 1, "q": "The unit of electrical energy used in bills is ...", "o": ["kilowatt-hour", "joule only", "volt", "ampere"], "a": 0, "p": "kWh."}, {"lv": 2, "q": "A 12 V supply drives 3 A through a resistor. What is its resistance?", "o": ["4 Ω", "36 Ω", "15 Ω", "0.25 Ω"], "a": 0, "p": "R = V/I."}, {"lv": 2, "q": "A 2000 W heater runs for 3 h. How much energy does it use?", "o": ["6 kWh", "600 kWh", "2 kWh", "666 kWh"], "a": 0, "p": "2 kW × 3 h."}, {"lv": 2, "q": "Resistors of 3 Ω and 6 Ω in parallel give a total of ...", "o": ["2 Ω", "9 Ω", "18 Ω", "4.5 Ω"], "a": 0, "p": "(3 × 6)/(3 + 6)."}, {"lv": 2, "q": "What does a fuse do?", "o": ["melts to break the circuit when the current is too large", "increases current", "stores charge", "produces light"], "a": 0, "p": "Safety."}, {"lv": 3, "q": "A 240 V kettle is rated 2400 W. What is the most suitable fuse?", "o": ["13 A", "3 A", "5 A", "1 A"], "a": 0, "p": "I = 10 A, so choose the next fuse above it."}, {"lv": 3, "q": "Electricity costs $0.30 per kWh. What is the cost of running a 1500 W air-conditioner for 8 h?", "o": ["$3.60", "$36.00", "$1.20", "$12.00"], "a": 0, "p": "1.5 × 8 = 12 kWh × $0.30."}, {"lv": 3, "q": "Why does a wire's resistance increase with length?", "o": ["Electrons collide with more atoms along a longer path.", "Longer wires are thicker.", "Voltage increases.", "Current increases."], "a": 0, "p": "R ∝ L."}, {"lv": 3, "q": "Why must the earth wire be connected to a metal-cased appliance?", "o": ["It gives fault current a low-resistance path to ground, preventing electric shock.", "It increases power.", "It saves energy.", "It is decoration."], "a": 0, "p": "Safety."}]}, {"id": "sgp-sci-k10-1", "name": "Chemistry: Acids, bases and salts", "desc": "pH, neutralisation, salt preparation", "idx": 1, "soal": [{"lv": 1, "q": "Which has pH less than 7?", "o": ["an acid", "an alkali", "pure water", "a salt solution only"], "a": 0, "p": "Acidic."}, {"lv": 1, "q": "Acids react with metals to give a salt and ...", "o": ["hydrogen", "oxygen", "carbon dioxide", "water only"], "a": 0, "p": "Fizzing shows H₂."}, {"lv": 1, "q": "Alkalis are soluble ...", "o": ["bases", "acids", "metals", "salts"], "a": 0, "p": "Definition."}, {"lv": 1, "q": "Neutralisation produces ...", "o": ["salt and water", "acid and base", "hydrogen and oxygen", "metal and gas"], "a": 0, "p": "Acid + base."}, {"lv": 2, "q": "Which indicator turns red in acid and blue in alkali?", "o": ["litmus", "methyl orange only", "phenolphthalein", "limewater"], "a": 0, "p": "Litmus paper."}, {"lv": 2, "q": "Zinc + sulfuric acid → ?", "o": ["zinc sulfate + hydrogen", "zinc oxide + water", "zinc chloride + hydrogen", "zinc + water"], "a": 0, "p": "Metal + acid."}, {"lv": 2, "q": "Which salt preparation method suits an insoluble salt such as barium sulfate?", "o": ["precipitation", "titration", "excess metal + acid", "evaporation only"], "a": 0, "p": "Mix two soluble salts."}, {"lv": 2, "q": "Calcium carbonate + hydrochloric acid → calcium chloride + water + ?", "o": ["carbon dioxide", "hydrogen", "oxygen", "chlorine"], "a": 0, "p": "Carbonate + acid."}, {"lv": 3, "q": "Why is titration used to prepare sodium chloride from HCl and NaOH?", "o": ["Both are soluble, so exact volumes are needed with no excess.", "One is insoluble.", "It makes gas.", "It is faster."], "a": 0, "p": "Prevents contamination."}, {"lv": 3, "q": "A solution has pH 1. Which is true?", "o": ["It is a strong acid with a high H⁺ concentration.", "It is a weak alkali.", "It is neutral.", "It has no H⁺ ions."], "a": 0, "p": "Low pH."}, {"lv": 3, "q": "Farmers add lime (calcium hydroxide) to soil to ...", "o": ["neutralise acidity", "make the soil more acidic", "kill plants", "add nitrogen only"], "a": 0, "p": "Raises pH."}, {"lv": 3, "q": "Ammonium salts warmed with an alkali release ...", "o": ["ammonia gas", "hydrogen", "oxygen", "carbon dioxide"], "a": 0, "p": "A test for NH₄⁺."}]}, {"id": "sgp-sci-k10-2", "name": "Biology: Reproduction", "desc": "Sexual and asexual reproduction", "idx": 2, "soal": [{"lv": 1, "q": "Asexual reproduction involves ...", "o": ["one parent", "two parents", "gametes", "fertilisation"], "a": 0, "p": "Offspring are identical."}, {"lv": 1, "q": "Sexual reproduction involves the fusion of ...", "o": ["gametes", "two adult cells", "two leaves", "roots"], "a": 0, "p": "Fertilisation."}, {"lv": 1, "q": "The male gamete in humans is the ...", "o": ["sperm", "egg", "ovary", "zygote"], "a": 0, "p": "Sperm."}, {"lv": 1, "q": "Fertilisation in humans usually takes place in the ...", "o": ["oviduct (fallopian tube)", "uterus", "ovary", "vagina"], "a": 0, "p": "Site of fertilisation."}, {"lv": 2, "q": "Which is an advantage of asexual reproduction?", "o": ["It is fast and needs only one parent.", "It produces variation.", "It needs a mate.", "It is slow."], "a": 0, "p": "Efficiency."}, {"lv": 2, "q": "In flowering plants, pollination is the transfer of pollen from ...", "o": ["anther to stigma", "stigma to anther", "ovary to petal", "root to leaf"], "a": 0, "p": "Definition."}, {"lv": 2, "q": "A zygote is formed by ...", "o": ["the fusion of male and female gametes", "mitosis of a sperm", "pollination only", "budding"], "a": 0, "p": "Fertilisation."}, {"lv": 2, "q": "Which is an example of asexual reproduction in plants?", "o": ["growing a plant from a stem cutting", "pollination", "seed formation by fertilisation", "cross-breeding"], "a": 0, "p": "Vegetative propagation."}, {"lv": 3, "q": "Why is variation from sexual reproduction important?", "o": ["It increases the chance that some individuals survive environmental changes.", "It makes offspring identical.", "It reduces the population.", "It is not important."], "a": 0, "p": "Adaptability."}, {"lv": 3, "q": "Insect-pollinated flowers usually have ...", "o": ["bright petals, scent and nectar", "feathery stigmas outside the flower", "small dull petals", "huge amounts of light pollen"], "a": 0, "p": "Attract insects."}, {"lv": 3, "q": "Which part of the flower develops into the fruit?", "o": ["ovary", "anther", "petal", "sepal"], "a": 0, "p": "After fertilisation."}, {"lv": 3, "q": "Why do gametes have half the number of chromosomes?", "o": ["so the zygote has the normal full number after fertilisation", "to make them smaller", "to move faster", "to avoid dividing"], "a": 0, "p": "Haploid + haploid = diploid."}]}], "11": [{"id": "sgp-sci-k11-0", "name": "H2 Physics: Forces and dynamics", "desc": "Newton's laws, momentum", "idx": 0, "soal": [{"lv": 1, "q": "Newton's second law states that F = ?", "o": ["ma", "mv", "m/a", "½mv²"], "a": 0, "p": "Or rate of change of momentum."}, {"lv": 1, "q": "Momentum is a ___ quantity.", "o": ["vector", "scalar", "dimensionless", "temperature"], "a": 0, "p": "It has direction."}, {"lv": 1, "q": "The unit of momentum is ...", "o": ["kg m s⁻¹", "N", "J", "kg m s⁻²"], "a": 0, "p": "Mass × velocity."}, {"lv": 1, "q": "Impulse equals ...", "o": ["change in momentum", "change in energy", "force × distance", "mass × acceleration"], "a": 0, "p": "FΔt = Δp."}, {"lv": 2, "q": "A 0.5 kg ball hits a wall at 6 m/s and rebounds at 4 m/s. What is the change in momentum?", "o": ["5 kg m s⁻¹", "1 kg m s⁻¹", "3 kg m s⁻¹", "2 kg m s⁻¹"], "a": 0, "p": "0.5 × (4 − (−6)) = 5."}, {"lv": 2, "q": "A 1200 kg car accelerates at 2.5 m s⁻². What resultant force is needed?", "o": ["3000 N", "480 N", "1202.5 N", "300 N"], "a": 0, "p": "F = ma."}, {"lv": 2, "q": "In a perfectly inelastic collision, ...", "o": ["momentum is conserved but kinetic energy is not", "kinetic energy is conserved", "neither is conserved", "momentum is lost"], "a": 0, "p": "The bodies stick together."}, {"lv": 2, "q": "A force of 20 N acts for 0.3 s. What is the impulse?", "o": ["6 N s", "66.7 N s", "20.3 N s", "0.015 N s"], "a": 0, "p": "F × t."}, {"lv": 3, "q": "A 3 kg trolley at 4 m/s collides with a stationary 1 kg trolley, and they move together. Find the loss in kinetic energy.", "o": ["6 J", "24 J", "18 J", "0 J"], "a": 0, "p": "v = 3 m/s; KE: 24 J → 18 J."}, {"lv": 3, "q": "A 2 kg mass rests on a slope at 30°. What is the component of its weight along the slope? (g = 9.81)", "o": ["9.81 N", "16.99 N", "19.62 N", "4.9 N"], "a": 0, "p": "mg sin 30°."}, {"lv": 3, "q": "A rocket ejects gas backwards. Why does it accelerate forward?", "o": ["By Newton's third law, the gas pushes the rocket forward with an equal and opposite force.", "Air pushes it.", "Gravity reverses.", "Mass increases."], "a": 0, "p": "Action–reaction."}, {"lv": 3, "q": "For a lift accelerating upwards at 2 m s⁻², the normal force on a 60 kg person is (g = 10) ...", "o": ["720 N", "600 N", "480 N", "120 N"], "a": 0, "p": "N = m(g + a)."}]}, {"id": "sgp-sci-k11-1", "name": "H2 Chemistry: Chemical bonding", "desc": "Ionic, covalent, metallic, shapes", "idx": 1, "soal": [{"lv": 1, "q": "Ionic bonding is the electrostatic attraction between ...", "o": ["oppositely charged ions", "shared electrons", "neutrons", "metal atoms only"], "a": 0, "p": "Lattice."}, {"lv": 1, "q": "Covalent bonds involve ...", "o": ["shared pairs of electrons", "transferred electrons", "delocalised protons", "ions only"], "a": 0, "p": "Sharing."}, {"lv": 1, "q": "Metallic bonding involves ...", "o": ["positive ions in a sea of delocalised electrons", "shared pairs only", "negative ions only", "no electrons"], "a": 0, "p": "This explains conductivity."}, {"lv": 1, "q": "The shape of a CH₄ molecule is ...", "o": ["tetrahedral", "linear", "trigonal planar", "bent"], "a": 0, "p": "Four bond pairs."}, {"lv": 2, "q": "What is the bond angle in a water molecule?", "o": ["about 104.5°", "109.5°", "120°", "180°"], "a": 0, "p": "Lone pairs compress the angle."}, {"lv": 2, "q": "The shape of CO₂ is ...", "o": ["linear", "bent", "tetrahedral", "pyramidal"], "a": 0, "p": "Two double bonds, no lone pairs on C."}, {"lv": 2, "q": "NH₃ has which shape?", "o": ["trigonal pyramidal", "trigonal planar", "tetrahedral", "linear"], "a": 0, "p": "Three bond pairs and one lone pair."}, {"lv": 2, "q": "Which molecule has hydrogen bonding between its molecules?", "o": ["H₂O", "CH₄", "CO₂", "H₂"], "a": 0, "p": "O–H bonds with lone pairs."}, {"lv": 3, "q": "Why does H₂O have a much higher boiling point than H₂S?", "o": ["Water forms hydrogen bonds between molecules.", "H₂S is ionic.", "Water is heavier.", "H₂S has hydrogen bonding."], "a": 0, "p": "Stronger intermolecular forces."}, {"lv": 3, "q": "BF₃ is trigonal planar but NH₃ is pyramidal because ...", "o": ["NH₃ has a lone pair on N; BF₃ has none on B", "B is larger", "F is more electronegative", "NH₃ is ionic"], "a": 0, "p": "VSEPR."}, {"lv": 3, "q": "Which is a polar molecule?", "o": ["HCl", "CO₂", "CH₄", "Cl₂"], "a": 0, "p": "There is an electronegativity difference and no symmetry to cancel it."}, {"lv": 3, "q": "Why do metals conduct electricity in the solid state?", "o": ["Delocalised electrons can move through the lattice.", "Ions move freely.", "Protons move.", "They contain water."], "a": 0, "p": "Mobile charge carriers."}]}, {"id": "sgp-sci-k11-2", "name": "H2 Biology: Cell structure and function", "desc": "Organelles, membranes", "idx": 2, "soal": [{"lv": 1, "q": "Which organelle is the site of aerobic respiration?", "o": ["mitochondrion", "ribosome", "Golgi body", "lysosome"], "a": 0, "p": "ATP production."}, {"lv": 1, "q": "Ribosomes are the site of ...", "o": ["protein synthesis", "lipid storage", "photosynthesis", "respiration"], "a": 0, "p": "Translation."}, {"lv": 1, "q": "Prokaryotic cells lack a ...", "o": ["membrane-bound nucleus", "cell membrane", "ribosome", "cytoplasm"], "a": 0, "p": "Bacteria."}, {"lv": 1, "q": "Lysosomes contain ...", "o": ["hydrolytic enzymes", "chlorophyll", "DNA only", "starch"], "a": 0, "p": "Digestion inside the cell."}, {"lv": 2, "q": "The Golgi apparatus mainly ...", "o": ["modifies, packages and sorts proteins", "makes ATP", "stores DNA", "carries out photosynthesis"], "a": 0, "p": "Processing and secretion."}, {"lv": 2, "q": "Rough ER differs from smooth ER because it ...", "o": ["has ribosomes attached", "makes lipids only", "has no membrane", "stores calcium only"], "a": 0, "p": "Protein synthesis."}, {"lv": 2, "q": "Which structure is found in plant cells but not animal cells?", "o": ["cell wall of cellulose", "mitochondria", "ribosomes", "nucleus"], "a": 0, "p": "Also chloroplasts and a large vacuole."}, {"lv": 2, "q": "The fluid mosaic model describes the ...", "o": ["cell surface membrane", "nucleus", "cell wall", "ribosome"], "a": 0, "p": "Phospholipids and proteins."}, {"lv": 3, "q": "Why do cells that secrete enzymes have extensive rough ER and Golgi?", "o": ["to synthesise, modify and package large amounts of protein for secretion", "to store fat", "to photosynthesise", "to divide faster"], "a": 0, "p": "Structure–function."}, {"lv": 3, "q": "Prokaryotic ribosomes are 70S while eukaryotic cytoplasmic ribosomes are ...", "o": ["80S", "70S", "60S", "100S"], "a": 0, "p": "Size difference."}, {"lv": 3, "q": "Which evidence supports the endosymbiotic theory?", "o": ["Mitochondria have their own circular DNA and 70S ribosomes.", "Mitochondria have no DNA.", "Nuclei are inside mitochondria.", "Ribosomes contain chlorophyll."], "a": 0, "p": "Bacterial features."}, {"lv": 3, "q": "Cholesterol in the membrane helps to ...", "o": ["regulate membrane fluidity", "carry oxygen", "synthesise protein", "store energy"], "a": 0, "p": "Stability."}]}], "12": [{"id": "sgp-sci-k12-0", "name": "H2 Physics: Electromagnetism", "desc": "Magnetic fields, induction", "idx": 0, "soal": [{"lv": 1, "q": "The SI unit of magnetic flux density is the ...", "o": ["tesla", "weber", "henry", "farad"], "a": 0, "p": "T."}, {"lv": 1, "q": "The force on a current-carrying wire in a magnetic field is F = ?", "o": ["BIL sin θ", "BIL cos θ", "B/IL", "IL/B"], "a": 0, "p": "Motor effect."}, {"lv": 1, "q": "Faraday's law relates the induced e.m.f. to the ...", "o": ["rate of change of magnetic flux linkage", "resistance", "current only", "mass"], "a": 0, "p": "ε = −dΦ/dt."}, {"lv": 1, "q": "Lenz's law says the induced current ...", "o": ["opposes the change that produces it", "aids the change", "is always zero", "is constant"], "a": 0, "p": "Conservation of energy."}, {"lv": 2, "q": "A 0.5 m wire carries 4 A perpendicular to a 0.2 T field. What is the force?", "o": ["0.4 N", "4 N", "0.1 N", "40 N"], "a": 0, "p": "0.2 × 4 × 0.5."}, {"lv": 2, "q": "A charge q moving at speed v perpendicular to a field B experiences force ...", "o": ["qvB", "qv/B", "qB/v", "q/vB"], "a": 0, "p": "Lorentz force."}, {"lv": 2, "q": "The magnetic flux through a coil of area 0.02 m² in a 0.5 T field (perpendicular) is ...", "o": ["0.01 Wb", "0.1 Wb", "25 Wb", "1 Wb"], "a": 0, "p": "Φ = BA."}, {"lv": 2, "q": "What is the main function of a transformer?", "o": ["to change alternating voltages", "to store charge", "to convert a.c. to d.c. alone", "to generate magnetism permanently"], "a": 0, "p": "Step up or step down."}, {"lv": 3, "q": "A 100-turn coil's flux changes from 0.03 Wb to 0 in 0.1 s. What is the induced e.m.f.?", "o": ["30 V", "3 V", "0.3 V", "300 V"], "a": 0, "p": "100 × 0.03/0.1."}, {"lv": 3, "q": "A proton enters a uniform magnetic field perpendicular to its velocity. Its path is ...", "o": ["circular", "straight", "parabolic", "spiral outward"], "a": 0, "p": "The force is always perpendicular to the velocity."}, {"lv": 3, "q": "Why are transformer cores laminated?", "o": ["to reduce eddy current losses", "to increase resistance of the coils", "to make them lighter only", "to store energy"], "a": 0, "p": "Efficiency."}, {"lv": 3, "q": "A magnet falls through a copper tube more slowly than through a plastic tube because ...", "o": ["induced eddy currents in the copper create an opposing magnetic force", "copper is magnetic", "plastic attracts the magnet", "air resistance is higher in copper"], "a": 0, "p": "Lenz's law."}]}, {"id": "sgp-sci-k12-1", "name": "H2 Chemistry: Organic reactions", "desc": "Functional groups and mechanisms", "idx": 1, "soal": [{"lv": 1, "q": "Alkanes undergo ___ with chlorine in UV light.", "o": ["free radical substitution", "electrophilic addition", "nucleophilic substitution", "condensation"], "a": 0, "p": "Mechanism."}, {"lv": 1, "q": "Alkenes typically undergo ...", "o": ["electrophilic addition", "free radical substitution", "nucleophilic addition", "elimination only"], "a": 0, "p": "The C=C reacts."}, {"lv": 1, "q": "Halogenoalkanes react with OH⁻ by ...", "o": ["nucleophilic substitution", "electrophilic addition", "free radical substitution", "oxidation"], "a": 0, "p": "SN1 / SN2."}, {"lv": 1, "q": "The functional group of a carboxylic acid is ...", "o": ["–COOH", "–OH", "–CHO", "–NH₂"], "a": 0, "p": "Carboxyl."}, {"lv": 2, "q": "Primary alcohols can be oxidised to ...", "o": ["aldehydes, then carboxylic acids", "ketones", "alkanes", "esters directly"], "a": 0, "p": "With acidified dichromate."}, {"lv": 2, "q": "Which reagent tests for an aldehyde?", "o": ["Tollens' reagent (silver mirror)", "bromine water", "limewater", "litmus"], "a": 0, "p": "Aldehydes reduce Ag⁺."}, {"lv": 2, "q": "Carboxylic acid + alcohol → ? (acid catalyst)", "o": ["ester + water", "ether", "aldehyde", "alkene"], "a": 0, "p": "Esterification."}, {"lv": 2, "q": "Which is an electrophile?", "o": ["Br⁺ (or polarised Br₂)", "OH⁻", "NH₃", "CN⁻"], "a": 0, "p": "It accepts electrons."}, {"lv": 3, "q": "Why do tertiary halogenoalkanes favour SN1?", "o": ["The tertiary carbocation intermediate is stabilised by alkyl groups.", "They have no leaving group.", "They are planar.", "They react with radicals."], "a": 0, "p": "Carbocation stability."}, {"lv": 3, "q": "Propene reacts with HBr. What is the major product?", "o": ["2-bromopropane", "1-bromopropane", "propane", "propan-1-ol"], "a": 0, "p": "Markovnikov's rule: the more stable secondary carbocation."}, {"lv": 3, "q": "Which reagent and conditions convert an alcohol to an alkene?", "o": ["excess concentrated H₂SO₄, heat", "NaOH(aq), room temperature", "UV light", "H₂/Ni"], "a": 0, "p": "Dehydration."}, {"lv": 3, "q": "Benzene undergoes substitution rather than addition because ...", "o": ["substitution preserves the stable delocalised π system", "benzene has no electrons", "addition is too fast", "benzene is saturated"], "a": 0, "p": "Aromatic stability."}]}, {"id": "sgp-sci-k12-2", "name": "H2 Biology: Genetics and inheritance", "desc": "Mendelian genetics, linkage", "idx": 2, "soal": [{"lv": 1, "q": "An allele is ...", "o": ["an alternative form of a gene", "a chromosome", "a protein", "a cell"], "a": 0, "p": "Gene variant."}, {"lv": 1, "q": "A phenotype is ...", "o": ["the observable characteristics", "the genetic code only", "the number of chromosomes", "a type of cell"], "a": 0, "p": "Expressed traits."}, {"lv": 1, "q": "Mendel's first law is the law of ...", "o": ["segregation", "independent assortment", "dominance only", "linkage"], "a": 0, "p": "Alleles separate."}, {"lv": 1, "q": "Heterozygous means ...", "o": ["two different alleles for a gene", "two identical alleles", "no alleles", "only recessive alleles"], "a": 0, "p": "For example, Aa."}, {"lv": 2, "q": "AaBb × AaBb, with independent assortment. What is the phenotypic ratio?", "o": ["9 : 3 : 3 : 1", "3 : 1", "1 : 2 : 1", "1 : 1 : 1 : 1"], "a": 0, "p": "A dihybrid cross."}, {"lv": 2, "q": "A test cross involves crossing with a ...", "o": ["homozygous recessive individual", "homozygous dominant individual", "heterozygote", "clone"], "a": 0, "p": "It reveals the genotype."}, {"lv": 2, "q": "Linked genes ...", "o": ["are on the same chromosome and tend to be inherited together", "assort independently", "are on different chromosomes", "never cross over"], "a": 0, "p": "Linkage."}, {"lv": 2, "q": "Codominance means ...", "o": ["both alleles are fully expressed in the heterozygote", "one allele masks the other", "neither is expressed", "a blending of colours"], "a": 0, "p": "For example, AB blood group."}, {"lv": 3, "q": "In a dihybrid test cross AaBb × aabb, offspring are 45% AaBb, 45% aabb, 5% Aabb, 5% aaBb. This suggests ...", "o": ["the genes are linked, with a 10% recombination frequency", "independent assortment", "codominance", "a lethal allele"], "a": 0, "p": "Recombinants are 10%."}, {"lv": 3, "q": "Red–green colour blindness is X-linked recessive. A carrier mother and a normal father have a son. What is P(son is colour blind)?", "o": ["1/2", "1/4", "0", "1"], "a": 0, "p": "The son gets X from his mother: 1/2 chance it is Xᶜ."}, {"lv": 3, "q": "A chi-squared test is used in genetics to ...", "o": ["test whether observed ratios differ significantly from expected ratios", "count chromosomes", "measure DNA length", "sequence genes"], "a": 0, "p": "Statistical test."}, {"lv": 3, "q": "Epistasis occurs when ...", "o": ["one gene affects the expression of another gene", "two alleles are codominant", "a gene is linked to sex", "a mutation is silent"], "a": 0, "p": "Gene interaction."}]}], "3": [{"id": "sgp-sci-k3-0", "name": "Diversity of living and non-living things", "desc": "Classification", "idx": 0, "soal": [{"lv": 1, "q": "Which is a living thing?", "o": ["a tree", "a rock", "a chair", "a toy car"], "a": 0, "p": "Trees grow and reproduce."}, {"lv": 1, "q": "Living things need ...", "o": ["food, water and air", "batteries", "paint", "plastic"], "a": 0, "p": "These are basic needs."}, {"lv": 1, "q": "Which is a non-living thing?", "o": ["a stone", "a cat", "a mushroom", "a fish"], "a": 0, "p": "Stones do not grow or reproduce."}, {"lv": 1, "q": "Which group does a mushroom belong to?", "o": ["fungi", "plants", "animals", "non-living things"], "a": 0, "p": "Mushrooms are fungi."}, {"lv": 2, "q": "Which characteristic is shared by ALL living things?", "o": ["they grow", "they can walk", "they have leaves", "they make sounds"], "a": 0, "p": "All living things grow."}, {"lv": 2, "q": "Bacteria are ...", "o": ["tiny living things", "non-living", "plants", "rocks"], "a": 0, "p": "They can only be seen with a microscope."}, {"lv": 2, "q": "How do fungi get their food?", "o": ["from dead or decaying matter", "by photosynthesis", "by hunting", "from sunlight"], "a": 0, "p": "Fungi cannot make their own food."}, {"lv": 2, "q": "Which animal is a mammal?", "o": ["dolphin", "shark", "turtle", "frog"], "a": 0, "p": "Dolphins feed their young with milk."}, {"lv": 3, "q": "A seed looks non-living, but it is a living thing because ...", "o": ["it can grow into a plant when conditions are right", "it is hard", "it is brown", "it is small"], "a": 0, "p": "Seeds can germinate."}, {"lv": 3, "q": "Which pair are both insects?", "o": ["butterfly and ant", "spider and ant", "snail and bee", "worm and fly"], "a": 0, "p": "Insects have 6 legs and 3 body parts."}, {"lv": 3, "q": "Which statement about plants is correct?", "o": ["Plants make their own food.", "Plants do not need water.", "Plants can move from place to place.", "Plants are non-living."], "a": 0, "p": "Through photosynthesis."}, {"lv": 3, "q": "Why is a car NOT a living thing even though it moves?", "o": ["It cannot grow or reproduce.", "It is too big.", "It has wheels.", "It is made of metal."], "a": 0, "p": "Movement alone is not enough."}]}, {"id": "sgp-sci-k3-1", "name": "Materials", "desc": "Properties and uses", "idx": 1, "soal": [{"lv": 1, "q": "Which material is transparent?", "o": ["glass", "wood", "metal", "cardboard"], "a": 0, "p": "Light passes through glass."}, {"lv": 1, "q": "Which material is best for a raincoat?", "o": ["plastic", "paper", "cotton", "wool"], "a": 0, "p": "Plastic is waterproof."}, {"lv": 1, "q": "Which material is flexible?", "o": ["rubber", "glass", "stone", "ceramic"], "a": 0, "p": "Rubber can bend."}, {"lv": 1, "q": "Which material floats on water?", "o": ["wood", "iron", "stone", "glass marble"], "a": 0, "p": "Wood is less dense than water."}, {"lv": 2, "q": "Why are cooking pots made of metal?", "o": ["Metal is a good conductor of heat.", "Metal is soft.", "Metal is transparent.", "Metal floats."], "a": 0, "p": "Heat passes through quickly."}, {"lv": 2, "q": "Why are pot handles made of plastic or wood?", "o": ["They are poor conductors of heat.", "They are heavy.", "They are shiny.", "They are magnetic."], "a": 0, "p": "They protect hands from heat."}, {"lv": 2, "q": "Which material is strong and used for building bridges?", "o": ["steel", "paper", "rubber", "cloth"], "a": 0, "p": "Steel has high strength."}, {"lv": 2, "q": "Which property makes a sponge useful for cleaning?", "o": ["it absorbs water", "it is hard", "it is shiny", "it is magnetic"], "a": 0, "p": "Sponges soak up water."}, {"lv": 3, "q": "Which material would be best for a window that should let in light but give privacy?", "o": ["frosted glass", "clear glass", "wood", "metal"], "a": 0, "p": "Translucent material."}, {"lv": 3, "q": "A boy tests materials by dropping water on them. Which result shows the material is waterproof?", "o": ["Water stays on top as droplets.", "Water soaks in.", "The material changes colour.", "The material breaks."], "a": 0, "p": "Water is not absorbed."}, {"lv": 3, "q": "Why are electrical wires made of copper covered in plastic?", "o": ["Copper conducts electricity; plastic insulates for safety.", "Plastic conducts electricity.", "Copper is waterproof.", "Both are magnetic."], "a": 0, "p": "Each material is chosen for its property."}, {"lv": 3, "q": "Which is the best material for a tablecloth?", "o": ["cotton", "glass", "steel", "stone"], "a": 0, "p": "It is soft, flexible and washable."}]}, {"id": "sgp-sci-k3-2", "name": "Magnets", "desc": "Properties and making magnets", "idx": 2, "soal": [{"lv": 1, "q": "Magnets attract objects made of ...", "o": ["iron", "plastic", "wood", "glass"], "a": 0, "p": "Iron is magnetic."}, {"lv": 1, "q": "The two ends of a magnet are called ...", "o": ["poles", "sides", "tips", "edges"], "a": 0, "p": "North and south poles."}, {"lv": 1, "q": "Like poles ...", "o": ["repel", "attract", "do nothing", "melt"], "a": 0, "p": "N–N or S–S push apart."}, {"lv": 1, "q": "Unlike poles ...", "o": ["attract", "repel", "do nothing", "spin"], "a": 0, "p": "N–S pull together."}, {"lv": 2, "q": "Which object is NOT attracted to a magnet?", "o": ["an aluminium can", "a steel spoon", "an iron nail", "a nickel coin"], "a": 0, "p": "Aluminium is not magnetic."}, {"lv": 2, "q": "A freely suspended bar magnet always points ...", "o": ["north–south", "east–west", "up–down", "randomly"], "a": 0, "p": "It aligns with the Earth's magnetic field."}, {"lv": 2, "q": "Which method can make a magnet?", "o": ["stroking an iron nail with a magnet in one direction", "heating a magnet", "dropping a magnet", "painting a nail"], "a": 0, "p": "This is the stroke method."}, {"lv": 2, "q": "Where is a bar magnet's force strongest?", "o": ["at the poles", "in the middle", "evenly everywhere", "nowhere"], "a": 0, "p": "Most paper clips stick at the ends."}, {"lv": 3, "q": "How can you test which of two magnets is stronger?", "o": ["See which magnet attracts more paper clips.", "See which is heavier.", "See which is bigger.", "See which colour is darker."], "a": 0, "p": "This is a fair measure of strength."}, {"lv": 3, "q": "Why might a magnet lose its magnetism?", "o": ["It is heated or dropped repeatedly.", "It is kept with a keeper.", "It is cleaned.", "It is stored in a box."], "a": 0, "p": "Heating or hammering disturbs it."}, {"lv": 3, "q": "A magnet attracts a paper clip through a sheet of paper. This shows that ...", "o": ["magnetic force can act through non-magnetic materials", "paper is magnetic", "magnets need contact", "paper clips are plastic"], "a": 0, "p": "Magnetic force can pass through some materials."}, {"lv": 3, "q": "How can a magnet be used to separate a mixture?", "o": ["It removes iron filings from sand.", "It removes salt from water.", "It removes sugar from tea.", "It separates rice from beans."], "a": 0, "p": "Only magnetic materials are attracted."}]}], "4": [{"id": "sgp-sci-k4-0", "name": "Life cycles", "desc": "Plants and animals", "idx": 0, "soal": [{"lv": 1, "q": "What is the first stage in a chicken's life cycle?", "o": ["egg", "chick", "adult", "pupa"], "a": 0, "p": "Chickens hatch from eggs."}, {"lv": 1, "q": "A young frog is called a ...", "o": ["tadpole", "larva", "chick", "nymph"], "a": 0, "p": "Tadpoles live in water."}, {"lv": 1, "q": "What does a caterpillar become?", "o": ["a butterfly", "a frog", "a beetle", "a bee"], "a": 0, "p": "After the pupa stage."}, {"lv": 1, "q": "A mosquito's life cycle has ___ stages.", "o": ["4", "3", "2", "5"], "a": 0, "p": "Egg, larva, pupa, adult."}, {"lv": 2, "q": "Which animal has a 3-stage life cycle?", "o": ["cockroach", "butterfly", "mosquito", "beetle"], "a": 0, "p": "Egg, nymph, adult."}, {"lv": 2, "q": "Why should we remove stagnant water around our homes?", "o": ["Mosquitoes lay eggs in it.", "It smells nice.", "It feeds plants.", "Birds drink it."], "a": 0, "p": "This prevents dengue."}, {"lv": 2, "q": "Which stage of a butterfly does NOT feed?", "o": ["pupa", "larva", "adult", "all stages feed"], "a": 0, "p": "The pupa is a resting stage."}, {"lv": 2, "q": "What does a seed need to germinate?", "o": ["water, air and warmth", "only soil", "only sunlight", "fertiliser only"], "a": 0, "p": "Light is not needed for germination."}, {"lv": 3, "q": "Why does a caterpillar eat a lot?", "o": ["to store energy for growth and the pupa stage", "to fly", "to make silk only", "to change colour"], "a": 0, "p": "It needs energy to change."}, {"lv": 3, "q": "A frog's life cycle and a butterfly's life cycle are similar because ...", "o": ["the young look different from the adults", "both have a pupa stage", "both live only in water", "both are mammals"], "a": 0, "p": "Both go through metamorphosis."}, {"lv": 3, "q": "Which is the correct order for a flowering plant?", "o": ["seed → seedling → adult plant → flower → fruit", "fruit → seed → flower", "flower → seedling → seed", "seedling → seed → fruit"], "a": 0, "p": "The typical sequence."}, {"lv": 3, "q": "Why do some animals lay many eggs?", "o": ["to increase the chance that some young survive", "because eggs are small", "to feed other animals on purpose", "because they cannot care for them at all"], "a": 0, "p": "Many young may die."}]}, {"id": "sgp-sci-k4-1", "name": "Matter", "desc": "States of matter, mass and volume", "idx": 1, "soal": [{"lv": 1, "q": "Matter is anything that has ...", "o": ["mass and occupies space", "colour", "a smell", "a sound"], "a": 0, "p": "This is the definition."}, {"lv": 1, "q": "Which state of matter has a definite shape?", "o": ["solid", "liquid", "gas", "all of them"], "a": 0, "p": "Solids keep their shape."}, {"lv": 1, "q": "Which state of matter takes the shape of its container but has a fixed volume?", "o": ["liquid", "solid", "gas", "none"], "a": 0, "p": "Liquids flow."}, {"lv": 1, "q": "Air is an example of a ...", "o": ["gas", "solid", "liquid", "non-matter"], "a": 0, "p": "Air is a mixture of gases."}, {"lv": 2, "q": "Which has no definite shape AND no definite volume?", "o": ["gas", "liquid", "solid", "ice"], "a": 0, "p": "Gas fills its container."}, {"lv": 2, "q": "How can we show that air has mass?", "o": ["A pumped-up ball weighs more than a flat one.", "Air is invisible.", "Air moves.", "Air is cold."], "a": 0, "p": "Added air adds mass."}, {"lv": 2, "q": "Which can be compressed easily?", "o": ["gas", "solid", "liquid", "wood"], "a": 0, "p": "Gas particles are far apart."}, {"lv": 2, "q": "Is light matter?", "o": ["No, it has no mass and does not occupy space.", "Yes, it is a gas.", "Yes, it is a solid.", "Yes, it is a liquid."], "a": 0, "p": "Light is energy."}, {"lv": 3, "q": "A syringe of air can be pushed in, but a syringe of water cannot. Why?", "o": ["Gas can be compressed, but liquid cannot easily be compressed.", "Water is lighter.", "Air is heavier.", "The syringe is broken."], "a": 0, "p": "This shows a difference between the states."}, {"lv": 3, "q": "A 200 ml stone is put into a container with 500 ml of water. What is the new water level?", "o": ["700 ml", "500 ml", "300 ml", "200 ml"], "a": 0, "p": "The stone displaces its own volume."}, {"lv": 3, "q": "Why does a balloon expand when you blow into it?", "o": ["More air takes up more space.", "The rubber grows.", "Air has no volume.", "Air is a solid."], "a": 0, "p": "Gas occupies space."}, {"lv": 3, "q": "Which pair is BOTH matter?", "o": ["water and sand", "light and heat", "sound and air", "shadow and stone"], "a": 0, "p": "Both have mass and volume."}]}, {"id": "sgp-sci-k4-2", "name": "Heat", "desc": "Heat, temperature, conductors", "idx": 2, "soal": [{"lv": 1, "q": "Heat flows from ...", "o": ["a hotter place to a colder place", "colder to hotter", "it does not flow", "only in metals"], "a": 0, "p": "Heat moves from hot to cold."}, {"lv": 1, "q": "Temperature is measured with a ...", "o": ["thermometer", "ruler", "balance", "compass"], "a": 0, "p": "In degrees Celsius."}, {"lv": 1, "q": "Which material is a good conductor of heat?", "o": ["metal", "wood", "plastic", "cloth"], "a": 0, "p": "Metals conduct heat well."}, {"lv": 1, "q": "The main source of heat for the Earth is ...", "o": ["the Sun", "the Moon", "stars at night", "clouds"], "a": 0, "p": "Solar energy."}, {"lv": 2, "q": "Why does a metal spoon in hot soup become hot?", "o": ["Heat is conducted through the metal.", "The spoon makes heat.", "Cold goes into the soup.", "Light heats it."], "a": 0, "p": "Conduction."}, {"lv": 2, "q": "Ice cubes melt when left on a table because they ...", "o": ["gain heat from the surroundings", "lose heat", "lose mass", "gain cold"], "a": 0, "p": "Heat moves into the ice."}, {"lv": 2, "q": "Why do we wear thick clothes in cold places?", "o": ["They are poor conductors and keep body heat in.", "They make heat.", "They let cold in.", "They are heavy."], "a": 0, "p": "Insulators reduce heat loss."}, {"lv": 2, "q": "What happens to most materials when heated?", "o": ["They expand.", "They contract.", "They become lighter.", "They disappear."], "a": 0, "p": "Particles move more."}, {"lv": 3, "q": "Why are gaps left between railway tracks?", "o": ["To allow for expansion on hot days.", "To save metal.", "To make noise.", "To let water flow."], "a": 0, "p": "Without gaps, the tracks would buckle."}, {"lv": 3, "q": "A hot drink in a metal cup and the same drink in a polystyrene cup are left in a room. Which stays hot longer?", "o": ["the polystyrene cup", "the metal cup", "both the same", "neither gets cold"], "a": 0, "p": "Polystyrene is a poor conductor."}, {"lv": 3, "q": "A thermometer reads 40 °C in water and 25 °C in the room. What will happen to the water over time?", "o": ["Its temperature will drop towards 25 °C.", "It will heat up.", "It will stay at 40 °C.", "It will freeze."], "a": 0, "p": "It loses heat to the surroundings."}, {"lv": 3, "q": "Why is a dented ping-pong ball put into hot water?", "o": ["The air inside expands and pushes out the dent.", "The water fills it.", "The plastic melts.", "Hot water is heavy."], "a": 0, "p": "Gas expands when heated."}]}], "5": [{"id": "sgp-sci-k5-0", "name": "Plant and human systems", "desc": "Respiratory and circulatory systems", "idx": 0, "soal": [{"lv": 1, "q": "Which organ takes in oxygen in humans?", "o": ["lungs", "heart", "stomach", "kidney"], "a": 0, "p": "Gas exchange happens in the lungs."}, {"lv": 1, "q": "The heart pumps ...", "o": ["blood", "air", "food", "water only"], "a": 0, "p": "Blood carries oxygen and nutrients."}, {"lv": 1, "q": "Plants take in carbon dioxide through ...", "o": ["tiny openings (stomata) in the leaves", "roots", "flowers", "stems only"], "a": 0, "p": "Stomata are pores."}, {"lv": 1, "q": "The water-carrying tubes in plants carry water from the ___ to the leaves.", "o": ["roots", "flowers", "fruits", "seeds"], "a": 0, "p": "Water travels upward."}, {"lv": 2, "q": "What does the circulatory system transport?", "o": ["oxygen, digested food and waste", "only air", "only water", "only bones"], "a": 0, "p": "It is the body's delivery system."}, {"lv": 2, "q": "During breathing out, the air contains more ___ than inhaled air.", "o": ["carbon dioxide", "oxygen", "nitrogen only", "helium"], "a": 0, "p": "CO₂ is a waste gas."}, {"lv": 2, "q": "Food-carrying tubes in plants carry ...", "o": ["food made in the leaves to other parts", "water from roots", "air", "soil"], "a": 0, "p": "Sugar moves from the leaves."}, {"lv": 2, "q": "Why does your heart beat faster when you run?", "o": ["to deliver more oxygen to the muscles", "to cool down", "to digest food", "to sleep"], "a": 0, "p": "Muscles need more oxygen."}, {"lv": 3, "q": "A stalk of celery is placed in red-dyed water. After a few hours the leaves turn red. This shows that ...", "o": ["water-carrying tubes transport water up the stem", "leaves make red dye", "food moves down", "celery is a root"], "a": 0, "p": "The dye travels up with the water."}, {"lv": 3, "q": "How do the respiratory and circulatory systems work together?", "o": ["Oxygen enters the blood in the lungs and the heart pumps it to body cells.", "The lungs pump blood.", "The heart takes in air.", "They do not work together."], "a": 0, "p": "Gas exchange plus transport."}, {"lv": 3, "q": "A ring of bark (with food-carrying tubes) is removed from a tree trunk. What happens over time?", "o": ["The roots do not get food and the tree may die.", "Water stops reaching the leaves immediately.", "The tree grows faster.", "Nothing happens."], "a": 0, "p": "Food cannot move down to the roots."}, {"lv": 3, "q": "How are the air sacs in the lungs adapted for gas exchange?", "o": ["They have thin walls, a large surface area and a rich blood supply.", "They are thick and hard.", "They have no blood vessels.", "They are very few."], "a": 0, "p": "This allows efficient diffusion."}]}, {"id": "sgp-sci-k5-1", "name": "Water cycle", "desc": "Evaporation, condensation, freezing", "idx": 1, "soal": [{"lv": 1, "q": "Evaporation is when water changes from ...", "o": ["liquid to gas", "gas to liquid", "solid to liquid", "liquid to solid"], "a": 0, "p": "Water becomes water vapour."}, {"lv": 1, "q": "Condensation is when water vapour ...", "o": ["cools and changes into liquid", "heats and becomes gas", "freezes", "melts"], "a": 0, "p": "Droplets form on cool surfaces."}, {"lv": 1, "q": "At what temperature does pure water freeze?", "o": ["0 °C", "100 °C", "10 °C", "−10 °C"], "a": 0, "p": "The freezing point."}, {"lv": 1, "q": "Rain falls from ...", "o": ["clouds", "the sun", "trees", "the ground"], "a": 0, "p": "Precipitation."}, {"lv": 2, "q": "Why do wet clothes dry faster on a sunny, windy day?", "o": ["Heat and wind increase the rate of evaporation.", "Clouds dry them.", "Water freezes.", "The clothes get heavier."], "a": 0, "p": "Warmer air and moving air speed up evaporation."}, {"lv": 2, "q": "Water droplets form on the outside of a cold glass because ...", "o": ["water vapour in the air condenses on the cold surface", "the glass leaks", "ice melts through the glass", "the glass sweats water out"], "a": 0, "p": "Condensation."}, {"lv": 2, "q": "Which is the correct order of the water cycle?", "o": ["evaporation → condensation → precipitation", "precipitation → freezing → melting", "condensation → evaporation → melting", "melting → boiling → freezing"], "a": 0, "p": "The basic cycle."}, {"lv": 2, "q": "Boiling differs from evaporation because boiling ...", "o": ["happens at a fixed temperature throughout the liquid", "happens at any temperature", "only happens at the surface", "makes ice"], "a": 0, "p": "Water boils at 100 °C."}, {"lv": 3, "q": "A dish of water is left in a room and its volume decreases. Which factor would slow this down?", "o": ["covering the dish", "placing it in sunlight", "using a wider dish", "using a fan"], "a": 0, "p": "Less exposed surface and still air."}, {"lv": 3, "q": "Why is the water cycle important to living things?", "o": ["It continuously supplies fresh water.", "It makes the Sun shine.", "It creates soil.", "It produces oxygen directly."], "a": 0, "p": "Water is recycled."}, {"lv": 3, "q": "The mirror in a bathroom fogs up after a hot shower. Explain.", "o": ["Warm water vapour condenses on the cooler mirror.", "The mirror heats up.", "Steam freezes.", "Light reflects water."], "a": 0, "p": "Condensation."}, {"lv": 3, "q": "Which change involves a loss of heat?", "o": ["condensation", "evaporation", "melting", "boiling"], "a": 0, "p": "Gas to liquid releases heat."}]}, {"id": "sgp-sci-k5-2", "name": "Electricity", "desc": "Circuits, conductors, insulators", "idx": 2, "soal": [{"lv": 1, "q": "An electric circuit needs a ___ path for current to flow.", "o": ["closed", "open", "broken", "short only"], "a": 0, "p": "A complete loop."}, {"lv": 1, "q": "Which is an electrical conductor?", "o": ["copper wire", "rubber band", "plastic spoon", "wooden stick"], "a": 0, "p": "Metals conduct."}, {"lv": 1, "q": "Which is an electrical insulator?", "o": ["plastic", "iron", "steel", "aluminium"], "a": 0, "p": "Plastic does not conduct."}, {"lv": 1, "q": "A battery is a source of ...", "o": ["electrical energy", "light only", "sound", "water"], "a": 0, "p": "It provides energy."}, {"lv": 2, "q": "Two bulbs are connected in series. If one bulb fuses, the other ...", "o": ["goes off", "becomes brighter", "stays on", "flickers"], "a": 0, "p": "The circuit is broken."}, {"lv": 2, "q": "Two bulbs are connected in parallel. If one fuses, the other ...", "o": ["stays lit", "goes off", "explodes", "dims to zero"], "a": 0, "p": "It has its own path."}, {"lv": 2, "q": "Adding more batteries in series to a circuit with one bulb makes the bulb ...", "o": ["brighter", "dimmer", "go off", "unchanged"], "a": 0, "p": "More voltage."}, {"lv": 2, "q": "What does a switch do?", "o": ["opens or closes a circuit", "stores electricity", "makes heat", "changes the battery"], "a": 0, "p": "It controls current flow."}, {"lv": 3, "q": "Why are the lights in a house connected in parallel?", "o": ["Each light can be switched on and off independently.", "To make them dimmer.", "To save bulbs.", "So they all go off together."], "a": 0, "p": "Separate paths."}, {"lv": 3, "q": "A circuit has a battery and a bulb, but the bulb does not light. Which is a possible cause?", "o": ["a loose connection", "the bulb is too bright", "there are too many wires", "the battery is new"], "a": 0, "p": "An open circuit."}, {"lv": 3, "q": "Which arrangement makes two bulbs brightest with the same number of batteries?", "o": ["bulbs in parallel", "bulbs in series", "only one wire", "no battery"], "a": 0, "p": "Each parallel bulb gets the full voltage."}, {"lv": 3, "q": "Why should you not touch switches with wet hands?", "o": ["Water can conduct electricity and cause electric shock.", "Water damages paint.", "Switches will freeze.", "It is just a rule with no reason."], "a": 0, "p": "Safety."}]}], "6": [{"id": "sgp-sci-k6-0", "name": "Energy forms and conversion", "desc": "Light, heat, kinetic, potential", "idx": 0, "soal": [{"lv": 1, "q": "A moving car has ___ energy.", "o": ["kinetic", "potential", "chemical only", "light only"], "a": 0, "p": "Energy of motion."}, {"lv": 1, "q": "Food contains ___ energy.", "o": ["chemical potential", "kinetic", "sound", "light"], "a": 0, "p": "Stored in food."}, {"lv": 1, "q": "A ball held high above the ground has ___ energy.", "o": ["gravitational potential", "kinetic", "sound", "electrical"], "a": 0, "p": "Due to its height."}, {"lv": 1, "q": "The Sun is the main source of ___ energy for Earth.", "o": ["light and heat", "sound", "elastic", "nuclear on Earth"], "a": 0, "p": "Solar energy."}, {"lv": 2, "q": "In a torch, chemical potential energy is converted into ...", "o": ["electrical, then light and heat energy", "sound energy only", "kinetic energy only", "potential energy"], "a": 0, "p": "Battery → bulb."}, {"lv": 2, "q": "When you rub your hands together, kinetic energy changes into ...", "o": ["heat energy", "light energy", "chemical energy", "potential energy"], "a": 0, "p": "Friction produces heat."}, {"lv": 2, "q": "A stretched rubber band has ___ energy.", "o": ["elastic potential", "kinetic", "light", "chemical"], "a": 0, "p": "Stored by stretching."}, {"lv": 2, "q": "In a solar cell, light energy is converted into ...", "o": ["electrical energy", "sound energy", "chemical energy", "kinetic energy"], "a": 0, "p": "Photovoltaic conversion."}, {"lv": 3, "q": "A ball is dropped from a height. As it falls, ...", "o": ["potential energy decreases and kinetic energy increases", "both increase", "kinetic energy decreases", "no energy changes"], "a": 0, "p": "Energy conversion."}, {"lv": 3, "q": "A ball bounces lower each time. Why?", "o": ["Some energy is converted into heat and sound at each bounce.", "Energy is destroyed.", "Gravity disappears.", "The ball gains energy."], "a": 0, "p": "Energy is not lost but converted."}, {"lv": 3, "q": "Which energy conversion happens in a wind turbine?", "o": ["kinetic → electrical", "electrical → kinetic", "light → chemical", "heat → light"], "a": 0, "p": "Moving air turns the blades."}, {"lv": 3, "q": "Plants convert light energy into ___ energy during photosynthesis.", "o": ["chemical potential", "kinetic", "sound", "elastic"], "a": 0, "p": "Stored in food."}]}, {"id": "sgp-sci-k6-1", "name": "Forces", "desc": "Friction, gravity, elastic spring force", "idx": 1, "soal": [{"lv": 1, "q": "A force can be a ...", "o": ["push or pull", "colour", "sound", "smell"], "a": 0, "p": "Definition."}, {"lv": 1, "q": "Gravity pulls objects ...", "o": ["towards the Earth", "away from the Earth", "sideways", "upwards"], "a": 0, "p": "Gravitational force."}, {"lv": 1, "q": "Friction acts ___ the direction of motion.", "o": ["opposite to", "in the same as", "at right angles to", "randomly to"], "a": 0, "p": "It opposes motion."}, {"lv": 1, "q": "The unit of force is the ...", "o": ["newton", "kilogram", "metre", "litre"], "a": 0, "p": "N."}, {"lv": 2, "q": "Which surface gives the most friction?", "o": ["sandpaper", "ice", "glass", "polished floor"], "a": 0, "p": "Rough surfaces give more friction."}, {"lv": 2, "q": "Why do shoe soles have grooves?", "o": ["to increase friction and prevent slipping", "to look nice", "to reduce weight", "to make noise"], "a": 0, "p": "Better grip."}, {"lv": 2, "q": "A spring stretches more when ...", "o": ["a heavier load is hung on it", "it is painted", "it is cooled", "a lighter load is hung"], "a": 0, "p": "A greater force means more extension."}, {"lv": 2, "q": "Which helps reduce friction in machines?", "o": ["oil", "sand", "rubber pads", "glue"], "a": 0, "p": "Lubricants."}, {"lv": 3, "q": "A spring is 10 cm long. With a 100 g mass it is 12 cm. How long is it with a 300 g mass (within its limit)?", "o": ["16 cm", "14 cm", "36 cm", "18 cm"], "a": 0, "p": "2 cm per 100 g; extension 6 cm."}, {"lv": 3, "q": "A box does not move when pushed gently. Why?", "o": ["Friction balances the pushing force.", "Gravity disappears.", "There is no force.", "The box is magnetic."], "a": 0, "p": "Balanced forces."}, {"lv": 3, "q": "Why is it harder to walk on ice than on a carpet?", "o": ["Ice has very little friction.", "Ice is heavier.", "Carpet is slippery.", "Ice has more gravity."], "a": 0, "p": "Low friction."}, {"lv": 3, "q": "A parachute slows a skydiver because ...", "o": ["its large surface area increases air resistance", "it reduces gravity", "it adds mass", "it is magnetic"], "a": 0, "p": "Air resistance acts upward."}]}, {"id": "sgp-sci-k6-2", "name": "Food chains and webs", "desc": "Interactions in an environment", "idx": 2, "soal": [{"lv": 1, "q": "In a food chain, the first organism is usually a ...", "o": ["producer (plant)", "consumer", "predator", "decomposer"], "a": 0, "p": "Plants make food."}, {"lv": 1, "q": "An animal that eats only plants is a ...", "o": ["herbivore", "carnivore", "omnivore", "decomposer"], "a": 0, "p": "Plant eater."}, {"lv": 1, "q": "An animal that eats both plants and animals is an ...", "o": ["omnivore", "herbivore", "carnivore", "insect"], "a": 0, "p": "Eats both."}, {"lv": 1, "q": "The arrow in a food chain shows ...", "o": ["the direction of energy flow ('is eaten by')", "who is bigger", "where animals live", "who is faster"], "a": 0, "p": "Energy moves along."}, {"lv": 2, "q": "In grass → grasshopper → frog → snake, the frog is a ...", "o": ["predator and prey", "producer", "decomposer", "herbivore"], "a": 0, "p": "It eats grasshoppers and is eaten by snakes."}, {"lv": 2, "q": "Decomposers such as fungi ...", "o": ["break down dead matter and return nutrients to the soil", "make food from sunlight", "hunt animals", "eat only plants"], "a": 0, "p": "Recyclers."}, {"lv": 2, "q": "A food web is ...", "o": ["many interconnected food chains", "one straight chain", "a spider's web", "a list of plants"], "a": 0, "p": "It shows complex feeding."}, {"lv": 2, "q": "Where does all the energy in a food chain originally come from?", "o": ["the Sun", "the soil", "water", "the predator"], "a": 0, "p": "Plants capture sunlight."}, {"lv": 3, "q": "In grass → rabbit → fox, what happens if all foxes are removed?", "o": ["The rabbit population increases, then grass decreases.", "Rabbits decrease.", "Grass increases.", "Nothing changes."], "a": 0, "p": "Fewer predators means more rabbits."}, {"lv": 3, "q": "Why are there usually fewer predators than prey?", "o": ["Energy is lost at each level, so less is available higher up.", "Predators are lazy.", "Prey are smaller.", "Predators do not eat."], "a": 0, "p": "Energy transfer is inefficient."}, {"lv": 3, "q": "A pesticide sprayed on crops harms birds that eat insects. Why?", "o": ["The poison passes along the food chain.", "Birds eat the pesticide cans.", "Birds breathe it in only.", "Insects attack birds."], "a": 0, "p": "Bioaccumulation."}, {"lv": 3, "q": "Which organism is a producer?", "o": ["algae", "fish", "shark", "mushroom"], "a": 0, "p": "Algae photosynthesise."}]}], "7": [{"id": "sgp-sci-k7-0", "name": "Scientific method and measurement", "desc": "Variables, SI units, instruments", "idx": 0, "soal": [{"lv": 1, "q": "In an experiment, the variable you change is the ...", "o": ["independent variable", "dependent variable", "controlled variable", "constant only"], "a": 0, "p": "You choose it."}, {"lv": 1, "q": "The SI unit of length is the ...", "o": ["metre", "centimetre", "inch", "foot"], "a": 0, "p": "Metre (m)."}, {"lv": 1, "q": "Which instrument measures mass?", "o": ["electronic balance", "measuring cylinder", "thermometer", "ruler"], "a": 0, "p": "Mass is measured with a balance."}, {"lv": 1, "q": "The SI unit of time is the ...", "o": ["second", "minute", "hour", "day"], "a": 0, "p": "s."}, {"lv": 2, "q": "Why must other variables be kept constant in a fair test?", "o": ["so only the independent variable affects the result", "to make it faster", "to make it longer", "because it looks neat"], "a": 0, "p": "Validity."}, {"lv": 2, "q": "Which instrument gives the most precise volume of 25 cm³ of liquid?", "o": ["pipette", "beaker", "measuring cylinder (100 cm³)", "conical flask"], "a": 0, "p": "Pipettes are very precise."}, {"lv": 2, "q": "When reading a measuring cylinder, your eye should be ...", "o": ["level with the bottom of the meniscus", "above the liquid", "below the cylinder", "at the top of the cylinder"], "a": 0, "p": "This avoids parallax error."}, {"lv": 2, "q": "Why repeat an experiment several times?", "o": ["to improve reliability", "to waste time", "to change the variables", "to get different answers"], "a": 0, "p": "Consistency."}, {"lv": 3, "q": "A student measures how temperature affects how fast sugar dissolves. What is the dependent variable?", "o": ["time taken for the sugar to dissolve", "temperature", "mass of sugar", "volume of water"], "a": 0, "p": "It is what is measured."}, {"lv": 3, "q": "Which is a hypothesis?", "o": ["If the temperature increases, sugar will dissolve faster.", "Sugar is sweet.", "Water is clear.", "I like science."], "a": 0, "p": "A testable prediction."}, {"lv": 3, "q": "Convert 2.5 kg into grams.", "o": ["2500 g", "250 g", "25 g", "25 000 g"], "a": 0, "p": "× 1000."}, {"lv": 3, "q": "Why should a thermometer not touch the bottom of a heated beaker?", "o": ["It would measure the beaker's temperature, not the liquid's.", "It will break the glass.", "It reads too slowly.", "It is not allowed."], "a": 0, "p": "This gives an accurate reading."}]}, {"id": "sgp-sci-k7-1", "name": "Cells", "desc": "Structure and organisation", "idx": 1, "soal": [{"lv": 1, "q": "The basic unit of life is the ...", "o": ["cell", "atom", "organ", "tissue"], "a": 0, "p": "All living things are made of cells."}, {"lv": 1, "q": "Which part controls cell activities?", "o": ["nucleus", "cytoplasm", "cell wall", "vacuole"], "a": 0, "p": "It contains genetic material."}, {"lv": 1, "q": "Which part is found only in plant cells?", "o": ["chloroplast", "nucleus", "cell membrane", "cytoplasm"], "a": 0, "p": "Chloroplasts are needed for photosynthesis."}, {"lv": 1, "q": "A group of similar cells working together forms a ...", "o": ["tissue", "organ", "system", "organism"], "a": 0, "p": "Level of organisation."}, {"lv": 2, "q": "Which part of a plant cell gives it a fixed shape?", "o": ["cell wall", "nucleus", "cytoplasm", "cell membrane"], "a": 0, "p": "Rigid cellulose."}, {"lv": 2, "q": "Which is the correct order of organisation?", "o": ["cell → tissue → organ → system → organism", "organ → cell → tissue", "tissue → cell → organ", "system → organ → cell"], "a": 0, "p": "Increasing complexity."}, {"lv": 2, "q": "What is the function of the cell membrane?", "o": ["controls the movement of substances in and out", "makes food", "stores starch only", "gives rigid support"], "a": 0, "p": "Partially permeable."}, {"lv": 2, "q": "Where do most chemical reactions take place in a cell?", "o": ["cytoplasm", "cell wall", "vacuole", "chloroplast only"], "a": 0, "p": "A jelly-like medium."}, {"lv": 3, "q": "Why do root hair cells have a long, thin extension?", "o": ["to increase the surface area for absorbing water", "to make food", "to store food", "to protect the plant"], "a": 0, "p": "Specialised cell."}, {"lv": 3, "q": "Red blood cells have no nucleus. What is the advantage?", "o": ["more space to carry oxygen", "they live longer", "they can divide faster", "they make food"], "a": 0, "p": "Specialisation."}, {"lv": 3, "q": "Which cell would have many chloroplasts?", "o": ["a palisade cell in a leaf", "a root hair cell", "a human nerve cell", "a red blood cell"], "a": 0, "p": "Main photosynthesis site."}, {"lv": 3, "q": "Why are nerve cells long?", "o": ["to carry messages over long distances", "to store fat", "to carry oxygen", "to absorb water"], "a": 0, "p": "Structure suits function."}]}, {"id": "sgp-sci-k7-2", "name": "Elements, compounds and mixtures", "desc": "Separation techniques", "idx": 2, "soal": [{"lv": 1, "q": "An element is made of ...", "o": ["only one type of atom", "two or more elements chemically combined", "a mixture of substances", "molecules of different elements"], "a": 0, "p": "For example, oxygen."}, {"lv": 1, "q": "Water (H₂O) is a ...", "o": ["compound", "element", "mixture", "metal"], "a": 0, "p": "Chemically combined H and O."}, {"lv": 1, "q": "Air is a ...", "o": ["mixture", "compound", "element", "metal"], "a": 0, "p": "Gases not chemically combined."}, {"lv": 1, "q": "Which method separates sand from water?", "o": ["filtration", "evaporation only", "magnet", "chromatography"], "a": 0, "p": "Insoluble solid from liquid."}, {"lv": 2, "q": "Which method gets salt from salt solution?", "o": ["evaporation", "filtration", "using a magnet", "decanting"], "a": 0, "p": "Water evaporates; salt remains."}, {"lv": 2, "q": "Which method separates the dyes in ink?", "o": ["chromatography", "filtration", "magnetic attraction", "sieving"], "a": 0, "p": "Separates by solubility."}, {"lv": 2, "q": "How does a compound differ from a mixture?", "o": ["A compound has fixed proportions and is chemically combined.", "A mixture has fixed proportions.", "A compound can be separated physically.", "They are the same."], "a": 0, "p": "Key difference."}, {"lv": 2, "q": "Which method obtains pure water from seawater?", "o": ["distillation", "filtration", "chromatography", "sieving"], "a": 0, "p": "Boil, then condense."}, {"lv": 3, "q": "A mixture of iron filings, sand and salt is separated. Which order works?", "o": ["magnet → add water and filter → evaporate the filtrate", "evaporate → magnet → filter", "filter → magnet → distil", "chromatography → magnet"], "a": 0, "p": "Iron first, then sand by filtering, then salt by evaporation."}, {"lv": 3, "q": "Why does a mixture have no fixed melting point?", "o": ["Its composition can vary.", "It is always a gas.", "It is a pure substance.", "It has no particles."], "a": 0, "p": "Impure."}, {"lv": 3, "q": "In chromatography, a dye that travels furthest is ...", "o": ["the most soluble in the solvent", "the least soluble", "insoluble", "the heaviest"], "a": 0, "p": "It is carried furthest."}, {"lv": 3, "q": "Which is an element?", "o": ["copper", "carbon dioxide", "salt water", "air"], "a": 0, "p": "One type of atom."}]}], "8": [{"id": "sgp-sci-k8-0", "name": "Particulate nature of matter", "desc": "Kinetic particle theory", "idx": 0, "soal": [{"lv": 1, "q": "All matter is made up of tiny ...", "o": ["particles", "cells", "waves", "bubbles"], "a": 0, "p": "Particle theory."}, {"lv": 1, "q": "In which state are particles closest together?", "o": ["solid", "liquid", "gas", "all are equal"], "a": 0, "p": "Closely packed."}, {"lv": 1, "q": "Particles in a gas move ...", "o": ["quickly and randomly", "not at all", "only in straight lines slowly", "only vibrate"], "a": 0, "p": "Free movement."}, {"lv": 1, "q": "Diffusion is ...", "o": ["the spreading of particles from high to low concentration", "melting", "freezing", "boiling"], "a": 0, "p": "Net movement."}, {"lv": 2, "q": "Why does diffusion happen faster in gases than in liquids?", "o": ["Gas particles move faster and have more space.", "Gas particles are larger.", "Liquids have no particles.", "Gases are heavier."], "a": 0, "p": "Kinetic theory."}, {"lv": 2, "q": "What happens to particles when a solid melts?", "o": ["They gain energy and can slide past each other.", "They stop moving.", "They disappear.", "They get smaller."], "a": 0, "p": "They overcome attractive forces."}, {"lv": 2, "q": "Why can gases be compressed?", "o": ["There are large spaces between particles.", "Particles are touching.", "Particles do not move.", "Gases have no mass."], "a": 0, "p": "Spaces can be reduced."}, {"lv": 2, "q": "Why does a smell spread through a room even without wind?", "o": ["Gas particles diffuse by random motion.", "Light carries it.", "Sound carries it.", "It sinks to the floor."], "a": 0, "p": "Brownian/random motion."}, {"lv": 3, "q": "Why does a liquid expand when heated?", "o": ["Particles move faster and further apart.", "Particles get bigger.", "More particles are made.", "Particles get heavier."], "a": 0, "p": "Thermal expansion."}, {"lv": 3, "q": "Pollen grains in water jiggle randomly under a microscope. This shows ...", "o": ["water particles are moving and colliding with the pollen", "pollen is alive and swimming", "water is still", "pollen is magnetic"], "a": 0, "p": "Brownian motion."}, {"lv": 3, "q": "Why does a tyre's pressure increase on a hot day?", "o": ["Air particles move faster and hit the walls harder and more often.", "The rubber shrinks.", "Air particles get larger.", "More air enters."], "a": 0, "p": "Particle collisions."}, {"lv": 3, "q": "A purple crystal is placed in water and the colour spreads. Which change would speed this up?", "o": ["using warmer water", "using colder water", "using a larger crystal only", "adding ice"], "a": 0, "p": "Faster particles."}]}, {"id": "sgp-sci-k8-1", "name": "Human digestive system", "desc": "Organs and enzymes", "idx": 1, "soal": [{"lv": 1, "q": "Digestion begins in the ...", "o": ["mouth", "stomach", "small intestine", "large intestine"], "a": 0, "p": "Chewing and saliva."}, {"lv": 1, "q": "Which organ produces bile?", "o": ["liver", "stomach", "pancreas", "gall bladder"], "a": 0, "p": "Bile is stored in the gall bladder."}, {"lv": 1, "q": "Digested food is absorbed mainly in the ...", "o": ["small intestine", "stomach", "mouth", "large intestine"], "a": 0, "p": "Villi absorb it."}, {"lv": 1, "q": "Water is mainly absorbed in the ...", "o": ["large intestine", "mouth", "oesophagus", "stomach"], "a": 0, "p": "Colon."}, {"lv": 2, "q": "Which enzyme digests starch?", "o": ["amylase", "protease", "lipase", "bile"], "a": 0, "p": "Starch → sugars."}, {"lv": 2, "q": "Protease breaks down proteins into ...", "o": ["amino acids", "glucose", "fatty acids", "starch"], "a": 0, "p": "Proteins → amino acids."}, {"lv": 2, "q": "Why does the stomach produce hydrochloric acid?", "o": ["to kill bacteria and provide the right pH for enzymes", "to digest starch", "to absorb water", "to produce bile"], "a": 0, "p": "Protection and enzyme conditions."}, {"lv": 2, "q": "What is peristalsis?", "o": ["wave-like muscle contractions that push food along the gut", "chewing", "absorbing water", "making enzymes"], "a": 0, "p": "Movement of food."}, {"lv": 3, "q": "How are villi adapted for absorption?", "o": ["large surface area, thin walls and a rich blood supply", "thick walls", "few blood vessels", "a small surface area"], "a": 0, "p": "Efficient absorption."}, {"lv": 3, "q": "Bile emulsifies fats. This means it ...", "o": ["breaks large fat droplets into smaller ones", "digests fat chemically", "absorbs fat", "turns fat into glucose"], "a": 0, "p": "Increases surface area for lipase."}, {"lv": 3, "q": "Why must large food molecules be digested?", "o": ["They are too large to be absorbed into the blood.", "They taste bad.", "They are poisonous.", "They contain no energy."], "a": 0, "p": "Small molecules can be absorbed."}, {"lv": 3, "q": "A person has their gall bladder removed. Which food would be hardest to digest?", "o": ["fatty food", "bread", "fruit", "rice"], "a": 0, "p": "Less bile is available for emulsifying fats."}]}, {"id": "sgp-sci-k8-2", "name": "Light", "desc": "Reflection and refraction", "idx": 2, "soal": [{"lv": 1, "q": "Light travels in ...", "o": ["straight lines", "curves", "circles", "zigzags"], "a": 0, "p": "Rectilinear propagation."}, {"lv": 1, "q": "The angle of incidence equals the angle of ...", "o": ["reflection", "refraction", "absorption", "diffraction"], "a": 0, "p": "Law of reflection."}, {"lv": 1, "q": "Refraction is the ...", "o": ["bending of light as it passes from one medium to another", "bouncing of light", "absorption of light", "splitting of mirrors"], "a": 0, "p": "Change of speed."}, {"lv": 1, "q": "A plane mirror image is ...", "o": ["laterally inverted (left-right reversed)", "upside down", "larger", "real"], "a": 0, "p": "Mirror reverses left and right."}, {"lv": 2, "q": "Light travels from air into glass. It bends ...", "o": ["towards the normal", "away from the normal", "it does not bend", "back into the air"], "a": 0, "p": "It slows down in denser media."}, {"lv": 2, "q": "Why does a straw look bent in water?", "o": ["Light refracts as it leaves the water.", "The straw bends.", "The water reflects it.", "Light stops in water."], "a": 0, "p": "Refraction."}, {"lv": 2, "q": "A ray hits a mirror at 40° to the normal. What is the angle of reflection?", "o": ["40°", "50°", "80°", "90°"], "a": 0, "p": "i = r."}, {"lv": 2, "q": "The image in a plane mirror is ___ from the mirror as the object.", "o": ["the same distance", "twice as far", "half as far", "much closer"], "a": 0, "p": "Property of plane mirrors."}, {"lv": 3, "q": "A ray hits a mirror at 30° to the mirror surface. What is the angle of reflection?", "o": ["60°", "30°", "90°", "120°"], "a": 0, "p": "Angle to the normal = 90 − 30 = 60°."}, {"lv": 3, "q": "Why does a swimming pool look shallower than it really is?", "o": ["Light refracts away from the normal as it leaves the water.", "Water magnifies the depth.", "Light reflects off the bottom only.", "The pool is shallow."], "a": 0, "p": "Apparent depth."}, {"lv": 3, "q": "Total internal reflection can occur when light goes ...", "o": ["from a denser to a less dense medium at a large angle", "from air into glass", "at any angle", "only in mirrors"], "a": 0, "p": "Beyond the critical angle."}, {"lv": 3, "q": "Optical fibres carry light using ...", "o": ["total internal reflection", "refraction only", "absorption", "diffusion"], "a": 0, "p": "Light bounces inside the fibre."}]}], "9": [{"id": "sgp-sci-k9-0", "name": "Physics: Kinematics", "desc": "Speed, velocity, acceleration, graphs", "idx": 0, "soal": [{"lv": 1, "q": "Velocity is speed in a given ...", "o": ["direction", "time", "mass", "colour"], "a": 0, "p": "A vector quantity."}, {"lv": 1, "q": "Acceleration = ?", "o": ["change in velocity ÷ time", "distance ÷ time", "mass × velocity", "force ÷ distance"], "a": 0, "p": "a = Δv/t."}, {"lv": 1, "q": "The SI unit of acceleration is ...", "o": ["m/s²", "m/s", "km/h", "N"], "a": 0, "p": "Metres per second squared."}, {"lv": 1, "q": "On a distance–time graph, the gradient gives the ...", "o": ["speed", "acceleration", "distance", "force"], "a": 0, "p": "Rate of change of distance."}, {"lv": 2, "q": "A car goes from 0 to 25 m/s in 5 s. What is its acceleration?", "o": ["5 m/s²", "125 m/s²", "20 m/s²", "0.2 m/s²"], "a": 0, "p": "25 ÷ 5."}, {"lv": 2, "q": "On a speed–time graph, the area under the line gives the ...", "o": ["distance travelled", "acceleration", "speed", "force"], "a": 0, "p": "Integration of speed."}, {"lv": 2, "q": "An object falls freely near the Earth's surface. Its acceleration is about ...", "o": ["10 m/s²", "1 m/s²", "100 m/s²", "0 m/s²"], "a": 0, "p": "g ≈ 10 m/s²."}, {"lv": 2, "q": "A horizontal line on a speed–time graph means ...", "o": ["constant speed", "the object is at rest", "accelerating", "decelerating"], "a": 0, "p": "No change in speed."}, {"lv": 3, "q": "A train decelerates uniformly from 30 m/s to rest in 10 s. How far does it travel?", "o": ["150 m", "300 m", "30 m", "3 m"], "a": 0, "p": "½ × 30 × 10."}, {"lv": 3, "q": "A car accelerates at 2 m/s² from 10 m/s for 5 s. What is its final speed?", "o": ["20 m/s", "12 m/s", "15 m/s", "50 m/s"], "a": 0, "p": "10 + 2 × 5."}, {"lv": 3, "q": "Why does a skydiver eventually reach terminal velocity?", "o": ["Air resistance increases until it equals weight.", "Gravity stops.", "Mass decreases.", "Air resistance disappears."], "a": 0, "p": "Balanced forces."}, {"lv": 3, "q": "A ball is thrown upward. At its highest point, ...", "o": ["its velocity is zero but acceleration is still about 10 m/s² downward", "both velocity and acceleration are zero", "acceleration is zero", "velocity is maximum"], "a": 0, "p": "Gravity still acts."}]}, {"id": "sgp-sci-k9-1", "name": "Chemistry: Atomic structure", "desc": "Protons, neutrons, electrons, isotopes", "idx": 1, "soal": [{"lv": 1, "q": "Which particle has a positive charge?", "o": ["proton", "electron", "neutron", "atom"], "a": 0, "p": "Protons are positive."}, {"lv": 1, "q": "Which particle has no charge?", "o": ["neutron", "proton", "electron", "ion"], "a": 0, "p": "Neutral."}, {"lv": 1, "q": "The atomic (proton) number is the number of ...", "o": ["protons", "neutrons", "electrons + neutrons", "shells"], "a": 0, "p": "It identifies the element."}, {"lv": 1, "q": "Electrons are found ...", "o": ["in shells around the nucleus", "in the nucleus", "inside protons", "nowhere"], "a": 0, "p": "Electron shells."}, {"lv": 2, "q": "An atom has 11 protons and 12 neutrons. What is its nucleon (mass) number?", "o": ["23", "11", "12", "1"], "a": 0, "p": "11 + 12."}, {"lv": 2, "q": "Isotopes have the same number of ___ but different numbers of ___.", "o": ["protons; neutrons", "neutrons; protons", "electrons; protons", "shells; electrons"], "a": 0, "p": "Definition."}, {"lv": 2, "q": "What is the electronic configuration of sodium (11 electrons)?", "o": ["2.8.1", "2.9", "2.8.2", "8.2.1"], "a": 0, "p": "2, then 8, then 1."}, {"lv": 2, "q": "How many neutrons are in ³⁵Cl (proton number 17)?", "o": ["18", "17", "35", "52"], "a": 0, "p": "35 − 17."}, {"lv": 3, "q": "An ion has 12 protons and 10 electrons. What is its charge?", "o": ["+2", "−2", "0", "+12"], "a": 0, "p": "12 − 10."}, {"lv": 3, "q": "Why do isotopes of the same element have the same chemical properties?", "o": ["They have the same electronic configuration.", "They have the same mass.", "They have the same number of neutrons.", "They are different elements."], "a": 0, "p": "Electrons determine chemistry."}, {"lv": 3, "q": "Chlorine has isotopes ³⁵Cl (75%) and ³⁷Cl (25%). What is its relative atomic mass?", "o": ["35.5", "36", "35", "37"], "a": 0, "p": "0.75 × 35 + 0.25 × 37."}, {"lv": 3, "q": "An element has the configuration 2.8.6. Which group is it in?", "o": ["Group VI (16)", "Group II", "Group VIII", "Group III"], "a": 0, "p": "6 outer electrons."}]}, {"id": "sgp-sci-k9-2", "name": "Biology: Transport in humans", "desc": "Heart, blood vessels, blood", "idx": 2, "soal": [{"lv": 1, "q": "Which blood cells fight infection?", "o": ["white blood cells", "red blood cells", "platelets", "plasma"], "a": 0, "p": "Immune defence."}, {"lv": 1, "q": "Which blood component helps blood to clot?", "o": ["platelets", "red blood cells", "plasma", "white blood cells"], "a": 0, "p": "Clotting."}, {"lv": 1, "q": "Arteries carry blood ___ the heart.", "o": ["away from", "towards", "around only", "into the lungs only"], "a": 0, "p": "Definition."}, {"lv": 1, "q": "The liquid part of blood is ...", "o": ["plasma", "platelets", "haemoglobin", "lymph only"], "a": 0, "p": "Mostly water."}, {"lv": 2, "q": "Which vessel has valves to prevent backflow?", "o": ["vein", "artery", "capillary", "aorta only"], "a": 0, "p": "Low pressure."}, {"lv": 2, "q": "Why are capillary walls one cell thick?", "o": ["for efficient exchange of substances", "to withstand high pressure", "to store blood", "to pump blood"], "a": 0, "p": "Short diffusion distance."}, {"lv": 2, "q": "Haemoglobin in red blood cells carries ...", "o": ["oxygen", "glucose", "carbon dioxide only", "fat"], "a": 0, "p": "Oxyhaemoglobin."}, {"lv": 2, "q": "Which chamber of the heart pumps blood to the whole body?", "o": ["left ventricle", "right ventricle", "left atrium", "right atrium"], "a": 0, "p": "It has a thick wall."}, {"lv": 3, "q": "Trace the path of blood from the body back to the body.", "o": ["vena cava → right atrium → right ventricle → lungs → left atrium → left ventricle → aorta", "aorta → left atrium → lungs → right ventricle", "lungs → vena cava → aorta", "right atrium → left ventricle → lungs"], "a": 0, "p": "Double circulation."}, {"lv": 3, "q": "Why does the left ventricle have a thicker wall than the right?", "o": ["It must pump blood at higher pressure around the whole body.", "It holds more blood.", "It receives blood from the lungs.", "It has valves."], "a": 0, "p": "Greater distance."}, {"lv": 3, "q": "A blood clot blocks a coronary artery. What may happen?", "o": ["Part of the heart muscle is starved of oxygen (heart attack).", "Blood pressure falls to zero everywhere.", "The lungs stop working directly.", "Nothing happens."], "a": 0, "p": "Ischaemia."}, {"lv": 3, "q": "How are red blood cells adapted to carry oxygen?", "o": ["biconcave shape, no nucleus and much haemoglobin", "large nucleus", "thick membrane", "many mitochondria only"], "a": 0, "p": "Maximises carrying capacity."}]}]}}};
